window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G14"] = {"bang":[{"i":0,"tieu_de_bang":"Hà Nội 1945 – Ba Đình","tieu_de":"Hà Nội 1945–1946: mười sáu tháng giữ một nền độc lập","sapo":"Cuối tháng Tám năm 1945, một vị khách gầy gò từ chiến khu Việt Bắc lặng lẽ bước lên căn gác của một hiệu lụa trên phố Hàng Ngang. Một tuần sau, hàng chục vạn người lần đầu được nghe giọng nói của Người ở Quảng trường Ba Đình. Rồi suốt mười sáu tháng tiếp theo, nhà nước vừa ra đời phải cùng lúc chống giặc đói, giặc dốt và giặc ngoại xâm. Gian trưng bày này mời bạn bước vào chính những tháng ngày ấy.","bia":{"src":"textures/bai/G14_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Vị khách về từ chiến khu","text":"Ngày 22/8/1945, Chủ tịch Hồ Chí Minh rời Tân Trào về xuôi. Người vừa qua một trận ốm nặng ở chiến khu, sức khỏe còn yếu, nhưng tin tức dồn dập từ khắp nơi không cho phép chậm trễ. Cuộc Tổng khởi nghĩa đang lan rộng, Hà Nội đã giành chính quyền từ ngày 19/8, Huế và Sài Gòn cũng đang sục sôi. Sau mấy ngày dừng chân ở làng Phú Gia ven Hồ Tây, ngày 25/8/1945, Người vào nội thành, ở tại căn gác hai nhà số 48 Hàng Ngang, cửa hiệu tơ lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô.\n\nNgười dân phố cổ khi ấy không biết vị khách gầy gò ấy là ai. Ngay cả nhiều người đã nghe đến cái tên Hồ Chí Minh cũng chưa biết rằng đó chính là Nguyễn Ái Quốc, cái tên đã gắn với phong trào giải phóng dân tộc suốt hơn hai mươi năm. Hà Nội những ngày ấy rợp cờ đỏ sao vàng, các ngả phố vang tiếng hát, nhưng quân Nhật vẫn còn đóng trong thành phố, còn những đạo quân nước ngoài khác đang chuẩn bị kéo vào từ hai đầu đất nước. Niềm vui và nỗi lo đan vào nhau trong từng ngày của mùa thu năm ấy. Và căn gác nhỏ giữa khu phố buôn bán sầm uất bỗng trở thành nơi làm việc của người sắp đứng đầu một nhà nước mới.","doc":1},{"loai":"doan","tieu_de":"Tám ngày, từ căn gác ra quảng trường","text":"Tám ngày trên căn gác Hàng Ngang là tám ngày làm việc không nghỉ. Ngày 26/8, ngay tại ngôi nhà này, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng. Cuộc họp quyết định chuẩn bị bản Tuyên ngôn Độc lập, tổ chức lễ ra mắt Chính phủ lâm thời và mở rộng thành phần Chính phủ để đoàn kết mọi lực lượng yêu nước. Ngày 28/8, danh sách Chính phủ lâm thời được công bố; bên cạnh những chiến sĩ cách mạng có nhiều nhân sĩ, trí thức không đảng phái. Cũng trong hai ngày 28 và 29/8, Người soạn thảo bản Tuyên ngôn Độc lập. Ngày 30/8 ở Huế, vua Bảo Đại thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời.\n\nChiều Chủ nhật 2/9/1945, tại vườn hoa Ba Đình, trước hàng chục vạn đồng bào, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Những gì diễn ra hôm ấy, từ lễ đài dựng gấp trong ít ngày, câu hỏi “Tôi nói, đồng bào nghe rõ không?”, đến lời thề của Chính phủ và của cả quảng trường, được kể lại trong các chuyên đề riêng của gian này. Ở đây, chỉ cần nhớ một điều: chỉ tám ngày tách buổi chiều lịch sử ấy với ngày Người đặt chân lên căn gác nhỏ.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hà Nội 1945 – Ba Đình”, nhìn từ xa."},{"loai":"doan","tieu_de":"“Ngàn cân treo sợi tóc”","text":"Niềm vui Độc lập chưa trọn một tháng thì những hiểm họa đã hiện rõ. Nạn đói năm Ất Dậu vừa cướp đi sinh mạng hơn hai triệu đồng bào từ Quảng Trị trở ra, như chính bản Tuyên ngôn đã nêu, và lũ lụt, vỡ đê năm ấy khiến nguy cơ một nạn đói mới luôn rình rập. Hơn chín mươi phần trăm dân số không biết chữ. Ngân khố quốc gia gần như trống rỗng, còn Ngân hàng Đông Dương, nơi nắm quyền phát hành giấy bạc, vẫn nằm trong tay tư bản Pháp.\n\nTheo thỏa thuận của các nước Đồng minh, quân đội nước ngoài vào Việt Nam giải giáp quân Nhật, lấy vĩ tuyến 16 làm ranh giới. Ở phía bắc, khoảng hai mươi vạn quân Tưởng Giới Thạch kéo vào, kéo theo các tổ chức người Việt thân Tưởng ra sức chống phá chính quyền. Ở phía nam, quân Anh vào và mở đường cho thực dân Pháp; ngày 23/9/1945, Pháp nổ súng đánh chiếm Sài Gòn, cuộc kháng chiến ở Nam Bộ bùng nổ. Trên đất nước khi ấy vẫn còn hàng vạn quân Nhật chờ giải giáp. Lịch sử gọi hoàn cảnh ấy bằng một hình ảnh: vận mệnh dân tộc như “ngàn cân treo sợi tóc”. Chính quyền mới phải cùng lúc đương đầu với ba thứ giặc mà Chủ tịch Hồ Chí Minh thường gọi tên: giặc đói, giặc dốt và giặc ngoại xâm.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình chiều 2/9/1945 (ảnh tư liệu của Mặt trận Việt Minh, thuộc phạm vi công cộng).","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Sáu nhiệm vụ cấp bách","text":"Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ. Người nêu sáu nhiệm vụ cấp bách. Ba nhiệm vụ đầu là phát động tăng gia sản xuất để chống đói, mở chiến dịch chống nạn mù chữ, tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu. Ba nhiệm vụ tiếp theo là giáo dục nhân dân tinh thần cần, kiệm, liêm, chính; bỏ ngay thuế thân, thuế chợ, thuế đò và tuyệt đối cấm hút thuốc phiện; tuyên bố tự do tín ngưỡng, lương giáo đoàn kết.\n\nĐọc lại danh sách ấy hôm nay, người ta thấy một cách nhìn rất rõ ràng. Cứu đói là giữ lấy sinh mạng của dân. Chống mù chữ là trao cho dân công cụ để hiểu quyền lợi và bổn phận của mình. Tổng tuyển cử là để chính quyền có nền tảng pháp lý vững chắc trước quốc dân và thế giới. Bỏ những thứ thuế bất công, cấm thuốc phiện là xóa đi những dấu vết nặng nề nhất của chế độ cũ. Đoàn kết lương giáo là giữ lấy khối đoàn kết toàn dân. Mỗi nhiệm vụ về sau đều trở thành một phong trào của cả nước; các chuyên đề trong gian này kể riêng về cuộc chiến chống giặc đói, phong trào Bình dân học vụ, Tuần lễ Vàng và cuộc Tổng tuyển cử ngày 6/1/1946.","doc":4},{"loai":"ban_co_biet","text":"Ngày 11/11/1945, để tránh mũi nhọn tấn công của kẻ thù và các thế lực chống đối, Đảng Cộng sản Đông Dương ra thông cáo “tự giải tán”. Thực chất Đảng rút vào hoạt động bí mật và tiếp tục lãnh đạo chính quyền, lãnh đạo cách mạng.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử; Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":5},{"loai":"doan","tieu_de":"Một chính quyền của toàn dân","text":"Muốn giữ được độc lập trong vòng vây ấy, Chủ tịch Hồ Chí Minh đặt lên hàng đầu khối đoàn kết toàn dân. Cựu hoàng Bảo Đại, nay là công dân Vĩnh Thụy, được mời làm Cố vấn tối cao của Chính phủ. Nhiều nhà nho, nhà khoa bảng, trí thức không đảng phái được mời gánh vác việc nước; trong số đó có cụ Huỳnh Thúc Kháng, người về sau giữ quyền Chủ tịch nước khi Người sang Pháp. Giới công thương được Người gửi thư riêng, khuyến khích họ góp sức xây dựng nền kinh tế nước nhà. Ngày 29/5/1946, Hội Liên hiệp quốc dân Việt Nam ra đời, mở rộng khối đoàn kết ra ngoài khuôn khổ Mặt trận Việt Minh.\n\nChính khối đoàn kết ấy làm nên những phong trào mà gian trưng bày này kể lại. Người giàu góp vàng, người nghèo góp gạo, người biết chữ dạy người chưa biết chữ; người già, người trẻ, nam và nữ cùng đi bỏ phiếu. Nhà nước mới không có ngân khố dồi dào, không có quân đội hiện đại, chưa được một quốc gia nào công nhận, nhưng có một thứ tài sản mà mọi đối thủ đều phải kiêng nể: lòng tin của nhân dân. Mười sáu tháng ở Hà Nội cũng là mười sáu tháng Người vun đắp tài sản ấy, để khi tiếng súng kháng chiến nổ ra, cả dân tộc đã sẵn sàng đứng lên.","doc":6},{"loai":"anh","src":"textures/bang_w/G14_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hà Nội 1945 – Ba Đình”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hòa để tiến","text":"Để không phải cùng lúc đối đầu với nhiều kẻ thù, Chủ tịch Hồ Chí Minh chủ trương những bước hòa hoãn có nguyên tắc. Trong những tháng cuối năm 1945, Chính phủ tạm thời nhân nhượng quân Tưởng một số quyền lợi, chấp nhận mở rộng Chính phủ và dành thêm ghế trong Quốc hội cho các đảng phái thân Tưởng. Nhờ vậy, cả nước có thể dồn sức chống thực dân Pháp ở Nam Bộ. Ngày 1/1/1946, Chính phủ liên hiệp lâm thời ra mắt. Nhưng khi Pháp và Tưởng thỏa thuận với nhau để quân Pháp ra Bắc thay quân Tưởng, tình thế đổi khác. Ngày 6/3/1946, Người ký với đại diện Pháp bản Hiệp định Sơ bộ, chọn hòa với Pháp để quân Tưởng phải rút về nước và có thêm thời gian xây dựng lực lượng (xem chuyên đề Hiệp định Sơ bộ).\n\nCuối tháng 5/1946, Người lên đường sang Pháp. Suốt hơn bốn tháng xa Tổ quốc, Người vừa theo dõi cuộc đàm phán ở Fontainebleau, vừa gặp gỡ kiều bào, trí thức và báo chí Pháp (xem chuyên đề Bốn tháng trên đất Pháp). Khi đàm phán bế tắc, ngày 14/9/1946, Người ký bản Tạm ước, cố giữ lấy từng ngày hòa bình cho đất nước. Ngày 20/10, Người về tới Hải Phòng; ít tuần sau, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_sainteny_agreement_march_6_1946.jpg","chu_thich":"Lễ ký Hiệp định Sơ bộ Việt – Pháp tại Hà Nội ngày 6/3/1946, một bước hòa hoãn để quân Tưởng phải rút về nước.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Ngày 28/2/1946, Pháp và Trung Hoa Dân quốc ký hiệp ước ở Trùng Khánh. Theo đó, Pháp trả lại các tô giới của mình trên đất Trung Quốc và nhượng một số quyền lợi ở Việt Nam, đổi lại quân Pháp được ra miền Bắc thay quân Tưởng. Hiệp định Sơ bộ 6/3/1946 ra đời trong thế buộc phải lựa chọn ấy.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử; Lịch sử Đảng Cộng sản Việt Nam","doc":8},{"loai":"doan","tieu_de":"Đêm 19/12/1946","text":"Hòa hoãn không ngăn được dã tâm của những kẻ muốn đặt lại ách thống trị. Ngày 20/11/1946, quân Pháp gây hấn ở Hải Phòng và Lạng Sơn. Sang tháng 12, chúng liên tiếp khiêu khích ngay giữa Hà Nội, rồi gửi tối hậu thư đòi tước vũ khí của lực lượng tự vệ Thủ đô. Từ đầu tháng ấy, Chủ tịch Hồ Chí Minh đã rời Bắc Bộ phủ về ở và làm việc tại làng Vạn Phúc, Hà Đông. Tại đây, trong đêm 19/12/1946, khi tiếng súng bảo vệ Thủ đô đã nổ khắp các phố phường, Người ra Lời kêu gọi toàn quốc kháng chiến. Diễn biến từng ngày của những tuần cuối cùng ấy được ghi lại trong chuyên đề Mốc thời gian.\n\nCó một vòng tròn lịch sử trong mười sáu tháng ấy. Hà Nội, nơi khai sinh nền độc lập chiều 2/9/1945, cũng là nơi tiếng súng kháng chiến toàn quốc mở đầu đêm 19/12/1946. Người dân Thủ đô từng hô vang lời thề độc lập ở Ba Đình; giờ đây, họ giữ lời thề ấy bằng những chiến lũy dựng giữa phố phường. Lời kêu gọi của Người vang lên như tiếng nói chung của cả dân tộc.","doc":9},{"loai":"trich","text":"Hỡi đồng bào toàn quốc! Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.","nguoi":"Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, 19/12/1946","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":10},{"loai":"doan","tieu_de":"Đi trong gian trưng bày","text":"Gian trưng bày dựng lại hai địa điểm tiêu biểu nhất của mười sáu tháng ấy. Ở một đầu là phố Hàng Ngang giữa khu phố cổ, với ngôi nhà số 48 mà căn phòng trên gác hai được phục dựng. Trong phòng có bàn viết, ghế tựa, đèn bàn, tủ sách, những đồ vật gợi lại không khí của những ngày viết Tuyên ngôn. Ở đầu kia là Quảng trường Ba Đình chiều 2/9/1945, với lễ đài khung gỗ, cột cờ, dinh Toàn quyền cũ và biển người. Trên thực tế, hai nơi cách nhau khoảng hai cây số; trong không gian ba chiều, chúng được nối bằng một đoạn đại lộ để bạn có thể đi bộ theo hành trình của bản Tuyên ngôn.\n\nDọc hành trình ấy là các bảng chuyên đề. Có những bảng kể về một ngày, một khoảnh khắc: buổi lễ ở Ba Đình, chữ ký ngày 6/3/1946. Có những bảng kể về cả một phong trào của nhân dân: Tuần lễ Vàng, Bình dân học vụ, chống giặc đói, lá phiếu đầu tiên. Có những bảng dừng lại trước một tấm ảnh tư liệu hay một câu nói của Người. Bảng Mốc thời gian giúp bạn đặt tất cả vào một dòng chảy chung. Bấm vào các đồ vật trong căn phòng Hàng Ngang, bạn sẽ nghe những câu chuyện nhỏ gắn với sự thật lịch sử; những đồ vật dựng để minh họa đều được ghi rõ là minh họa.","doc":11},{"loai":"anh","src":"textures/bang_w/G14_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hà Nội 1945 – Ba Đình”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hai địa chỉ hôm nay","text":"Hai địa điểm dựng trong gian trưng bày đều còn giữa lòng Hà Nội. Ngôi nhà số 48 Hàng Ngang nay là di tích lịch sử, đón khách lên thăm căn phòng nơi bản Tuyên ngôn được soạn thảo (xem chuyên đề Số 48 Hàng Ngang hôm nay). Quảng trường Ba Đình vẫn là trái tim chính trị của cả nước; bên quảng trường là Lăng Chủ tịch Hồ Chí Minh. Từ phố cổ đi về phía tây chừng hai cây số, qua những con phố rợp bóng cây, bạn sẽ đi lại quãng đường của bản Tuyên ngôn năm ấy. Đó là quãng đường từ trang bản thảo trên căn gác nhỏ đến giọng đọc vang lên trước hàng chục vạn đồng bào.\n\nMười sáu tháng ở Hà Nội khép lại bằng tiếng súng, nhưng những gì được dựng nên trong mười sáu tháng ấy không mất đi. Chính phủ, Quốc hội, Hiến pháp, những lớp học tối, những quỹ góp của góp công và khối đoàn kết toàn dân đã theo Người lên chiến khu, trở thành nền móng cho chín năm kháng chiến trường kỳ. Vì thế, gian trưng bày này không chỉ kể về một ngày Độc lập, mà về cả một năm rưỡi gian nan để giữ gìn nền độc lập ấy.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, 3/9/1945; Lời kêu gọi toàn quốc kháng chiến, 19/12/1946)","Võ Nguyên Giáp, Những năm tháng không thể nào quên, NXB Quân đội nhân dân","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh; Di tích 48 Hàng Ngang, Hà Nội"],"doc":[{"t":"Hà Nội 1945–1946: mười sáu tháng giữ một nền độc lập. Cuối tháng Tám năm 1945, một vị khách gầy gò từ chiến khu Việt Bắc lặng lẽ bước lên căn gác của một hiệu lụa trên phố Hàng Ngang. Một tuần sau, hàng chục vạn người lần đầu được nghe giọng nói của Người ở Quảng trường Ba Đình. Rồi suốt mười sáu tháng tiếp theo, nhà nước vừa ra đời phải cùng lúc chống giặc đói, giặc dốt và giặc ngoại xâm. Gian trưng bày này mời bạn bước vào chính những tháng ngày ấy."},{"t":"Vị khách về từ chiến khu. Ngày 22/8/1945, Chủ tịch Hồ Chí Minh rời Tân Trào về xuôi. Người vừa qua một trận ốm nặng ở chiến khu, sức khỏe còn yếu, nhưng tin tức dồn dập từ khắp nơi không cho phép chậm trễ. Cuộc Tổng khởi nghĩa đang lan rộng, Hà Nội đã giành chính quyền từ ngày 19/8, Huế và Sài Gòn cũng đang sục sôi. Sau mấy ngày dừng chân ở làng Phú Gia ven Hồ Tây, ngày 25/8/1945, Người vào nội thành, ở tại căn gác hai nhà số 48 Hàng Ngang, cửa hiệu tơ lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô. Người dân phố cổ khi ấy không biết vị khách gầy gò ấy là ai. Ngay cả nhiều người đã nghe đến cái tên Hồ Chí Minh cũng chưa biết rằng đó chính là Nguyễn Ái Quốc, cái tên đã gắn với phong trào giải phóng dân tộc suốt hơn hai mươi năm. Hà Nội những ngày ấy rợp cờ đỏ sao vàng, các ngả phố vang tiếng hát, nhưng quân Nhật vẫn còn đóng trong thành phố, còn những đạo quân nước ngoài khác đang chuẩn bị kéo vào từ hai đầu đất nước. Niềm vui và nỗi lo đan vào nhau trong từng ngày của mùa thu năm ấy. Và căn gác nhỏ giữa khu phố buôn bán sầm uất bỗng trở thành nơi làm việc của người sắp đứng đầu một nhà nước mới."},{"t":"Tám ngày, từ căn gác ra quảng trường. Tám ngày trên căn gác Hàng Ngang là tám ngày làm việc không nghỉ. Ngày 26/8, ngay tại ngôi nhà này, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng. Cuộc họp quyết định chuẩn bị bản Tuyên ngôn Độc lập, tổ chức lễ ra mắt Chính phủ lâm thời và mở rộng thành phần Chính phủ để đoàn kết mọi lực lượng yêu nước. Ngày 28/8, danh sách Chính phủ lâm thời được công bố; bên cạnh những chiến sĩ cách mạng có nhiều nhân sĩ, trí thức không đảng phái. Cũng trong hai ngày 28 và 29/8, Người soạn thảo bản Tuyên ngôn Độc lập. Ngày 30/8 ở Huế, vua Bảo Đại thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời. Chiều Chủ nhật 2/9/1945, tại vườn hoa Ba Đình, trước hàng chục vạn đồng bào, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Những gì diễn ra hôm ấy, từ lễ đài dựng gấp trong ít ngày, câu hỏi “Tôi nói, đồng bào nghe rõ không?”, đến lời thề của Chính phủ và của cả quảng trường, được kể lại trong các chuyên đề riêng của gian này. Ở đây, chỉ cần nhớ một điều: chỉ tám ngày tách buổi chiều lịch sử ấy với ngày Người đặt chân lên căn gác nhỏ."},{"t":"“Ngàn cân treo sợi tóc”. Niềm vui Độc lập chưa trọn một tháng thì những hiểm họa đã hiện rõ. Nạn đói năm Ất Dậu vừa cướp đi sinh mạng hơn hai triệu đồng bào từ Quảng Trị trở ra, như chính bản Tuyên ngôn đã nêu, và lũ lụt, vỡ đê năm ấy khiến nguy cơ một nạn đói mới luôn rình rập. Hơn chín mươi phần trăm dân số không biết chữ. Ngân khố quốc gia gần như trống rỗng, còn Ngân hàng Đông Dương, nơi nắm quyền phát hành giấy bạc, vẫn nằm trong tay tư bản Pháp. Theo thỏa thuận của các nước Đồng minh, quân đội nước ngoài vào Việt Nam giải giáp quân Nhật, lấy vĩ tuyến 16 làm ranh giới. Ở phía bắc, khoảng hai mươi vạn quân Tưởng Giới Thạch kéo vào, kéo theo các tổ chức người Việt thân Tưởng ra sức chống phá chính quyền. Ở phía nam, quân Anh vào và mở đường cho thực dân Pháp; ngày 23/9/1945, Pháp nổ súng đánh chiếm Sài Gòn, cuộc kháng chiến ở Nam Bộ bùng nổ. Trên đất nước khi ấy vẫn còn hàng vạn quân Nhật chờ giải giáp. Lịch sử gọi hoàn cảnh ấy bằng một hình ảnh: vận mệnh dân tộc như “ngàn cân treo sợi tóc”. Chính quyền mới phải cùng lúc đương đầu với ba thứ giặc mà Chủ tịch Hồ Chí Minh thường gọi tên: giặc đói, giặc dốt và giặc ngoại xâm."},{"t":"Sáu nhiệm vụ cấp bách. Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ. Người nêu sáu nhiệm vụ cấp bách. Ba nhiệm vụ đầu là phát động tăng gia sản xuất để chống đói, mở chiến dịch chống nạn mù chữ, tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu. Ba nhiệm vụ tiếp theo là giáo dục nhân dân tinh thần cần, kiệm, liêm, chính; bỏ ngay thuế thân, thuế chợ, thuế đò và tuyệt đối cấm hút thuốc phiện; tuyên bố tự do tín ngưỡng, lương giáo đoàn kết. Đọc lại danh sách ấy hôm nay, người ta thấy một cách nhìn rất rõ ràng. Cứu đói là giữ lấy sinh mạng của dân. Chống mù chữ là trao cho dân công cụ để hiểu quyền lợi và bổn phận của mình. Tổng tuyển cử là để chính quyền có nền tảng pháp lý vững chắc trước quốc dân và thế giới. Bỏ những thứ thuế bất công, cấm thuốc phiện là xóa đi những dấu vết nặng nề nhất của chế độ cũ. Đoàn kết lương giáo là giữ lấy khối đoàn kết toàn dân. Mỗi nhiệm vụ về sau đều trở thành một phong trào của cả nước; các chuyên đề trong gian này kể riêng về cuộc chiến chống giặc đói, phong trào Bình dân học vụ, Tuần lễ Vàng và cuộc Tổng tuyển cử ngày 6/1/1946."},{"t":"Bạn có biết? Ngày 11/11/1945, để tránh mũi nhọn tấn công của kẻ thù và các thế lực chống đối, Đảng Cộng sản Đông Dương ra thông cáo “tự giải tán”. Thực chất Đảng rút vào hoạt động bí mật và tiếp tục lãnh đạo chính quyền, lãnh đạo cách mạng."},{"t":"Một chính quyền của toàn dân. Muốn giữ được độc lập trong vòng vây ấy, Chủ tịch Hồ Chí Minh đặt lên hàng đầu khối đoàn kết toàn dân. Cựu hoàng Bảo Đại, nay là công dân Vĩnh Thụy, được mời làm Cố vấn tối cao của Chính phủ. Nhiều nhà nho, nhà khoa bảng, trí thức không đảng phái được mời gánh vác việc nước; trong số đó có cụ Huỳnh Thúc Kháng, người về sau giữ quyền Chủ tịch nước khi Người sang Pháp. Giới công thương được Người gửi thư riêng, khuyến khích họ góp sức xây dựng nền kinh tế nước nhà. Ngày 29/5/1946, Hội Liên hiệp quốc dân Việt Nam ra đời, mở rộng khối đoàn kết ra ngoài khuôn khổ Mặt trận Việt Minh. Chính khối đoàn kết ấy làm nên những phong trào mà gian trưng bày này kể lại. Người giàu góp vàng, người nghèo góp gạo, người biết chữ dạy người chưa biết chữ; người già, người trẻ, nam và nữ cùng đi bỏ phiếu. Nhà nước mới không có ngân khố dồi dào, không có quân đội hiện đại, chưa được một quốc gia nào công nhận, nhưng có một thứ tài sản mà mọi đối thủ đều phải kiêng nể: lòng tin của nhân dân. Mười sáu tháng ở Hà Nội cũng là mười sáu tháng Người vun đắp tài sản ấy, để khi tiếng súng kháng chiến nổ ra, cả dân tộc đã sẵn sàng đứng lên."},{"t":"Hòa để tiến. Để không phải cùng lúc đối đầu với nhiều kẻ thù, Chủ tịch Hồ Chí Minh chủ trương những bước hòa hoãn có nguyên tắc. Trong những tháng cuối năm 1945, Chính phủ tạm thời nhân nhượng quân Tưởng một số quyền lợi, chấp nhận mở rộng Chính phủ và dành thêm ghế trong Quốc hội cho các đảng phái thân Tưởng. Nhờ vậy, cả nước có thể dồn sức chống thực dân Pháp ở Nam Bộ. Ngày 1/1/1946, Chính phủ liên hiệp lâm thời ra mắt. Nhưng khi Pháp và Tưởng thỏa thuận với nhau để quân Pháp ra Bắc thay quân Tưởng, tình thế đổi khác. Ngày 6/3/1946, Người ký với đại diện Pháp bản Hiệp định Sơ bộ, chọn hòa với Pháp để quân Tưởng phải rút về nước và có thêm thời gian xây dựng lực lượng (xem chuyên đề Hiệp định Sơ bộ). Cuối tháng 5/1946, Người lên đường sang Pháp. Suốt hơn bốn tháng xa Tổ quốc, Người vừa theo dõi cuộc đàm phán ở Fontainebleau, vừa gặp gỡ kiều bào, trí thức và báo chí Pháp (xem chuyên đề Bốn tháng trên đất Pháp). Khi đàm phán bế tắc, ngày 14/9/1946, Người ký bản Tạm ước, cố giữ lấy từng ngày hòa bình cho đất nước. Ngày 20/10, Người về tới Hải Phòng; ít tuần sau, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa."},{"t":"Bạn có biết? Ngày 28/2/1946, Pháp và Trung Hoa Dân quốc ký hiệp ước ở Trùng Khánh. Theo đó, Pháp trả lại các tô giới của mình trên đất Trung Quốc và nhượng một số quyền lợi ở Việt Nam, đổi lại quân Pháp được ra miền Bắc thay quân Tưởng. Hiệp định Sơ bộ 6/3/1946 ra đời trong thế buộc phải lựa chọn ấy."},{"t":"Đêm 19/12/1946. Hòa hoãn không ngăn được dã tâm của những kẻ muốn đặt lại ách thống trị. Ngày 20/11/1946, quân Pháp gây hấn ở Hải Phòng và Lạng Sơn. Sang tháng 12, chúng liên tiếp khiêu khích ngay giữa Hà Nội, rồi gửi tối hậu thư đòi tước vũ khí của lực lượng tự vệ Thủ đô. Từ đầu tháng ấy, Chủ tịch Hồ Chí Minh đã rời Bắc Bộ phủ về ở và làm việc tại làng Vạn Phúc, Hà Đông. Tại đây, trong đêm 19/12/1946, khi tiếng súng bảo vệ Thủ đô đã nổ khắp các phố phường, Người ra Lời kêu gọi toàn quốc kháng chiến. Diễn biến từng ngày của những tuần cuối cùng ấy được ghi lại trong chuyên đề Mốc thời gian. Có một vòng tròn lịch sử trong mười sáu tháng ấy. Hà Nội, nơi khai sinh nền độc lập chiều 2/9/1945, cũng là nơi tiếng súng kháng chiến toàn quốc mở đầu đêm 19/12/1946. Người dân Thủ đô từng hô vang lời thề độc lập ở Ba Đình; giờ đây, họ giữ lời thề ấy bằng những chiến lũy dựng giữa phố phường. Lời kêu gọi của Người vang lên như tiếng nói chung của cả dân tộc."},{"t":"Hỡi đồng bào toàn quốc! Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ. — Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, 19/12/1946"},{"t":"Đi trong gian trưng bày. Gian trưng bày dựng lại hai địa điểm tiêu biểu nhất của mười sáu tháng ấy. Ở một đầu là phố Hàng Ngang giữa khu phố cổ, với ngôi nhà số 48 mà căn phòng trên gác hai được phục dựng. Trong phòng có bàn viết, ghế tựa, đèn bàn, tủ sách, những đồ vật gợi lại không khí của những ngày viết Tuyên ngôn. Ở đầu kia là Quảng trường Ba Đình chiều 2/9/1945, với lễ đài khung gỗ, cột cờ, dinh Toàn quyền cũ và biển người. Trên thực tế, hai nơi cách nhau khoảng hai cây số; trong không gian ba chiều, chúng được nối bằng một đoạn đại lộ để bạn có thể đi bộ theo hành trình của bản Tuyên ngôn. Dọc hành trình ấy là các bảng chuyên đề. Có những bảng kể về một ngày, một khoảnh khắc: buổi lễ ở Ba Đình, chữ ký ngày 6/3/1946. Có những bảng kể về cả một phong trào của nhân dân: Tuần lễ Vàng, Bình dân học vụ, chống giặc đói, lá phiếu đầu tiên. Có những bảng dừng lại trước một tấm ảnh tư liệu hay một câu nói của Người. Bảng Mốc thời gian giúp bạn đặt tất cả vào một dòng chảy chung. Bấm vào các đồ vật trong căn phòng Hàng Ngang, bạn sẽ nghe những câu chuyện nhỏ gắn với sự thật lịch sử; những đồ vật dựng để minh họa đều được ghi rõ là minh họa."},{"t":"Hai địa chỉ hôm nay. Hai địa điểm dựng trong gian trưng bày đều còn giữa lòng Hà Nội. Ngôi nhà số 48 Hàng Ngang nay là di tích lịch sử, đón khách lên thăm căn phòng nơi bản Tuyên ngôn được soạn thảo (xem chuyên đề Số 48 Hàng Ngang hôm nay). Quảng trường Ba Đình vẫn là trái tim chính trị của cả nước; bên quảng trường là Lăng Chủ tịch Hồ Chí Minh. Từ phố cổ đi về phía tây chừng hai cây số, qua những con phố rợp bóng cây, bạn sẽ đi lại quãng đường của bản Tuyên ngôn năm ấy. Đó là quãng đường từ trang bản thảo trên căn gác nhỏ đến giọng đọc vang lên trước hàng chục vạn đồng bào. Mười sáu tháng ở Hà Nội khép lại bằng tiếng súng, nhưng những gì được dựng nên trong mười sáu tháng ấy không mất đi. Chính phủ, Quốc hội, Hiến pháp, những lớp học tối, những quỹ góp của góp công và khối đoàn kết toàn dân đã theo Người lên chiến khu, trở thành nền móng cho chín năm kháng chiến trường kỳ. Vì thế, gian trưng bày này không chỉ kể về một ngày Độc lập, mà về cả một năm rưỡi gian nan để giữ gìn nền độc lập ấy."}],"so_chu":2379},{"i":1,"tieu_de_bang":"Tuần lễ Vàng: cả nước góp vàng giữ độc lập","tieu_de":"Tuần lễ Vàng: ngân khố quốc gia từ những chiếc nhẫn, đôi hoa tai","sapo":"Nhà nước mới ra đời với một ngân khố gần như trống rỗng. Vậy mà chỉ trong một tuần của tháng 9/1945, từ những gia đình buôn bán khá giả trên phố Hàng Ngang đến những người dân nghèo ở thôn quê, đồng bào cả nước đã góp nên hàng trăm kilôgam vàng. Điều gì khiến người ta trao chiếc nhẫn, đôi hoa tai của mình cho một chính phủ ra đời chưa đầy một tháng?","bia":{"src":"textures/bai/G14_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Chiếc két bạc của một nhà nước mới","text":"Con số kiểm kê kho bạc mà chính quyền cách mạng tiếp quản cuối tháng 8/1945 nói lên tất cả. Toàn bộ ngân quỹ chỉ còn hơn 1,2 triệu đồng bạc Đông Dương, trong đó gần một nửa là tiền rách, không thể lưu hành. Không có dự trữ vàng, không có ngoại tệ. Ngân hàng Đông Dương, cơ quan nắm quyền phát hành giấy bạc suốt thời thuộc địa, vẫn do tư bản Pháp kiểm soát và không phục vụ chính quyền mới.\n\nTrong khi đó, những khoản phải chi dồn đến từng ngày. Phải có tiền nuôi các đơn vị Giải phóng quân và tự vệ đang lớn lên nhanh chóng, mua sắm vũ khí, trang bị. Phải có gạo cứu những vùng vừa qua nạn đói năm Ất Dậu. Phải duy trì bộ máy chính quyền từ trung ương đến làng xã. Rồi khi khoảng hai mươi vạn quân Tưởng kéo vào miền Bắc, chúng tung ra tiền “quan kim”, “quốc tệ” đã mất giá, buộc chính quyền phải chấp nhận cho lưu hành, làm rối loạn thị trường, vật giá leo thang. Chính quyền non trẻ đứng trước nguy cơ bị bóp nghẹt không chỉ bằng súng đạn, mà bằng chính chiếc két bạc gần như trống không của mình.","doc":1},{"loai":"trich","text":"Chúng giữ độc quyền in giấy bạc, xuất cảng và nhập cảng. Chúng đặt ra hàng trăm thứ thuế vô lý, làm cho dân ta, nhất là dân cày và dân buôn trở nên bần cùng.","nguoi":"Hồ Chí Minh, Tuyên ngôn Độc lập, 2/9/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":2},{"loai":"doan","tieu_de":"Hai ngày sau Tuyên ngôn: Quỹ Độc lập","text":"Những dòng cáo trạng ấy vừa vang lên ở Ba Đình thì chỉ hai ngày sau, ngày 4/9/1945, Chủ tịch Hồ Chí Minh ký Sắc lệnh số 4 thành lập Quỹ Độc lập. Quỹ nhận tiền, vàng và đồ vật quý do nhân dân tự nguyện đóng góp để ủng hộ Chính phủ. Tên gọi của quỹ đã nói hết mục đích: đây không phải một thứ thuế mới, cũng không phải lệnh trưng thu, mà là lời mời mỗi người dân tự tay góp phần giữ lấy nền độc lập vừa giành được.\n\nLựa chọn ấy có lý do sâu xa. Suốt hơn tám mươi năm thuộc địa, người dân chỉ biết đến chính quyền qua thuế thân, thuế chợ, thuế đò và những đợt thu vét. Một nhà nước tự nhận là của dân không thể mở đầu bằng việc cưỡng ép dân. Ngay trong tháng 9/1945, Chính phủ tuyên bố bỏ thuế thân, thứ thuế đánh lên đầu người bị căm ghét nhất thời Pháp thuộc. Nguồn thu giảm đi trong khi nhu cầu chi tăng vọt, nên con đường khả dĩ nhất là dựa vào lòng tự nguyện của nhân dân. Nhưng cần một đợt vận động lớn hơn, nhanh hơn, có sức lay động cả nước. Đó là Tuần lễ Vàng.","doc":3},{"loai":"anh","src":"textures/bang_w/G14_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tuần lễ Vàng: cả nước góp vàng giữ độc lập”, nhìn từ xa."},{"loai":"doan","tieu_de":"Thư của vị Chủ tịch gửi đồng bào","text":"Tuần lễ Vàng được tổ chức từ ngày 17 đến ngày 24/9/1945. Trong thư kêu gọi đồng bào hưởng ứng, Chủ tịch Hồ Chí Minh giải thích bằng những lời lẽ giản dị mà thẳng thắn. Muốn củng cố nền độc lập, chống nạn xâm lăng thì phải có sức mạnh. Tuần lễ Vàng sẽ thu góp số vàng trong nhân dân, nhất là của những nhà giàu có, để dùng vào việc cần cấp và quan trọng nhất lúc bấy giờ là quốc phòng. Người không hứa hẹn điều gì xa xôi. Người chỉ nói rõ vàng sẽ được dùng vào đâu và vì sao phải góp ngay lúc này.\n\nLời kêu gọi ấy như sự tiếp nối trực tiếp câu kết của bản Tuyên ngôn đọc ở Ba Đình hai tuần trước. Câu kết ấy viết rằng toàn thể dân tộc quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập (xem chuyên đề Lời Bác). Nếu “tính mạng” sẽ còn được thử thách trên chiến trường, thì “của cải” được thử thách trước tiên, bằng chính Tuần lễ Vàng. Và lịch sử đã đặt một sự trùng hợp nghiệt ngã vào giữa tuần lễ ấy: ngày 23/9/1945, thực dân Pháp nổ súng đánh chiếm Sài Gòn. Chữ “quốc phòng” trong thư của Người không còn là một lời dự báo, mà đã thành việc của từng ngày.","doc":4},{"loai":"doan","tieu_de":"Vì sao lại là vàng?","text":"Giữa lúc tiền tệ hỗn loạn, đồng bạc Đông Dương nằm trong tay ngân hàng của người Pháp, tiền “quan kim” của quân Tưởng mất giá từng ngày, vàng là thứ tài sản duy nhất giữ được giá trị. Với người Việt thời ấy, vàng cũng là hình thức để dành quen thuộc nhất: chiếc nhẫn cưới, đôi hoa tai của con gái, chiếc kiềng, chiếc vòng là của hồi môn, là vốn liếng dành cho lúc ốm đau, hoạn nạn. Góp vàng vì thế không phải góp phần dư thừa, mà nhiều khi là góp phần dành dụm quý giá nhất của cả một gia đình.\n\nVới nhà nước, vàng có sức mạnh mà giấy bạc thời ấy không có. Vàng có thể dùng để mua vũ khí, thuốc men, những thứ không thể trả bằng đồng tiền đang mất giá. Vàng là chỗ dựa để về sau nhà nước có thể phát hành đồng tiền của chính mình, thoát khỏi sự lệ thuộc vào Ngân hàng Đông Dương. Hiểu điều đó, Tuần lễ Vàng không chỉ là một đợt quyên góp. Đó là bước đầu tiên để một quốc gia độc lập tự đứng vững về tài chính, trong hoàn cảnh không có một đồng viện trợ nào từ bên ngoài.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","chu_thich":"Phố Hàng Ngang (người Pháp gọi là rue des Cantonnais) đầu thế kỷ XX — con phố buôn bán sầm uất, nơi có hiệu lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một tuần của những tấm lòng","text":"Khắp các thành phố, thị xã, làng quê, các ban vận động Tuần lễ Vàng được lập ra. Người giàu góp nhiều, người nghèo góp ít. Có người tháo chiếc nhẫn đang đeo trên tay, có người góp đôi hoa tai, chiếc vòng, có người mang đến những kỷ vật đã cất giữ qua mấy thế hệ. Những người không có vàng thì góp tiền, góp bạc, góp những gì mình có. Ở Hà Nội, nhiều nhà công thương hưởng ứng mạnh mẽ; các đoàn thể phụ nữ, thanh niên đi vận động từng khu phố.\n\nTinh thần tự nguyện là nét nổi bật nhất. Người ta góp vì hiểu rằng số vàng hôm nay là để giữ lấy nền độc lập mà chính mình vừa tự tay giành lại, là để con cháu không phải sống lại những ngày thuộc địa. Trong không khí sôi nổi ấy, lòng yêu nước được đo bằng những việc làm cụ thể, có thể cầm nắm được. Những đóng góp nhỏ bé của vô số người bình thường, cộng lại, đã trở thành nguồn lực đầu tiên của ngân khố quốc gia. Và cũng từ đây, nhiều người dân lần đầu tiên cảm thấy mình là chủ nhân thật sự của một đất nước, có quyền và có bổn phận với vận mệnh chung.","doc":6},{"loai":"doan","tieu_de":"Gia đình trên phố Hàng Ngang","text":"Trong số những tấm lòng ấy, câu chuyện của gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ được nhắc đến nhiều nhất. Chủ hiệu tơ lụa Phúc Lợi ở số 48 Hàng Ngang là một gia đình công thương có tiếng ở Hà Nội. Ngôi nhà của gia đình cũng là nơi Chủ tịch Hồ Chí Minh ở trong những ngày viết Tuyên ngôn Độc lập (xem chuyên đề Nhà số 48 Hàng Ngang). Từ trước Cách mạng, ông bà đã có cảm tình và ủng hộ Mặt trận Việt Minh. Khi chính quyền mới cần đến, gia đình không đắn đo.\n\nTheo các tư liệu được báo chí nhiều lần dẫn lại, tổng số vàng gia đình ông bà hiến cho cách mạng và chính quyền mới lên tới 5.147 lạng, một con số hiếm có. Bên cạnh vàng, gia đình còn góp tiền, góp vải vóc, quần áo cho cán bộ. Tấm gương ấy giúp lan tỏa niềm tin trong giới công thương: những người buôn bán hiểu rằng chính quyền mới cần họ, trân trọng họ, và nền độc lập cũng là điều kiện để việc làm ăn chân chính được yên ổn, phát đạt. Một gia đình thương nhân đã đặt trọn niềm tin vào vị Chủ tịch từng ở trên căn gác nhà mình.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_memorial_in_honour_of_ho_chi_minh_in_the_hanoi_o.jpg","chu_thich":"Di tích nhà số 48 Hàng Ngang trong phố cổ Hà Nội ngày nay (ảnh năm 2016, giấy phép CC BY 2.0).","credit":"Ảnh: shankar s. from Dubai, united arab emira · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"370 kilôgam vàng","text":"Qua Quỹ Độc lập và Tuần lễ Vàng, nhân dân cả nước đã đóng góp được 370 kilôgam vàng và 20 triệu đồng. Với một nhà nước bắt đầu từ ngân quỹ hơn một triệu đồng, trong đó gần nửa là tiền rách, đó là một bước ngoặt. Con số ấy càng đáng quý khi nhớ rằng người đóng góp vừa đi qua nạn đói khủng khiếp nhất trong lịch sử cận đại, nhiều vùng vẫn đang thiếu ăn, và ở miền Nam chiến tranh đã bùng nổ.\n\nNguồn lực ấy được dùng vào những việc cấp bách nhất: nuôi quân, mua sắm vũ khí, cứu đói và duy trì hoạt động của bộ máy nhà nước. Nhờ có nó, Chính phủ có thêm điều kiện để chuẩn bị một bước đi quan trọng khác: phát hành đồng tiền của chính mình. Năm 1946, giấy bạc Việt Nam in hình Chủ tịch Hồ Chí Minh bắt đầu được phát hành, được nhân dân quen gọi là “tiền Cụ Hồ”, từng bước thay thế đồng bạc của Ngân hàng Đông Dương. Từ chiếc két bạc gần như trống rỗng tháng 8/1945, nhà nước non trẻ đã có trong tay những công cụ đầu tiên của một nền tài chính độc lập.","doc":8},{"loai":"ban_co_biet","text":"Bên cạnh Quỹ Độc lập và Tuần lễ Vàng, Chính phủ còn phát động quyên góp cho “Quỹ Đảm phụ quốc phòng”; riêng quỹ này nhân dân đóng góp được khoảng 40 triệu đồng.","nguon_ten":"Lịch sử 12, NXB Giáo dục Việt Nam","doc":9},{"loai":"doan","tieu_de":"Một lá phiếu tín nhiệm bằng vàng","text":"Người ta có thể tính giá trị của 370 kilôgam vàng, nhưng khó tính được giá trị của điều làm nên con số ấy. Chính phủ lâm thời ra mắt quốc dân chưa đầy một tháng, chưa có Quốc hội, chưa có Hiến pháp, chưa được một nước nào công nhận. Vậy mà người dân sẵn lòng trao cho chính phủ ấy những tài sản quý nhất của gia đình. Có thể coi đó là một cuộc bỏ phiếu tín nhiệm diễn ra trước cả cuộc Tổng tuyển cử ngày 6/1/1946, với lá phiếu được viết bằng vàng, bằng tiền, bằng những kỷ vật.\n\nTuần lễ Vàng cũng cho thấy cách Chủ tịch Hồ Chí Minh nhìn nhận các tầng lớp trong xã hội. Người không coi những người giàu có là đối tượng phải e dè, mà mời họ cùng gánh vác việc nước và công khai ghi nhận công lao của họ. Ngày 13/10/1945, Người gửi thư cho giới công thương, nhắc rằng “việc nước và việc nhà bao giờ cũng đi đôi với nhau”, khuyến khích họ góp sức xây dựng một nền kinh tế, tài chính vững vàng và thịnh vượng. Khối đại đoàn kết toàn dân tộc mà Người luôn đặt lên hàng đầu, qua Tuần lễ Vàng, đã hiện ra thành những hiện vật có thể cân, đong, đếm được.","doc":10},{"loai":"anh","src":"textures/bang_w/G14_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tuần lễ Vàng: cả nước góp vàng giữ độc lập”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngôi nhà số 48 Hàng Ngang, nơi gia đình ông bà Trịnh Văn Bô từng đón Chủ tịch Hồ Chí Minh, nay là di tích lịch sử giữa lòng phố cổ, vẫn mở cửa đón khách tham quan. Câu chuyện Tuần lễ Vàng và tấm lòng của giới công thương Hà Nội được nhắc lại mỗi dịp Quốc khánh, và mỗi ngày 13/10, khi cả nước tôn vinh đội ngũ doanh nhân. Trong gian trưng bày này, phố Hàng Ngang được dựng lại với những dãy nhà ống, cửa hiệu, gợi nhớ khung cảnh buôn bán sầm uất nơi một gia đình thương nhân đã đặt trọn niềm tin vào chính quyền mới.\n\nĐiều còn lại lâu bền nhất của Tuần lễ Vàng không nằm trong một tủ kính. Đó là một bài học được nhắc lại nhiều lần trong lịch sử dân tộc: khi nhà nước thật sự vì dân, dân sẵn lòng chia sẻ cả những gì quý giá nhất. Từ mùa thu 1945, những phong trào góp của, góp công cho kháng chiến còn tiếp nối suốt những năm dài sau đó, từ hũ gạo nuôi quân đến những chiếc xe đạp thồ trên đường ra mặt trận. Tất cả như bắt đầu từ một tuần của tháng Chín, khi chiếc két bạc của một nhà nước mới được lấp đầy bằng lòng tin.","doc":11},{"loai":"ban_co_biet","text":"Ngày 13/10 hằng năm được chọn làm Ngày Doanh nhân Việt Nam, bắt nguồn từ bức thư Chủ tịch Hồ Chí Minh gửi giới công thương ngày 13/10/1945, chỉ ba tuần sau Tuần lễ Vàng.","nguon_ten":"Quyết định của Thủ tướng Chính phủ về Ngày Doanh nhân Việt Nam (2004); Hồ Chí Minh Toàn tập, tập 4","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Tuyên ngôn Độc lập; Thư gửi giới công thương Việt Nam, 13/10/1945)","Báo Đại biểu Nhân dân, “Chuyện gia đình hiến tặng hơn 5.000 lượng vàng cho cách mạng” – https://daibieunhandan.vn/chuyen-gia-dinh-hien-tang-hon-5-000-luong-vang-cho-cach-mang-10193524.html","Lịch sử 12, NXB Giáo dục Việt Nam","Di tích 48 Hàng Ngang, Hà Nội; Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Tuần lễ Vàng: ngân khố quốc gia từ những chiếc nhẫn, đôi hoa tai. Nhà nước mới ra đời với một ngân khố gần như trống rỗng. Vậy mà chỉ trong một tuần của tháng 9/1945, từ những gia đình buôn bán khá giả trên phố Hàng Ngang đến những người dân nghèo ở thôn quê, đồng bào cả nước đã góp nên hàng trăm kilôgam vàng. Điều gì khiến người ta trao chiếc nhẫn, đôi hoa tai của mình cho một chính phủ ra đời chưa đầy một tháng?"},{"t":"Chiếc két bạc của một nhà nước mới. Con số kiểm kê kho bạc mà chính quyền cách mạng tiếp quản cuối tháng 8/1945 nói lên tất cả. Toàn bộ ngân quỹ chỉ còn hơn 1,2 triệu đồng bạc Đông Dương, trong đó gần một nửa là tiền rách, không thể lưu hành. Không có dự trữ vàng, không có ngoại tệ. Ngân hàng Đông Dương, cơ quan nắm quyền phát hành giấy bạc suốt thời thuộc địa, vẫn do tư bản Pháp kiểm soát và không phục vụ chính quyền mới. Trong khi đó, những khoản phải chi dồn đến từng ngày. Phải có tiền nuôi các đơn vị Giải phóng quân và tự vệ đang lớn lên nhanh chóng, mua sắm vũ khí, trang bị. Phải có gạo cứu những vùng vừa qua nạn đói năm Ất Dậu. Phải duy trì bộ máy chính quyền từ trung ương đến làng xã. Rồi khi khoảng hai mươi vạn quân Tưởng kéo vào miền Bắc, chúng tung ra tiền “quan kim”, “quốc tệ” đã mất giá, buộc chính quyền phải chấp nhận cho lưu hành, làm rối loạn thị trường, vật giá leo thang. Chính quyền non trẻ đứng trước nguy cơ bị bóp nghẹt không chỉ bằng súng đạn, mà bằng chính chiếc két bạc gần như trống không của mình."},{"t":"Chúng giữ độc quyền in giấy bạc, xuất cảng và nhập cảng. Chúng đặt ra hàng trăm thứ thuế vô lý, làm cho dân ta, nhất là dân cày và dân buôn trở nên bần cùng. — Hồ Chí Minh, Tuyên ngôn Độc lập, 2/9/1945"},{"t":"Hai ngày sau Tuyên ngôn: Quỹ Độc lập. Những dòng cáo trạng ấy vừa vang lên ở Ba Đình thì chỉ hai ngày sau, ngày 4/9/1945, Chủ tịch Hồ Chí Minh ký Sắc lệnh số 4 thành lập Quỹ Độc lập. Quỹ nhận tiền, vàng và đồ vật quý do nhân dân tự nguyện đóng góp để ủng hộ Chính phủ. Tên gọi của quỹ đã nói hết mục đích: đây không phải một thứ thuế mới, cũng không phải lệnh trưng thu, mà là lời mời mỗi người dân tự tay góp phần giữ lấy nền độc lập vừa giành được. Lựa chọn ấy có lý do sâu xa. Suốt hơn tám mươi năm thuộc địa, người dân chỉ biết đến chính quyền qua thuế thân, thuế chợ, thuế đò và những đợt thu vét. Một nhà nước tự nhận là của dân không thể mở đầu bằng việc cưỡng ép dân. Ngay trong tháng 9/1945, Chính phủ tuyên bố bỏ thuế thân, thứ thuế đánh lên đầu người bị căm ghét nhất thời Pháp thuộc. Nguồn thu giảm đi trong khi nhu cầu chi tăng vọt, nên con đường khả dĩ nhất là dựa vào lòng tự nguyện của nhân dân. Nhưng cần một đợt vận động lớn hơn, nhanh hơn, có sức lay động cả nước. Đó là Tuần lễ Vàng."},{"t":"Thư của vị Chủ tịch gửi đồng bào. Tuần lễ Vàng được tổ chức từ ngày 17 đến ngày 24/9/1945. Trong thư kêu gọi đồng bào hưởng ứng, Chủ tịch Hồ Chí Minh giải thích bằng những lời lẽ giản dị mà thẳng thắn. Muốn củng cố nền độc lập, chống nạn xâm lăng thì phải có sức mạnh. Tuần lễ Vàng sẽ thu góp số vàng trong nhân dân, nhất là của những nhà giàu có, để dùng vào việc cần cấp và quan trọng nhất lúc bấy giờ là quốc phòng. Người không hứa hẹn điều gì xa xôi. Người chỉ nói rõ vàng sẽ được dùng vào đâu và vì sao phải góp ngay lúc này. Lời kêu gọi ấy như sự tiếp nối trực tiếp câu kết của bản Tuyên ngôn đọc ở Ba Đình hai tuần trước. Câu kết ấy viết rằng toàn thể dân tộc quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập (xem chuyên đề Lời Bác). Nếu “tính mạng” sẽ còn được thử thách trên chiến trường, thì “của cải” được thử thách trước tiên, bằng chính Tuần lễ Vàng. Và lịch sử đã đặt một sự trùng hợp nghiệt ngã vào giữa tuần lễ ấy: ngày 23/9/1945, thực dân Pháp nổ súng đánh chiếm Sài Gòn. Chữ “quốc phòng” trong thư của Người không còn là một lời dự báo, mà đã thành việc của từng ngày."},{"t":"Vì sao lại là vàng?. Giữa lúc tiền tệ hỗn loạn, đồng bạc Đông Dương nằm trong tay ngân hàng của người Pháp, tiền “quan kim” của quân Tưởng mất giá từng ngày, vàng là thứ tài sản duy nhất giữ được giá trị. Với người Việt thời ấy, vàng cũng là hình thức để dành quen thuộc nhất: chiếc nhẫn cưới, đôi hoa tai của con gái, chiếc kiềng, chiếc vòng là của hồi môn, là vốn liếng dành cho lúc ốm đau, hoạn nạn. Góp vàng vì thế không phải góp phần dư thừa, mà nhiều khi là góp phần dành dụm quý giá nhất của cả một gia đình. Với nhà nước, vàng có sức mạnh mà giấy bạc thời ấy không có. Vàng có thể dùng để mua vũ khí, thuốc men, những thứ không thể trả bằng đồng tiền đang mất giá. Vàng là chỗ dựa để về sau nhà nước có thể phát hành đồng tiền của chính mình, thoát khỏi sự lệ thuộc vào Ngân hàng Đông Dương. Hiểu điều đó, Tuần lễ Vàng không chỉ là một đợt quyên góp. Đó là bước đầu tiên để một quốc gia độc lập tự đứng vững về tài chính, trong hoàn cảnh không có một đồng viện trợ nào từ bên ngoài."},{"t":"Một tuần của những tấm lòng. Khắp các thành phố, thị xã, làng quê, các ban vận động Tuần lễ Vàng được lập ra. Người giàu góp nhiều, người nghèo góp ít. Có người tháo chiếc nhẫn đang đeo trên tay, có người góp đôi hoa tai, chiếc vòng, có người mang đến những kỷ vật đã cất giữ qua mấy thế hệ. Những người không có vàng thì góp tiền, góp bạc, góp những gì mình có. Ở Hà Nội, nhiều nhà công thương hưởng ứng mạnh mẽ; các đoàn thể phụ nữ, thanh niên đi vận động từng khu phố. Tinh thần tự nguyện là nét nổi bật nhất. Người ta góp vì hiểu rằng số vàng hôm nay là để giữ lấy nền độc lập mà chính mình vừa tự tay giành lại, là để con cháu không phải sống lại những ngày thuộc địa. Trong không khí sôi nổi ấy, lòng yêu nước được đo bằng những việc làm cụ thể, có thể cầm nắm được. Những đóng góp nhỏ bé của vô số người bình thường, cộng lại, đã trở thành nguồn lực đầu tiên của ngân khố quốc gia. Và cũng từ đây, nhiều người dân lần đầu tiên cảm thấy mình là chủ nhân thật sự của một đất nước, có quyền và có bổn phận với vận mệnh chung."},{"t":"Gia đình trên phố Hàng Ngang. Trong số những tấm lòng ấy, câu chuyện của gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ được nhắc đến nhiều nhất. Chủ hiệu tơ lụa Phúc Lợi ở số 48 Hàng Ngang là một gia đình công thương có tiếng ở Hà Nội. Ngôi nhà của gia đình cũng là nơi Chủ tịch Hồ Chí Minh ở trong những ngày viết Tuyên ngôn Độc lập (xem chuyên đề Nhà số 48 Hàng Ngang). Từ trước Cách mạng, ông bà đã có cảm tình và ủng hộ Mặt trận Việt Minh. Khi chính quyền mới cần đến, gia đình không đắn đo. Theo các tư liệu được báo chí nhiều lần dẫn lại, tổng số vàng gia đình ông bà hiến cho cách mạng và chính quyền mới lên tới 5.147 lạng, một con số hiếm có. Bên cạnh vàng, gia đình còn góp tiền, góp vải vóc, quần áo cho cán bộ. Tấm gương ấy giúp lan tỏa niềm tin trong giới công thương: những người buôn bán hiểu rằng chính quyền mới cần họ, trân trọng họ, và nền độc lập cũng là điều kiện để việc làm ăn chân chính được yên ổn, phát đạt. Một gia đình thương nhân đã đặt trọn niềm tin vào vị Chủ tịch từng ở trên căn gác nhà mình."},{"t":"370 kilôgam vàng. Qua Quỹ Độc lập và Tuần lễ Vàng, nhân dân cả nước đã đóng góp được 370 kilôgam vàng và 20 triệu đồng. Với một nhà nước bắt đầu từ ngân quỹ hơn một triệu đồng, trong đó gần nửa là tiền rách, đó là một bước ngoặt. Con số ấy càng đáng quý khi nhớ rằng người đóng góp vừa đi qua nạn đói khủng khiếp nhất trong lịch sử cận đại, nhiều vùng vẫn đang thiếu ăn, và ở miền Nam chiến tranh đã bùng nổ. Nguồn lực ấy được dùng vào những việc cấp bách nhất: nuôi quân, mua sắm vũ khí, cứu đói và duy trì hoạt động của bộ máy nhà nước. Nhờ có nó, Chính phủ có thêm điều kiện để chuẩn bị một bước đi quan trọng khác: phát hành đồng tiền của chính mình. Năm 1946, giấy bạc Việt Nam in hình Chủ tịch Hồ Chí Minh bắt đầu được phát hành, được nhân dân quen gọi là “tiền Cụ Hồ”, từng bước thay thế đồng bạc của Ngân hàng Đông Dương. Từ chiếc két bạc gần như trống rỗng tháng 8/1945, nhà nước non trẻ đã có trong tay những công cụ đầu tiên của một nền tài chính độc lập."},{"t":"Bạn có biết? Bên cạnh Quỹ Độc lập và Tuần lễ Vàng, Chính phủ còn phát động quyên góp cho “Quỹ Đảm phụ quốc phòng”; riêng quỹ này nhân dân đóng góp được khoảng 40 triệu đồng."},{"t":"Một lá phiếu tín nhiệm bằng vàng. Người ta có thể tính giá trị của 370 kilôgam vàng, nhưng khó tính được giá trị của điều làm nên con số ấy. Chính phủ lâm thời ra mắt quốc dân chưa đầy một tháng, chưa có Quốc hội, chưa có Hiến pháp, chưa được một nước nào công nhận. Vậy mà người dân sẵn lòng trao cho chính phủ ấy những tài sản quý nhất của gia đình. Có thể coi đó là một cuộc bỏ phiếu tín nhiệm diễn ra trước cả cuộc Tổng tuyển cử ngày 6/1/1946, với lá phiếu được viết bằng vàng, bằng tiền, bằng những kỷ vật. Tuần lễ Vàng cũng cho thấy cách Chủ tịch Hồ Chí Minh nhìn nhận các tầng lớp trong xã hội. Người không coi những người giàu có là đối tượng phải e dè, mà mời họ cùng gánh vác việc nước và công khai ghi nhận công lao của họ. Ngày 13/10/1945, Người gửi thư cho giới công thương, nhắc rằng “việc nước và việc nhà bao giờ cũng đi đôi với nhau”, khuyến khích họ góp sức xây dựng một nền kinh tế, tài chính vững vàng và thịnh vượng. Khối đại đoàn kết toàn dân tộc mà Người luôn đặt lên hàng đầu, qua Tuần lễ Vàng, đã hiện ra thành những hiện vật có thể cân, đong, đếm được."},{"t":"Dấu tích hôm nay. Ngôi nhà số 48 Hàng Ngang, nơi gia đình ông bà Trịnh Văn Bô từng đón Chủ tịch Hồ Chí Minh, nay là di tích lịch sử giữa lòng phố cổ, vẫn mở cửa đón khách tham quan. Câu chuyện Tuần lễ Vàng và tấm lòng của giới công thương Hà Nội được nhắc lại mỗi dịp Quốc khánh, và mỗi ngày 13/10, khi cả nước tôn vinh đội ngũ doanh nhân. Trong gian trưng bày này, phố Hàng Ngang được dựng lại với những dãy nhà ống, cửa hiệu, gợi nhớ khung cảnh buôn bán sầm uất nơi một gia đình thương nhân đã đặt trọn niềm tin vào chính quyền mới. Điều còn lại lâu bền nhất của Tuần lễ Vàng không nằm trong một tủ kính. Đó là một bài học được nhắc lại nhiều lần trong lịch sử dân tộc: khi nhà nước thật sự vì dân, dân sẵn lòng chia sẻ cả những gì quý giá nhất. Từ mùa thu 1945, những phong trào góp của, góp công cho kháng chiến còn tiếp nối suốt những năm dài sau đó, từ hũ gạo nuôi quân đến những chiếc xe đạp thồ trên đường ra mặt trận. Tất cả như bắt đầu từ một tuần của tháng Chín, khi chiếc két bạc của một nhà nước mới được lấp đầy bằng lòng tin."},{"t":"Bạn có biết? Ngày 13/10 hằng năm được chọn làm Ngày Doanh nhân Việt Nam, bắt nguồn từ bức thư Chủ tịch Hồ Chí Minh gửi giới công thương ngày 13/10/1945, chỉ ba tuần sau Tuần lễ Vàng."}],"so_chu":2173},{"i":2,"tieu_de_bang":"Diệt giặc dốt: những lớp Bình dân học vụ","tieu_de":"“Vợ chưa biết thì chồng bảo”: cuộc chiến chống giặc dốt mùa thu 1945","sapo":"Năm 1945, cứ một trăm người Việt Nam thì chừng chín mươi lăm người không biết đọc, biết viết. Chỉ khoảng một năm sau, hai triệu rưỡi người đã tự tay viết được tên mình. Cuộc chiến chống “giặc dốt” ấy diễn ra gần như không có trường sở, không có ngân sách, mà trên lá chuối, dưới ánh đèn dầu, theo lời kêu gọi của một vị Chủ tịch.","bia":{"src":"textures/bai/G14_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Dấu điểm chỉ và những con số","text":"Trước năm 1945, ở nhiều làng quê Việt Nam, khi phải ký vào một tờ văn tự, một lá đơn hay một tờ biên nhận, phần đông người dân chỉ biết in dấu ngón tay thay cho chữ ký. Họ không đọc được điều mình vừa điểm chỉ. Tờ giấy ấy có thể là một món nợ, một lần cầm cố ruộng đất, một lời cam kết mà họ không hiểu hết. Mù chữ không chỉ là thiếu hiểu biết; nó biến người dân thành kẻ yếu thế trước bất cứ ai cầm trong tay tờ giấy có chữ.\n\nCác số liệu thống kê được nêu lại trong nhiều tài liệu về phong trào Bình dân học vụ cho thấy quy mô của thảm cảnh ấy. Trong một trăm người Việt Nam, chỉ khoảng ba em nhỏ từ tám đến mười sáu tuổi được đến trường, khoảng hai người lớn biết chữ, còn lại chừng chín mươi lăm người mù chữ. Phụ nữ gần như bị gạt hẳn ra khỏi con đường học vấn. Đó là di sản của hơn tám mươi năm thuộc địa mà nước Việt Nam Dân chủ Cộng hòa phải tiếp nhận ngay từ ngày đầu tiên, cùng lúc với nạn đói, ngân khố trống rỗng và quân đội nước ngoài trên đất nước.","doc":1},{"loai":"doan","tieu_de":"“Nhà tù nhiều hơn trường học”","text":"Bản Tuyên ngôn Độc lập đọc ở Ba Đình đã gọi đích danh căn nguyên của nạn mù chữ. Trong bản cáo trạng chế độ thực dân, Chủ tịch Hồ Chí Minh viết rằng chúng lập ra nhà tù nhiều hơn trường học, và chúng thi hành chính sách ngu dân. Chữ quốc ngữ tuy đã phổ biến trên sách báo từ đầu thế kỷ XX, nhưng với phần lớn nông dân và thợ thuyền, việc tự đọc một tờ báo vẫn là điều xa lạ.\n\nTrước Cách mạng, đã có những người trí thức yêu nước tìm cách thắp lên ánh sáng. Năm 1938, Hội Truyền bá quốc ngữ được thành lập ở Hà Nội, do học giả Nguyễn Văn Tố làm hội trưởng, mở các lớp học miễn phí cho người nghèo. Nhiều trí thức, sinh viên trẻ đã tình nguyện đứng lớp trong phong trào ấy, và họ trở thành lực lượng nòng cốt cho những lớp học sau này. Nhưng một hội đoàn hoạt động dưới sự kiểm soát của chính quyền thuộc địa không thể vươn tới hàng triệu người. Phải có một nhà nước của chính mình, việc xóa nạn mù chữ mới trở thành quốc sách. Và Chủ tịch Hồ Chí Minh đã không để việc ấy phải chờ lâu.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Diệt giặc dốt: những lớp Bình dân học vụ”, nhìn từ xa."},{"loai":"doan","tieu_de":"Nhiệm vụ thứ hai trong sáu nhiệm vụ","text":"Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, tại phiên họp đầu tiên của Chính phủ, Chủ tịch Hồ Chí Minh nêu sáu nhiệm vụ cấp bách của nhà nước mới. Nhiệm vụ thứ nhất là cứu đói. Ngay sau đó, ở vị trí thứ hai, là chống nạn mù chữ. Người đặt “giặc dốt” ngang hàng với giặc đói và giặc ngoại xâm, và đưa ra một nhận định đầy tin tưởng: chỉ cần ba tháng là đủ để học đọc, học viết tiếng nước ta theo vần quốc ngữ.\n\nNhận định ấy không phải lời cổ vũ suông. Chữ quốc ngữ ghi âm bằng mẫu tự La-tinh; học xong bảng chữ cái và cách ghép vần, người học có thể tự đánh vần những câu mình vẫn nói hằng ngày. Người muốn cả dân tộc hiểu rằng thoát nạn mù chữ là việc làm được, và làm được nhanh, nếu mọi người cùng bắt tay vào. Lời phát biểu hôm ấy trở thành tuyên ngôn của cả phong trào.","doc":3},{"loai":"trich","text":"Nạn dốt là một trong những phương pháp độc ác mà bọn thực dân dùng để cai trị chúng ta. Hơn chín mươi phần trăm đồng bào chúng ta mù chữ. Nhưng chỉ cần ba tháng là đủ để học đọc, học viết tiếng nước ta theo vần quốc ngữ. Một dân tộc dốt là một dân tộc yếu. Vì vậy, tôi đề nghị mở một chiến dịch để chống nạn mù chữ.","nguoi":"Hồ Chí Minh, phiên họp đầu tiên của Chính phủ, 3/9/1945","nguon_ten":"Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa — Hồ Chí Minh Toàn tập, tập 4","doc":4},{"loai":"doan","tieu_de":"Ba sắc lệnh ngày 8/9/1945","text":"Năm ngày sau, ngày 8/9/1945, Chủ tịch Hồ Chí Minh ký ba sắc lệnh về bình dân học vụ. Sắc lệnh thứ nhất lập Nha Bình dân học vụ, cơ quan chuyên trách việc dạy chữ cho người lớn, thuộc Bộ Quốc gia Giáo dục do ông Vũ Đình Hòe làm Bộ trưởng. Sắc lệnh thứ hai quy định mở các lớp học bình dân buổi tối cho nông dân và thợ thuyền: trong thời hạn sáu tháng, làng nào, thị trấn nào cũng phải có ít nhất một lớp học. Sắc lệnh thứ ba quy định việc học chữ quốc ngữ từ nay là bắt buộc và không mất tiền; hạn trong một năm, toàn thể dân chúng Việt Nam trên tám tuổi phải biết đọc, biết viết chữ quốc ngữ.\n\nĐó là một quyết định táo bạo. Theo tính toán thời ấy, phong trào cần hơn một trăm nghìn người dạy và khoảng 200 triệu đồng mỗi năm, trong khi ngân sách chỉ dành được khoảng 2 triệu đồng, lúc ngân khố gần như trống rỗng (xem chuyên đề Tuần lễ Vàng). Nhưng chính quyền mới hiểu rằng không thể chờ đủ tiền, đủ trường rồi mới dạy. Nhà nước không đủ sức thì phải dựa vào sức dân: mỗi người biết chữ sẽ là một người thầy, mỗi mái nhà có thể thành một lớp học.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_chinh_phu_lam_thoi.jpg","chu_thich":"Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa — chính phủ đã đưa việc chống nạn mù chữ vào sáu nhiệm vụ cấp bách ngay từ phiên họp đầu tiên.","credit":"Ảnh: Vietnam Government · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Lời kêu gọi “Chống nạn thất học”","text":"Tháng 10/1945, Chủ tịch Hồ Chí Minh ra lời kêu gọi “Chống nạn thất học”. Người mở đầu bằng việc nhắc lại chính sách ngu dân của thực dân. Rồi Người chỉ ra rằng muốn giữ vững nền độc lập, muốn làm cho dân mạnh nước giàu, mọi người Việt Nam phải hiểu biết quyền lợi và bổn phận của mình, phải có kiến thức mới để tham gia xây dựng nước nhà. Và trước hết, phải biết đọc, biết viết chữ quốc ngữ. Những người đã biết chữ hãy dạy cho những người chưa biết; những người chưa biết hãy gắng sức mà học.\n\nĐiều làm nên sức sống của lời kêu gọi là cách Người biến mỗi mối quan hệ quen thuộc trong đời sống thành một cặp thầy trò. Người giàu có được đề nghị mở lớp học ngay tại nhà mình để dạy cho hàng xóm láng giềng; chủ đồn điền, chủ hầm mỏ, chủ nhà máy mở lớp cho những người làm của mình. Không cần một bộ máy đồ sộ, lời kêu gọi len vào từng gia đình, từng xóm ngõ, từng xưởng thợ, và biến việc học chữ thành việc của tất cả mọi người.","doc":6},{"loai":"trich","text":"Vợ chưa biết thì chồng bảo, em chưa biết thì anh bảo, cha mẹ không biết thì con bảo, người ăn người làm không biết thì chủ nhà bảo.","nguoi":"Hồ Chí Minh, Chống nạn thất học, tháng 10/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":7},{"loai":"doan","tieu_de":"“Phụ nữ lại càng cần phải học”","text":"Trong lời kêu gọi ấy, Người dành một câu riêng cho phụ nữ. Phụ nữ lại càng cần phải học, vì đã lâu chị em bị kìm hãm; đây là lúc chị em phải cố gắng để kịp nam giới, để xứng đáng mình là một phần tử trong nước, có quyền bầu cử và ứng cử. Câu nói ấy mang ý nghĩa đặc biệt khi đặt cạnh sắc lệnh về Tổng tuyển cử ký cùng ngày 8/9/1945. Sắc lệnh ấy lần đầu tiên trao cho phụ nữ Việt Nam quyền bầu cử và ứng cử ngang với nam giới (xem chuyên đề Lá phiếu đầu tiên).\n\nBiết chữ, người phụ nữ mới có thể tự đọc tên người ứng cử, tự hiểu điều mình lựa chọn, tự đọc được những sắc lệnh nói về quyền lợi của chính mình. Học chữ vì thế gắn liền với quyền làm chủ. Trong hoàn cảnh hàng nghìn năm người phụ nữ bị ràng buộc bởi lễ giáo cũ, lời kêu gọi của vị Chủ tịch nước mở ra một cánh cửa mà trước đó rất ít người dám nghĩ tới. Những người con gái học được chữ trở về dạy lại mẹ mình, đúng như tinh thần “con bảo cha mẹ” mà Người đã viết.","doc":8},{"loai":"ban_co_biet","text":"Nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa (tháng 9/1945), Chủ tịch Hồ Chí Minh viết thư gửi học sinh với câu nổi tiếng: “Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.”","nguon_ten":"Hồ Chí Minh, Thư gửi các học sinh, tháng 9/1945 — Hồ Chí Minh Toàn tập, tập 4","doc":9},{"loai":"doan","tieu_de":"Lớp học dưới gốc cây, chữ viết trên lá chuối","text":"Lớp Bình dân học vụ mọc lên khắp nơi: trong đình làng, sân chùa, nhà thờ, dưới gốc cây, trong những gian nhà riêng được chủ nhà nhường lại. Người lớn đi làm đồng, làm thợ cả ngày, tối về học dưới ánh đèn dầu. Thiếu giấy, người học viết lên lá chuối; thiếu mực, người ta dùng phấn, dùng than để viết; giấy vụn được gom góp lại dành cho học viên. Người dạy phần lớn tình nguyện, không lương; thầy giáo có khi là một cậu học trò, trò có khi là một cụ già.\n\nCách dạy cũng mới. Thay vì bắt học thuộc lòng như lối học cũ, các lớp dạy ghép vần theo âm, để người học nhanh chóng tự đánh vần được những câu quen thuộc. Người dân gọi vui việc đi học chữ là “đi học i tờ”, theo những chữ cái đầu tiên trên trang vần. Nhiều hồi ức còn kể về những tấm bảng chữ đặt ở cổng chợ, đầu làng để người qua lại tập đọc, một cách kiểm tra vui mà hiệu quả. Những cách làm hồn nhiên ấy biến việc học chữ thành niềm vui, thành niềm tự hào chung của cả xóm, cả làng.","doc":10},{"loai":"anh","src":"textures/bang_w/G14_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Diệt giặc dốt: những lớp Bình dân học vụ”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một năm, hai triệu rưỡi người biết chữ","text":"Sau khoảng một năm hoạt động, phong trào đã tổ chức được gần 75.000 lớp học với khoảng 96.000 người dạy, giúp khoảng 2,5 triệu người biết đọc, biết viết. Con số ấy càng đáng kinh ngạc khi nhớ rằng cùng thời gian đó, đất nước phải chống đói, chống quân xâm lược ở Nam Bộ, đối phó với quân Tưởng ở miền Bắc, tổ chức Tổng tuyển cử và đàm phán với Pháp.\n\nPhong trào không dừng lại khi kháng chiến toàn quốc bùng nổ. Ở vùng tự do và trên các chiến khu, lớp bình dân học vụ vẫn tiếp tục, người ta vừa kháng chiến vừa học chữ. Sau khi miền Bắc hòa bình, công cuộc xóa nạn mù chữ tiếp tục được đẩy mạnh. Đến năm 1958, ở vùng đồng bằng và trung du miền Bắc về cơ bản đã xóa xong nạn mù chữ, với khoảng 93,4% người trong độ tuổi từ 12 đến 50 biết đọc, biết viết. Từ những lớp học đơn sơ mùa thu 1945, cả một dân tộc đã từng bước bước ra khỏi bóng tối của chính sách ngu dân thời thuộc địa.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoi_vndcch_khoa_i.jpg","chu_thich":"Học chữ gắn liền với quyền công dân: Quốc hội khóa I được bầu ra trong cuộc Tổng tuyển cử ngày 6/1/1946, khi phong trào Bình dân học vụ đang lan khắp cả nước.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Tên gọi “bình dân học vụ” đến nay vẫn sống trong tiếng Việt, gợi nhắc một thời cả nước đi học. Ba sắc lệnh năm 1945 về bình dân học vụ được cơ quan lưu trữ nhà nước giới thiệu như những văn bản quý của buổi đầu lập quốc. Lời kêu gọi “Chống nạn thất học” được in trong Hồ Chí Minh Toàn tập và vẫn được trích dẫn mỗi khi nói về khuyến học. Nhiều thập kỷ sau, tinh thần ấy tiếp tục được khơi dậy qua các phong trào xây dựng xã hội học tập. Gần đây là phong trào “Bình dân học vụ số” nhằm phổ cập kỹ năng số cho mọi người dân, mượn lại chính cái tên của mùa thu 1945.\n\nTrong gian trưng bày này, bảng chuyên đề về Bình dân học vụ đặt cạnh những câu chuyện về Tuần lễ Vàng và chống giặc đói, bởi ba phong trào ấy diễn ra cùng một lúc, cùng một tinh thần. Chủ tịch Hồ Chí Minh từng coi dốt nát là một thứ giặc. Cuộc chiến với thứ giặc ấy không có tiếng súng, nhưng thắng lợi của nó đã góp phần làm nên sức mạnh để dân tộc bước vào cuộc kháng chiến trường kỳ.","doc":12},{"loai":"ban_co_biet","text":"Ngày 8/9, ngày Chủ tịch Hồ Chí Minh ký các sắc lệnh về bình dân học vụ năm 1945, về sau cũng là ngày được UNESCO chọn làm Ngày Quốc tế Xóa mù chữ. Đó là một sự trùng hợp mà nhiều tài liệu về phong trào vẫn nhắc đến.","nguon_ten":"UNESCO – International Literacy Day (8/9); Cục Văn thư và Lưu trữ nhà nước, “Ba sắc lệnh về bình dân học vụ năm 1945”","doc":13}],"nguon":["Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, 3/9/1945; Chống nạn thất học, 10/1945; Thư gửi các học sinh, 9/1945)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Cục Văn thư và Lưu trữ nhà nước, “Ba sắc lệnh về bình dân học vụ năm 1945”","Báo VnExpress, “Phong trào bình dân học vụ 75 năm trước” – https://vnexpress.net/phong-trao-binh-dan-hoc-vu-75-nam-truoc-4166631.html","Lịch sử giáo dục Việt Nam — phong trào Bình dân học vụ"],"doc":[{"t":"“Vợ chưa biết thì chồng bảo”: cuộc chiến chống giặc dốt mùa thu 1945. Năm 1945, cứ một trăm người Việt Nam thì chừng chín mươi lăm người không biết đọc, biết viết. Chỉ khoảng một năm sau, hai triệu rưỡi người đã tự tay viết được tên mình. Cuộc chiến chống “giặc dốt” ấy diễn ra gần như không có trường sở, không có ngân sách, mà trên lá chuối, dưới ánh đèn dầu, theo lời kêu gọi của một vị Chủ tịch."},{"t":"Dấu điểm chỉ và những con số. Trước năm 1945, ở nhiều làng quê Việt Nam, khi phải ký vào một tờ văn tự, một lá đơn hay một tờ biên nhận, phần đông người dân chỉ biết in dấu ngón tay thay cho chữ ký. Họ không đọc được điều mình vừa điểm chỉ. Tờ giấy ấy có thể là một món nợ, một lần cầm cố ruộng đất, một lời cam kết mà họ không hiểu hết. Mù chữ không chỉ là thiếu hiểu biết; nó biến người dân thành kẻ yếu thế trước bất cứ ai cầm trong tay tờ giấy có chữ. Các số liệu thống kê được nêu lại trong nhiều tài liệu về phong trào Bình dân học vụ cho thấy quy mô của thảm cảnh ấy. Trong một trăm người Việt Nam, chỉ khoảng ba em nhỏ từ tám đến mười sáu tuổi được đến trường, khoảng hai người lớn biết chữ, còn lại chừng chín mươi lăm người mù chữ. Phụ nữ gần như bị gạt hẳn ra khỏi con đường học vấn. Đó là di sản của hơn tám mươi năm thuộc địa mà nước Việt Nam Dân chủ Cộng hòa phải tiếp nhận ngay từ ngày đầu tiên, cùng lúc với nạn đói, ngân khố trống rỗng và quân đội nước ngoài trên đất nước."},{"t":"“Nhà tù nhiều hơn trường học”. Bản Tuyên ngôn Độc lập đọc ở Ba Đình đã gọi đích danh căn nguyên của nạn mù chữ. Trong bản cáo trạng chế độ thực dân, Chủ tịch Hồ Chí Minh viết rằng chúng lập ra nhà tù nhiều hơn trường học, và chúng thi hành chính sách ngu dân. Chữ quốc ngữ tuy đã phổ biến trên sách báo từ đầu thế kỷ XX, nhưng với phần lớn nông dân và thợ thuyền, việc tự đọc một tờ báo vẫn là điều xa lạ. Trước Cách mạng, đã có những người trí thức yêu nước tìm cách thắp lên ánh sáng. Năm 1938, Hội Truyền bá quốc ngữ được thành lập ở Hà Nội, do học giả Nguyễn Văn Tố làm hội trưởng, mở các lớp học miễn phí cho người nghèo. Nhiều trí thức, sinh viên trẻ đã tình nguyện đứng lớp trong phong trào ấy, và họ trở thành lực lượng nòng cốt cho những lớp học sau này. Nhưng một hội đoàn hoạt động dưới sự kiểm soát của chính quyền thuộc địa không thể vươn tới hàng triệu người. Phải có một nhà nước của chính mình, việc xóa nạn mù chữ mới trở thành quốc sách. Và Chủ tịch Hồ Chí Minh đã không để việc ấy phải chờ lâu."},{"t":"Nhiệm vụ thứ hai trong sáu nhiệm vụ. Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, tại phiên họp đầu tiên của Chính phủ, Chủ tịch Hồ Chí Minh nêu sáu nhiệm vụ cấp bách của nhà nước mới. Nhiệm vụ thứ nhất là cứu đói. Ngay sau đó, ở vị trí thứ hai, là chống nạn mù chữ. Người đặt “giặc dốt” ngang hàng với giặc đói và giặc ngoại xâm, và đưa ra một nhận định đầy tin tưởng: chỉ cần ba tháng là đủ để học đọc, học viết tiếng nước ta theo vần quốc ngữ. Nhận định ấy không phải lời cổ vũ suông. Chữ quốc ngữ ghi âm bằng mẫu tự La-tinh; học xong bảng chữ cái và cách ghép vần, người học có thể tự đánh vần những câu mình vẫn nói hằng ngày. Người muốn cả dân tộc hiểu rằng thoát nạn mù chữ là việc làm được, và làm được nhanh, nếu mọi người cùng bắt tay vào. Lời phát biểu hôm ấy trở thành tuyên ngôn của cả phong trào."},{"t":"Nạn dốt là một trong những phương pháp độc ác mà bọn thực dân dùng để cai trị chúng ta. Hơn chín mươi phần trăm đồng bào chúng ta mù chữ. Nhưng chỉ cần ba tháng là đủ để học đọc, học viết tiếng nước ta theo vần quốc ngữ. Một dân tộc dốt là một dân tộc yếu. Vì vậy, tôi đề nghị mở một chiến dịch để chống nạn mù chữ. — Hồ Chí Minh, phiên họp đầu tiên của Chính phủ, 3/9/1945"},{"t":"Ba sắc lệnh ngày 8/9/1945. Năm ngày sau, ngày 8/9/1945, Chủ tịch Hồ Chí Minh ký ba sắc lệnh về bình dân học vụ. Sắc lệnh thứ nhất lập Nha Bình dân học vụ, cơ quan chuyên trách việc dạy chữ cho người lớn, thuộc Bộ Quốc gia Giáo dục do ông Vũ Đình Hòe làm Bộ trưởng. Sắc lệnh thứ hai quy định mở các lớp học bình dân buổi tối cho nông dân và thợ thuyền: trong thời hạn sáu tháng, làng nào, thị trấn nào cũng phải có ít nhất một lớp học. Sắc lệnh thứ ba quy định việc học chữ quốc ngữ từ nay là bắt buộc và không mất tiền; hạn trong một năm, toàn thể dân chúng Việt Nam trên tám tuổi phải biết đọc, biết viết chữ quốc ngữ. Đó là một quyết định táo bạo. Theo tính toán thời ấy, phong trào cần hơn một trăm nghìn người dạy và khoảng 200 triệu đồng mỗi năm, trong khi ngân sách chỉ dành được khoảng 2 triệu đồng, lúc ngân khố gần như trống rỗng (xem chuyên đề Tuần lễ Vàng). Nhưng chính quyền mới hiểu rằng không thể chờ đủ tiền, đủ trường rồi mới dạy. Nhà nước không đủ sức thì phải dựa vào sức dân: mỗi người biết chữ sẽ là một người thầy, mỗi mái nhà có thể thành một lớp học."},{"t":"Lời kêu gọi “Chống nạn thất học”. Tháng 10/1945, Chủ tịch Hồ Chí Minh ra lời kêu gọi “Chống nạn thất học”. Người mở đầu bằng việc nhắc lại chính sách ngu dân của thực dân. Rồi Người chỉ ra rằng muốn giữ vững nền độc lập, muốn làm cho dân mạnh nước giàu, mọi người Việt Nam phải hiểu biết quyền lợi và bổn phận của mình, phải có kiến thức mới để tham gia xây dựng nước nhà. Và trước hết, phải biết đọc, biết viết chữ quốc ngữ. Những người đã biết chữ hãy dạy cho những người chưa biết; những người chưa biết hãy gắng sức mà học. Điều làm nên sức sống của lời kêu gọi là cách Người biến mỗi mối quan hệ quen thuộc trong đời sống thành một cặp thầy trò. Người giàu có được đề nghị mở lớp học ngay tại nhà mình để dạy cho hàng xóm láng giềng; chủ đồn điền, chủ hầm mỏ, chủ nhà máy mở lớp cho những người làm của mình. Không cần một bộ máy đồ sộ, lời kêu gọi len vào từng gia đình, từng xóm ngõ, từng xưởng thợ, và biến việc học chữ thành việc của tất cả mọi người."},{"t":"Vợ chưa biết thì chồng bảo, em chưa biết thì anh bảo, cha mẹ không biết thì con bảo, người ăn người làm không biết thì chủ nhà bảo. — Hồ Chí Minh, Chống nạn thất học, tháng 10/1945"},{"t":"“Phụ nữ lại càng cần phải học”. Trong lời kêu gọi ấy, Người dành một câu riêng cho phụ nữ. Phụ nữ lại càng cần phải học, vì đã lâu chị em bị kìm hãm; đây là lúc chị em phải cố gắng để kịp nam giới, để xứng đáng mình là một phần tử trong nước, có quyền bầu cử và ứng cử. Câu nói ấy mang ý nghĩa đặc biệt khi đặt cạnh sắc lệnh về Tổng tuyển cử ký cùng ngày 8/9/1945. Sắc lệnh ấy lần đầu tiên trao cho phụ nữ Việt Nam quyền bầu cử và ứng cử ngang với nam giới (xem chuyên đề Lá phiếu đầu tiên). Biết chữ, người phụ nữ mới có thể tự đọc tên người ứng cử, tự hiểu điều mình lựa chọn, tự đọc được những sắc lệnh nói về quyền lợi của chính mình. Học chữ vì thế gắn liền với quyền làm chủ. Trong hoàn cảnh hàng nghìn năm người phụ nữ bị ràng buộc bởi lễ giáo cũ, lời kêu gọi của vị Chủ tịch nước mở ra một cánh cửa mà trước đó rất ít người dám nghĩ tới. Những người con gái học được chữ trở về dạy lại mẹ mình, đúng như tinh thần “con bảo cha mẹ” mà Người đã viết."},{"t":"Bạn có biết? Nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa (tháng 9/1945), Chủ tịch Hồ Chí Minh viết thư gửi học sinh với câu nổi tiếng: “Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.”"},{"t":"Lớp học dưới gốc cây, chữ viết trên lá chuối. Lớp Bình dân học vụ mọc lên khắp nơi: trong đình làng, sân chùa, nhà thờ, dưới gốc cây, trong những gian nhà riêng được chủ nhà nhường lại. Người lớn đi làm đồng, làm thợ cả ngày, tối về học dưới ánh đèn dầu. Thiếu giấy, người học viết lên lá chuối; thiếu mực, người ta dùng phấn, dùng than để viết; giấy vụn được gom góp lại dành cho học viên. Người dạy phần lớn tình nguyện, không lương; thầy giáo có khi là một cậu học trò, trò có khi là một cụ già. Cách dạy cũng mới. Thay vì bắt học thuộc lòng như lối học cũ, các lớp dạy ghép vần theo âm, để người học nhanh chóng tự đánh vần được những câu quen thuộc. Người dân gọi vui việc đi học chữ là “đi học i tờ”, theo những chữ cái đầu tiên trên trang vần. Nhiều hồi ức còn kể về những tấm bảng chữ đặt ở cổng chợ, đầu làng để người qua lại tập đọc, một cách kiểm tra vui mà hiệu quả. Những cách làm hồn nhiên ấy biến việc học chữ thành niềm vui, thành niềm tự hào chung của cả xóm, cả làng."},{"t":"Một năm, hai triệu rưỡi người biết chữ. Sau khoảng một năm hoạt động, phong trào đã tổ chức được gần 75.000 lớp học với khoảng 96.000 người dạy, giúp khoảng 2,5 triệu người biết đọc, biết viết. Con số ấy càng đáng kinh ngạc khi nhớ rằng cùng thời gian đó, đất nước phải chống đói, chống quân xâm lược ở Nam Bộ, đối phó với quân Tưởng ở miền Bắc, tổ chức Tổng tuyển cử và đàm phán với Pháp. Phong trào không dừng lại khi kháng chiến toàn quốc bùng nổ. Ở vùng tự do và trên các chiến khu, lớp bình dân học vụ vẫn tiếp tục, người ta vừa kháng chiến vừa học chữ. Sau khi miền Bắc hòa bình, công cuộc xóa nạn mù chữ tiếp tục được đẩy mạnh. Đến năm 1958, ở vùng đồng bằng và trung du miền Bắc về cơ bản đã xóa xong nạn mù chữ, với khoảng 93,4% người trong độ tuổi từ 12 đến 50 biết đọc, biết viết. Từ những lớp học đơn sơ mùa thu 1945, cả một dân tộc đã từng bước bước ra khỏi bóng tối của chính sách ngu dân thời thuộc địa."},{"t":"Dấu tích hôm nay. Tên gọi “bình dân học vụ” đến nay vẫn sống trong tiếng Việt, gợi nhắc một thời cả nước đi học. Ba sắc lệnh năm 1945 về bình dân học vụ được cơ quan lưu trữ nhà nước giới thiệu như những văn bản quý của buổi đầu lập quốc. Lời kêu gọi “Chống nạn thất học” được in trong Hồ Chí Minh Toàn tập và vẫn được trích dẫn mỗi khi nói về khuyến học. Nhiều thập kỷ sau, tinh thần ấy tiếp tục được khơi dậy qua các phong trào xây dựng xã hội học tập. Gần đây là phong trào “Bình dân học vụ số” nhằm phổ cập kỹ năng số cho mọi người dân, mượn lại chính cái tên của mùa thu 1945. Trong gian trưng bày này, bảng chuyên đề về Bình dân học vụ đặt cạnh những câu chuyện về Tuần lễ Vàng và chống giặc đói, bởi ba phong trào ấy diễn ra cùng một lúc, cùng một tinh thần. Chủ tịch Hồ Chí Minh từng coi dốt nát là một thứ giặc. Cuộc chiến với thứ giặc ấy không có tiếng súng, nhưng thắng lợi của nó đã góp phần làm nên sức mạnh để dân tộc bước vào cuộc kháng chiến trường kỳ."},{"t":"Bạn có biết? Ngày 8/9, ngày Chủ tịch Hồ Chí Minh ký các sắc lệnh về bình dân học vụ năm 1945, về sau cũng là ngày được UNESCO chọn làm Ngày Quốc tế Xóa mù chữ. Đó là một sự trùng hợp mà nhiều tài liệu về phong trào vẫn nhắc đến."}],"so_chu":2160},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ căn gác Hàng Ngang đến đêm 19/12: 31 mốc của 481 ngày lập quốc","sapo":"Chưa đầy mười sáu tháng tách ngày Người về Hà Nội với đêm toàn quốc kháng chiến. Trong 481 ngày ấy, một nhà nước được khai sinh, có Chính phủ, có Quốc hội, có Hiến pháp, và đứng vững trước thù trong giặc ngoài. Đặt các mốc cạnh nhau, ta nghe thấy nhịp thở dồn dập của những ngày lập quốc.","bia":{"src":"textures/bai/G14_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cách đọc một dòng thời gian","text":"Ba mươi mốt mốc dưới đây trải trên 481 ngày, từ buổi Chủ tịch Hồ Chí Minh bước lên căn gác nhà 48 Hàng Ngang đến đêm Người ra Lời kêu gọi toàn quốc kháng chiến. Đừng chỉ đọc từng mốc; hãy để ý khoảng cách giữa chúng. Có những tuần dồn dập tới mức gần như ngày nào cũng có một quyết định lớn, và có những tháng dài mà về sau mới hiểu là quãng lặng trước giông bão. Dòng thời gian có thể chia thành năm chặng: tám ngày trên căn gác; tháng Chín của những sắc lệnh; những bước dựng nền móng hợp hiến; những chữ ký đổi lấy thời gian; và hai mươi chín ngày cuối cùng trước tiếng súng. Mỗi chặng có một nhịp riêng. Cùng nhau, chúng kể câu chuyện của những “lần đầu tiên”. Đó là lần đầu tiên người Việt Nam có một bản tuyên ngôn độc lập, một chính phủ của mình, một cuộc tổng tuyển cử theo chế độ phổ thông đầu phiếu, một Quốc hội và một bản Hiến pháp.","doc":1},{"loai":"moc","items":[["22/8/1945","Rời Tân Trào về xuôi khi cuộc Tổng khởi nghĩa đang lan rộng; Hà Nội đã giành chính quyền từ ngày 19/8."],["23–25/8/1945","Dừng chân mấy ngày ở làng Phú Gia ven Hồ Tây, ngoại thành Hà Nội."],["25/8/1945","Vào nội thành, ở và làm việc trên gác hai nhà số 48 Hàng Ngang của gia đình ông bà Trịnh Văn Bô."],["26/8/1945","Chủ trì cuộc họp Ban Thường vụ Trung ương Đảng tại 48 Hàng Ngang, quyết định chuẩn bị Tuyên ngôn Độc lập và lễ ra mắt Chính phủ lâm thời."],["28/8/1945","Công bố thành phần Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa do Hồ Chí Minh làm Chủ tịch kiêm Bộ trưởng Bộ Ngoại giao."],["28–29/8/1945","Soạn thảo bản Tuyên ngôn Độc lập trên gác hai nhà 48 Hàng Ngang."],["30/8/1945","Vua Bảo Đại thoái vị tại Ngọ Môn, Huế, trao ấn kiếm cho đoàn đại biểu Chính phủ lâm thời."],["2/9/1945","Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa."],["3/9/1945","Chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ, nêu sáu nhiệm vụ cấp bách."],["4/9/1945","Ký Sắc lệnh số 4 lập Quỹ Độc lập, nhận tiền, vàng, đồ vật quý do nhân dân tự nguyện đóng góp."],["8/9/1945","Ký sắc lệnh về Tổng tuyển cử bầu Quốc hội và ba sắc lệnh về bình dân học vụ, lập Nha Bình dân học vụ."],["9/1945","Viết thư gửi học sinh nhân ngày khai trường đầu tiên của nước Việt Nam độc lập."],["17–24/9/1945","Tuần lễ Vàng; cùng Quỹ Độc lập, nhân dân cả nước góp được 370 kilôgam vàng và 20 triệu đồng."],["23/9/1945","Thực dân Pháp nổ súng đánh chiếm Sài Gòn; Nam Bộ kháng chiến bùng nổ."],["10/1945","Ra lời kêu gọi “Chống nạn thất học”: người đã biết chữ dạy cho người chưa biết chữ."],["11/11/1945","Đảng Cộng sản Đông Dương tuyên bố tự giải tán, thực chất rút vào hoạt động bí mật."],["1/1/1946","Chính phủ liên hiệp lâm thời ra mắt quốc dân."],["6/1/1946","Tổng tuyển cử bầu Quốc hội khóa I trong cả nước; Người trúng cử tại Hà Nội với 98,4% số phiếu."],["28/2/1946","Pháp và Trung Hoa Dân quốc ký hiệp ước ở Trùng Khánh, thỏa thuận để quân Pháp ra miền Bắc thay quân Tưởng."],["2/3/1946","Kỳ họp thứ nhất Quốc hội khóa I tại Nhà hát Lớn; Người được bầu làm Chủ tịch Chính phủ Liên hiệp kháng chiến."],["6/3/1946","Ký Hiệp định Sơ bộ với đại diện Chính phủ Pháp."],["7/3/1946","Cùng Chính phủ gặp đồng bào tại quảng trường Nhà hát Lớn, giải thích vì sao phải ký Hiệp định."],["29/5/1946","Hội Liên hiệp quốc dân Việt Nam ra đời, mở rộng khối đoàn kết toàn dân."],["31/5/1946","Lên đường thăm nước Pháp; cụ Huỳnh Thúc Kháng giữ quyền Chủ tịch nước."],["14/9/1946","Ký Tạm ước Việt – Pháp tại Paris, cố giữ hòa bình khi cuộc đàm phán ở Fontainebleau bế tắc."],["20/10/1946","Về tới Hải Phòng sau hơn bốn tháng xa Tổ quốc."],["9/11/1946","Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa."],["20/11/1946","Quân Pháp gây hấn, tấn công ở Hải Phòng và Lạng Sơn."],["Đầu 12/1946","Rời Bắc Bộ phủ về ở và làm việc tại làng Vạn Phúc, Hà Đông."],["18/12/1946","Phía Pháp gửi tối hậu thư đòi giải giáp tự vệ Hà Nội; Ban Thường vụ Trung ương Đảng họp mở rộng tại Vạn Phúc trong hai ngày 18 và 19/12."],["19/12/1946","Khoảng 20 giờ, cuộc chiến đấu bảo vệ Thủ đô bắt đầu; trong đêm ấy, Người ra Lời kêu gọi toàn quốc kháng chiến."]],"doc":2},{"loai":"anh","src":"textures/bang_w/G14_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chặng một: tám ngày trên căn gác","text":"Tám ngày từ 25/8 đến 2/9/1945 là chặng ngắn nhất nhưng dày đặc nhất. Trong tám ngày ấy, quyết định tổ chức lễ tuyên bố độc lập được đưa ra, Chính phủ lâm thời được công bố, bản Tuyên ngôn được viết xong, và ở kinh đô Huế, triều đại quân chủ cuối cùng khép lại. Hãy để ý rằng việc công bố Chính phủ ngày 28/8 diễn ra trước khi bản Tuyên ngôn được đọc: một nhà nước cần có những người đứng ra chịu trách nhiệm trước quốc dân trước khi tuyên bố với thế giới. Sự thoái vị của vua Bảo Đại ngày 30/8 cũng mang ý nghĩa pháp lý lớn: khi Tuyên ngôn vang lên ở Ba Đình, trên đất nước chỉ còn một chính quyền hợp pháp duy nhất là Chính phủ lâm thời. Các chuyên đề về căn gác Hàng Ngang và lễ đài Ba Đình kể chi tiết từng ngày ấy.","doc":3},{"loai":"doan","tieu_de":"Chặng hai: tháng Chín của những sắc lệnh","text":"Chỉ một ngày sau lễ Độc lập, Chính phủ đã họp phiên đầu tiên; hai ngày sau, Quỹ Độc lập ra đời; sáu ngày sau, sắc lệnh về Tổng tuyển cử và các sắc lệnh về bình dân học vụ được ký. Nhịp độ ấy phản ánh một cách nghĩ: phải nhanh chóng xây nền móng pháp lý và củng cố lòng tin của nhân dân trước khi những thử thách lớn hơn ập đến. Và thử thách đã đến rất nhanh. Ngày 23/9, khi Tuần lễ Vàng còn đang diễn ra, thực dân Pháp nổ súng ở Sài Gòn. Trong cùng một tuần, người dân nhiều nơi góp vàng giữ nước, còn đồng bào Nam Bộ đã phải cầm vũ khí. Đặt hai mốc ấy cạnh nhau, ta hiểu vì sao Chủ tịch Hồ Chí Minh nói đến giặc đói, giặc dốt và giặc ngoại xâm như ba mặt trận phải đánh cùng một lúc. Các chuyên đề Tuần lễ Vàng và Bình dân học vụ kể rõ hơn về những mặt trận ấy.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","chu_thich":"Văn bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa, lưu tại Trung tâm Lưu trữ quốc gia III — văn kiện mở đầu dòng thời gian của những ngày lập quốc.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Chặng ba: dựng nền móng hợp hiến","text":"Từ cuối năm 1945 đến mùa xuân 1946, dòng thời gian chuyển sang những mốc mang tính thể chế. Ngày 11/11/1945, Đảng Cộng sản Đông Dương tuyên bố tự giải tán, thực chất rút vào hoạt động bí mật, để tránh mũi nhọn công kích của các thế lực chống đối. Ngày 1/1/1946, Chính phủ liên hiệp lâm thời ra mắt với sự tham gia của cả những đảng phái đối lập. Năm ngày sau, cuộc Tổng tuyển cử diễn ra trên cả nước, kể cả ở những vùng đang có chiến sự ở Nam Bộ. Ngày 2/3/1946, Quốc hội họp kỳ thứ nhất tại Nhà hát Lớn, lập ra Chính phủ Liên hiệp kháng chiến. Mốc cuối cùng của chặng này nằm tận cuối năm: ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên. Hơn mười bốn tháng sau lễ Độc lập, nhà nước mới đã có đủ chính phủ do dân bầu, quốc hội và hiến pháp, những nền tảng của một nhà nước pháp quyền dân chủ.","doc":5},{"loai":"ban_co_biet","text":"Bản Hiến pháp đầu tiên, thông qua ngày 9/11/1946, gồm lời nói đầu, 7 chương và 70 điều. Điều thứ nhất khẳng định tất cả quyền bính trong nước là của toàn thể nhân dân Việt Nam, không phân biệt nòi giống, gái trai, giàu nghèo, giai cấp, tôn giáo.","nguon_ten":"Hiến pháp nước Việt Nam Dân chủ Cộng hòa năm 1946; Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam","doc":6},{"loai":"doan","tieu_de":"Chặng bốn: những chữ ký đổi lấy thời gian","text":"Giữa chặng ba và chặng năm là một chuỗi mốc ngoại giao. Chỉ sáu ngày sau khi Pháp và Tưởng thỏa thuận với nhau ở Trùng Khánh, ngày 6/3/1946, Hiệp định Sơ bộ được ký. Ngay hôm sau, Chủ tịch Hồ Chí Minh cùng Chính phủ ra gặp đồng bào ở quảng trường Nhà hát Lớn để giải thích vì sao phải hòa. Ngày 31/5, Người lên đường sang Pháp; ngày 14/9, Người ký Tạm ước tại Paris, và ngày 20/10 về tới Hải Phòng. Đọc liền các mốc ấy, ta thấy một chiến lược nhất quán: mỗi chữ ký là để đổi lấy thời gian, để quân Tưởng rút về nước, để lực lượng vũ trang kịp lớn lên, để nhân dân kịp chuẩn bị. Từ ngày ký Hiệp định Sơ bộ đến đêm toàn quốc kháng chiến là 288 ngày. Quãng thời gian hòa hoãn ấy không dài, nhưng đủ để đất nước bước vào cuộc kháng chiến lâu dài với một thế trận khác hẳn. Chi tiết về Hiệp định Sơ bộ và chuyến đi Pháp được kể trong các chuyên đề riêng.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_with_vietnamese_expats_in_france_194.jpg","chu_thich":"Chủ tịch Hồ Chí Minh giữa kiều bào tại Pháp năm 1946, trong hơn bốn tháng Người vắng mặt ở Hà Nội.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trong thời gian Chủ tịch Hồ Chí Minh ở Pháp năm 1946, cụ Huỳnh Thúc Kháng — Bộ trưởng Bộ Nội vụ, một nhà nho yêu nước nổi tiếng — được giao giữ quyền Chủ tịch nước. Trước lúc lên đường, Người dặn cụ: “Dĩ bất biến, ứng vạn biến” — lấy cái không thay đổi để ứng phó với muôn sự thay đổi.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":8},{"loai":"doan","tieu_de":"Chặng năm: hai mươi chín ngày","text":"Từ ngày 20/11/1946, khi quân Pháp gây hấn ở Hải Phòng và Lạng Sơn, đến đêm 19/12 chỉ có hai mươi chín ngày. Đầu tháng 12, Chủ tịch Hồ Chí Minh rời Bắc Bộ phủ về làng Vạn Phúc, Hà Đông. Những mốc cuối dồn lại như những nhịp trống. Phía Pháp liên tiếp khiêu khích giữa Hà Nội, ngày 18/12 gửi tối hậu thư đòi giải giáp tự vệ Thủ đô. Cùng lúc, Ban Thường vụ Trung ương Đảng họp mở rộng ở Vạn Phúc trong hai ngày 18 và 19/12, quyết định phát động toàn quốc kháng chiến. Khoảng 20 giờ tối 19/12, đèn điện Thủ đô vụt tắt, hiệu lệnh chiến đấu vang lên. Lời kêu gọi toàn quốc kháng chiến ra đời trong đêm ấy và được phát đi trên sóng Đài Tiếng nói Việt Nam sáng hôm sau. Mốc cuối cùng của dòng thời gian khép lại những tháng ngày ở Hà Nội và mở ra chín năm kháng chiến trường kỳ.","doc":9},{"loai":"anh","src":"textures/bang_w/G14_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những điều dòng thời gian không ghi","text":"Một dòng thời gian chỉ ghi được những sự kiện có ngày tháng. Nó không ghi được những đêm Chủ tịch Hồ Chí Minh làm việc khuya ở Bắc Bộ phủ, những lá thư Người viết cho học sinh, cho giới công thương, cho đồng bào Nam Bộ, những lần Người tiếp khách trong nước và quốc tế. Nó cũng không ghi được tên của vô số người đã góp một chiếc nhẫn, dạy một lớp học tối, đi bỏ phiếu dưới làn đạn. Vì vậy, hãy đọc các mốc này cùng với những chuyên đề khác trong gian: mỗi mốc là một cánh cửa dẫn vào một câu chuyện. Tuần lễ Vàng, Bình dân học vụ, chống giặc đói, lá phiếu đầu tiên, chuyến đi Pháp, mỗi câu chuyện là một lát cắt, còn dòng thời gian là sợi chỉ xâu chúng lại với nhau.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Phần lớn các địa điểm trên dòng thời gian vẫn còn và có thể đến thăm. Căn gác nhà 48 Hàng Ngang là di tích giữa phố cổ. Quảng trường Ba Đình nay là nơi có Lăng Chủ tịch Hồ Chí Minh. Bắc Bộ phủ, nơi Chính phủ họp phiên đầu tiên, nay là Nhà khách Chính phủ ở số 12 Ngô Quyền. Nhà hát Lớn, nơi Quốc hội khóa I họp kỳ thứ nhất và nơi diễn ra cuộc gặp đồng bào ngày 7/3/1946, vẫn đứng ở đầu phố Tràng Tiền. Ở Huế, Ngọ Môn vẫn còn đó, nơi vua Bảo Đại đọc chiếu thoái vị. Ở làng lụa Vạn Phúc, ngôi nhà nơi Người viết Lời kêu gọi toàn quốc kháng chiến được gìn giữ như một di tích lịch sử. Văn bản Tuyên ngôn Độc lập được bảo quản tại Trung tâm Lưu trữ quốc gia III. Đi qua những địa chỉ ấy theo đúng thứ tự thời gian, bạn sẽ đi lại hành trình 481 ngày của những năm tháng lập quốc.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam; Hiến pháp năm 1946","Võ Nguyên Giáp, Những năm tháng không thể nào quên, NXB Quân đội nhân dân","Di tích 48 Hàng Ngang, Hà Nội; Di tích nơi Chủ tịch Hồ Chí Minh viết Lời kêu gọi toàn quốc kháng chiến, Vạn Phúc, Hà Đông"],"doc":[{"t":"Từ căn gác Hàng Ngang đến đêm 19/12: 31 mốc của 481 ngày lập quốc. Chưa đầy mười sáu tháng tách ngày Người về Hà Nội với đêm toàn quốc kháng chiến. Trong 481 ngày ấy, một nhà nước được khai sinh, có Chính phủ, có Quốc hội, có Hiến pháp, và đứng vững trước thù trong giặc ngoài. Đặt các mốc cạnh nhau, ta nghe thấy nhịp thở dồn dập của những ngày lập quốc."},{"t":"Cách đọc một dòng thời gian. Ba mươi mốt mốc dưới đây trải trên 481 ngày, từ buổi Chủ tịch Hồ Chí Minh bước lên căn gác nhà 48 Hàng Ngang đến đêm Người ra Lời kêu gọi toàn quốc kháng chiến. Đừng chỉ đọc từng mốc; hãy để ý khoảng cách giữa chúng. Có những tuần dồn dập tới mức gần như ngày nào cũng có một quyết định lớn, và có những tháng dài mà về sau mới hiểu là quãng lặng trước giông bão. Dòng thời gian có thể chia thành năm chặng: tám ngày trên căn gác; tháng Chín của những sắc lệnh; những bước dựng nền móng hợp hiến; những chữ ký đổi lấy thời gian; và hai mươi chín ngày cuối cùng trước tiếng súng. Mỗi chặng có một nhịp riêng. Cùng nhau, chúng kể câu chuyện của những “lần đầu tiên”. Đó là lần đầu tiên người Việt Nam có một bản tuyên ngôn độc lập, một chính phủ của mình, một cuộc tổng tuyển cử theo chế độ phổ thông đầu phiếu, một Quốc hội và một bản Hiến pháp."},{"t":"Các mốc thời gian. 22/8/1945: Rời Tân Trào về xuôi khi cuộc Tổng khởi nghĩa đang lan rộng; Hà Nội đã giành chính quyền từ ngày 19/8. 23–25/8/1945: Dừng chân mấy ngày ở làng Phú Gia ven Hồ Tây, ngoại thành Hà Nội. 25/8/1945: Vào nội thành, ở và làm việc trên gác hai nhà số 48 Hàng Ngang của gia đình ông bà Trịnh Văn Bô. 26/8/1945: Chủ trì cuộc họp Ban Thường vụ Trung ương Đảng tại 48 Hàng Ngang, quyết định chuẩn bị Tuyên ngôn Độc lập và lễ ra mắt Chính phủ lâm thời. 28/8/1945: Công bố thành phần Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa do Hồ Chí Minh làm Chủ tịch kiêm Bộ trưởng Bộ Ngoại giao. 28–29/8/1945: Soạn thảo bản Tuyên ngôn Độc lập trên gác hai nhà 48 Hàng Ngang. 30/8/1945: Vua Bảo Đại thoái vị tại Ngọ Môn, Huế, trao ấn kiếm cho đoàn đại biểu Chính phủ lâm thời. 2/9/1945: Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa. 3/9/1945: Chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ, nêu sáu nhiệm vụ cấp bách. 4/9/1945: Ký Sắc lệnh số 4 lập Quỹ Độc lập, nhận tiền, vàng, đồ vật quý do nhân dân tự nguyện đóng góp. 8/9/1945: Ký sắc lệnh về Tổng tuyển cử bầu Quốc hội và ba sắc lệnh về bình dân học vụ, lập Nha Bình dân học vụ. 9/1945: Viết thư gửi học sinh nhân ngày khai trường đầu tiên của nước Việt Nam độc lập. 17–24/9/1945: Tuần lễ Vàng; cùng Quỹ Độc lập, nhân dân cả nước góp được 370 kilôgam vàng và 20 triệu đồng. 23/9/1945: Thực dân Pháp nổ súng đánh chiếm Sài Gòn; Nam Bộ kháng chiến bùng nổ. 10/1945: Ra lời kêu gọi “Chống nạn thất học”: người đã biết chữ dạy cho người chưa biết chữ. 11/11/1945: Đảng Cộng sản Đông Dương tuyên bố tự giải tán, thực chất rút vào hoạt động bí mật. 1/1/1946: Chính phủ liên hiệp lâm thời ra mắt quốc dân. 6/1/1946: Tổng tuyển cử bầu Quốc hội khóa I trong cả nước; Người trúng cử tại Hà Nội với 98,4% số phiếu. 28/2/1946: Pháp và Trung Hoa Dân quốc ký hiệp ước ở Trùng Khánh, thỏa thuận để quân Pháp ra miền Bắc thay quân Tưởng. 2/3/1946: Kỳ họp thứ nhất Quốc hội khóa I tại Nhà hát Lớn; Người được bầu làm Chủ tịch Chính phủ Liên hiệp kháng chiến. 6/3/1946: Ký Hiệp định Sơ bộ với đại diện Chính phủ Pháp. 7/3/1946: Cùng Chính phủ gặp đồng bào tại quảng trường Nhà hát Lớn, giải thích vì sao phải ký Hiệp định. 29/5/1946: Hội Liên hiệp quốc dân Việt Nam ra đời, mở rộng khối đoàn kết toàn dân. 31/5/1946: Lên đường thăm nước Pháp; cụ Huỳnh Thúc Kháng giữ quyền Chủ tịch nước. 14/9/1946: Ký Tạm ước Việt – Pháp tại Paris, cố giữ hòa bình khi cuộc đàm phán ở Fontainebleau bế tắc. 20/10/1946: Về tới Hải Phòng sau hơn bốn tháng xa Tổ quốc. 9/11/1946: Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa. 20/11/1946: Quân Pháp gây hấn, tấn công ở Hải Phòng và Lạng Sơn. Đầu 12/1946: Rời Bắc Bộ phủ về ở và làm việc tại làng Vạn Phúc, Hà Đông. 18/12/1946: Phía Pháp gửi tối hậu thư đòi giải giáp tự vệ Hà Nội; Ban Thường vụ Trung ương Đảng họp mở rộng tại Vạn Phúc trong hai ngày 18 và 19/12. 19/12/1946: Khoảng 20 giờ, cuộc chiến đấu bảo vệ Thủ đô bắt đầu; trong đêm ấy, Người ra Lời kêu gọi toàn quốc kháng chiến."},{"t":"Chặng một: tám ngày trên căn gác. Tám ngày từ 25/8 đến 2/9/1945 là chặng ngắn nhất nhưng dày đặc nhất. Trong tám ngày ấy, quyết định tổ chức lễ tuyên bố độc lập được đưa ra, Chính phủ lâm thời được công bố, bản Tuyên ngôn được viết xong, và ở kinh đô Huế, triều đại quân chủ cuối cùng khép lại. Hãy để ý rằng việc công bố Chính phủ ngày 28/8 diễn ra trước khi bản Tuyên ngôn được đọc: một nhà nước cần có những người đứng ra chịu trách nhiệm trước quốc dân trước khi tuyên bố với thế giới. Sự thoái vị của vua Bảo Đại ngày 30/8 cũng mang ý nghĩa pháp lý lớn: khi Tuyên ngôn vang lên ở Ba Đình, trên đất nước chỉ còn một chính quyền hợp pháp duy nhất là Chính phủ lâm thời. Các chuyên đề về căn gác Hàng Ngang và lễ đài Ba Đình kể chi tiết từng ngày ấy."},{"t":"Chặng hai: tháng Chín của những sắc lệnh. Chỉ một ngày sau lễ Độc lập, Chính phủ đã họp phiên đầu tiên; hai ngày sau, Quỹ Độc lập ra đời; sáu ngày sau, sắc lệnh về Tổng tuyển cử và các sắc lệnh về bình dân học vụ được ký. Nhịp độ ấy phản ánh một cách nghĩ: phải nhanh chóng xây nền móng pháp lý và củng cố lòng tin của nhân dân trước khi những thử thách lớn hơn ập đến. Và thử thách đã đến rất nhanh. Ngày 23/9, khi Tuần lễ Vàng còn đang diễn ra, thực dân Pháp nổ súng ở Sài Gòn. Trong cùng một tuần, người dân nhiều nơi góp vàng giữ nước, còn đồng bào Nam Bộ đã phải cầm vũ khí. Đặt hai mốc ấy cạnh nhau, ta hiểu vì sao Chủ tịch Hồ Chí Minh nói đến giặc đói, giặc dốt và giặc ngoại xâm như ba mặt trận phải đánh cùng một lúc. Các chuyên đề Tuần lễ Vàng và Bình dân học vụ kể rõ hơn về những mặt trận ấy."},{"t":"Chặng ba: dựng nền móng hợp hiến. Từ cuối năm 1945 đến mùa xuân 1946, dòng thời gian chuyển sang những mốc mang tính thể chế. Ngày 11/11/1945, Đảng Cộng sản Đông Dương tuyên bố tự giải tán, thực chất rút vào hoạt động bí mật, để tránh mũi nhọn công kích của các thế lực chống đối. Ngày 1/1/1946, Chính phủ liên hiệp lâm thời ra mắt với sự tham gia của cả những đảng phái đối lập. Năm ngày sau, cuộc Tổng tuyển cử diễn ra trên cả nước, kể cả ở những vùng đang có chiến sự ở Nam Bộ. Ngày 2/3/1946, Quốc hội họp kỳ thứ nhất tại Nhà hát Lớn, lập ra Chính phủ Liên hiệp kháng chiến. Mốc cuối cùng của chặng này nằm tận cuối năm: ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên. Hơn mười bốn tháng sau lễ Độc lập, nhà nước mới đã có đủ chính phủ do dân bầu, quốc hội và hiến pháp, những nền tảng của một nhà nước pháp quyền dân chủ."},{"t":"Bạn có biết? Bản Hiến pháp đầu tiên, thông qua ngày 9/11/1946, gồm lời nói đầu, 7 chương và 70 điều. Điều thứ nhất khẳng định tất cả quyền bính trong nước là của toàn thể nhân dân Việt Nam, không phân biệt nòi giống, gái trai, giàu nghèo, giai cấp, tôn giáo."},{"t":"Chặng bốn: những chữ ký đổi lấy thời gian. Giữa chặng ba và chặng năm là một chuỗi mốc ngoại giao. Chỉ sáu ngày sau khi Pháp và Tưởng thỏa thuận với nhau ở Trùng Khánh, ngày 6/3/1946, Hiệp định Sơ bộ được ký. Ngay hôm sau, Chủ tịch Hồ Chí Minh cùng Chính phủ ra gặp đồng bào ở quảng trường Nhà hát Lớn để giải thích vì sao phải hòa. Ngày 31/5, Người lên đường sang Pháp; ngày 14/9, Người ký Tạm ước tại Paris, và ngày 20/10 về tới Hải Phòng. Đọc liền các mốc ấy, ta thấy một chiến lược nhất quán: mỗi chữ ký là để đổi lấy thời gian, để quân Tưởng rút về nước, để lực lượng vũ trang kịp lớn lên, để nhân dân kịp chuẩn bị. Từ ngày ký Hiệp định Sơ bộ đến đêm toàn quốc kháng chiến là 288 ngày. Quãng thời gian hòa hoãn ấy không dài, nhưng đủ để đất nước bước vào cuộc kháng chiến lâu dài với một thế trận khác hẳn. Chi tiết về Hiệp định Sơ bộ và chuyến đi Pháp được kể trong các chuyên đề riêng."},{"t":"Bạn có biết? Trong thời gian Chủ tịch Hồ Chí Minh ở Pháp năm 1946, cụ Huỳnh Thúc Kháng — Bộ trưởng Bộ Nội vụ, một nhà nho yêu nước nổi tiếng — được giao giữ quyền Chủ tịch nước. Trước lúc lên đường, Người dặn cụ: “Dĩ bất biến, ứng vạn biến” — lấy cái không thay đổi để ứng phó với muôn sự thay đổi."},{"t":"Chặng năm: hai mươi chín ngày. Từ ngày 20/11/1946, khi quân Pháp gây hấn ở Hải Phòng và Lạng Sơn, đến đêm 19/12 chỉ có hai mươi chín ngày. Đầu tháng 12, Chủ tịch Hồ Chí Minh rời Bắc Bộ phủ về làng Vạn Phúc, Hà Đông. Những mốc cuối dồn lại như những nhịp trống. Phía Pháp liên tiếp khiêu khích giữa Hà Nội, ngày 18/12 gửi tối hậu thư đòi giải giáp tự vệ Thủ đô. Cùng lúc, Ban Thường vụ Trung ương Đảng họp mở rộng ở Vạn Phúc trong hai ngày 18 và 19/12, quyết định phát động toàn quốc kháng chiến. Khoảng 20 giờ tối 19/12, đèn điện Thủ đô vụt tắt, hiệu lệnh chiến đấu vang lên. Lời kêu gọi toàn quốc kháng chiến ra đời trong đêm ấy và được phát đi trên sóng Đài Tiếng nói Việt Nam sáng hôm sau. Mốc cuối cùng của dòng thời gian khép lại những tháng ngày ở Hà Nội và mở ra chín năm kháng chiến trường kỳ."},{"t":"Những điều dòng thời gian không ghi. Một dòng thời gian chỉ ghi được những sự kiện có ngày tháng. Nó không ghi được những đêm Chủ tịch Hồ Chí Minh làm việc khuya ở Bắc Bộ phủ, những lá thư Người viết cho học sinh, cho giới công thương, cho đồng bào Nam Bộ, những lần Người tiếp khách trong nước và quốc tế. Nó cũng không ghi được tên của vô số người đã góp một chiếc nhẫn, dạy một lớp học tối, đi bỏ phiếu dưới làn đạn. Vì vậy, hãy đọc các mốc này cùng với những chuyên đề khác trong gian: mỗi mốc là một cánh cửa dẫn vào một câu chuyện. Tuần lễ Vàng, Bình dân học vụ, chống giặc đói, lá phiếu đầu tiên, chuyến đi Pháp, mỗi câu chuyện là một lát cắt, còn dòng thời gian là sợi chỉ xâu chúng lại với nhau."},{"t":"Dấu tích hôm nay. Phần lớn các địa điểm trên dòng thời gian vẫn còn và có thể đến thăm. Căn gác nhà 48 Hàng Ngang là di tích giữa phố cổ. Quảng trường Ba Đình nay là nơi có Lăng Chủ tịch Hồ Chí Minh. Bắc Bộ phủ, nơi Chính phủ họp phiên đầu tiên, nay là Nhà khách Chính phủ ở số 12 Ngô Quyền. Nhà hát Lớn, nơi Quốc hội khóa I họp kỳ thứ nhất và nơi diễn ra cuộc gặp đồng bào ngày 7/3/1946, vẫn đứng ở đầu phố Tràng Tiền. Ở Huế, Ngọ Môn vẫn còn đó, nơi vua Bảo Đại đọc chiếu thoái vị. Ở làng lụa Vạn Phúc, ngôi nhà nơi Người viết Lời kêu gọi toàn quốc kháng chiến được gìn giữ như một di tích lịch sử. Văn bản Tuyên ngôn Độc lập được bảo quản tại Trung tâm Lưu trữ quốc gia III. Đi qua những địa chỉ ấy theo đúng thứ tự thời gian, bạn sẽ đi lại hành trình 481 ngày của những năm tháng lập quốc."}],"so_chu":1537},{"i":4,"tieu_de_bang":"Quảng trường Ba Đình ngày 2/9/1945","tieu_de":"Biển người ở Ba Đình: ai đã có mặt chiều 2/9/1945?","sapo":"Tấm ảnh đen trắng không ghi tên người chụp, cũng không ghi tên một ai trong đám đông. Vậy mà nó là một trong những chân dung đầy đủ nhất của dân tộc Việt Nam trong ngày Độc lập. Họ là ai, từ đâu đến, đã cùng nhau thề điều gì, và số phận họ ra sao sau buổi chiều ấy?","bia":{"src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Chủ nhật, mùng 2 tháng 9","text":"Ngày 2/9/1945 là một ngày Chủ nhật. Từ sáng sớm, Hà Nội đã rực rỡ cờ đỏ sao vàng, hoa và biểu ngữ, từ các phố phường nội thành đến những con đường dẫn về khu Ba Đình. Từng đoàn người nối nhau kéo về vườn hoa trước dinh Toàn quyền cũ. Đó là công nhân các nhà máy, nông dân các làng ngoại thành, tiểu thương phố cổ, học sinh, sinh viên, các đoàn phụ nữ, các cụ phụ lão, đồng bào thuộc mọi tầng lớp và tôn giáo. Các đội tự vệ làm nhiệm vụ giữ gìn trật tự quanh quảng trường. Nhiều người ăn mặc chỉnh tề như đi dự một ngày hội lớn của dân tộc.\n\nCác tư liệu thường ghi có hàng chục vạn người tham dự; có tư liệu ước tính tới khoảng nửa triệu người. Dù con số chính xác không thể kiểm đếm, đó là một cuộc tập hợp có quy mô hiếm thấy ở Hà Nội thời bấy giờ. Theo nhiều tư liệu, buổi lễ bắt đầu vào khoảng 14 giờ chiều. Tấm ảnh chụp quảng trường hôm ấy ghi lại chính biển người này, những con người đã rời nhà từ sáng để chờ nghe một bản tuyên bố mà họ biết sẽ thay đổi cuộc đời mình.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","chu_thich":"Quảng trường Ba Đình ngày 2/9/1945: hàng chục vạn đồng bào dự lễ tuyên bố độc lập (ảnh không rõ tác giả, thuộc phạm vi công cộng).","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Vườn hoa mang tên một cuộc khởi nghĩa","text":"Nơi diễn ra buổi lễ vốn là một vườn hoa tròn trong khu hành chính do người Pháp quy hoạch ở phía tây thành phố. Thời thuộc địa, nơi đây mang tên Rond-point Puginier, tức vườn hoa Puginier, theo tên một giám mục người Pháp từng ở Hà Nội cuối thế kỷ XIX. Mùa hè năm 1945, chỉ ít tuần trước Cách mạng Tháng Tám, vườn hoa được đổi tên thành vườn hoa Ba Đình.\n\nCái tên ấy nhắc nhớ cuộc khởi nghĩa Ba Đình ở Nga Sơn, Thanh Hóa, những năm 1886–1887, do Đinh Công Tráng và Phạm Bành lãnh đạo, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương chống thực dân Pháp. Chỉ ít tuần sau khi mang tên mới, vườn hoa chứng kiến ngày dân tộc tuyên bố thoát khỏi ách thực dân. Khoảng đất rộng ngay cạnh dinh Toàn quyền, trung tâm quyền lực của chế độ thuộc địa, đủ sức chứa một đám đông khổng lồ và trở thành nơi nhân dân làm chủ. Sự chuyển đổi ấy, từ tên một giáo sĩ ngoại quốc sang tên một cuộc khởi nghĩa của người Việt, như một lời báo trước cho buổi chiều mùa thu năm ấy.","doc":2},{"loai":"ban_co_biet","text":"Tên Ba Đình của cuộc khởi nghĩa 1886–1887 bắt nguồn từ ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê ở Nga Sơn, Thanh Hóa, nơi nghĩa quân dựng căn cứ; mỗi làng có một ngôi đình, nên căn cứ được gọi là Ba Đình.","nguon_ten":"Đại cương lịch sử Việt Nam, NXB Giáo dục; Khu di tích khởi nghĩa Ba Đình, Nga Sơn, Thanh Hóa","doc":3},{"loai":"doan","tieu_de":"Những người trong khung hình","text":"Những gương mặt trong tấm ảnh phần lớn không được ghi tên. Nhưng chính sự vô danh ấy làm nên giá trị của bức ảnh: đây là chân dung của một dân tộc, không phải của một cá nhân. Nhiều người trong đám đông vừa sống sót qua nạn đói năm Ất Dậu, nạn đói mà chính bản Tuyên ngôn đọc chiều hôm ấy nhắc tới với hơn hai triệu đồng bào chết đói. Nhiều người khác vừa cùng nhau xông vào Phủ Khâm sai sáng 19/8, giành chính quyền ở Thủ đô. Có những người lần đầu tiên trong đời đứng trước một vị lãnh tụ mà trước đó họ chỉ nghe tên.\n\nTrong biển người ấy, có những người về sau được lịch sử nhắc tên. Theo lời kể được báo chí ghi lại, người được giao kéo lá cờ đỏ sao vàng trong nghi thức chào cờ là hai thiếu nữ Hà Nội, Lê Thi và Đàm Thị Loan. Bà Lê Thi về sau trở thành giáo sư, nhà nghiên cứu, qua đời năm 2020 ở tuổi 95; mỗi dịp Quốc khánh, câu chuyện về hai cô gái kéo cờ năm ấy vẫn được kể lại. Trên lễ đài là các thành viên Chính phủ lâm thời; dưới lễ đài là vô vàn con người bình thường mà tên tuổi chỉ còn trong ký ức gia đình.","doc":4},{"loai":"anh","src":"textures/bang_w/G14_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình ngày 2/9/1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Lời thề của quảng trường","text":"Sau khi Chủ tịch Hồ Chí Minh đọc xong bản Tuyên ngôn và các thành viên Chính phủ lâm thời tuyên thệ, đến lượt những người đứng dưới quảng trường. Theo các tư liệu về buổi lễ, cả biển người đồng thanh nhắc lại lời thề độc lập. Họ thề kiên quyết ủng hộ Chính phủ lâm thời và Chủ tịch Hồ Chí Minh. Nếu thực dân Pháp trở lại xâm lược thì quyết không đi lính cho Pháp, không làm việc cho Pháp, không bán lương thực cho Pháp, không đưa đường cho Pháp.\n\nĐó là những lời thề rất cụ thể, gắn với việc làm của từng người: người nông dân giữ hạt gạo, người thợ giữ đôi tay, người dân quê giữ con đường làng. Nếu bản Tuyên ngôn là lời tuyên bố của Chính phủ trước thế giới, thì lời thề này là lời cam kết của nhân dân với chính mình. Tấm ảnh chụp đám đông, vì thế, không chỉ là ảnh của những người đi dự lễ; đó là ảnh của những người vừa tự nguyện nhận lấy bổn phận giữ nước. Chỉ ít tháng sau, lời thề ấy bắt đầu được thử thách bằng máu, trước tiên ở Nam Bộ, rồi ở chính Thủ đô.","doc":5},{"loai":"doan","tieu_de":"Tấm ảnh không tên tác giả","text":"Tấm ảnh được lưu truyền đến nay không ghi tên người chụp. Ngày ấy, một số nhiếp ảnh gia Hà Nội đã có mặt để ghi lại buổi lễ; nhiều bức ảnh của họ về sau được lưu giữ trong các cơ quan lưu trữ, bảo tàng và được in lại vô số lần trên sách báo. Nhưng không ít tấm đến nay không xác định được tác giả, và tấm ảnh này là một trong số đó. Máy ảnh thời ấy còn nặng nề, phim hiếm, mỗi lần bấm máy đều phải cân nhắc; vậy mà những người cầm máy vẫn để lại cho hậu thế những khung hình quý giá về ngày hội non sông.\n\nNgày nay, bức ảnh thuộc phạm vi công cộng và được giới thiệu rộng rãi, trở thành một trong những hình ảnh quen thuộc nhất về ngày Độc lập. Cùng với ảnh toàn cảnh lễ đài và ảnh Chủ tịch Hồ Chí Minh đọc Tuyên ngôn, nó giúp các thế hệ sau hình dung trọn vẹn buổi chiều lịch sử. Trong đó không chỉ có người đứng trên lễ đài, mà có cả những người đứng dưới, những người đã làm nên ý nghĩa của từng lời Tuyên ngôn.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","chu_thich":"Toàn cảnh lễ đài và quảng trường Ba Đình ngày 2/9/1945 — ảnh lưu trong hệ thống Lưu trữ quốc gia Việt Nam.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Họ đi đâu sau buổi chiều ấy","text":"Niềm vui ở Ba Đình trọn vẹn được ít ngày. Ba tuần sau, ngày 23/9/1945, tiếng súng xâm lược nổ ở Sài Gòn; nhiều thanh niên Hà Nội đã xung phong vào những đoàn quân Nam tiến. Những tháng tiếp theo, người Hà Nội lại có mặt trong Tuần lễ Vàng, trong các lớp bình dân học vụ, trong ngày bỏ phiếu 6/1/1946 (xem các chuyên đề cùng gian).\n\nRồi đêm 19/12/1946, khi toàn quốc kháng chiến bùng nổ, chính người dân Thủ đô đã biến phố phường thành chiến lũy. Tự vệ, Vệ quốc quân cùng nhân dân Hà Nội chiến đấu suốt sáu mươi ngày đêm với tinh thần “Quyết tử cho Tổ quốc quyết sinh”, đến đêm 17/2/1947 mới rút ra ngoài thành, tiếp tục kháng chiến. Không ít người từng đứng ở Ba Đình chiều 2/9/1945 đã nằm lại trên những con phố ấy. Tấm ảnh đen trắng vì thế ghi lại một khoảnh khắc hiếm hoi khi niềm vui của cả dân tộc còn trọn vẹn, trước chín năm kháng chiến gian khổ.","doc":7},{"loai":"anh","src":"textures/bang_w/G14_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình ngày 2/9/1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Quảng trường sau ngày ấy","text":"Quảng trường Ba Đình tiếp tục là nơi ghi dấu những mốc lớn của đất nước. Ngày 1/1/1955, ít tháng sau ngày giải phóng Thủ đô 10/10/1954, người dân Hà Nội lại tập hợp ở đây trong cuộc mít tinh chào mừng Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh về Thủ đô. Ngày 9/9/1969, cũng tại quảng trường này, lễ truy điệu Chủ tịch Hồ Chí Minh được tổ chức và bản Di chúc của Người được công bố. Sau đó, Lăng Chủ tịch Hồ Chí Minh được xây dựng bên quảng trường, khánh thành năm 1975.\n\nNgày nay, trước Lăng, lễ thượng cờ diễn ra mỗi sáng sớm và lễ hạ cờ mỗi tối, thu hút rất nhiều người dân và du khách. Mỗi dịp 2/9, người ta lại tìm về, đứng trên chính khoảng đất nơi cha ông mình từng nghe lời Tuyên ngôn. Trong gian trưng bày này, biển người năm ấy được dựng lại quanh lễ đài, để bạn có thể đứng vào chỗ của họ và nhìn về phía lễ đài như họ đã nhìn trong buổi chiều mùa thu năm 1945.","doc":8},{"loai":"ban_co_biet","text":"Theo nhiều tài liệu về lịch sử Hà Nội, người quyết định đổi tên vườn hoa Puginier thành vườn hoa Ba Đình vào mùa hè năm 1945 là bác sĩ Trần Văn Lai, Thị trưởng Hà Nội khi ấy.","nguon_ten":"VOV, “Ai đặt tên vườn hoa Ba Đình?”; Báo Người Hà Nội, “Thị trưởng Trần Văn Lai – người để lại nhiều dấu ấn cho Thủ đô Hà Nội”","doc":9}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Võ Nguyên Giáp, Những năm tháng không thể nào quên, NXB Quân đội nhân dân","Báo Công an nhân dân, “Lời thề độc lập trên quảng trường Ba Đình lịch sử”","Báo Nhân Dân, “Người phụ nữ kéo cờ Tổ quốc trong Ngày Độc lập 2-9”","VOV, “Ai đặt tên vườn hoa Ba Đình?”","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Biển người ở Ba Đình: ai đã có mặt chiều 2/9/1945?. Tấm ảnh đen trắng không ghi tên người chụp, cũng không ghi tên một ai trong đám đông. Vậy mà nó là một trong những chân dung đầy đủ nhất của dân tộc Việt Nam trong ngày Độc lập. Họ là ai, từ đâu đến, đã cùng nhau thề điều gì, và số phận họ ra sao sau buổi chiều ấy?"},{"t":"Chủ nhật, mùng 2 tháng 9. Ngày 2/9/1945 là một ngày Chủ nhật. Từ sáng sớm, Hà Nội đã rực rỡ cờ đỏ sao vàng, hoa và biểu ngữ, từ các phố phường nội thành đến những con đường dẫn về khu Ba Đình. Từng đoàn người nối nhau kéo về vườn hoa trước dinh Toàn quyền cũ. Đó là công nhân các nhà máy, nông dân các làng ngoại thành, tiểu thương phố cổ, học sinh, sinh viên, các đoàn phụ nữ, các cụ phụ lão, đồng bào thuộc mọi tầng lớp và tôn giáo. Các đội tự vệ làm nhiệm vụ giữ gìn trật tự quanh quảng trường. Nhiều người ăn mặc chỉnh tề như đi dự một ngày hội lớn của dân tộc. Các tư liệu thường ghi có hàng chục vạn người tham dự; có tư liệu ước tính tới khoảng nửa triệu người. Dù con số chính xác không thể kiểm đếm, đó là một cuộc tập hợp có quy mô hiếm thấy ở Hà Nội thời bấy giờ. Theo nhiều tư liệu, buổi lễ bắt đầu vào khoảng 14 giờ chiều. Tấm ảnh chụp quảng trường hôm ấy ghi lại chính biển người này, những con người đã rời nhà từ sáng để chờ nghe một bản tuyên bố mà họ biết sẽ thay đổi cuộc đời mình."},{"t":"Vườn hoa mang tên một cuộc khởi nghĩa. Nơi diễn ra buổi lễ vốn là một vườn hoa tròn trong khu hành chính do người Pháp quy hoạch ở phía tây thành phố. Thời thuộc địa, nơi đây mang tên Rond-point Puginier, tức vườn hoa Puginier, theo tên một giám mục người Pháp từng ở Hà Nội cuối thế kỷ XIX. Mùa hè năm 1945, chỉ ít tuần trước Cách mạng Tháng Tám, vườn hoa được đổi tên thành vườn hoa Ba Đình. Cái tên ấy nhắc nhớ cuộc khởi nghĩa Ba Đình ở Nga Sơn, Thanh Hóa, những năm 1886–1887, do Đinh Công Tráng và Phạm Bành lãnh đạo, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương chống thực dân Pháp. Chỉ ít tuần sau khi mang tên mới, vườn hoa chứng kiến ngày dân tộc tuyên bố thoát khỏi ách thực dân. Khoảng đất rộng ngay cạnh dinh Toàn quyền, trung tâm quyền lực của chế độ thuộc địa, đủ sức chứa một đám đông khổng lồ và trở thành nơi nhân dân làm chủ. Sự chuyển đổi ấy, từ tên một giáo sĩ ngoại quốc sang tên một cuộc khởi nghĩa của người Việt, như một lời báo trước cho buổi chiều mùa thu năm ấy."},{"t":"Bạn có biết? Tên Ba Đình của cuộc khởi nghĩa 1886–1887 bắt nguồn từ ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê ở Nga Sơn, Thanh Hóa, nơi nghĩa quân dựng căn cứ; mỗi làng có một ngôi đình, nên căn cứ được gọi là Ba Đình."},{"t":"Những người trong khung hình. Những gương mặt trong tấm ảnh phần lớn không được ghi tên. Nhưng chính sự vô danh ấy làm nên giá trị của bức ảnh: đây là chân dung của một dân tộc, không phải của một cá nhân. Nhiều người trong đám đông vừa sống sót qua nạn đói năm Ất Dậu, nạn đói mà chính bản Tuyên ngôn đọc chiều hôm ấy nhắc tới với hơn hai triệu đồng bào chết đói. Nhiều người khác vừa cùng nhau xông vào Phủ Khâm sai sáng 19/8, giành chính quyền ở Thủ đô. Có những người lần đầu tiên trong đời đứng trước một vị lãnh tụ mà trước đó họ chỉ nghe tên. Trong biển người ấy, có những người về sau được lịch sử nhắc tên. Theo lời kể được báo chí ghi lại, người được giao kéo lá cờ đỏ sao vàng trong nghi thức chào cờ là hai thiếu nữ Hà Nội, Lê Thi và Đàm Thị Loan. Bà Lê Thi về sau trở thành giáo sư, nhà nghiên cứu, qua đời năm 2020 ở tuổi 95; mỗi dịp Quốc khánh, câu chuyện về hai cô gái kéo cờ năm ấy vẫn được kể lại. Trên lễ đài là các thành viên Chính phủ lâm thời; dưới lễ đài là vô vàn con người bình thường mà tên tuổi chỉ còn trong ký ức gia đình."},{"t":"Lời thề của quảng trường. Sau khi Chủ tịch Hồ Chí Minh đọc xong bản Tuyên ngôn và các thành viên Chính phủ lâm thời tuyên thệ, đến lượt những người đứng dưới quảng trường. Theo các tư liệu về buổi lễ, cả biển người đồng thanh nhắc lại lời thề độc lập. Họ thề kiên quyết ủng hộ Chính phủ lâm thời và Chủ tịch Hồ Chí Minh. Nếu thực dân Pháp trở lại xâm lược thì quyết không đi lính cho Pháp, không làm việc cho Pháp, không bán lương thực cho Pháp, không đưa đường cho Pháp. Đó là những lời thề rất cụ thể, gắn với việc làm của từng người: người nông dân giữ hạt gạo, người thợ giữ đôi tay, người dân quê giữ con đường làng. Nếu bản Tuyên ngôn là lời tuyên bố của Chính phủ trước thế giới, thì lời thề này là lời cam kết của nhân dân với chính mình. Tấm ảnh chụp đám đông, vì thế, không chỉ là ảnh của những người đi dự lễ; đó là ảnh của những người vừa tự nguyện nhận lấy bổn phận giữ nước. Chỉ ít tháng sau, lời thề ấy bắt đầu được thử thách bằng máu, trước tiên ở Nam Bộ, rồi ở chính Thủ đô."},{"t":"Tấm ảnh không tên tác giả. Tấm ảnh được lưu truyền đến nay không ghi tên người chụp. Ngày ấy, một số nhiếp ảnh gia Hà Nội đã có mặt để ghi lại buổi lễ; nhiều bức ảnh của họ về sau được lưu giữ trong các cơ quan lưu trữ, bảo tàng và được in lại vô số lần trên sách báo. Nhưng không ít tấm đến nay không xác định được tác giả, và tấm ảnh này là một trong số đó. Máy ảnh thời ấy còn nặng nề, phim hiếm, mỗi lần bấm máy đều phải cân nhắc; vậy mà những người cầm máy vẫn để lại cho hậu thế những khung hình quý giá về ngày hội non sông. Ngày nay, bức ảnh thuộc phạm vi công cộng và được giới thiệu rộng rãi, trở thành một trong những hình ảnh quen thuộc nhất về ngày Độc lập. Cùng với ảnh toàn cảnh lễ đài và ảnh Chủ tịch Hồ Chí Minh đọc Tuyên ngôn, nó giúp các thế hệ sau hình dung trọn vẹn buổi chiều lịch sử. Trong đó không chỉ có người đứng trên lễ đài, mà có cả những người đứng dưới, những người đã làm nên ý nghĩa của từng lời Tuyên ngôn."},{"t":"Họ đi đâu sau buổi chiều ấy. Niềm vui ở Ba Đình trọn vẹn được ít ngày. Ba tuần sau, ngày 23/9/1945, tiếng súng xâm lược nổ ở Sài Gòn; nhiều thanh niên Hà Nội đã xung phong vào những đoàn quân Nam tiến. Những tháng tiếp theo, người Hà Nội lại có mặt trong Tuần lễ Vàng, trong các lớp bình dân học vụ, trong ngày bỏ phiếu 6/1/1946 (xem các chuyên đề cùng gian). Rồi đêm 19/12/1946, khi toàn quốc kháng chiến bùng nổ, chính người dân Thủ đô đã biến phố phường thành chiến lũy. Tự vệ, Vệ quốc quân cùng nhân dân Hà Nội chiến đấu suốt sáu mươi ngày đêm với tinh thần “Quyết tử cho Tổ quốc quyết sinh”, đến đêm 17/2/1947 mới rút ra ngoài thành, tiếp tục kháng chiến. Không ít người từng đứng ở Ba Đình chiều 2/9/1945 đã nằm lại trên những con phố ấy. Tấm ảnh đen trắng vì thế ghi lại một khoảnh khắc hiếm hoi khi niềm vui của cả dân tộc còn trọn vẹn, trước chín năm kháng chiến gian khổ."},{"t":"Quảng trường sau ngày ấy. Quảng trường Ba Đình tiếp tục là nơi ghi dấu những mốc lớn của đất nước. Ngày 1/1/1955, ít tháng sau ngày giải phóng Thủ đô 10/10/1954, người dân Hà Nội lại tập hợp ở đây trong cuộc mít tinh chào mừng Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh về Thủ đô. Ngày 9/9/1969, cũng tại quảng trường này, lễ truy điệu Chủ tịch Hồ Chí Minh được tổ chức và bản Di chúc của Người được công bố. Sau đó, Lăng Chủ tịch Hồ Chí Minh được xây dựng bên quảng trường, khánh thành năm 1975. Ngày nay, trước Lăng, lễ thượng cờ diễn ra mỗi sáng sớm và lễ hạ cờ mỗi tối, thu hút rất nhiều người dân và du khách. Mỗi dịp 2/9, người ta lại tìm về, đứng trên chính khoảng đất nơi cha ông mình từng nghe lời Tuyên ngôn. Trong gian trưng bày này, biển người năm ấy được dựng lại quanh lễ đài, để bạn có thể đứng vào chỗ của họ và nhìn về phía lễ đài như họ đã nhìn trong buổi chiều mùa thu năm 1945."},{"t":"Bạn có biết? Theo nhiều tài liệu về lịch sử Hà Nội, người quyết định đổi tên vườn hoa Puginier thành vườn hoa Ba Đình vào mùa hè năm 1945 là bác sĩ Trần Văn Lai, Thị trưởng Hà Nội khi ấy."}],"so_chu":1586},{"i":5,"tieu_de_bang":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, 2/9/1945","tieu_de":"“Tôi nói, đồng bào nghe rõ không?”: khoảnh khắc trên lễ đài Ba Đình","sapo":"Trong tấm ảnh đen trắng, vị Chủ tịch nước đứng trên lễ đài giữa biển người, trong bộ áo ka-ki giản dị. Không ai dưới quảng trường hôm ấy biết rằng giữa bài đọc, Người sẽ dừng lại để hỏi một câu không hề có trong văn bản. Ai đã bấm máy ghi lại khoảnh khắc ấy, ai đã quay những thước phim còn lại đến hôm nay — và vì sao một câu hỏi giản dị lại trở thành ký ức chung của cả dân tộc?","bia":{"src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hai giờ chiều, một người bước tới trước micro","text":"Chiều Chủ nhật 2/9/1945, theo nhiều tư liệu vào khoảng 14 giờ, lá cờ đỏ sao vàng được kéo lên giữa Quảng trường Ba Đình trong tiếng hát Tiến quân ca. Trên lễ đài khung gỗ, các thành viên Chính phủ lâm thời đứng thành hàng. Rồi một người bước tới trước micro. Trong hồi ký “Những năm tháng không thể nào quên”, Đại tướng Võ Nguyên Giáp tả lại hình ảnh ấy. Đó là một cụ già gầy gò, trán cao, mắt sáng, râu thưa, đội chiếc mũ đã cũ, mặc bộ áo ka-ki cao cổ, chân đi đôi dép cao su trắng.\n\nVới phần đông trong hàng chục vạn người đứng chật quảng trường và các ngả phố xung quanh, đó là lần đầu tiên họ được nhìn thấy vị Chủ tịch của nước mình. Cái tên Hồ Chí Minh mới được dùng từ tháng 8/1942. Theo nhiều tư liệu, khi ấy không ít người chưa biết con người đứng trên lễ đài chính là Nguyễn Ái Quốc, cái tên đã gắn với phong trào yêu nước từ hơn hai mươi năm trước. Bức ảnh tư liệu của bảng này ghi lại đúng giờ phút ấy: vị Chủ tịch đứng trên lễ đài, đọc bản Tuyên ngôn Độc lập trước quốc dân.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập trên lễ đài Quảng trường Ba Đình, chiều 2/9/1945. Ảnh được lưu hành với dòng nguồn “Front pour l'indépendance du Việt-Nam”, tức Mặt trận Việt Minh.","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một vị Chủ tịch không lễ phục, không gươm vàng","text":"Hình ảnh ấy khác hẳn những gì người Hà Nội từng quen thấy ở các nghi lễ quyền lực. Suốt thời thuộc địa, quan chức cai trị xuất hiện trong lễ phục, đeo gươm, có lính bồng súng đứng hầu. Ở Huế, chỉ ba ngày trước, vua Bảo Đại mới thoái vị tại Ngọ Môn, khép lại chế độ quân chủ cùng long bào và ấn kiếm (xem chuyên đề Mốc thời gian).\n\nVị Chủ tịch nước đầu tiên của Việt Nam độc lập không mặc lễ phục. Bộ quần áo ka-ki và đôi dép cao su là trang phục của một người vừa từ chiến khu Tân Trào trở về. Đó cũng là một thông điệp không cần lời: chính quyền mới là chính quyền của dân, người đứng đầu nó sống như người dân. Sự giản dị ấy không phải lựa chọn nhất thời cho một ngày lễ. Suốt những năm về sau, ở Bắc Bộ phủ, ở núi rừng Việt Bắc, rồi trong ngôi nhà sàn ở Phủ Chủ tịch, Người vẫn giữ nếp sống như thế. Đôi dép cao su dần trở thành một trong những hình ảnh quen thuộc nhất gắn với Người, được nhắc đến trong thơ ca, âm nhạc và trong ký ức của bao thế hệ.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, 2/9/1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"“Hỡi đồng bào cả nước”","text":"Bản Tuyên ngôn mở đầu bằng lời gọi: “Hỡi đồng bào cả nước”. Hôm nay ta nghe lời ấy thật quen, nhưng vào năm 1945 nó mang một sức nặng khác. Hơn tám mươi năm, người dân xứ này bị gọi là “dân bản xứ”, là “người An Nam” trong giấy tờ của chính quyền thuộc địa, là “thần dân” trước ngai vàng. Chữ “đồng bào”, những người cùng chung một bọc, gợi nhớ truyền thuyết mẹ Âu Cơ, đặt mọi người đứng dưới quảng trường ngang hàng nhau, không phân biệt giàu nghèo, sang hèn, lương hay giáo.\n\nNội dung bản Tuyên ngôn, từ những lời trích tuyên ngôn của nước Mỹ và của Cách mạng Pháp đến bản cáo trạng tội ác thực dân, được phân tích kỹ trong chuyên đề Bản Tuyên ngôn Độc lập. Ở đây, điều đáng chú ý là cách văn kiện ấy đến với người nghe. Không có đài phát thanh truyền đi khắp nước, không có màn hình lớn. Chỉ có một chiếc micro trên lễ đài, những chiếc loa phóng thanh dựng quanh quảng trường, và giọng nói xứ Nghệ của vị Chủ tịch vang tới những hàng người đứng xa nhất.","doc":3},{"loai":"doan","tieu_de":"Một câu hỏi không có trong văn bản","text":"Đang đọc, Người bỗng ngừng lại và hỏi đồng bào một câu không có trong bản thảo. Theo lời kể của nhiều người có mặt, cả quảng trường đồng thanh đáp lại. Rồi Người đọc tiếp, và buổi lễ trở lại nhịp trang nghiêm của nó.\n\nCâu hỏi ấy không có trong bản thảo viết trên căn gác Hàng Ngang, cũng không có trong văn bản Tuyên ngôn được lưu giữ đến nay. Vậy mà nó trở thành một trong những câu nói được nhắc lại nhiều nhất của ngày Độc lập, đến mức được chọn làm lời đề từ cho chính gian trưng bày này. Sức nặng của nó nằm ở sự giản dị. Giữa giờ phút long trọng nhất, khi một quốc gia đang tuyên bố sự ra đời của mình với thế giới, người đứng đầu quốc gia ấy lo trước hết một điều rất cụ thể. Đó là những người đứng ở cuối quảng trường có nghe thấy không. Với nhiều người dự lễ, từ phút ấy lễ đài không còn là nơi cao xa. Vị Chủ tịch đang trò chuyện với họ và chờ họ trả lời. Lối nói hỏi – đáp gần gũi ấy về sau trở thành nét quen thuộc trong nhiều buổi Người nói chuyện với đồng bào, bộ đội.","doc":4},{"loai":"trich","text":"Tôi nói, đồng bào nghe rõ không?","nguoi":"Chủ tịch Hồ Chí Minh, trên lễ đài Quảng trường Ba Đình, chiều 2/9/1945","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":5},{"loai":"doan","tieu_de":"Người bấm máy trước lễ đài","text":"Những bức ảnh chụp Chủ tịch Hồ Chí Minh trên lễ đài chiều hôm ấy nay là tư liệu vô giá, nhưng tên người chụp từng tấm không phải lúc nào cũng được ghi rõ. Tấm ảnh của bảng này được lưu hành với dòng nguồn bằng tiếng Pháp “Front pour l'indépendance du Việt-Nam”, tức Mặt trận Việt Minh. Điều đó cho thấy nó từng được phổ biến như một tư liệu tuyên truyền của chính quyền cách mạng trong những ngày đầu.\n\nTrong số các nhà nhiếp ảnh có mặt, báo chí thường nhắc tới nghệ sĩ Nguyễn Bá Khoản (1917–1993), quê Thường Tín, tỉnh Hà Tây cũ. Theo Báo Thái Nguyên, thời ấy chưa có ống kính chụp xa, nên ông phải chọn chỗ đứng, căn góc máy và ánh sáng thật kỹ. Ông kể lại: “Bình tĩnh, tôi bấm liền mấy kiểu với những tốc độ khác nhau”. Ngoài khoảnh khắc Người đọc Tuyên ngôn, ông còn chụp đội danh dự, đoàn người diễu hành, và tráng phim ngay trong ngày 2/9. Theo ghi chú tư liệu, nhà nhiếp ảnh Võ An Ninh cũng bấm máy trong ngày lịch sử ấy (xem chuyên đề Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945).","doc":6},{"loai":"ban_co_biet","text":"Theo Báo Thái Nguyên, những bức ảnh Nguyễn Bá Khoản chụp chiều 2/9/1945 được trưng bày lần đầu ngày 19/8/1946 tại nhà triển lãm Tràng Tiền, Hà Nội, đúng dịp kỷ niệm một năm Cách mạng Tháng Tám. Năm 1990, ông trao tặng Trung tâm Lưu trữ quốc gia khoảng hai nghìn tác phẩm ảnh của mình.","nguon_ten":"Báo Thái Nguyên, “Nhớ người chụp bức ảnh lịch sử Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập”, 2/9/2018","doc":7},{"loai":"doan","tieu_de":"Những thước phim chưa rõ người quay","text":"Không chỉ có ảnh. Buổi lễ còn được ghi lại trên phim, nhưng người quay đến nay vẫn là một câu hỏi. Trong một bài viết đăng trên tạp chí Nghệ thuật Điện ảnh năm 1990, được báo Dân trí dẫn lại, đạo diễn Đặng Nhật Minh nêu hai giả thiết. Giả thiết thứ nhất nhắc tới ông Hương Ký, chủ một hiệu ảnh ở Hà Nội, người được giao quay buổi lễ nhưng sau đó báo lại rằng máy móc gặp sự cố, không quay được.\n\nGiả thiết thứ hai, được tác giả cho là có căn cứ hơn, hướng tới những thành viên phái bộ Mỹ do Archimedes Patti dẫn đầu. Khi ấy họ đang có mặt ở Hà Nội và có thể đi lại khắp quảng trường mà không ai để ý. Đáng chú ý, lời kể của nhà nhiếp ảnh Nguyễn Bá Khoản, được Báo Thái Nguyên thuật lại, cũng nhắc tới một người nước ngoài cao lớn. Người ấy mặc đồ sáng màu, đội mũ, đặt máy quay trên chân ba càng ở phía bên phải lễ đài. Dù người quay là ai, những thước phim ấy đã giữ lại hình ảnh vị Chủ tịch đọc bản Tuyên ngôn cho các thế hệ về sau.","doc":8},{"loai":"anh","src":"textures/bang_w/G14_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, 2/9/1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Sau lời đọc là những lời thề","text":"Khi Người đọc xong câu kết của bản Tuyên ngôn (xem chuyên đề Lời Bác), buổi lễ chuyển sang phần tuyên thệ. Các thành viên Chính phủ lâm thời thề trước quốc dân, nguyện lãnh đạo nhân dân giữ vững nền độc lập vừa giành được. Theo nhiều tư liệu, Bộ trưởng Bộ Nội vụ Võ Nguyên Giáp sau đó thay mặt Chính phủ phát biểu, nói về tình hình đất nước và những chính sách lớn của chính quyền mới.\n\nĐứng đầu Ban tổ chức Lễ Độc lập là ông Nguyễn Hữu Đang. Mọi việc, từ lễ đài, cờ hoa, loa phóng thanh đến việc tập hợp và giữ trật tự cho hàng chục vạn người, được chuẩn bị chỉ trong khoảng một tuần. Lực lượng tự vệ và thanh niên làm nòng cốt, trong khi quân Nhật vẫn còn đóng trong thành phố. Buổi lễ diễn ra trọn vẹn. Những ngày sau, toàn văn bản Tuyên ngôn được in trên báo chí cách mạng và truyền đi các địa phương, để những người không có mặt ở Ba Đình cũng được đọc, được nghe lời tuyên bố độc lập của dân tộc mình.","doc":9},{"loai":"ban_co_biet","text":"Đài Tiếng nói Việt Nam phát sóng buổi đầu tiên ngày 7/9/1945, năm ngày sau lễ Độc lập, với lời xướng: “Đây là Tiếng nói Việt Nam, phát thanh từ Hà Nội, thủ đô nước Việt Nam Dân chủ Cộng hòa”. Chiều 2/9, giọng đọc Tuyên ngôn mới chỉ vang qua những chiếc loa quanh quảng trường.","nguon_ten":"Đài Tiếng nói Việt Nam","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Lễ đài năm 1945 chỉ là công trình tạm và không còn đến ngày nay. Quảng trường Ba Đình hôm nay, với Lăng Chủ tịch Hồ Chí Minh và cột cờ giữa quảng trường, là nơi diễn ra lễ chào cờ mỗi sáng và những dịp lễ lớn của đất nước, trong đó có Quốc khánh 2/9. Nhiều bức ảnh về ngày Độc lập đang được bảo quản trong hệ thống Lưu trữ quốc gia, nhờ những nhà nhiếp ảnh như Nguyễn Bá Khoản đã giữ gìn và trao tặng phim, ảnh của mình. Ảnh và tư liệu về buổi lễ cũng thường xuyên được giới thiệu tại Bảo tàng Hồ Chí Minh.\n\nTrong gian trưng bày 3D, lễ đài được dựng lại dựa trên ảnh tư liệu và những mô tả còn lưu lại: khung gỗ khoác vải, phông nền phía sau, loa phóng thanh hướng ra quảng trường. Đứng trước lễ đài, bạn có thể hình dung mình là một người trong đám đông chiều hôm ấy, lắng nghe giọng đọc qua loa và bất ngờ được hỏi một câu. Tấm ảnh trên bảng này nhắc rằng nền độc lập không chỉ được tuyên bố bằng văn bản, mà bằng cả một cuộc trò chuyện giữa người đứng đầu đất nước và nhân dân.","doc":11},{"loai":"anh","src":"textures/bang_w/G14_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, 2/9/1945”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký)","Báo Thái Nguyên – Nhớ người chụp bức ảnh lịch sử Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập (2/9/2018): https://baothainguyen.vn/chinh-tri/201809/nho-nguoi-chup-buc-anh-lich-su-chu-tich-ho-chi-minh-doc-tuyen-ngon-doc-lap-367A524/","Báo Dân trí – Bí ẩn về những thước phim quay Lễ Độc lập mùng 2/9/1945 (dẫn bài của đạo diễn Đặng Nhật Minh, 1990): https://dantri.com.vn/van-hoa/bi-an-ve-nhung-thuoc-phim-quay-le-doc-lap-mung-291945-1409145151.htm","Bảo tàng Hồ Chí Minh","Đài Tiếng nói Việt Nam"],"doc":[{"t":"“Tôi nói, đồng bào nghe rõ không?”: khoảnh khắc trên lễ đài Ba Đình. Trong tấm ảnh đen trắng, vị Chủ tịch nước đứng trên lễ đài giữa biển người, trong bộ áo ka-ki giản dị. Không ai dưới quảng trường hôm ấy biết rằng giữa bài đọc, Người sẽ dừng lại để hỏi một câu không hề có trong văn bản. Ai đã bấm máy ghi lại khoảnh khắc ấy, ai đã quay những thước phim còn lại đến hôm nay — và vì sao một câu hỏi giản dị lại trở thành ký ức chung của cả dân tộc?"},{"t":"Hai giờ chiều, một người bước tới trước micro. Chiều Chủ nhật 2/9/1945, theo nhiều tư liệu vào khoảng 14 giờ, lá cờ đỏ sao vàng được kéo lên giữa Quảng trường Ba Đình trong tiếng hát Tiến quân ca. Trên lễ đài khung gỗ, các thành viên Chính phủ lâm thời đứng thành hàng. Rồi một người bước tới trước micro. Trong hồi ký “Những năm tháng không thể nào quên”, Đại tướng Võ Nguyên Giáp tả lại hình ảnh ấy. Đó là một cụ già gầy gò, trán cao, mắt sáng, râu thưa, đội chiếc mũ đã cũ, mặc bộ áo ka-ki cao cổ, chân đi đôi dép cao su trắng. Với phần đông trong hàng chục vạn người đứng chật quảng trường và các ngả phố xung quanh, đó là lần đầu tiên họ được nhìn thấy vị Chủ tịch của nước mình. Cái tên Hồ Chí Minh mới được dùng từ tháng 8/1942. Theo nhiều tư liệu, khi ấy không ít người chưa biết con người đứng trên lễ đài chính là Nguyễn Ái Quốc, cái tên đã gắn với phong trào yêu nước từ hơn hai mươi năm trước. Bức ảnh tư liệu của bảng này ghi lại đúng giờ phút ấy: vị Chủ tịch đứng trên lễ đài, đọc bản Tuyên ngôn Độc lập trước quốc dân."},{"t":"Một vị Chủ tịch không lễ phục, không gươm vàng. Hình ảnh ấy khác hẳn những gì người Hà Nội từng quen thấy ở các nghi lễ quyền lực. Suốt thời thuộc địa, quan chức cai trị xuất hiện trong lễ phục, đeo gươm, có lính bồng súng đứng hầu. Ở Huế, chỉ ba ngày trước, vua Bảo Đại mới thoái vị tại Ngọ Môn, khép lại chế độ quân chủ cùng long bào và ấn kiếm (xem chuyên đề Mốc thời gian). Vị Chủ tịch nước đầu tiên của Việt Nam độc lập không mặc lễ phục. Bộ quần áo ka-ki và đôi dép cao su là trang phục của một người vừa từ chiến khu Tân Trào trở về. Đó cũng là một thông điệp không cần lời: chính quyền mới là chính quyền của dân, người đứng đầu nó sống như người dân. Sự giản dị ấy không phải lựa chọn nhất thời cho một ngày lễ. Suốt những năm về sau, ở Bắc Bộ phủ, ở núi rừng Việt Bắc, rồi trong ngôi nhà sàn ở Phủ Chủ tịch, Người vẫn giữ nếp sống như thế. Đôi dép cao su dần trở thành một trong những hình ảnh quen thuộc nhất gắn với Người, được nhắc đến trong thơ ca, âm nhạc và trong ký ức của bao thế hệ."},{"t":"“Hỡi đồng bào cả nước”. Bản Tuyên ngôn mở đầu bằng lời gọi: “Hỡi đồng bào cả nước”. Hôm nay ta nghe lời ấy thật quen, nhưng vào năm 1945 nó mang một sức nặng khác. Hơn tám mươi năm, người dân xứ này bị gọi là “dân bản xứ”, là “người An Nam” trong giấy tờ của chính quyền thuộc địa, là “thần dân” trước ngai vàng. Chữ “đồng bào”, những người cùng chung một bọc, gợi nhớ truyền thuyết mẹ Âu Cơ, đặt mọi người đứng dưới quảng trường ngang hàng nhau, không phân biệt giàu nghèo, sang hèn, lương hay giáo. Nội dung bản Tuyên ngôn, từ những lời trích tuyên ngôn của nước Mỹ và của Cách mạng Pháp đến bản cáo trạng tội ác thực dân, được phân tích kỹ trong chuyên đề Bản Tuyên ngôn Độc lập. Ở đây, điều đáng chú ý là cách văn kiện ấy đến với người nghe. Không có đài phát thanh truyền đi khắp nước, không có màn hình lớn. Chỉ có một chiếc micro trên lễ đài, những chiếc loa phóng thanh dựng quanh quảng trường, và giọng nói xứ Nghệ của vị Chủ tịch vang tới những hàng người đứng xa nhất."},{"t":"Một câu hỏi không có trong văn bản. Đang đọc, Người bỗng ngừng lại và hỏi đồng bào một câu không có trong bản thảo. Theo lời kể của nhiều người có mặt, cả quảng trường đồng thanh đáp lại. Rồi Người đọc tiếp, và buổi lễ trở lại nhịp trang nghiêm của nó. Câu hỏi ấy không có trong bản thảo viết trên căn gác Hàng Ngang, cũng không có trong văn bản Tuyên ngôn được lưu giữ đến nay. Vậy mà nó trở thành một trong những câu nói được nhắc lại nhiều nhất của ngày Độc lập, đến mức được chọn làm lời đề từ cho chính gian trưng bày này. Sức nặng của nó nằm ở sự giản dị. Giữa giờ phút long trọng nhất, khi một quốc gia đang tuyên bố sự ra đời của mình với thế giới, người đứng đầu quốc gia ấy lo trước hết một điều rất cụ thể. Đó là những người đứng ở cuối quảng trường có nghe thấy không. Với nhiều người dự lễ, từ phút ấy lễ đài không còn là nơi cao xa. Vị Chủ tịch đang trò chuyện với họ và chờ họ trả lời. Lối nói hỏi – đáp gần gũi ấy về sau trở thành nét quen thuộc trong nhiều buổi Người nói chuyện với đồng bào, bộ đội."},{"t":"Tôi nói, đồng bào nghe rõ không? — Chủ tịch Hồ Chí Minh, trên lễ đài Quảng trường Ba Đình, chiều 2/9/1945"},{"t":"Người bấm máy trước lễ đài. Những bức ảnh chụp Chủ tịch Hồ Chí Minh trên lễ đài chiều hôm ấy nay là tư liệu vô giá, nhưng tên người chụp từng tấm không phải lúc nào cũng được ghi rõ. Tấm ảnh của bảng này được lưu hành với dòng nguồn bằng tiếng Pháp “Front pour l'indépendance du Việt-Nam”, tức Mặt trận Việt Minh. Điều đó cho thấy nó từng được phổ biến như một tư liệu tuyên truyền của chính quyền cách mạng trong những ngày đầu. Trong số các nhà nhiếp ảnh có mặt, báo chí thường nhắc tới nghệ sĩ Nguyễn Bá Khoản (1917–1993), quê Thường Tín, tỉnh Hà Tây cũ. Theo Báo Thái Nguyên, thời ấy chưa có ống kính chụp xa, nên ông phải chọn chỗ đứng, căn góc máy và ánh sáng thật kỹ. Ông kể lại: “Bình tĩnh, tôi bấm liền mấy kiểu với những tốc độ khác nhau”. Ngoài khoảnh khắc Người đọc Tuyên ngôn, ông còn chụp đội danh dự, đoàn người diễu hành, và tráng phim ngay trong ngày 2/9. Theo ghi chú tư liệu, nhà nhiếp ảnh Võ An Ninh cũng bấm máy trong ngày lịch sử ấy (xem chuyên đề Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945)."},{"t":"Bạn có biết? Theo Báo Thái Nguyên, những bức ảnh Nguyễn Bá Khoản chụp chiều 2/9/1945 được trưng bày lần đầu ngày 19/8/1946 tại nhà triển lãm Tràng Tiền, Hà Nội, đúng dịp kỷ niệm một năm Cách mạng Tháng Tám. Năm 1990, ông trao tặng Trung tâm Lưu trữ quốc gia khoảng hai nghìn tác phẩm ảnh của mình."},{"t":"Những thước phim chưa rõ người quay. Không chỉ có ảnh. Buổi lễ còn được ghi lại trên phim, nhưng người quay đến nay vẫn là một câu hỏi. Trong một bài viết đăng trên tạp chí Nghệ thuật Điện ảnh năm 1990, được báo Dân trí dẫn lại, đạo diễn Đặng Nhật Minh nêu hai giả thiết. Giả thiết thứ nhất nhắc tới ông Hương Ký, chủ một hiệu ảnh ở Hà Nội, người được giao quay buổi lễ nhưng sau đó báo lại rằng máy móc gặp sự cố, không quay được. Giả thiết thứ hai, được tác giả cho là có căn cứ hơn, hướng tới những thành viên phái bộ Mỹ do Archimedes Patti dẫn đầu. Khi ấy họ đang có mặt ở Hà Nội và có thể đi lại khắp quảng trường mà không ai để ý. Đáng chú ý, lời kể của nhà nhiếp ảnh Nguyễn Bá Khoản, được Báo Thái Nguyên thuật lại, cũng nhắc tới một người nước ngoài cao lớn. Người ấy mặc đồ sáng màu, đội mũ, đặt máy quay trên chân ba càng ở phía bên phải lễ đài. Dù người quay là ai, những thước phim ấy đã giữ lại hình ảnh vị Chủ tịch đọc bản Tuyên ngôn cho các thế hệ về sau."},{"t":"Sau lời đọc là những lời thề. Khi Người đọc xong câu kết của bản Tuyên ngôn (xem chuyên đề Lời Bác), buổi lễ chuyển sang phần tuyên thệ. Các thành viên Chính phủ lâm thời thề trước quốc dân, nguyện lãnh đạo nhân dân giữ vững nền độc lập vừa giành được. Theo nhiều tư liệu, Bộ trưởng Bộ Nội vụ Võ Nguyên Giáp sau đó thay mặt Chính phủ phát biểu, nói về tình hình đất nước và những chính sách lớn của chính quyền mới. Đứng đầu Ban tổ chức Lễ Độc lập là ông Nguyễn Hữu Đang. Mọi việc, từ lễ đài, cờ hoa, loa phóng thanh đến việc tập hợp và giữ trật tự cho hàng chục vạn người, được chuẩn bị chỉ trong khoảng một tuần. Lực lượng tự vệ và thanh niên làm nòng cốt, trong khi quân Nhật vẫn còn đóng trong thành phố. Buổi lễ diễn ra trọn vẹn. Những ngày sau, toàn văn bản Tuyên ngôn được in trên báo chí cách mạng và truyền đi các địa phương, để những người không có mặt ở Ba Đình cũng được đọc, được nghe lời tuyên bố độc lập của dân tộc mình."},{"t":"Bạn có biết? Đài Tiếng nói Việt Nam phát sóng buổi đầu tiên ngày 7/9/1945, năm ngày sau lễ Độc lập, với lời xướng: “Đây là Tiếng nói Việt Nam, phát thanh từ Hà Nội, thủ đô nước Việt Nam Dân chủ Cộng hòa”. Chiều 2/9, giọng đọc Tuyên ngôn mới chỉ vang qua những chiếc loa quanh quảng trường."},{"t":"Dấu tích hôm nay. Lễ đài năm 1945 chỉ là công trình tạm và không còn đến ngày nay. Quảng trường Ba Đình hôm nay, với Lăng Chủ tịch Hồ Chí Minh và cột cờ giữa quảng trường, là nơi diễn ra lễ chào cờ mỗi sáng và những dịp lễ lớn của đất nước, trong đó có Quốc khánh 2/9. Nhiều bức ảnh về ngày Độc lập đang được bảo quản trong hệ thống Lưu trữ quốc gia, nhờ những nhà nhiếp ảnh như Nguyễn Bá Khoản đã giữ gìn và trao tặng phim, ảnh của mình. Ảnh và tư liệu về buổi lễ cũng thường xuyên được giới thiệu tại Bảo tàng Hồ Chí Minh. Trong gian trưng bày 3D, lễ đài được dựng lại dựa trên ảnh tư liệu và những mô tả còn lưu lại: khung gỗ khoác vải, phông nền phía sau, loa phóng thanh hướng ra quảng trường. Đứng trước lễ đài, bạn có thể hình dung mình là một người trong đám đông chiều hôm ấy, lắng nghe giọng đọc qua loa và bất ngờ được hỏi một câu. Tấm ảnh trên bảng này nhắc rằng nền độc lập không chỉ được tuyên bố bằng văn bản, mà bằng cả một cuộc trò chuyện giữa người đứng đầu đất nước và nhân dân."}],"so_chu":1883},{"i":6,"tieu_de_bang":"Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945","tieu_de":"Người thầy và người học trò: Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp năm 1945","sapo":"Trong tấm ảnh năm 1945, vị Chủ tịch nước năm mươi lăm tuổi đứng bên người Bộ trưởng Bộ Nội vụ vừa bước sang tuổi ba mươi tư. Năm năm trước, họ mới gặp nhau lần đầu ở Côn Minh, bên kia biên giới. Giữa hai khoảnh khắc ấy là những năm ở Cao Bằng, là khu rừng nơi ba mươi tư chiến sĩ làm lễ thành lập đội, và một lời dặn giữa cơn sốt ở Tân Trào mà người học trò nhớ suốt đời.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_and_vo_nguyen_giap_1945.jpg","credit":"Ảnh: An Ninh Võ · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hai người trong một khung hình","text":"Tấm ảnh được ghi tác giả là nghệ sĩ nhiếp ảnh Võ An Ninh, và theo ghi chú của tư liệu, được chụp ngày 2/9/1945, ngày lập quốc. Trong khung hình là hai con người sẽ gắn tên tuổi với nhau suốt mấy chục năm lịch sử. Đó là Chủ tịch Hồ Chí Minh, người vừa đọc bản Tuyên ngôn Độc lập, và Võ Nguyên Giáp, Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời.\n\nNăm ấy, Người năm mươi lăm tuổi. Võ Nguyên Giáp sinh ngày 25/8/1911, vừa bước sang tuổi ba mươi tư ít ngày trước buổi lễ. Khoảng cách tuổi tác giữa hai người xấp xỉ một thế hệ, và quan hệ giữa họ thường được nhắc tới như quan hệ thầy – trò. Chính Đại tướng, trong những hồi ký viết về sau, luôn coi Người là người thầy lớn đã dìu dắt mình từ một nhà giáo dạy sử trở thành người cầm quân. Nhưng để hiểu vì sao hai người cùng đứng trong khung hình năm 1945, phải lùi lại năm năm, tới một thành phố bên kia biên giới phía bắc.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_and_vo_nguyen_giap_1945.jpg","chu_thich":"Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời, năm 1945. Ảnh được ghi tác giả Võ An Ninh.","credit":"Ảnh: An Ninh Võ · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Côn Minh, mùa hè năm 1940","text":"Tháng 6/1940, Võ Nguyên Giáp khi ấy là thầy giáo dạy lịch sử ở trường tư thục Thăng Long, Hà Nội, và đã có nhiều năm hoạt động cách mạng. Trước sự khủng bố ngày càng gắt gao của chính quyền thực dân, ông cùng Phạm Văn Đồng được tổ chức đưa sang Trung Quốc. Ở Côn Minh, tỉnh lỵ Vân Nam, hai người lần đầu gặp Nguyễn Ái Quốc, người mà trước đó họ chỉ biết qua tài liệu và những lời truyền tụng.\n\nTheo hồi ký “Từ nhân dân mà ra” của Đại tướng, Người dự định gửi hai ông sang Diên An, căn cứ của Đảng Cộng sản Trung Quốc, để học tập, và khuyên Võ Nguyên Giáp nên chú tâm học quân sự. Nhưng khi hai ông còn đang chờ lên đường thì tin nước Pháp bại trận trước phát xít Đức truyền tới. Người nhận định đây là thời cơ thuận lợi cho cách mạng Việt Nam, liền cho gọi hai ông quay lại để chuẩn bị về nước. Lời khuyên học quân sự năm ấy, nhìn lại về sau, như một dự báo về con đường của người thầy giáo dạy sử.","doc":2},{"loai":"doan","tieu_de":"Những năm ở Cao Bằng","text":"Ngày 28/1/1941, Nguyễn Ái Quốc về nước qua cột mốc 108 và đặt cơ quan ở Pác Bó. Võ Nguyên Giáp cùng các đồng chí được Người giao công việc ở Cao Bằng: mở các lớp huấn luyện chính trị ngắn ngày, xây dựng cơ sở Việt Minh trong đồng bào Tày, Nùng, Dao, Mông. Ông mang bí danh Văn; về sau bộ đội và đồng bào thân mật gọi ông là “anh Văn”.\n\nTrong thời gian Người bị chính quyền Tưởng Giới Thạch bắt giam ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1944, các cán bộ ở Cao Bằng vẫn tiếp tục những việc Người đã vạch ra. Năm 1943, Võ Nguyên Giáp phụ trách các đội xung phong Nam tiến, mở đường nối căn cứ Cao Bằng với căn cứ Bắc Sơn – Võ Nhai. Trên nền tảng những cơ sở được gây dựng bền bỉ trong mấy năm ấy, tháng 6/1945 Khu giải phóng Việt Bắc ra đời, với trung tâm là Tân Trào.","doc":3},{"loai":"ban_co_biet","text":"Theo hồi ký của Đại tướng Võ Nguyên Giáp, trong thời gian Người bị giam ở Quảng Tây, có lúc tin Người đã mất trong tù truyền về Cao Bằng, các đồng chí ở nhà đã làm lễ truy điệu. Ít lâu sau, họ mới nhận được mấy dòng chữ viết tay của Người gửi về, báo tin Người vẫn bình an.","nguon_ten":"Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký)","doc":4},{"loai":"doan","tieu_de":"Khu rừng Trần Hưng Đạo","text":"Tháng 9/1944, Người trở lại Pác Bó. Lúc ấy, liên tỉnh Cao – Bắc – Lạng đang chuẩn bị phát động khởi nghĩa. Nghe báo cáo, Người cho rằng thời cơ khởi nghĩa toàn dân chưa tới, nếu nổ ra sớm lực lượng cách mạng sẽ bị kẻ thù tập trung đàn áp, và quyết định đình chỉ kế hoạch. Thay vào đó, Người chủ trương lập một đội vũ trang tập trung, vừa chiến đấu vừa tuyên truyền, và giao cho Võ Nguyên Giáp tổ chức.\n\nNgày 22/12/1944, tại khu rừng Trần Hưng Đạo thuộc Nguyên Bình, Cao Bằng, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời với 34 chiến sĩ, do Võ Nguyên Giáp trực tiếp chỉ huy. Trong bản chỉ thị thành lập đội, Người viết: “Tên Đội Việt Nam Tuyên truyền Giải phóng quân nghĩa là chính trị trọng hơn quân sự. Nó là đội tuyên truyền”. Chỉ vài ngày sau, đội đánh thắng hai trận đầu tiên ở Phai Khắt và Nà Ngần. Đội quân nhỏ bé ấy là tiền thân của Quân đội nhân dân Việt Nam, và người chỉ huy đầu tiên của nó chính là thầy giáo dạy sử năm nào.","doc":5},{"loai":"anh","src":"textures/bang_w/G14_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Tân Trào, những ngày Người ốm nặng","text":"Tháng 5/1945, Người rời Cao Bằng về Tân Trào, Tuyên Quang. Võ Nguyên Giáp ở bên Người trong những tháng quyết định ấy. Khoảng cuối tháng 7/1945, Người lên cơn sốt nặng, nhiều lúc mê man, trong căn lán nhỏ ở rừng Nà Lừa. Theo hồi ký của Đại tướng, một ông lang người Tày trong vùng đã dùng thuốc nam chữa, và Người dần qua khỏi.\n\nTrong những ngày ốm ấy, Người gọi Võ Nguyên Giáp đến bên và dặn dò nhiều việc lớn. Lời dặn được Đại tướng ghi lại trong hồi ký “Những năm tháng không thể nào quên” đã trở thành một trong những câu nói nổi tiếng nhất của thời kỳ Tổng khởi nghĩa. Nó cho thấy tầm nhìn của Người về thời cơ: phát xít Nhật sắp đầu hàng, và dân tộc phải giành lấy chính quyền trước khi quân Đồng minh kéo vào Đông Dương. Nó cũng cho thấy sự tin cậy Người dành cho người học trò, bởi những lời ấy được nói ra giữa lúc chính Người đang ốm nặng, giữa rừng sâu, khi cả dân tộc sắp bước vào giờ quyết định.","doc":6},{"loai":"trich","text":"Lúc này thời cơ thuận lợi đã tới, dù hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập.","nguoi":"Chủ tịch Hồ Chí Minh dặn Võ Nguyên Giáp tại Tân Trào, 1945 — theo hồi ký của Đại tướng Võ Nguyên Giáp","nguon_ten":"Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký)","doc":7},{"loai":"doan","tieu_de":"Từ cây đa Tân Trào đến lễ đài Ba Đình","text":"Chiều 16/8/1945, dưới gốc cây đa Tân Trào, Võ Nguyên Giáp đọc bản Quân lệnh số 1 rồi dẫn một đơn vị Giải phóng quân xuất quân tiến về Thái Nguyên, mở đầu cuộc Tổng khởi nghĩa ở vùng trung du. Cùng thời gian ấy, Quốc dân Đại hội Tân Trào họp, bầu ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa).\n\nChưa đầy hai tuần sau, người chỉ huy Giải phóng quân trở thành Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời công bố ngày 28/8/1945. Chiều 2/9, ông đứng trên lễ đài Ba Đình, và theo nhiều tư liệu, đã thay mặt Chính phủ phát biểu sau khi Người đọc xong bản Tuyên ngôn. Từ căn lán ở rừng Nà Lừa đến lễ đài giữa Thủ đô chỉ cách nhau vài tuần. Tấm ảnh hai người đứng cạnh nhau năm 1945 vì thế không chỉ là một bức chân dung, mà là điểm hội tụ của cả một chặng đường dài hai người đã cùng đi.","doc":8},{"loai":"ban_co_biet","text":"Tác giả được ghi của bức ảnh là nghệ sĩ nhiếp ảnh Võ An Ninh (1907–2009). Ông cũng đã chụp nhiều bức ảnh về nạn đói năm Ất Dậu 1945 ở đồng bằng Bắc Bộ, những tư liệu hình ảnh hiếm hoi còn lại về thảm họa ấy. Cũng như Đại tướng Võ Nguyên Giáp, ông sống qua tuổi một trăm.","nguon_ten":"Ghi chú tư liệu ảnh; Hội Nghệ sĩ Nhiếp ảnh Việt Nam","doc":9},{"loai":"doan","tieu_de":"Một năm giữa thù trong giặc ngoài","text":"Những tháng làm Bộ trưởng Bộ Nội vụ là những tháng nặng nề. Bộ phải lo xây dựng chính quyền nhân dân các cấp, giữ gìn an ninh trật tự. Ở miền Bắc có khoảng hai mươi vạn quân Tưởng cùng các tổ chức chống đối, còn ở miền Nam thực dân Pháp đã nổ súng xâm lược từ ngày 23/9/1945. Tháng 3/1946, tại kỳ họp thứ nhất, Quốc hội khóa I bầu ông làm Chủ tịch Ủy ban Kháng chiến. Ngày 7/3/1946, ông thay mặt Chính phủ giải thích Hiệp định Sơ bộ trước đồng bào Hà Nội (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946).\n\nMùa xuân năm ấy, ông là thành viên phái đoàn Việt Nam dự Hội nghị trù bị Đà Lạt với phía Pháp. Khi Chủ tịch Hồ Chí Minh sang Pháp từ cuối tháng 5 đến tháng 10/1946, Võ Nguyên Giáp là một trong những người gánh vác công việc ở trong nước, chuẩn bị lực lượng cho khả năng chiến tranh. Tháng 11/1946, ông được giao làm Bộ trưởng Bộ Quốc phòng, chỉ hơn một tháng trước đêm toàn quốc kháng chiến.","doc":10},{"loai":"anh","src":"textures/bang_w/G14_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ Bộ trưởng Nội vụ đến Đại tướng","text":"Năm 1948, Chủ tịch Hồ Chí Minh ký sắc lệnh phong Võ Nguyên Giáp quân hàm Đại tướng, vị Đại tướng đầu tiên của Quân đội nhân dân Việt Nam. Ông trực tiếp chỉ huy nhiều chiến dịch lớn trong kháng chiến chống thực dân Pháp, mà đỉnh cao là Chiến dịch Điện Biên Phủ năm 1954. Theo hồi ký của Đại tướng, trước khi ông lên đường ra mặt trận Điện Biên Phủ, Người đã trao cho ông toàn quyền quyết định tại chỗ, một sự tin cậy hiếm có giữa người đứng đầu đất nước và vị tổng chỉ huy.\n\nSuốt cuộc đời, Đại tướng luôn bày tỏ lòng kính trọng sâu sắc đối với Chủ tịch Hồ Chí Minh, coi Người là người thầy đã dìu dắt mình trên con đường cách mạng. Những trang hồi ký của ông về Người, từ Côn Minh, Pác Bó, Tân Trào đến Ba Đình, là nguồn tư liệu quý để hậu thế hiểu thêm về những năm tháng ấy. Ông qua đời ngày 4/10/2013 tại Hà Nội, hưởng thọ 103 tuổi.","doc":11},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Những nơi hai người từng cùng đi qua nay đều là di tích được gìn giữ. Ở Cao Bằng có Khu di tích Pác Bó và Khu di tích rừng Trần Hưng Đạo, nơi Đội Việt Nam Tuyên truyền Giải phóng quân làm lễ thành lập. Ở Tân Trào, Tuyên Quang, lán Nà Lừa, đình Tân Trào và cây đa Tân Trào vẫn đón khách về thăm. Tại Hà Nội, ngôi nhà số 30 Hoàng Diệu, nơi Đại tướng sống và làm việc nhiều thập kỷ, là địa chỉ quen thuộc của những người muốn tìm hiểu về ông. Phần mộ Đại tướng ở Vũng Chùa – Đảo Yến, trên vùng đất Quảng Bình quê hương ông.\n\nNhiều hiện vật về quãng đời cầm quân của ông đang được lưu giữ tại Bảo tàng Lịch sử Quân sự Việt Nam. Còn tấm ảnh năm 1945 trên bảng này, đặt trong gian Hà Nội 1945 – Ba Đình, mang một lời nhắc. Ngày lập quốc không chỉ có một người đọc Tuyên ngôn, mà có cả những người học trò đã cùng Người đi suốt chặng đường từ biên giới về tới Thủ đô.","doc":12},{"loai":"anh","src":"textures/bang_w/G14_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945”, nhìn từ trên cao."}],"nguon":["Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký)","Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật (Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân)","Bảo tàng Lịch sử Quân sự Việt Nam"],"doc":[{"t":"Người thầy và người học trò: Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp năm 1945. Trong tấm ảnh năm 1945, vị Chủ tịch nước năm mươi lăm tuổi đứng bên người Bộ trưởng Bộ Nội vụ vừa bước sang tuổi ba mươi tư. Năm năm trước, họ mới gặp nhau lần đầu ở Côn Minh, bên kia biên giới. Giữa hai khoảnh khắc ấy là những năm ở Cao Bằng, là khu rừng nơi ba mươi tư chiến sĩ làm lễ thành lập đội, và một lời dặn giữa cơn sốt ở Tân Trào mà người học trò nhớ suốt đời."},{"t":"Hai người trong một khung hình. Tấm ảnh được ghi tác giả là nghệ sĩ nhiếp ảnh Võ An Ninh, và theo ghi chú của tư liệu, được chụp ngày 2/9/1945, ngày lập quốc. Trong khung hình là hai con người sẽ gắn tên tuổi với nhau suốt mấy chục năm lịch sử. Đó là Chủ tịch Hồ Chí Minh, người vừa đọc bản Tuyên ngôn Độc lập, và Võ Nguyên Giáp, Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời. Năm ấy, Người năm mươi lăm tuổi. Võ Nguyên Giáp sinh ngày 25/8/1911, vừa bước sang tuổi ba mươi tư ít ngày trước buổi lễ. Khoảng cách tuổi tác giữa hai người xấp xỉ một thế hệ, và quan hệ giữa họ thường được nhắc tới như quan hệ thầy – trò. Chính Đại tướng, trong những hồi ký viết về sau, luôn coi Người là người thầy lớn đã dìu dắt mình từ một nhà giáo dạy sử trở thành người cầm quân. Nhưng để hiểu vì sao hai người cùng đứng trong khung hình năm 1945, phải lùi lại năm năm, tới một thành phố bên kia biên giới phía bắc."},{"t":"Côn Minh, mùa hè năm 1940. Tháng 6/1940, Võ Nguyên Giáp khi ấy là thầy giáo dạy lịch sử ở trường tư thục Thăng Long, Hà Nội, và đã có nhiều năm hoạt động cách mạng. Trước sự khủng bố ngày càng gắt gao của chính quyền thực dân, ông cùng Phạm Văn Đồng được tổ chức đưa sang Trung Quốc. Ở Côn Minh, tỉnh lỵ Vân Nam, hai người lần đầu gặp Nguyễn Ái Quốc, người mà trước đó họ chỉ biết qua tài liệu và những lời truyền tụng. Theo hồi ký “Từ nhân dân mà ra” của Đại tướng, Người dự định gửi hai ông sang Diên An, căn cứ của Đảng Cộng sản Trung Quốc, để học tập, và khuyên Võ Nguyên Giáp nên chú tâm học quân sự. Nhưng khi hai ông còn đang chờ lên đường thì tin nước Pháp bại trận trước phát xít Đức truyền tới. Người nhận định đây là thời cơ thuận lợi cho cách mạng Việt Nam, liền cho gọi hai ông quay lại để chuẩn bị về nước. Lời khuyên học quân sự năm ấy, nhìn lại về sau, như một dự báo về con đường của người thầy giáo dạy sử."},{"t":"Những năm ở Cao Bằng. Ngày 28/1/1941, Nguyễn Ái Quốc về nước qua cột mốc 108 và đặt cơ quan ở Pác Bó. Võ Nguyên Giáp cùng các đồng chí được Người giao công việc ở Cao Bằng: mở các lớp huấn luyện chính trị ngắn ngày, xây dựng cơ sở Việt Minh trong đồng bào Tày, Nùng, Dao, Mông. Ông mang bí danh Văn; về sau bộ đội và đồng bào thân mật gọi ông là “anh Văn”. Trong thời gian Người bị chính quyền Tưởng Giới Thạch bắt giam ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1944, các cán bộ ở Cao Bằng vẫn tiếp tục những việc Người đã vạch ra. Năm 1943, Võ Nguyên Giáp phụ trách các đội xung phong Nam tiến, mở đường nối căn cứ Cao Bằng với căn cứ Bắc Sơn – Võ Nhai. Trên nền tảng những cơ sở được gây dựng bền bỉ trong mấy năm ấy, tháng 6/1945 Khu giải phóng Việt Bắc ra đời, với trung tâm là Tân Trào."},{"t":"Bạn có biết? Theo hồi ký của Đại tướng Võ Nguyên Giáp, trong thời gian Người bị giam ở Quảng Tây, có lúc tin Người đã mất trong tù truyền về Cao Bằng, các đồng chí ở nhà đã làm lễ truy điệu. Ít lâu sau, họ mới nhận được mấy dòng chữ viết tay của Người gửi về, báo tin Người vẫn bình an."},{"t":"Khu rừng Trần Hưng Đạo. Tháng 9/1944, Người trở lại Pác Bó. Lúc ấy, liên tỉnh Cao – Bắc – Lạng đang chuẩn bị phát động khởi nghĩa. Nghe báo cáo, Người cho rằng thời cơ khởi nghĩa toàn dân chưa tới, nếu nổ ra sớm lực lượng cách mạng sẽ bị kẻ thù tập trung đàn áp, và quyết định đình chỉ kế hoạch. Thay vào đó, Người chủ trương lập một đội vũ trang tập trung, vừa chiến đấu vừa tuyên truyền, và giao cho Võ Nguyên Giáp tổ chức. Ngày 22/12/1944, tại khu rừng Trần Hưng Đạo thuộc Nguyên Bình, Cao Bằng, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời với 34 chiến sĩ, do Võ Nguyên Giáp trực tiếp chỉ huy. Trong bản chỉ thị thành lập đội, Người viết: “Tên Đội Việt Nam Tuyên truyền Giải phóng quân nghĩa là chính trị trọng hơn quân sự. Nó là đội tuyên truyền”. Chỉ vài ngày sau, đội đánh thắng hai trận đầu tiên ở Phai Khắt và Nà Ngần. Đội quân nhỏ bé ấy là tiền thân của Quân đội nhân dân Việt Nam, và người chỉ huy đầu tiên của nó chính là thầy giáo dạy sử năm nào."},{"t":"Tân Trào, những ngày Người ốm nặng. Tháng 5/1945, Người rời Cao Bằng về Tân Trào, Tuyên Quang. Võ Nguyên Giáp ở bên Người trong những tháng quyết định ấy. Khoảng cuối tháng 7/1945, Người lên cơn sốt nặng, nhiều lúc mê man, trong căn lán nhỏ ở rừng Nà Lừa. Theo hồi ký của Đại tướng, một ông lang người Tày trong vùng đã dùng thuốc nam chữa, và Người dần qua khỏi. Trong những ngày ốm ấy, Người gọi Võ Nguyên Giáp đến bên và dặn dò nhiều việc lớn. Lời dặn được Đại tướng ghi lại trong hồi ký “Những năm tháng không thể nào quên” đã trở thành một trong những câu nói nổi tiếng nhất của thời kỳ Tổng khởi nghĩa. Nó cho thấy tầm nhìn của Người về thời cơ: phát xít Nhật sắp đầu hàng, và dân tộc phải giành lấy chính quyền trước khi quân Đồng minh kéo vào Đông Dương. Nó cũng cho thấy sự tin cậy Người dành cho người học trò, bởi những lời ấy được nói ra giữa lúc chính Người đang ốm nặng, giữa rừng sâu, khi cả dân tộc sắp bước vào giờ quyết định."},{"t":"Lúc này thời cơ thuận lợi đã tới, dù hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập. — Chủ tịch Hồ Chí Minh dặn Võ Nguyên Giáp tại Tân Trào, 1945 — theo hồi ký của Đại tướng Võ Nguyên Giáp"},{"t":"Từ cây đa Tân Trào đến lễ đài Ba Đình. Chiều 16/8/1945, dưới gốc cây đa Tân Trào, Võ Nguyên Giáp đọc bản Quân lệnh số 1 rồi dẫn một đơn vị Giải phóng quân xuất quân tiến về Thái Nguyên, mở đầu cuộc Tổng khởi nghĩa ở vùng trung du. Cùng thời gian ấy, Quốc dân Đại hội Tân Trào họp, bầu ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa). Chưa đầy hai tuần sau, người chỉ huy Giải phóng quân trở thành Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời công bố ngày 28/8/1945. Chiều 2/9, ông đứng trên lễ đài Ba Đình, và theo nhiều tư liệu, đã thay mặt Chính phủ phát biểu sau khi Người đọc xong bản Tuyên ngôn. Từ căn lán ở rừng Nà Lừa đến lễ đài giữa Thủ đô chỉ cách nhau vài tuần. Tấm ảnh hai người đứng cạnh nhau năm 1945 vì thế không chỉ là một bức chân dung, mà là điểm hội tụ của cả một chặng đường dài hai người đã cùng đi."},{"t":"Bạn có biết? Tác giả được ghi của bức ảnh là nghệ sĩ nhiếp ảnh Võ An Ninh (1907–2009). Ông cũng đã chụp nhiều bức ảnh về nạn đói năm Ất Dậu 1945 ở đồng bằng Bắc Bộ, những tư liệu hình ảnh hiếm hoi còn lại về thảm họa ấy. Cũng như Đại tướng Võ Nguyên Giáp, ông sống qua tuổi một trăm."},{"t":"Một năm giữa thù trong giặc ngoài. Những tháng làm Bộ trưởng Bộ Nội vụ là những tháng nặng nề. Bộ phải lo xây dựng chính quyền nhân dân các cấp, giữ gìn an ninh trật tự. Ở miền Bắc có khoảng hai mươi vạn quân Tưởng cùng các tổ chức chống đối, còn ở miền Nam thực dân Pháp đã nổ súng xâm lược từ ngày 23/9/1945. Tháng 3/1946, tại kỳ họp thứ nhất, Quốc hội khóa I bầu ông làm Chủ tịch Ủy ban Kháng chiến. Ngày 7/3/1946, ông thay mặt Chính phủ giải thích Hiệp định Sơ bộ trước đồng bào Hà Nội (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946). Mùa xuân năm ấy, ông là thành viên phái đoàn Việt Nam dự Hội nghị trù bị Đà Lạt với phía Pháp. Khi Chủ tịch Hồ Chí Minh sang Pháp từ cuối tháng 5 đến tháng 10/1946, Võ Nguyên Giáp là một trong những người gánh vác công việc ở trong nước, chuẩn bị lực lượng cho khả năng chiến tranh. Tháng 11/1946, ông được giao làm Bộ trưởng Bộ Quốc phòng, chỉ hơn một tháng trước đêm toàn quốc kháng chiến."},{"t":"Từ Bộ trưởng Nội vụ đến Đại tướng. Năm 1948, Chủ tịch Hồ Chí Minh ký sắc lệnh phong Võ Nguyên Giáp quân hàm Đại tướng, vị Đại tướng đầu tiên của Quân đội nhân dân Việt Nam. Ông trực tiếp chỉ huy nhiều chiến dịch lớn trong kháng chiến chống thực dân Pháp, mà đỉnh cao là Chiến dịch Điện Biên Phủ năm 1954. Theo hồi ký của Đại tướng, trước khi ông lên đường ra mặt trận Điện Biên Phủ, Người đã trao cho ông toàn quyền quyết định tại chỗ, một sự tin cậy hiếm có giữa người đứng đầu đất nước và vị tổng chỉ huy. Suốt cuộc đời, Đại tướng luôn bày tỏ lòng kính trọng sâu sắc đối với Chủ tịch Hồ Chí Minh, coi Người là người thầy đã dìu dắt mình trên con đường cách mạng. Những trang hồi ký của ông về Người, từ Côn Minh, Pác Bó, Tân Trào đến Ba Đình, là nguồn tư liệu quý để hậu thế hiểu thêm về những năm tháng ấy. Ông qua đời ngày 4/10/2013 tại Hà Nội, hưởng thọ 103 tuổi."},{"t":"Dấu tích hôm nay. Những nơi hai người từng cùng đi qua nay đều là di tích được gìn giữ. Ở Cao Bằng có Khu di tích Pác Bó và Khu di tích rừng Trần Hưng Đạo, nơi Đội Việt Nam Tuyên truyền Giải phóng quân làm lễ thành lập. Ở Tân Trào, Tuyên Quang, lán Nà Lừa, đình Tân Trào và cây đa Tân Trào vẫn đón khách về thăm. Tại Hà Nội, ngôi nhà số 30 Hoàng Diệu, nơi Đại tướng sống và làm việc nhiều thập kỷ, là địa chỉ quen thuộc của những người muốn tìm hiểu về ông. Phần mộ Đại tướng ở Vũng Chùa – Đảo Yến, trên vùng đất Quảng Bình quê hương ông. Nhiều hiện vật về quãng đời cầm quân của ông đang được lưu giữ tại Bảo tàng Lịch sử Quân sự Việt Nam. Còn tấm ảnh năm 1945 trên bảng này, đặt trong gian Hà Nội 1945 – Ba Đình, mang một lời nhắc. Ngày lập quốc không chỉ có một người đọc Tuyên ngôn, mà có cả những người học trò đã cùng Người đi suốt chặng đường từ biên giới về tới Thủ đô."}],"so_chu":1942},{"i":7,"tieu_de_bang":"Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa","tieu_de":"Nội các của cả dân tộc: Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa","sapo":"Trong danh sách mười lăm thành viên Chính phủ lâm thời công bố ngày 28/8/1945 có một nhà thơ hai mươi sáu tuổi, một học giả đứng đầu hội truyền bá chữ quốc ngữ, một bác sĩ đang ở Sài Gòn và một trí thức Công giáo. Họ không đi cùng một con đường, nhưng cùng được mời ngồi chung một nội các. Chủ tịch Hồ Chí Minh đã chọn người như thế nào, và chính phủ ấy đã làm gì trong những ngày đầu tiên của nước Việt Nam độc lập?","bia":{"src":"textures/ht/ht_anh_chinh_phu_lam_thoi.jpg","credit":"Ảnh: Vietnam Government · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Mười lăm cái tên trên một bản tuyên cáo","text":"Ngày 28/8/1945, Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa ra bản tuyên cáo, công bố thành phần của mình trước quốc dân. Đó cũng là những ngày Chủ tịch Hồ Chí Minh soạn bản Tuyên ngôn Độc lập trên căn gác nhà 48 Hàng Ngang. Danh sách gồm mười lăm người. Hồ Chí Minh làm Chủ tịch kiêm Bộ trưởng Bộ Ngoại giao. Võ Nguyên Giáp giữ Bộ Nội vụ, Trần Huy Liệu giữ Bộ Thông tin Tuyên truyền, Chu Văn Tấn giữ Bộ Quốc phòng, Phạm Văn Đồng giữ Bộ Tài chính.\n\nDương Đức Hiền giữ Bộ Thanh niên, Nguyễn Mạnh Hà giữ Bộ Kinh tế quốc gia, Nguyễn Văn Tố giữ Bộ Cứu tế xã hội, Vũ Trọng Khánh giữ Bộ Tư pháp. Phạm Ngọc Thạch giữ Bộ Y tế, Đào Trọng Kim giữ Bộ Giao thông công chính, Lê Văn Hiến giữ Bộ Lao động, Vũ Đình Hòe giữ Bộ Quốc gia Giáo dục. Hai người nữa, Cù Huy Cận và Nguyễn Văn Xuân, làm Bộ trưởng không giữ bộ nào. Đọc kỹ danh sách, người đương thời nhận ra một điều khác thường: bên cạnh những người cộng sản từ chiến khu và nhà tù trở về, có nhiều trí thức, nhân sĩ chưa từng là đảng viên cộng sản.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_chinh_phu_lam_thoi.jpg","chu_thich":"Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa — ảnh tư liệu, trong kho lưu trữ được ghi thời điểm tháng 3/1946.","credit":"Ảnh: Vietnam Government · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ Tân Trào đến căn gác Hàng Ngang","text":"Chính phủ ấy không ra đời từ con số không. Quốc dân Đại hội Tân Trào (16–17/8/1945) đã bầu ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch, giao nhiệm vụ lãnh đạo cuộc Tổng khởi nghĩa. Ủy ban có vai trò như một chính phủ lâm thời, nhưng thành phần chủ yếu là những người hoạt động trong Mặt trận Việt Minh.\n\nVề tới Hà Nội, Người thấy cần một bộ máy rộng rãi hơn, đại diện cho toàn dân tộc. Tại cuộc họp Ban Thường vụ Trung ương Đảng do Người chủ trì ở nhà 48 Hàng Ngang ngày 26/8/1945, việc mở rộng thành phần Chính phủ được bàn định (xem chuyên đề Nhà số 48 Hàng Ngang). Theo nhiều tư liệu, một số thành viên của Ủy ban Dân tộc giải phóng đã tự nguyện rút lui, nhường chỗ cho các nhân sĩ, trí thức có uy tín. Ủy ban được cải tổ thành Chính phủ lâm thời, và chỉ hai ngày sau, danh sách được công bố. Tất cả diễn ra trong chưa đầy hai tuần kể từ những ngày họp ở Tân Trào, giữa lúc chính quyền cách mạng ở nhiều nơi còn đang được thiết lập.","doc":2},{"loai":"doan","tieu_de":"Những gương mặt trí thức","text":"Người đứng đầu Bộ Cứu tế xã hội là học giả Nguyễn Văn Tố, uyên thâm cả Hán học lẫn Tây học, từng làm Hội trưởng Hội Truyền bá quốc ngữ, tổ chức mở lớp dạy chữ cho người nghèo từ cuối những năm 1930. Bộ Quốc gia Giáo dục được giao cho luật gia Vũ Đình Hòe, người sáng lập và điều hành tạp chí Thanh Nghị, tờ báo quy tụ nhiều trí thức trẻ ở Hà Nội. Luật sư Vũ Trọng Khánh giữ Bộ Tư pháp. Bộ Kinh tế quốc gia do ông Nguyễn Mạnh Hà, một trí thức Công giáo, đảm nhiệm.\n\nỞ phía nam, bác sĩ Phạm Ngọc Thạch, người lãnh đạo phong trào Thanh niên Tiền phong rất đông đảo ở Sài Gòn, được mời làm Bộ trưởng Bộ Y tế. Nhà thơ Huy Cận, một gương mặt tiêu biểu của phong trào Thơ mới với tập “Lửa thiêng”, vào Chính phủ khi mới hai mươi sáu tuổi. Sự lựa chọn ấy có chủ đích. Chủ tịch Hồ Chí Minh muốn chính phủ đầu tiên của nước Việt Nam độc lập là chính phủ của toàn dân tộc, quy tụ những người có tài, có đức thuộc mọi giới, mọi tôn giáo, mọi miền đất nước.","doc":3},{"loai":"anh","src":"textures/bang_w/G14_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những người từ chiến khu và nhà tù","text":"Bên cạnh các trí thức là những chiến sĩ cách mạng đã qua nhiều thử thách. Võ Nguyên Giáp vừa dẫn Giải phóng quân từ Tân Trào tiến về xuôi (xem chuyên đề Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945). Phạm Văn Đồng từng trải qua nhiều năm tù ở Côn Đảo. Chu Văn Tấn là người chỉ huy Cứu quốc quân ở vùng Bắc Sơn – Võ Nhai. Trần Huy Liệu, nhà báo và nhà sử học, từng bị giam ở Côn Đảo và Sơn La. Lê Văn Hiến cũng là người đi ra từ nhà tù thực dân.\n\nCũng những ngày ấy, một số thành viên nhận nhiệm vụ đặc biệt. Ngày 30/8/1945, tại Ngọ Môn, Huế, vua Bảo Đại thoái vị, trao ấn kiếm cho phái đoàn Chính phủ lâm thời do Trần Huy Liệu dẫn đầu, trong đó có Bộ trưởng Cù Huy Cận. Chiều 2/9, trên lễ đài Ba Đình, Chính phủ lâm thời chính thức ra mắt quốc dân và làm lễ tuyên thệ, nguyện lãnh đạo nhân dân giữ vững nền độc lập. Người dân Hà Nội lần đầu được thấy tận mắt những người sẽ gánh vác việc nước.","doc":4},{"loai":"ban_co_biet","text":"Bộ trưởng Bộ Lao động Lê Văn Hiến là tác giả cuốn hồi ký “Ngục Kon Tum”, kể về những năm ông cùng nhiều chiến sĩ cách mạng bị giam cầm, khổ sai trong nhà tù thực dân ở Tây Nguyên.","nguon_ten":"Lê Văn Hiến, Ngục Kon Tum (hồi ký)","doc":5},{"loai":"doan","tieu_de":"Phiên họp đầu tiên ở Bắc Bộ phủ","text":"Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ. Người nêu sáu nhiệm vụ cấp bách. Thứ nhất, phát động chiến dịch tăng gia sản xuất để chống nạn đói. Thứ hai, mở chiến dịch chống nạn mù chữ. Thứ ba, tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu để có một hiến pháp dân chủ. Thứ tư, mở chiến dịch giáo dục lại tinh thần nhân dân bằng cách thực hiện cần, kiệm, liêm, chính. Thứ năm, bỏ ngay thuế thân, thuế chợ, thuế đò và tuyệt đối cấm hút thuốc phiện. Thứ sáu, tuyên bố tự do tín ngưỡng, lương giáo đoàn kết.\n\nSáu nhiệm vụ ấy trở thành chương trình hành động của Chính phủ trong những tháng tiếp theo. Mỗi nhiệm vụ lại mở ra một mặt trận riêng: chống giặc đói, chống giặc dốt, Tổng tuyển cử, xây dựng đời sống mới. Riêng nhiệm vụ cuối cùng, nói về tôn giáo, gắn trực tiếp với tinh thần của chính thành phần Chính phủ, nơi người Công giáo và người không theo đạo cùng ngồi chung bàn họp.","doc":6},{"loai":"trich","text":"Thực dân và phong kiến thi hành chính sách chia rẽ đồng bào Giáo và đồng bào Lương, để dễ thống trị. Tôi đề nghị Chính phủ ta tuyên bố: tín ngưỡng tự do và Lương Giáo đoàn kết.","nguoi":"Hồ Chí Minh, Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, phiên họp Chính phủ ngày 3/9/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":7},{"loai":"doan","tieu_de":"Những việc làm ngay","text":"Những tuần sau đó, bộ máy mới làm việc với nhịp độ khẩn trương. Ngày 8/9/1945, Chủ tịch Hồ Chí Minh ký sắc lệnh về Tổng tuyển cử bầu Quốc hội và các sắc lệnh lập Nha Bình dân học vụ (xem chuyên đề Diệt giặc dốt). Từ ngày 17 đến 24/9, Tuần lễ Vàng được phát động để bù đắp phần nào cho ngân khố gần như trống rỗng mà Bộ trưởng Bộ Tài chính Phạm Văn Đồng tiếp quản (xem chuyên đề Tuần lễ Vàng).\n\nTinh thần đoàn kết còn được thể hiện bằng những quyết định khác thường. Cựu hoàng Bảo Đại, sau khi thoái vị, được mời ra Hà Nội làm Cố vấn tối cao của Chính phủ với tên công dân Vĩnh Thụy. Cụ Bùi Bằng Đoàn, nguyên Thượng thư triều Nguyễn, được mời đứng đầu Ban Thanh tra đặc biệt của Chính phủ. Với một nhà nước mới ra đời, lòng tin của mọi tầng lớp xã hội cũng là một thứ tài sản quý như vàng trong ngân khố. Chủ tịch Hồ Chí Minh hiểu rõ điều đó, nên không bỏ qua bất cứ người có tài, có đức nào sẵn lòng góp sức cho nền độc lập.","doc":8},{"loai":"anh","src":"textures/bang_w/G14_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Mở rộng để đoàn kết","text":"Cuối năm 1945, sức ép của quân Tưởng và các đảng phái dựa vào quân Tưởng như Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội ngày càng lớn. Chủ tịch Hồ Chí Minh chủ trương nhân nhượng có nguyên tắc để giữ vững chính quyền. Ngày 1/1/1946, Chính phủ lâm thời được cải tổ thành Chính phủ liên hiệp lâm thời, có thêm đại diện các đảng phái ấy; ông Nguyễn Hải Thần của Việt Nam Cách mạng Đồng minh hội giữ chức Phó Chủ tịch.\n\nSau Tổng tuyển cử, ngày 2/3/1946, Quốc hội khóa I thông qua thành phần Chính phủ Liên hiệp kháng chiến do Người làm Chủ tịch (xem chuyên đề Quốc hội khóa I). Trong Chính phủ mới, cụ Huỳnh Thúc Kháng, nhà nho yêu nước từng bị thực dân đày ra Côn Đảo, nhận giữ Bộ Nội vụ; luật sư Phan Anh giữ Bộ Quốc phòng. Một số thành viên cũ tự nguyện rút ra để nhường ghế. Qua mỗi lần cải tổ, cái lõi vẫn giữ nguyên: một chính phủ đặt lợi ích dân tộc lên trên mọi khác biệt đảng phái, tôn giáo.","doc":9},{"loai":"ban_co_biet","text":"Nhiều ngành ngày nay lấy ngày 28/8/1945, ngày công bố thành phần Chính phủ lâm thời, làm ngày truyền thống của mình, trong đó có ngành Ngoại giao, Nội vụ, Tư pháp, Tài chính và Giao thông vận tải.","nguon_ten":"Văn phòng Chính phủ – Lịch sử Chính phủ Việt Nam; Cổng thông tin điện tử các bộ, ngành","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Bắc Bộ phủ, nơi Chính phủ lâm thời họp phiên đầu tiên và làm việc trong những tháng đầu, nay là Nhà khách Chính phủ ở số 12 Ngô Quyền, Hà Nội. Nhiều văn bản gốc của Chính phủ những ngày đầu, từ các sắc lệnh do Chủ tịch Hồ Chí Minh ký đến biên bản các phiên họp Hội đồng Chính phủ, đang được bảo quản tại Trung tâm Lưu trữ quốc gia III. Đây là nơi lưu giữ tài liệu của các cơ quan nhà nước từ năm 1945 trở đi.\n\nTấm ảnh trên bảng này, trong kho tư liệu được ghi thời điểm tháng 3/1946, tức khi bộ máy Chính phủ đã qua những lần mở rộng, gợi lại diện mạo của những con người gánh vác việc nước buổi đầu. Nhiều người trong số họ tiếp tục gắn bó với cuộc kháng chiến trường kỳ. Có người không trở về: học giả Nguyễn Văn Tố, vị Bộ trưởng Bộ Cứu tế xã hội năm 1945, bị thực dân Pháp bắt và sát hại ở Bắc Kạn tháng 10/1947. Mỗi cái tên trong danh sách mười lăm người năm ấy là một câu chuyện riêng về lựa chọn đứng về phía dân tộc.","doc":11},{"loai":"anh","src":"textures/bang_w/G14_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa)","Văn phòng Chính phủ – Lịch sử Chính phủ Việt Nam","Trung tâm Lưu trữ quốc gia III – Biên bản Hội đồng Chính phủ 1945 – 1954","Lê Văn Hiến, Ngục Kon Tum (hồi ký)"],"doc":[{"t":"Nội các của cả dân tộc: Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa. Trong danh sách mười lăm thành viên Chính phủ lâm thời công bố ngày 28/8/1945 có một nhà thơ hai mươi sáu tuổi, một học giả đứng đầu hội truyền bá chữ quốc ngữ, một bác sĩ đang ở Sài Gòn và một trí thức Công giáo. Họ không đi cùng một con đường, nhưng cùng được mời ngồi chung một nội các. Chủ tịch Hồ Chí Minh đã chọn người như thế nào, và chính phủ ấy đã làm gì trong những ngày đầu tiên của nước Việt Nam độc lập?"},{"t":"Mười lăm cái tên trên một bản tuyên cáo. Ngày 28/8/1945, Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa ra bản tuyên cáo, công bố thành phần của mình trước quốc dân. Đó cũng là những ngày Chủ tịch Hồ Chí Minh soạn bản Tuyên ngôn Độc lập trên căn gác nhà 48 Hàng Ngang. Danh sách gồm mười lăm người. Hồ Chí Minh làm Chủ tịch kiêm Bộ trưởng Bộ Ngoại giao. Võ Nguyên Giáp giữ Bộ Nội vụ, Trần Huy Liệu giữ Bộ Thông tin Tuyên truyền, Chu Văn Tấn giữ Bộ Quốc phòng, Phạm Văn Đồng giữ Bộ Tài chính. Dương Đức Hiền giữ Bộ Thanh niên, Nguyễn Mạnh Hà giữ Bộ Kinh tế quốc gia, Nguyễn Văn Tố giữ Bộ Cứu tế xã hội, Vũ Trọng Khánh giữ Bộ Tư pháp. Phạm Ngọc Thạch giữ Bộ Y tế, Đào Trọng Kim giữ Bộ Giao thông công chính, Lê Văn Hiến giữ Bộ Lao động, Vũ Đình Hòe giữ Bộ Quốc gia Giáo dục. Hai người nữa, Cù Huy Cận và Nguyễn Văn Xuân, làm Bộ trưởng không giữ bộ nào. Đọc kỹ danh sách, người đương thời nhận ra một điều khác thường: bên cạnh những người cộng sản từ chiến khu và nhà tù trở về, có nhiều trí thức, nhân sĩ chưa từng là đảng viên cộng sản."},{"t":"Từ Tân Trào đến căn gác Hàng Ngang. Chính phủ ấy không ra đời từ con số không. Quốc dân Đại hội Tân Trào (16–17/8/1945) đã bầu ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch, giao nhiệm vụ lãnh đạo cuộc Tổng khởi nghĩa. Ủy ban có vai trò như một chính phủ lâm thời, nhưng thành phần chủ yếu là những người hoạt động trong Mặt trận Việt Minh. Về tới Hà Nội, Người thấy cần một bộ máy rộng rãi hơn, đại diện cho toàn dân tộc. Tại cuộc họp Ban Thường vụ Trung ương Đảng do Người chủ trì ở nhà 48 Hàng Ngang ngày 26/8/1945, việc mở rộng thành phần Chính phủ được bàn định (xem chuyên đề Nhà số 48 Hàng Ngang). Theo nhiều tư liệu, một số thành viên của Ủy ban Dân tộc giải phóng đã tự nguyện rút lui, nhường chỗ cho các nhân sĩ, trí thức có uy tín. Ủy ban được cải tổ thành Chính phủ lâm thời, và chỉ hai ngày sau, danh sách được công bố. Tất cả diễn ra trong chưa đầy hai tuần kể từ những ngày họp ở Tân Trào, giữa lúc chính quyền cách mạng ở nhiều nơi còn đang được thiết lập."},{"t":"Những gương mặt trí thức. Người đứng đầu Bộ Cứu tế xã hội là học giả Nguyễn Văn Tố, uyên thâm cả Hán học lẫn Tây học, từng làm Hội trưởng Hội Truyền bá quốc ngữ, tổ chức mở lớp dạy chữ cho người nghèo từ cuối những năm 1930. Bộ Quốc gia Giáo dục được giao cho luật gia Vũ Đình Hòe, người sáng lập và điều hành tạp chí Thanh Nghị, tờ báo quy tụ nhiều trí thức trẻ ở Hà Nội. Luật sư Vũ Trọng Khánh giữ Bộ Tư pháp. Bộ Kinh tế quốc gia do ông Nguyễn Mạnh Hà, một trí thức Công giáo, đảm nhiệm. Ở phía nam, bác sĩ Phạm Ngọc Thạch, người lãnh đạo phong trào Thanh niên Tiền phong rất đông đảo ở Sài Gòn, được mời làm Bộ trưởng Bộ Y tế. Nhà thơ Huy Cận, một gương mặt tiêu biểu của phong trào Thơ mới với tập “Lửa thiêng”, vào Chính phủ khi mới hai mươi sáu tuổi. Sự lựa chọn ấy có chủ đích. Chủ tịch Hồ Chí Minh muốn chính phủ đầu tiên của nước Việt Nam độc lập là chính phủ của toàn dân tộc, quy tụ những người có tài, có đức thuộc mọi giới, mọi tôn giáo, mọi miền đất nước."},{"t":"Những người từ chiến khu và nhà tù. Bên cạnh các trí thức là những chiến sĩ cách mạng đã qua nhiều thử thách. Võ Nguyên Giáp vừa dẫn Giải phóng quân từ Tân Trào tiến về xuôi (xem chuyên đề Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945). Phạm Văn Đồng từng trải qua nhiều năm tù ở Côn Đảo. Chu Văn Tấn là người chỉ huy Cứu quốc quân ở vùng Bắc Sơn – Võ Nhai. Trần Huy Liệu, nhà báo và nhà sử học, từng bị giam ở Côn Đảo và Sơn La. Lê Văn Hiến cũng là người đi ra từ nhà tù thực dân. Cũng những ngày ấy, một số thành viên nhận nhiệm vụ đặc biệt. Ngày 30/8/1945, tại Ngọ Môn, Huế, vua Bảo Đại thoái vị, trao ấn kiếm cho phái đoàn Chính phủ lâm thời do Trần Huy Liệu dẫn đầu, trong đó có Bộ trưởng Cù Huy Cận. Chiều 2/9, trên lễ đài Ba Đình, Chính phủ lâm thời chính thức ra mắt quốc dân và làm lễ tuyên thệ, nguyện lãnh đạo nhân dân giữ vững nền độc lập. Người dân Hà Nội lần đầu được thấy tận mắt những người sẽ gánh vác việc nước."},{"t":"Bạn có biết? Bộ trưởng Bộ Lao động Lê Văn Hiến là tác giả cuốn hồi ký “Ngục Kon Tum”, kể về những năm ông cùng nhiều chiến sĩ cách mạng bị giam cầm, khổ sai trong nhà tù thực dân ở Tây Nguyên."},{"t":"Phiên họp đầu tiên ở Bắc Bộ phủ. Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ tại Bắc Bộ phủ. Người nêu sáu nhiệm vụ cấp bách. Thứ nhất, phát động chiến dịch tăng gia sản xuất để chống nạn đói. Thứ hai, mở chiến dịch chống nạn mù chữ. Thứ ba, tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu để có một hiến pháp dân chủ. Thứ tư, mở chiến dịch giáo dục lại tinh thần nhân dân bằng cách thực hiện cần, kiệm, liêm, chính. Thứ năm, bỏ ngay thuế thân, thuế chợ, thuế đò và tuyệt đối cấm hút thuốc phiện. Thứ sáu, tuyên bố tự do tín ngưỡng, lương giáo đoàn kết. Sáu nhiệm vụ ấy trở thành chương trình hành động của Chính phủ trong những tháng tiếp theo. Mỗi nhiệm vụ lại mở ra một mặt trận riêng: chống giặc đói, chống giặc dốt, Tổng tuyển cử, xây dựng đời sống mới. Riêng nhiệm vụ cuối cùng, nói về tôn giáo, gắn trực tiếp với tinh thần của chính thành phần Chính phủ, nơi người Công giáo và người không theo đạo cùng ngồi chung bàn họp."},{"t":"Thực dân và phong kiến thi hành chính sách chia rẽ đồng bào Giáo và đồng bào Lương, để dễ thống trị. Tôi đề nghị Chính phủ ta tuyên bố: tín ngưỡng tự do và Lương Giáo đoàn kết. — Hồ Chí Minh, Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, phiên họp Chính phủ ngày 3/9/1945"},{"t":"Những việc làm ngay. Những tuần sau đó, bộ máy mới làm việc với nhịp độ khẩn trương. Ngày 8/9/1945, Chủ tịch Hồ Chí Minh ký sắc lệnh về Tổng tuyển cử bầu Quốc hội và các sắc lệnh lập Nha Bình dân học vụ (xem chuyên đề Diệt giặc dốt). Từ ngày 17 đến 24/9, Tuần lễ Vàng được phát động để bù đắp phần nào cho ngân khố gần như trống rỗng mà Bộ trưởng Bộ Tài chính Phạm Văn Đồng tiếp quản (xem chuyên đề Tuần lễ Vàng). Tinh thần đoàn kết còn được thể hiện bằng những quyết định khác thường. Cựu hoàng Bảo Đại, sau khi thoái vị, được mời ra Hà Nội làm Cố vấn tối cao của Chính phủ với tên công dân Vĩnh Thụy. Cụ Bùi Bằng Đoàn, nguyên Thượng thư triều Nguyễn, được mời đứng đầu Ban Thanh tra đặc biệt của Chính phủ. Với một nhà nước mới ra đời, lòng tin của mọi tầng lớp xã hội cũng là một thứ tài sản quý như vàng trong ngân khố. Chủ tịch Hồ Chí Minh hiểu rõ điều đó, nên không bỏ qua bất cứ người có tài, có đức nào sẵn lòng góp sức cho nền độc lập."},{"t":"Mở rộng để đoàn kết. Cuối năm 1945, sức ép của quân Tưởng và các đảng phái dựa vào quân Tưởng như Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội ngày càng lớn. Chủ tịch Hồ Chí Minh chủ trương nhân nhượng có nguyên tắc để giữ vững chính quyền. Ngày 1/1/1946, Chính phủ lâm thời được cải tổ thành Chính phủ liên hiệp lâm thời, có thêm đại diện các đảng phái ấy; ông Nguyễn Hải Thần của Việt Nam Cách mạng Đồng minh hội giữ chức Phó Chủ tịch. Sau Tổng tuyển cử, ngày 2/3/1946, Quốc hội khóa I thông qua thành phần Chính phủ Liên hiệp kháng chiến do Người làm Chủ tịch (xem chuyên đề Quốc hội khóa I). Trong Chính phủ mới, cụ Huỳnh Thúc Kháng, nhà nho yêu nước từng bị thực dân đày ra Côn Đảo, nhận giữ Bộ Nội vụ; luật sư Phan Anh giữ Bộ Quốc phòng. Một số thành viên cũ tự nguyện rút ra để nhường ghế. Qua mỗi lần cải tổ, cái lõi vẫn giữ nguyên: một chính phủ đặt lợi ích dân tộc lên trên mọi khác biệt đảng phái, tôn giáo."},{"t":"Bạn có biết? Nhiều ngành ngày nay lấy ngày 28/8/1945, ngày công bố thành phần Chính phủ lâm thời, làm ngày truyền thống của mình, trong đó có ngành Ngoại giao, Nội vụ, Tư pháp, Tài chính và Giao thông vận tải."},{"t":"Dấu tích hôm nay. Bắc Bộ phủ, nơi Chính phủ lâm thời họp phiên đầu tiên và làm việc trong những tháng đầu, nay là Nhà khách Chính phủ ở số 12 Ngô Quyền, Hà Nội. Nhiều văn bản gốc của Chính phủ những ngày đầu, từ các sắc lệnh do Chủ tịch Hồ Chí Minh ký đến biên bản các phiên họp Hội đồng Chính phủ, đang được bảo quản tại Trung tâm Lưu trữ quốc gia III. Đây là nơi lưu giữ tài liệu của các cơ quan nhà nước từ năm 1945 trở đi. Tấm ảnh trên bảng này, trong kho tư liệu được ghi thời điểm tháng 3/1946, tức khi bộ máy Chính phủ đã qua những lần mở rộng, gợi lại diện mạo của những con người gánh vác việc nước buổi đầu. Nhiều người trong số họ tiếp tục gắn bó với cuộc kháng chiến trường kỳ. Có người không trở về: học giả Nguyễn Văn Tố, vị Bộ trưởng Bộ Cứu tế xã hội năm 1945, bị thực dân Pháp bắt và sát hại ở Bắc Kạn tháng 10/1947. Mỗi cái tên trong danh sách mười lăm người năm ấy là một câu chuyện riêng về lựa chọn đứng về phía dân tộc."}],"so_chu":1863},{"i":8,"tieu_de_bang":"Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, 1946","tieu_de":"Lá phiếu đầu tiên: Tổng tuyển cử 6/1/1946 và Quốc hội khóa I","sapo":"Tấm ảnh được ghi ngày 2/3/1946, ngày những người đại biểu do dân bầu ra lần đầu tiên ngồi lại với nhau trong một nghị trường giữa Thủ đô. Để có được ngày ấy, khoảng tám mươi chín phần trăm cử tri cả nước đã đi bầu, có nơi phải bỏ phiếu dưới làn đạn. Và chỉ bốn ngày sau phiên họp, Chính phủ do chính Quốc hội ấy thông qua đặt bút ký một hiệp định định đoạt vận nước.","bia":{"src":"textures/ht/ht_anh_quoc_hoi_vndcch_khoa_i.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một ngày ở Nhà hát Lớn","text":"Ngày 2/3/1946, Nhà hát Lớn Hà Nội, công trình do người Pháp xây dựng và khánh thành năm 1911, đón những vị khách chưa từng có: các đại biểu Quốc hội đầu tiên của nước Việt Nam Dân chủ Cộng hòa. Hơn sáu tháng trước, sáng 19/8/1945, quảng trường trước nhà hát là nơi diễn ra cuộc mít tinh mở đầu cuộc khởi nghĩa giành chính quyền ở Hà Nội. Nay trong khán phòng ấy, lần đầu tiên người Việt Nam họp nghị viện của chính mình.\n\nTấm ảnh tư liệu của bảng này được ghi đúng ngày hôm ấy. Trong hàng ghế đại biểu có công nhân, nông dân, trí thức, nhà công thương, chức sắc tôn giáo, đại biểu đồng bào các dân tộc thiểu số, và cả những người phụ nữ lần đầu bước vào nghị trường. Họ là kết quả của một cuộc bầu cử được chuẩn bị chỉ trong khoảng bốn tháng, giữa lúc đất nước bị bủa vây bởi nạn đói, quân đội nước ngoài và cuộc chiến đã bùng nổ ở Nam Bộ. Để hiểu giá trị của căn phòng ấy, cần trở lại một buổi họp Chính phủ mùa thu năm trước.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoi_vndcch_khoa_i.jpg","chu_thich":"Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa — ảnh tư liệu được ghi ngày 2/3/1946, ngày khai mạc kỳ họp thứ nhất.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ý tưởng từ phiên họp Chính phủ đầu tiên","text":"Tại phiên họp đầu tiên của Chính phủ ngày 3/9/1945 (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa), trong sáu nhiệm vụ cấp bách, Chủ tịch Hồ Chí Minh dành nhiệm vụ thứ ba cho Tổng tuyển cử. Người nhắc rằng dưới chế độ quân chủ chuyên chế rồi chế độ thực dân, nước ta chưa từng có hiến pháp, nhân dân không được hưởng quyền tự do dân chủ.\n\nĐề nghị ấy được biến thành hành động gần như tức thì. Ngày 8/9/1945, chỉ sáu ngày sau lễ Độc lập, Người ký sắc lệnh về cuộc Tổng tuyển cử để bầu Quốc dân Đại hội. Ngày 20/9/1945, một Ban dự thảo Hiến pháp gồm bảy người, trong đó có chính Chủ tịch Hồ Chí Minh, được thành lập. Tháng 10/1945, thể lệ Tổng tuyển cử được ban hành. Điều đáng chú ý là nguyên tắc phổ thông đầu phiếu được đặt ra ngay từ đầu, không kèm điều kiện về tài sản hay học vấn, vào lúc hơn chín phần mười dân số còn chưa biết chữ.","doc":2},{"loai":"trich","text":"Chúng ta phải có một hiến pháp dân chủ. Tôi đề nghị Chính phủ tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu. Tất cả công dân trai gái mười tám tuổi đều có quyền ứng cử và bầu cử, không phân biệt giàu nghèo, tôn giáo, dòng giống, v.v.","nguoi":"Hồ Chí Minh, Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, 3/9/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":3},{"loai":"doan","tieu_de":"Bốn tháng chuẩn bị giữa vòng vây","text":"Ngày bầu cử ban đầu được ấn định là 23/12/1945. Nhưng những tháng cuối năm ấy, các tổ chức dựa vào quân Tưởng như Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội ra sức phản đối, đòi chia ghế, xuyên tạc cuộc bầu cử. Ở Nam Bộ và nam Trung Bộ, thực dân Pháp đã nổ súng xâm lược từ ngày 23/9/1945. Để có thêm thời gian cho việc nộp đơn ứng cử và chuẩn bị ở các địa phương, Chính phủ quyết định lùi ngày bầu cử sang Chủ nhật 6/1/1946.\n\nKhắp nơi, các ban bầu cử được lập, danh sách cử tri được niêm yết, báo chí và khẩu hiệu cổ động đi bầu xuất hiện ở phố phường, làng xóm. Trên báo Cứu quốc ngày 31/12/1945, Chủ tịch Hồ Chí Minh có bài “Ý nghĩa Tổng tuyển cử”. Người viết rằng Tổng tuyển cử là dịp cho toàn thể quốc dân tự do lựa chọn những người có tài, có đức để gánh vác công việc nước nhà. Hễ là người muốn lo việc nước thì đều có quyền ra ứng cử, hễ là công dân thì đều có quyền đi bầu cử.","doc":4},{"loai":"anh","src":"textures/bang_w/G14_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, 1946”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vị Chủ tịch ứng cử như mọi công dân","text":"Nhiều địa phương muốn giới thiệu Chủ tịch Hồ Chí Minh ra ứng cử ở nơi mình. Theo nhiều tư liệu, Người cảm ơn đồng bào và cho biết mình chỉ ứng cử ở một nơi là Hà Nội, như mọi công dân khác. Trên lá phiếu của Thủ đô, vị Chủ tịch nước là một ứng cử viên trong danh sách chung, để cử tri tự quyết định.\n\nNgày 5/1/1946, trước ngày bầu cử, Người ra Lời kêu gọi quốc dân đi bỏ phiếu. Lời kêu gọi ngắn, lặp đi lặp lại hai chữ “ngày mai” như một nhịp trống thúc giục. Người nhắc đến các chiến sĩ đang chiến đấu ở miền Nam: họ dùng súng đạn chống quân thù, còn nhân dân dùng lá phiếu, vì “một lá phiếu cũng có sức lực như một viên đạn”. Với hàng triệu người lần đầu cầm lá phiếu, đó là lời mời bước vào một đời sống chính trị hoàn toàn mới, nơi người dân không còn là thần dân hay dân thuộc địa mà là chủ nhân của đất nước.","doc":5},{"loai":"trich","text":"Ngày mai mồng 6 tháng Giêng năm 1946. Ngày mai là một ngày sẽ đưa quốc dân ta lên con đường mới mẻ. Ngày mai là một ngày vui sướng của đồng bào ta, vì ngày mai là ngày Tổng tuyển cử, vì ngày mai là một ngày đầu tiên trong lịch sử Việt Nam mà nhân dân ta bắt đầu hưởng dụng quyền dân chủ của mình.","nguoi":"Hồ Chí Minh, Lời kêu gọi quốc dân đi bỏ phiếu, 5/1/1946","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":6},{"loai":"doan","tieu_de":"Chủ nhật 6/1/1946","text":"Sáng 6/1/1946, theo nhiều tư liệu, Chủ tịch Hồ Chí Minh đến bỏ phiếu tại phòng bỏ phiếu đặt ở số nhà 10 phố Hàng Vôi, Hà Nội. Ở Thủ đô, 91,95% cử tri đi bầu. Người trúng cử với 98,4% số phiếu, cao nhất trong số các đại biểu của Hà Nội. Tính chung cả nước, tỷ lệ cử tri đi bầu đạt khoảng 89%, một con số đáng kinh ngạc với một dân tộc lần đầu biết đến lá phiếu.\n\nỞ Nam Bộ và nam Trung Bộ, cuộc bầu cử diễn ra giữa chiến tranh. Nhiều nơi cử tri phải bỏ phiếu dưới làn đạn của thực dân Pháp, và không ít cán bộ, cử tri đã hy sinh để bảo vệ hòm phiếu. Kết quả, cả nước bầu ra 333 đại biểu. Lời Người nói về sức lực của lá phiếu, chỉ một ngày trước đó, đã được chính đồng bào ở những vùng có chiến sự chứng minh bằng hành động.","doc":7},{"loai":"ban_co_biet","text":"Với cuộc Tổng tuyển cử ngày 6/1/1946, phụ nữ Việt Nam lần đầu tiên được bầu cử và ứng cử ngang quyền với nam giới. Khi ấy, ở nhiều nước châu Âu, quyền bầu cử của phụ nữ cũng mới vừa được công nhận.","nguon_ten":"Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam","doc":8},{"loai":"doan","tieu_de":"Bốn trăm lẻ ba ghế","text":"Kết quả bầu cử không khép lại cuộc đấu tranh chính trị. Để giữ khối đoàn kết và tránh cớ cho quân Tưởng can thiệp, Chủ tịch Hồ Chí Minh đề nghị một giải pháp đặc biệt. Tại kỳ họp thứ nhất, Quốc hội chấp thuận dành thêm 70 ghế không qua bầu cử cho đại diện Việt Nam Quốc dân Đảng và Việt Nam Cách mạng Đồng minh hội. Tổng số đại biểu vì thế lên tới 403 người. Đó là một sự nhân nhượng lớn nhưng có nguyên tắc, vì quyền quyết định vẫn thuộc về Quốc hội mà đa số đại biểu do dân bầu.\n\nThành phần Quốc hội khóa I phản ánh tinh thần đoàn kết mà Chủ tịch Hồ Chí Minh theo đuổi từ ngày lập quốc. Trong nghị trường có những nhà cách mạng từng qua nhà tù thực dân, những nhân sĩ, trí thức nổi tiếng như học giả Nguyễn Văn Tố, những người không đảng phái, các chức sắc tôn giáo và đại biểu của nhiều dân tộc.","doc":9},{"loai":"anh","src":"textures/bang_w/G14_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, 1946”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Phiên họp ngày 2/3/1946","text":"Kỳ họp thứ nhất chỉ diễn ra trong ngày 2/3/1946 nhưng đưa ra những quyết định lớn. Quốc hội nhất trí bầu Chủ tịch Hồ Chí Minh làm Chủ tịch Chính phủ Liên hiệp kháng chiến và thông qua danh sách Chính phủ do Người giới thiệu (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa). Quốc hội lập Ban Thường trực do học giả Nguyễn Văn Tố làm Trưởng ban, và lập Ủy ban Kháng chiến do Võ Nguyên Giáp làm Chủ tịch.\n\nThời điểm của phiên họp mang ý nghĩa đặc biệt. Chỉ mấy ngày trước đó, ngày 28/2/1946, Chính phủ Tưởng Giới Thạch và Chính phủ Pháp ký Hiệp ước Hoa – Pháp, mở đường cho quân Pháp kéo ra miền Bắc. Bốn ngày sau phiên họp, ngày 6/3/1946, Chính phủ do Quốc hội vừa thông qua đặt bút ký Hiệp định Sơ bộ với Pháp (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946). Có một Quốc hội do toàn dân bầu ra đứng sau là tư cách pháp lý quan trọng nhất của Chính phủ khi ngồi vào bàn đàm phán với một cường quốc.","doc":10},{"loai":"doan","tieu_de":"Bản Hiến pháp đầu tiên","text":"Kỳ họp thứ hai của Quốc hội khóa I diễn ra từ ngày 28/10 đến 9/11/1946, sau khi Chủ tịch Hồ Chí Minh từ Pháp trở về. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa, gồm Lời nói đầu, bảy chương và bảy mươi điều. Điều thứ nhất khẳng định nước Việt Nam là một nước dân chủ cộng hòa, tất cả quyền bính trong nước là của toàn thể nhân dân Việt Nam, không phân biệt nòi giống, gái trai, giàu nghèo, giai cấp, tôn giáo.\n\nTại kỳ họp này, Quốc hội cũng thông qua Chính phủ mới do Người đứng đầu. Bản Hiến pháp ngắn gọn mà tiến bộ ấy ra đời chỉ hơn một tháng trước đêm toàn quốc kháng chiến 19/12/1946. Tinh thần của nó, quyền làm chủ của nhân dân và sự bình đẳng của mọi công dân trước pháp luật, đã trở thành nền móng cho các bản hiến pháp của nước Việt Nam về sau.","doc":11},{"loai":"ban_co_biet","text":"Do chiến tranh bùng nổ ngay sau đó, Hiến pháp năm 1946 chưa được chính thức công bố để thi hành. Suốt những năm kháng chiến, Chính phủ và Ban Thường trực Quốc hội vẫn dựa vào tinh thần và các nguyên tắc của bản Hiến pháp này để điều hành đất nước.","nguon_ten":"Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam","doc":12},{"loai":"doan","tieu_de":"Mười bốn năm và dấu tích hôm nay","text":"Quốc hội khóa I hoạt động suốt mười bốn năm, qua trọn cuộc kháng chiến chống thực dân Pháp, có kỳ họp diễn ra giữa chiến khu Việt Bắc, cho tới khi Quốc hội khóa II được bầu ngày 8/5/1960. Chủ tịch Hồ Chí Minh tiếp tục là đại biểu Quốc hội các khóa II và III.\n\nNhà hát Lớn Hà Nội hôm nay vẫn là nhà hát nghệ thuật hàng đầu của Thủ đô, và không phải khán giả nào cũng biết khán phòng ấy từng là nghị trường đầu tiên của nước Việt Nam độc lập. Nhiều tài liệu gốc về Tổng tuyển cử và Quốc hội khóa I được lưu giữ tại Trung tâm Lưu trữ quốc gia III. Ngày nay, Quốc hội họp tại Nhà Quốc hội bên Quảng trường Ba Đình, chỉ cách nơi đọc Tuyên ngôn Độc lập một quãng ngắn. Tấm ảnh năm 1946 trên bảng này nối hai không gian ấy: lời tuyên bố độc lập chiều 2/9/1945 đã trở thành một nhà nước có Quốc hội, có Hiến pháp của mình.","doc":13},{"loai":"anh","src":"textures/bang_w/G14_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, 1946”, nhìn từ trên cao."}],"nguon":["Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Những nhiệm vụ cấp bách…; Ý nghĩa Tổng tuyển cử; Lời kêu gọi quốc dân đi bỏ phiếu)","Hiến pháp nước Việt Nam Dân chủ Cộng hòa năm 1946","Trung tâm Lưu trữ quốc gia III"],"doc":[{"t":"Lá phiếu đầu tiên: Tổng tuyển cử 6/1/1946 và Quốc hội khóa I. Tấm ảnh được ghi ngày 2/3/1946, ngày những người đại biểu do dân bầu ra lần đầu tiên ngồi lại với nhau trong một nghị trường giữa Thủ đô. Để có được ngày ấy, khoảng tám mươi chín phần trăm cử tri cả nước đã đi bầu, có nơi phải bỏ phiếu dưới làn đạn. Và chỉ bốn ngày sau phiên họp, Chính phủ do chính Quốc hội ấy thông qua đặt bút ký một hiệp định định đoạt vận nước."},{"t":"Một ngày ở Nhà hát Lớn. Ngày 2/3/1946, Nhà hát Lớn Hà Nội, công trình do người Pháp xây dựng và khánh thành năm 1911, đón những vị khách chưa từng có: các đại biểu Quốc hội đầu tiên của nước Việt Nam Dân chủ Cộng hòa. Hơn sáu tháng trước, sáng 19/8/1945, quảng trường trước nhà hát là nơi diễn ra cuộc mít tinh mở đầu cuộc khởi nghĩa giành chính quyền ở Hà Nội. Nay trong khán phòng ấy, lần đầu tiên người Việt Nam họp nghị viện của chính mình. Tấm ảnh tư liệu của bảng này được ghi đúng ngày hôm ấy. Trong hàng ghế đại biểu có công nhân, nông dân, trí thức, nhà công thương, chức sắc tôn giáo, đại biểu đồng bào các dân tộc thiểu số, và cả những người phụ nữ lần đầu bước vào nghị trường. Họ là kết quả của một cuộc bầu cử được chuẩn bị chỉ trong khoảng bốn tháng, giữa lúc đất nước bị bủa vây bởi nạn đói, quân đội nước ngoài và cuộc chiến đã bùng nổ ở Nam Bộ. Để hiểu giá trị của căn phòng ấy, cần trở lại một buổi họp Chính phủ mùa thu năm trước."},{"t":"Ý tưởng từ phiên họp Chính phủ đầu tiên. Tại phiên họp đầu tiên của Chính phủ ngày 3/9/1945 (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa), trong sáu nhiệm vụ cấp bách, Chủ tịch Hồ Chí Minh dành nhiệm vụ thứ ba cho Tổng tuyển cử. Người nhắc rằng dưới chế độ quân chủ chuyên chế rồi chế độ thực dân, nước ta chưa từng có hiến pháp, nhân dân không được hưởng quyền tự do dân chủ. Đề nghị ấy được biến thành hành động gần như tức thì. Ngày 8/9/1945, chỉ sáu ngày sau lễ Độc lập, Người ký sắc lệnh về cuộc Tổng tuyển cử để bầu Quốc dân Đại hội. Ngày 20/9/1945, một Ban dự thảo Hiến pháp gồm bảy người, trong đó có chính Chủ tịch Hồ Chí Minh, được thành lập. Tháng 10/1945, thể lệ Tổng tuyển cử được ban hành. Điều đáng chú ý là nguyên tắc phổ thông đầu phiếu được đặt ra ngay từ đầu, không kèm điều kiện về tài sản hay học vấn, vào lúc hơn chín phần mười dân số còn chưa biết chữ."},{"t":"Chúng ta phải có một hiến pháp dân chủ. Tôi đề nghị Chính phủ tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu. Tất cả công dân trai gái mười tám tuổi đều có quyền ứng cử và bầu cử, không phân biệt giàu nghèo, tôn giáo, dòng giống, v.v. — Hồ Chí Minh, Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, 3/9/1945"},{"t":"Bốn tháng chuẩn bị giữa vòng vây. Ngày bầu cử ban đầu được ấn định là 23/12/1945. Nhưng những tháng cuối năm ấy, các tổ chức dựa vào quân Tưởng như Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội ra sức phản đối, đòi chia ghế, xuyên tạc cuộc bầu cử. Ở Nam Bộ và nam Trung Bộ, thực dân Pháp đã nổ súng xâm lược từ ngày 23/9/1945. Để có thêm thời gian cho việc nộp đơn ứng cử và chuẩn bị ở các địa phương, Chính phủ quyết định lùi ngày bầu cử sang Chủ nhật 6/1/1946. Khắp nơi, các ban bầu cử được lập, danh sách cử tri được niêm yết, báo chí và khẩu hiệu cổ động đi bầu xuất hiện ở phố phường, làng xóm. Trên báo Cứu quốc ngày 31/12/1945, Chủ tịch Hồ Chí Minh có bài “Ý nghĩa Tổng tuyển cử”. Người viết rằng Tổng tuyển cử là dịp cho toàn thể quốc dân tự do lựa chọn những người có tài, có đức để gánh vác công việc nước nhà. Hễ là người muốn lo việc nước thì đều có quyền ra ứng cử, hễ là công dân thì đều có quyền đi bầu cử."},{"t":"Vị Chủ tịch ứng cử như mọi công dân. Nhiều địa phương muốn giới thiệu Chủ tịch Hồ Chí Minh ra ứng cử ở nơi mình. Theo nhiều tư liệu, Người cảm ơn đồng bào và cho biết mình chỉ ứng cử ở một nơi là Hà Nội, như mọi công dân khác. Trên lá phiếu của Thủ đô, vị Chủ tịch nước là một ứng cử viên trong danh sách chung, để cử tri tự quyết định. Ngày 5/1/1946, trước ngày bầu cử, Người ra Lời kêu gọi quốc dân đi bỏ phiếu. Lời kêu gọi ngắn, lặp đi lặp lại hai chữ “ngày mai” như một nhịp trống thúc giục. Người nhắc đến các chiến sĩ đang chiến đấu ở miền Nam: họ dùng súng đạn chống quân thù, còn nhân dân dùng lá phiếu, vì “một lá phiếu cũng có sức lực như một viên đạn”. Với hàng triệu người lần đầu cầm lá phiếu, đó là lời mời bước vào một đời sống chính trị hoàn toàn mới, nơi người dân không còn là thần dân hay dân thuộc địa mà là chủ nhân của đất nước."},{"t":"Ngày mai mồng 6 tháng Giêng năm 1946. Ngày mai là một ngày sẽ đưa quốc dân ta lên con đường mới mẻ. Ngày mai là một ngày vui sướng của đồng bào ta, vì ngày mai là ngày Tổng tuyển cử, vì ngày mai là một ngày đầu tiên trong lịch sử Việt Nam mà nhân dân ta bắt đầu hưởng dụng quyền dân chủ của mình. — Hồ Chí Minh, Lời kêu gọi quốc dân đi bỏ phiếu, 5/1/1946"},{"t":"Chủ nhật 6/1/1946. Sáng 6/1/1946, theo nhiều tư liệu, Chủ tịch Hồ Chí Minh đến bỏ phiếu tại phòng bỏ phiếu đặt ở số nhà 10 phố Hàng Vôi, Hà Nội. Ở Thủ đô, 91,95% cử tri đi bầu. Người trúng cử với 98,4% số phiếu, cao nhất trong số các đại biểu của Hà Nội. Tính chung cả nước, tỷ lệ cử tri đi bầu đạt khoảng 89%, một con số đáng kinh ngạc với một dân tộc lần đầu biết đến lá phiếu. Ở Nam Bộ và nam Trung Bộ, cuộc bầu cử diễn ra giữa chiến tranh. Nhiều nơi cử tri phải bỏ phiếu dưới làn đạn của thực dân Pháp, và không ít cán bộ, cử tri đã hy sinh để bảo vệ hòm phiếu. Kết quả, cả nước bầu ra 333 đại biểu. Lời Người nói về sức lực của lá phiếu, chỉ một ngày trước đó, đã được chính đồng bào ở những vùng có chiến sự chứng minh bằng hành động."},{"t":"Bạn có biết? Với cuộc Tổng tuyển cử ngày 6/1/1946, phụ nữ Việt Nam lần đầu tiên được bầu cử và ứng cử ngang quyền với nam giới. Khi ấy, ở nhiều nước châu Âu, quyền bầu cử của phụ nữ cũng mới vừa được công nhận."},{"t":"Bốn trăm lẻ ba ghế. Kết quả bầu cử không khép lại cuộc đấu tranh chính trị. Để giữ khối đoàn kết và tránh cớ cho quân Tưởng can thiệp, Chủ tịch Hồ Chí Minh đề nghị một giải pháp đặc biệt. Tại kỳ họp thứ nhất, Quốc hội chấp thuận dành thêm 70 ghế không qua bầu cử cho đại diện Việt Nam Quốc dân Đảng và Việt Nam Cách mạng Đồng minh hội. Tổng số đại biểu vì thế lên tới 403 người. Đó là một sự nhân nhượng lớn nhưng có nguyên tắc, vì quyền quyết định vẫn thuộc về Quốc hội mà đa số đại biểu do dân bầu. Thành phần Quốc hội khóa I phản ánh tinh thần đoàn kết mà Chủ tịch Hồ Chí Minh theo đuổi từ ngày lập quốc. Trong nghị trường có những nhà cách mạng từng qua nhà tù thực dân, những nhân sĩ, trí thức nổi tiếng như học giả Nguyễn Văn Tố, những người không đảng phái, các chức sắc tôn giáo và đại biểu của nhiều dân tộc."},{"t":"Phiên họp ngày 2/3/1946. Kỳ họp thứ nhất chỉ diễn ra trong ngày 2/3/1946 nhưng đưa ra những quyết định lớn. Quốc hội nhất trí bầu Chủ tịch Hồ Chí Minh làm Chủ tịch Chính phủ Liên hiệp kháng chiến và thông qua danh sách Chính phủ do Người giới thiệu (xem chuyên đề Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa). Quốc hội lập Ban Thường trực do học giả Nguyễn Văn Tố làm Trưởng ban, và lập Ủy ban Kháng chiến do Võ Nguyên Giáp làm Chủ tịch. Thời điểm của phiên họp mang ý nghĩa đặc biệt. Chỉ mấy ngày trước đó, ngày 28/2/1946, Chính phủ Tưởng Giới Thạch và Chính phủ Pháp ký Hiệp ước Hoa – Pháp, mở đường cho quân Pháp kéo ra miền Bắc. Bốn ngày sau phiên họp, ngày 6/3/1946, Chính phủ do Quốc hội vừa thông qua đặt bút ký Hiệp định Sơ bộ với Pháp (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946). Có một Quốc hội do toàn dân bầu ra đứng sau là tư cách pháp lý quan trọng nhất của Chính phủ khi ngồi vào bàn đàm phán với một cường quốc."},{"t":"Bản Hiến pháp đầu tiên. Kỳ họp thứ hai của Quốc hội khóa I diễn ra từ ngày 28/10 đến 9/11/1946, sau khi Chủ tịch Hồ Chí Minh từ Pháp trở về. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa, gồm Lời nói đầu, bảy chương và bảy mươi điều. Điều thứ nhất khẳng định nước Việt Nam là một nước dân chủ cộng hòa, tất cả quyền bính trong nước là của toàn thể nhân dân Việt Nam, không phân biệt nòi giống, gái trai, giàu nghèo, giai cấp, tôn giáo. Tại kỳ họp này, Quốc hội cũng thông qua Chính phủ mới do Người đứng đầu. Bản Hiến pháp ngắn gọn mà tiến bộ ấy ra đời chỉ hơn một tháng trước đêm toàn quốc kháng chiến 19/12/1946. Tinh thần của nó, quyền làm chủ của nhân dân và sự bình đẳng của mọi công dân trước pháp luật, đã trở thành nền móng cho các bản hiến pháp của nước Việt Nam về sau."},{"t":"Bạn có biết? Do chiến tranh bùng nổ ngay sau đó, Hiến pháp năm 1946 chưa được chính thức công bố để thi hành. Suốt những năm kháng chiến, Chính phủ và Ban Thường trực Quốc hội vẫn dựa vào tinh thần và các nguyên tắc của bản Hiến pháp này để điều hành đất nước."},{"t":"Mười bốn năm và dấu tích hôm nay. Quốc hội khóa I hoạt động suốt mười bốn năm, qua trọn cuộc kháng chiến chống thực dân Pháp, có kỳ họp diễn ra giữa chiến khu Việt Bắc, cho tới khi Quốc hội khóa II được bầu ngày 8/5/1960. Chủ tịch Hồ Chí Minh tiếp tục là đại biểu Quốc hội các khóa II và III. Nhà hát Lớn Hà Nội hôm nay vẫn là nhà hát nghệ thuật hàng đầu của Thủ đô, và không phải khán giả nào cũng biết khán phòng ấy từng là nghị trường đầu tiên của nước Việt Nam độc lập. Nhiều tài liệu gốc về Tổng tuyển cử và Quốc hội khóa I được lưu giữ tại Trung tâm Lưu trữ quốc gia III. Ngày nay, Quốc hội họp tại Nhà Quốc hội bên Quảng trường Ba Đình, chỉ cách nơi đọc Tuyên ngôn Độc lập một quãng ngắn. Tấm ảnh năm 1946 trên bảng này nối hai không gian ấy: lời tuyên bố độc lập chiều 2/9/1945 đã trở thành một nhà nước có Quốc hội, có Hiến pháp của mình."}],"so_chu":1959},{"i":9,"tieu_de_bang":"Ngày Tiễu trừ nạn đói, Hà Nội 1945","tieu_de":"“Lúc chúng ta nâng bát cơm mà ăn…”: mặt trận chống giặc đói mùa thu 1945","sapo":"Hơn một tháng sau ngày Độc lập, một tấm ảnh tư liệu ở Hà Nội mang cái tên nghe như lệnh ra quân: “Ngày Tiễu trừ nạn đói”. Mùa thu năm 1945, cái đói cũng là một thứ giặc, và nó vừa cướp đi hơn hai triệu sinh mạng. Nhà nước non trẻ đã đánh thứ giặc ấy bằng những bữa cơm nhịn, những hũ gạo nhỏ và những luống khoai trồng vội trên đất vừa rút lũ.","bia":{"src":"textures/ht/ht_anh_ngay_tieu_tru_nan_doi.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một cái tên như lệnh ra quân","text":"Trong kho ảnh tư liệu về những ngày đầu của nước Việt Nam Dân chủ Cộng hòa, có một tấm ảnh được ghi là của Bộ Thông tin Tuyên truyền, niên đại tháng 10/1945, mang dòng chú “Ngày Tiễu trừ nạn đói”. Chữ “tiễu trừ” vốn thuộc về ngôn ngữ quân sự: người ta vẫn nói tiễu trừ giặc cướp, tiễu trừ thổ phỉ. Đặt chữ ấy cạnh hai chữ “nạn đói”, những người tổ chức muốn nói với dân Thủ đô một điều giản dị mà nghiêm trọng: cái đói là kẻ thù, và phải đánh nó như đánh giặc.\n\nLúc ấy, Hà Nội mới hưởng độc lập hơn một tháng. Cờ đỏ sao vàng còn tươi màu trên các phố, nhưng ký ức về mùa xuân năm Ất Dậu chưa hề phai. Chỉ mấy tháng trước, người đói từ các tỉnh đồng bằng đã lũ lượt kéo về thành phố tìm cái ăn; nhiều người gục ngã ngay trên hè phố, và các hội thiện phải dùng xe đi thu nhặt thi thể. Tấm ảnh vì thế không chỉ ghi lại một cuộc vận động. Nó ghi lại quyết tâm của cả một thành phố không để cảnh tượng ấy lặp lại.","doc":1},{"loai":"doan","tieu_de":"Mùa xuân năm Ất Dậu","text":"Nạn đói bắt đầu từ cuối năm 1944, lên đến đỉnh điểm trong những tháng đầu năm 1945, trải dài từ Quảng Trị ra khắp các tỉnh Bắc Kỳ. Nguyên nhân không chỉ ở trời. Để phục vụ chiến tranh, phát xít Nhật buộc nông dân nhổ lúa trồng đay và các loại cây công nghiệp, đồng thời vơ vét thóc gạo với giá rẻ mạt. Chính quyền thực dân Pháp thì bắt dân bán thóc theo định suất và tích trữ lương thực cho quân đội. Đường vận chuyển gạo từ Nam Kỳ ra Bắc gần như bị chiến tranh cắt đứt. Khi mùa màng thất bát, người nông dân không còn một hạt thóc dự trữ.\n\nChiều 2/9/1945, bản Tuyên ngôn Độc lập đọc ở Ba Đình đã nêu con số ấy như một lời cáo trạng: từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào ta bị chết đói. Những tỉnh đông dân của đồng bằng Bắc Bộ như Thái Bình, Nam Định chịu tổn thất nặng nề nhất.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngày Tiễu trừ nạn đói, Hà Nội 1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Giặc đói chực trở lại","text":"Cách mạng Tháng Tám thành công khi vết thương của nạn đói còn chưa kịp lành, thì thiên tai lại ập đến. Tháng 8/1945, nước lũ làm vỡ đê ở chín tỉnh Bắc Bộ; tiếp theo là hạn hán kéo dài, khiến khoảng một nửa diện tích ruộng đất không cày cấy được. Kho thóc của nhà nước mới gần như trống rỗng. Trong khi đó, khoảng hai mươi vạn quân Tưởng kéo vào miền Bắc cũng cần lương thực, còn những chuyến gạo từ phương Nam sắp bị tiếng súng ở Nam Bộ chặn lại. Nguy cơ một nạn đói thứ hai, ngay trong năm đầu độc lập, là hoàn toàn có thật.\n\nNgày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ lâm thời. Trong sáu nhiệm vụ cấp bách Người nêu ra (xem chuyên đề về Chính phủ lâm thời), việc đầu tiên được gọi đúng tên: nhân dân đang đói. Người đề nghị phát động ngay một chiến dịch tăng gia sản xuất. Trong lúc chờ ngô, khoai và các thứ lương thực phụ phải ba, bốn tháng mới có, Người đề nghị mở một cuộc lạc quyên: mười ngày một lần, mọi người nhịn ăn một bữa, gạo tiết kiệm được góp lại để phát cho người nghèo.","doc":3},{"loai":"doan","tieu_de":"Mười ngày nhịn một bữa","text":"Ít ngày sau, trong tháng 9/1945, Chủ tịch Hồ Chí Minh gửi tới đồng bào cả nước lời kêu gọi cứu đói. Người không viết bằng giọng mệnh lệnh của một nguyên thủ, mà bằng lời của một người trong nhà nói với anh em. Người đề nghị đồng bào, và nói rõ mình xin thực hành trước, cứ mười ngày nhịn ăn một bữa, mỗi tháng nhịn ba bữa, đem số gạo ấy cứu dân nghèo. Như thế, những người nghèo sẽ có bữa rau bữa cháo để chờ mùa lúa năm sau, khỏi đến nỗi chết đói.\n\nLời đề nghị tưởng nhỏ mà tính toán rất thực tế. Một bữa gạo của một người không đáng là bao, nhưng nhân lên với hàng triệu gia đình, mỗi tháng ba lần, nó thành những kho gạo đủ nuôi người nghèo qua mấy tháng giáp hạt. Quan trọng hơn, nó biến việc cứu đói thành việc của từng mâm cơm: ai cũng có thể góp, và ai góp cũng hiểu gạo của mình đi đâu. Người đứng đầu Nhà nước tự nhận phần nhịn trước, nên lời kêu gọi mang sức nặng của một tấm gương chứ không chỉ của một chủ trương.","doc":4},{"loai":"trich","text":"Lúc chúng ta nâng bát cơm mà ăn, nghĩ đến kẻ đói khổ, chúng ta không khỏi động lòng.","nguoi":"Hồ Chí Minh, Lời kêu gọi đồng bào cả nước cứu đói, tháng 9/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":5},{"loai":"doan","tieu_de":"Hũ gạo trong mỗi gian bếp","text":"Lời kêu gọi đi vào đời sống bằng những hình thức rất cụ thể. Trong nhiều gia đình, cạnh chum gạo ăn hằng ngày có thêm một chiếc hũ nhỏ: mỗi bữa, người nội trợ bớt ra một nắm, dồn lại thành “hũ gạo cứu đói”. Ở các khu phố, làng xóm, những “ngày đồng tâm” được tổ chức, khi cả cộng đồng cùng nhịn một bữa để góp gạo. Các đoàn thể thanh niên, phụ nữ, học sinh đi từng nhà lạc quyên tiền, gạo, quần áo cũ. Chính quyền bãi bỏ những lệnh ngăn cấm chuyên chở thóc gạo giữa các địa phương có từ thời trước, để gạo có thể về nhanh những vùng bị lụt.\n\nNhững ngày vận động mang tên như “Ngày Tiễu trừ nạn đói” trong tấm ảnh là những dịp để Thủ đô dồn sức vào cùng một thời điểm, biến lời kêu gọi của Chủ tịch nước thành cảnh người người góp gạo.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_ngay_tieu_tru_nan_doi.jpg","chu_thich":"“Ngày Tiễu trừ nạn đói” ở Hà Nội, tháng 10/1945 — ảnh tư liệu của Bộ Thông tin Tuyên truyền.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Không để một tấc đất bỏ hoang","text":"Lạc quyên chỉ giúp người đói qua cơn giáp hạt; muốn diệt tận gốc giặc đói phải làm ra thêm lương thực. Chủ tịch Hồ Chí Minh nhiều lần nhắc lại khẩu hiệu: “Tăng gia sản xuất! Tăng gia sản xuất ngay! Tăng gia sản xuất nữa!”. Trong Chính phủ lâm thời, Bộ Canh nông do nhà thơ Huy Cận làm Bộ trưởng. Nông dân được vận động trồng ngay các loại cây ngắn ngày như khoai lang, ngô, đậu, rau màu trên những chân ruộng vừa rút nước lũ. Đất công, bãi bồi ven sông, vườn tược đều được đem ra trồng trọt, theo tinh thần không để một tấc đất bỏ hoang.\n\nCùng với đó là những chính sách chạm đến quyền lợi thiết thân của người cày. Ruộng đất của thực dân và Việt gian bị tịch thu, tạm cấp cho nông dân nghèo; ruộng đất công được chia lại công bằng hơn; địa tô được giảm 25%. Thuế thân, thứ thuế nặng nề gắn với kiếp dân thuộc địa, bị bãi bỏ theo đúng một trong những nhiệm vụ cấp bách nêu ngày 3/9. Người nông dân hiểu rằng mỗi luống khoai họ trồng lúc ấy vừa để nuôi gia đình, vừa để giữ lấy chính quyền của mình.","doc":7},{"loai":"ban_co_biet","text":"Để dành lương thực cứu đói, Chính phủ nghiêm cấm việc đầu cơ tích trữ lúa gạo và cấm dùng gạo, ngô, khoai, sắn để nấu rượu.","nguon_ten":"Lịch sử 12, NXB Giáo dục Việt Nam","doc":8},{"loai":"doan","tieu_de":"Mùa xuân Bính Tuất không lặp lại mùa xuân Ất Dậu","text":"Nhờ những biện pháp đồng bộ ấy, chỉ trong một thời gian ngắn, sản xuất nông nghiệp ở miền Bắc được phục hồi. Những vụ khoai, ngô trồng từ cuối năm 1945 cho thu hoạch vào đầu năm 1946, lấp chỗ trống trong những tháng giáp hạt vốn đáng sợ nhất. Đến năm 1946, nạn đói về cơ bản đã bị đẩy lùi. Mùa xuân Ất Dậu năm trước đã cướp đi hơn hai triệu sinh mạng; mùa xuân Bính Tuất năm ấy, dù đất nước còn bộn bề thù trong giặc ngoài, thảm cảnh đó đã không tái diễn.\n\nVới nhiều người dân, đó là bằng chứng đầu tiên và rõ ràng nhất về sự khác biệt giữa chế độ cũ và chính quyền mới. Cùng với phong trào Bình dân học vụ chống giặc dốt (xem chuyên đề về các lớp Bình dân học vụ), thắng lợi trước giặc đói giúp nhà nước non trẻ đứng vững trong lòng dân. Để rồi khi cuộc kháng chiến toàn quốc bùng nổ cuối năm 1946, hàng triệu người đã sẵn sàng đi theo chính quyền từng cùng họ vượt qua cái đói.","doc":9},{"loai":"anh","src":"textures/bang_w/G14_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngày Tiễu trừ nạn đói, Hà Nội 1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Độc lập phải hiện ra trong bát cơm","text":"Chống giặc đói, với Chủ tịch Hồ Chí Minh, không chỉ là một chiến dịch cứu trợ. Trong những văn kiện của những tháng đầu chính quyền mới, Người nhiều lần đặt việc làm cho dân có ăn lên trước tiên, rồi mới đến có mặc, có chỗ ở, có học hành. Người hiểu rằng độc lập không thể chỉ nằm trên giấy; nó phải hiện ra trong bát cơm, manh áo của từng gia đình.\n\nTinh thần ấy thể hiện cả trong cách Người sống. Lời đề nghị nhịn ăn mười ngày một bữa đi kèm câu “tôi xin thực hành trước”. Theo hồi ức của những người từng làm việc bên Người, bữa ăn của vị Chủ tịch nước ở Bắc Bộ phủ những năm ấy vẫn đạm bạc như bữa ăn của một gia đình bình thường. Chính sự nhất quán giữa lời nói và việc làm đã khiến những hũ gạo nhỏ khắp nơi đầy lên, và khiến lời kêu gọi năm ấy còn được nhắc lại đến hôm nay.","doc":10},{"loai":"trich","text":"Chúng ta tranh được tự do, độc lập rồi mà dân cứ chết đói, chết rét, thì tự do, độc lập cũng không làm gì. Dân chỉ biết rõ giá trị của tự do, của độc lập khi mà dân được ăn no, mặc đủ.","nguoi":"Hồ Chí Minh","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":11},{"loai":"ban_co_biet","text":"Nhiếp ảnh gia Võ An Ninh, người sau này có mặt ghi hình những ngày Độc lập ở Hà Nội, đã chụp một loạt ảnh về nạn đói năm Ất Dậu — những tư liệu hình ảnh hiếm hoi còn lại về thảm cảnh ấy.","nguon_ten":"Hội Nghệ sĩ Nhiếp ảnh Việt Nam; Bảo tàng Lịch sử quốc gia","doc":12},{"loai":"anh","src":"textures/bang_w/G14_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngày Tiễu trừ nạn đói, Hà Nội 1945”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, tấm ảnh “Ngày Tiễu trừ nạn đói” thuộc nhóm ảnh tư liệu hiếm hoi còn lại về phong trào cứu đói những tháng đầu độc lập. Cùng với những bức ảnh về nạn đói năm Ất Dậu, nó thường được giới thiệu trong các cuộc trưng bày, sách ảnh về Cách mạng Tháng Tám và những năm đầu của nước Việt Nam Dân chủ Cộng hòa. Lời kêu gọi cứu đói và bài nói ngày 3/9/1945 được in trong bộ Hồ Chí Minh Toàn tập, để người đọc hôm nay có thể tìm lại nguyên văn.\n\nTrong gian trưng bày này, tấm ảnh được đặt giữa không gian Hà Nội mùa thu 1945, không xa căn gác Hàng Ngang và lễ đài Ba Đình. Sự sắp đặt ấy có chủ ý: niềm vui độc lập và cuộc chiến chống cái đói diễn ra cùng một lúc, trên cùng những con phố, với cùng những con người. Đứng trước tấm ảnh, khách tham quan có thể nhớ lại lời kêu gọi năm ấy: mỗi lần nâng bát cơm lên, hãy nghĩ đến những người đang đói.","doc":13}],"nguon":["Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật (Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa, 3/9/1945; Lời kêu gọi cứu đói, 9/1945)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945","Lịch sử 12, NXB Giáo dục Việt Nam","Thành ủy TP. Hồ Chí Minh — Bài học tuyên truyền từ hoạt động cứu đói năm 1945: https://hcmcpv.org.vn/tin-tuc/bai-hoc-tuyen-truyen-tu-hoat-dong-cuu-doi-nam-1945-1491881549","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"“Lúc chúng ta nâng bát cơm mà ăn…”: mặt trận chống giặc đói mùa thu 1945. Hơn một tháng sau ngày Độc lập, một tấm ảnh tư liệu ở Hà Nội mang cái tên nghe như lệnh ra quân: “Ngày Tiễu trừ nạn đói”. Mùa thu năm 1945, cái đói cũng là một thứ giặc, và nó vừa cướp đi hơn hai triệu sinh mạng. Nhà nước non trẻ đã đánh thứ giặc ấy bằng những bữa cơm nhịn, những hũ gạo nhỏ và những luống khoai trồng vội trên đất vừa rút lũ."},{"t":"Một cái tên như lệnh ra quân. Trong kho ảnh tư liệu về những ngày đầu của nước Việt Nam Dân chủ Cộng hòa, có một tấm ảnh được ghi là của Bộ Thông tin Tuyên truyền, niên đại tháng 10/1945, mang dòng chú “Ngày Tiễu trừ nạn đói”. Chữ “tiễu trừ” vốn thuộc về ngôn ngữ quân sự: người ta vẫn nói tiễu trừ giặc cướp, tiễu trừ thổ phỉ. Đặt chữ ấy cạnh hai chữ “nạn đói”, những người tổ chức muốn nói với dân Thủ đô một điều giản dị mà nghiêm trọng: cái đói là kẻ thù, và phải đánh nó như đánh giặc. Lúc ấy, Hà Nội mới hưởng độc lập hơn một tháng. Cờ đỏ sao vàng còn tươi màu trên các phố, nhưng ký ức về mùa xuân năm Ất Dậu chưa hề phai. Chỉ mấy tháng trước, người đói từ các tỉnh đồng bằng đã lũ lượt kéo về thành phố tìm cái ăn; nhiều người gục ngã ngay trên hè phố, và các hội thiện phải dùng xe đi thu nhặt thi thể. Tấm ảnh vì thế không chỉ ghi lại một cuộc vận động. Nó ghi lại quyết tâm của cả một thành phố không để cảnh tượng ấy lặp lại."},{"t":"Mùa xuân năm Ất Dậu. Nạn đói bắt đầu từ cuối năm 1944, lên đến đỉnh điểm trong những tháng đầu năm 1945, trải dài từ Quảng Trị ra khắp các tỉnh Bắc Kỳ. Nguyên nhân không chỉ ở trời. Để phục vụ chiến tranh, phát xít Nhật buộc nông dân nhổ lúa trồng đay và các loại cây công nghiệp, đồng thời vơ vét thóc gạo với giá rẻ mạt. Chính quyền thực dân Pháp thì bắt dân bán thóc theo định suất và tích trữ lương thực cho quân đội. Đường vận chuyển gạo từ Nam Kỳ ra Bắc gần như bị chiến tranh cắt đứt. Khi mùa màng thất bát, người nông dân không còn một hạt thóc dự trữ. Chiều 2/9/1945, bản Tuyên ngôn Độc lập đọc ở Ba Đình đã nêu con số ấy như một lời cáo trạng: từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào ta bị chết đói. Những tỉnh đông dân của đồng bằng Bắc Bộ như Thái Bình, Nam Định chịu tổn thất nặng nề nhất."},{"t":"Giặc đói chực trở lại. Cách mạng Tháng Tám thành công khi vết thương của nạn đói còn chưa kịp lành, thì thiên tai lại ập đến. Tháng 8/1945, nước lũ làm vỡ đê ở chín tỉnh Bắc Bộ; tiếp theo là hạn hán kéo dài, khiến khoảng một nửa diện tích ruộng đất không cày cấy được. Kho thóc của nhà nước mới gần như trống rỗng. Trong khi đó, khoảng hai mươi vạn quân Tưởng kéo vào miền Bắc cũng cần lương thực, còn những chuyến gạo từ phương Nam sắp bị tiếng súng ở Nam Bộ chặn lại. Nguy cơ một nạn đói thứ hai, ngay trong năm đầu độc lập, là hoàn toàn có thật. Ngày 3/9/1945, chỉ một ngày sau lễ Độc lập, Chủ tịch Hồ Chí Minh chủ trì phiên họp đầu tiên của Chính phủ lâm thời. Trong sáu nhiệm vụ cấp bách Người nêu ra (xem chuyên đề về Chính phủ lâm thời), việc đầu tiên được gọi đúng tên: nhân dân đang đói. Người đề nghị phát động ngay một chiến dịch tăng gia sản xuất. Trong lúc chờ ngô, khoai và các thứ lương thực phụ phải ba, bốn tháng mới có, Người đề nghị mở một cuộc lạc quyên: mười ngày một lần, mọi người nhịn ăn một bữa, gạo tiết kiệm được góp lại để phát cho người nghèo."},{"t":"Mười ngày nhịn một bữa. Ít ngày sau, trong tháng 9/1945, Chủ tịch Hồ Chí Minh gửi tới đồng bào cả nước lời kêu gọi cứu đói. Người không viết bằng giọng mệnh lệnh của một nguyên thủ, mà bằng lời của một người trong nhà nói với anh em. Người đề nghị đồng bào, và nói rõ mình xin thực hành trước, cứ mười ngày nhịn ăn một bữa, mỗi tháng nhịn ba bữa, đem số gạo ấy cứu dân nghèo. Như thế, những người nghèo sẽ có bữa rau bữa cháo để chờ mùa lúa năm sau, khỏi đến nỗi chết đói. Lời đề nghị tưởng nhỏ mà tính toán rất thực tế. Một bữa gạo của một người không đáng là bao, nhưng nhân lên với hàng triệu gia đình, mỗi tháng ba lần, nó thành những kho gạo đủ nuôi người nghèo qua mấy tháng giáp hạt. Quan trọng hơn, nó biến việc cứu đói thành việc của từng mâm cơm: ai cũng có thể góp, và ai góp cũng hiểu gạo của mình đi đâu. Người đứng đầu Nhà nước tự nhận phần nhịn trước, nên lời kêu gọi mang sức nặng của một tấm gương chứ không chỉ của một chủ trương."},{"t":"Lúc chúng ta nâng bát cơm mà ăn, nghĩ đến kẻ đói khổ, chúng ta không khỏi động lòng. — Hồ Chí Minh, Lời kêu gọi đồng bào cả nước cứu đói, tháng 9/1945"},{"t":"Hũ gạo trong mỗi gian bếp. Lời kêu gọi đi vào đời sống bằng những hình thức rất cụ thể. Trong nhiều gia đình, cạnh chum gạo ăn hằng ngày có thêm một chiếc hũ nhỏ: mỗi bữa, người nội trợ bớt ra một nắm, dồn lại thành “hũ gạo cứu đói”. Ở các khu phố, làng xóm, những “ngày đồng tâm” được tổ chức, khi cả cộng đồng cùng nhịn một bữa để góp gạo. Các đoàn thể thanh niên, phụ nữ, học sinh đi từng nhà lạc quyên tiền, gạo, quần áo cũ. Chính quyền bãi bỏ những lệnh ngăn cấm chuyên chở thóc gạo giữa các địa phương có từ thời trước, để gạo có thể về nhanh những vùng bị lụt. Những ngày vận động mang tên như “Ngày Tiễu trừ nạn đói” trong tấm ảnh là những dịp để Thủ đô dồn sức vào cùng một thời điểm, biến lời kêu gọi của Chủ tịch nước thành cảnh người người góp gạo."},{"t":"Không để một tấc đất bỏ hoang. Lạc quyên chỉ giúp người đói qua cơn giáp hạt; muốn diệt tận gốc giặc đói phải làm ra thêm lương thực. Chủ tịch Hồ Chí Minh nhiều lần nhắc lại khẩu hiệu: “Tăng gia sản xuất! Tăng gia sản xuất ngay! Tăng gia sản xuất nữa!”. Trong Chính phủ lâm thời, Bộ Canh nông do nhà thơ Huy Cận làm Bộ trưởng. Nông dân được vận động trồng ngay các loại cây ngắn ngày như khoai lang, ngô, đậu, rau màu trên những chân ruộng vừa rút nước lũ. Đất công, bãi bồi ven sông, vườn tược đều được đem ra trồng trọt, theo tinh thần không để một tấc đất bỏ hoang. Cùng với đó là những chính sách chạm đến quyền lợi thiết thân của người cày. Ruộng đất của thực dân và Việt gian bị tịch thu, tạm cấp cho nông dân nghèo; ruộng đất công được chia lại công bằng hơn; địa tô được giảm 25%. Thuế thân, thứ thuế nặng nề gắn với kiếp dân thuộc địa, bị bãi bỏ theo đúng một trong những nhiệm vụ cấp bách nêu ngày 3/9. Người nông dân hiểu rằng mỗi luống khoai họ trồng lúc ấy vừa để nuôi gia đình, vừa để giữ lấy chính quyền của mình."},{"t":"Bạn có biết? Để dành lương thực cứu đói, Chính phủ nghiêm cấm việc đầu cơ tích trữ lúa gạo và cấm dùng gạo, ngô, khoai, sắn để nấu rượu."},{"t":"Mùa xuân Bính Tuất không lặp lại mùa xuân Ất Dậu. Nhờ những biện pháp đồng bộ ấy, chỉ trong một thời gian ngắn, sản xuất nông nghiệp ở miền Bắc được phục hồi. Những vụ khoai, ngô trồng từ cuối năm 1945 cho thu hoạch vào đầu năm 1946, lấp chỗ trống trong những tháng giáp hạt vốn đáng sợ nhất. Đến năm 1946, nạn đói về cơ bản đã bị đẩy lùi. Mùa xuân Ất Dậu năm trước đã cướp đi hơn hai triệu sinh mạng; mùa xuân Bính Tuất năm ấy, dù đất nước còn bộn bề thù trong giặc ngoài, thảm cảnh đó đã không tái diễn. Với nhiều người dân, đó là bằng chứng đầu tiên và rõ ràng nhất về sự khác biệt giữa chế độ cũ và chính quyền mới. Cùng với phong trào Bình dân học vụ chống giặc dốt (xem chuyên đề về các lớp Bình dân học vụ), thắng lợi trước giặc đói giúp nhà nước non trẻ đứng vững trong lòng dân. Để rồi khi cuộc kháng chiến toàn quốc bùng nổ cuối năm 1946, hàng triệu người đã sẵn sàng đi theo chính quyền từng cùng họ vượt qua cái đói."},{"t":"Độc lập phải hiện ra trong bát cơm. Chống giặc đói, với Chủ tịch Hồ Chí Minh, không chỉ là một chiến dịch cứu trợ. Trong những văn kiện của những tháng đầu chính quyền mới, Người nhiều lần đặt việc làm cho dân có ăn lên trước tiên, rồi mới đến có mặc, có chỗ ở, có học hành. Người hiểu rằng độc lập không thể chỉ nằm trên giấy; nó phải hiện ra trong bát cơm, manh áo của từng gia đình. Tinh thần ấy thể hiện cả trong cách Người sống. Lời đề nghị nhịn ăn mười ngày một bữa đi kèm câu “tôi xin thực hành trước”. Theo hồi ức của những người từng làm việc bên Người, bữa ăn của vị Chủ tịch nước ở Bắc Bộ phủ những năm ấy vẫn đạm bạc như bữa ăn của một gia đình bình thường. Chính sự nhất quán giữa lời nói và việc làm đã khiến những hũ gạo nhỏ khắp nơi đầy lên, và khiến lời kêu gọi năm ấy còn được nhắc lại đến hôm nay."},{"t":"Chúng ta tranh được tự do, độc lập rồi mà dân cứ chết đói, chết rét, thì tự do, độc lập cũng không làm gì. Dân chỉ biết rõ giá trị của tự do, của độc lập khi mà dân được ăn no, mặc đủ. — Hồ Chí Minh"},{"t":"Bạn có biết? Nhiếp ảnh gia Võ An Ninh, người sau này có mặt ghi hình những ngày Độc lập ở Hà Nội, đã chụp một loạt ảnh về nạn đói năm Ất Dậu — những tư liệu hình ảnh hiếm hoi còn lại về thảm cảnh ấy."},{"t":"Dấu tích hôm nay. Ngày nay, tấm ảnh “Ngày Tiễu trừ nạn đói” thuộc nhóm ảnh tư liệu hiếm hoi còn lại về phong trào cứu đói những tháng đầu độc lập. Cùng với những bức ảnh về nạn đói năm Ất Dậu, nó thường được giới thiệu trong các cuộc trưng bày, sách ảnh về Cách mạng Tháng Tám và những năm đầu của nước Việt Nam Dân chủ Cộng hòa. Lời kêu gọi cứu đói và bài nói ngày 3/9/1945 được in trong bộ Hồ Chí Minh Toàn tập, để người đọc hôm nay có thể tìm lại nguyên văn. Trong gian trưng bày này, tấm ảnh được đặt giữa không gian Hà Nội mùa thu 1945, không xa căn gác Hàng Ngang và lễ đài Ba Đình. Sự sắp đặt ấy có chủ ý: niềm vui độc lập và cuộc chiến chống cái đói diễn ra cùng một lúc, trên cùng những con phố, với cùng những con người. Đứng trước tấm ảnh, khách tham quan có thể nhớ lại lời kêu gọi năm ấy: mỗi lần nâng bát cơm lên, hãy nghĩ đến những người đang đói."}],"so_chu":1948},{"i":10,"tieu_de_bang":"Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, 1946","tieu_de":"Bốn tháng trên đất Pháp: Chủ tịch Hồ Chí Minh giữa kiều bào năm 1946","sapo":"Năm 1923, một thanh niên tên Nguyễn Ái Quốc lặng lẽ rời Paris. Hai mươi ba năm sau, người ấy trở lại, lần này là Chủ tịch nước Việt Nam Dân chủ Cộng hòa, thượng khách của nước Pháp. Giữa những cuộc đàm phán căng thẳng, có những buổi gặp mà Người dành trọn cho đồng bào mình: người lính thợ, người thủy thủ, cậu sinh viên, vị kỹ sư đang sống xa Tổ quốc.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_with_vietnamese_expats_in_france_194.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Sân bay Le Bourget, tháng 6/1946","text":"Ngày 22/6/1946, máy bay chở Chủ tịch Hồ Chí Minh hạ cánh xuống sân bay Le Bourget ở ngoại ô Paris. Cùng với nghi lễ đón tiếp của Chính phủ Pháp dành cho một thượng khách, sân bay hôm ấy đông nghẹt kiều bào, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp.\n\nVới những người lớn tuổi trong đám đông, gương mặt ấy không hoàn toàn xa lạ. Hơn hai mươi năm trước, một thanh niên tên Nguyễn Ái Quốc từng sống ở Paris, làm nghề sửa ảnh, viết báo Le Paria, gửi bản Yêu sách của nhân dân An Nam tới Hội nghị Versailles năm 1919 và thường lui tới với những người lao động Việt Nam ở các khu phố nghèo. Tháng 6/1923, người thanh niên ấy bí mật rời Paris sang Liên Xô. Nay người trở lại, không còn phải tránh con mắt của mật thám, mà bước xuống sân bay trong tư cách người đứng đầu một quốc gia.","doc":1},{"loai":"doan","tieu_de":"Những ngày chờ ở Biarritz","text":"Chuyến đi bắt đầu từ ngày 31/5/1946, khi Người rời Hà Nội theo lời mời của Chính phủ Pháp. Cùng thời gian ấy, phái đoàn Chính phủ do Phạm Văn Đồng dẫn đầu cũng lên đường sang dự cuộc đàm phán chính thức. Khi Người tới nơi, nước Pháp đang ở giữa một cuộc chuyển giao quyền lực: cuộc bầu cử Quốc hội lập hiến vừa diễn ra đầu tháng 6 và chính phủ mới chưa thành lập. Vì vậy, Người được mời nghỉ tạm ở Biarritz, thành phố nghỉ mát bên bờ Đại Tây Dương ở miền tây nam nước Pháp, cho đến ngày 22/6.\n\nNgay ở nơi xa Paris ấy, kiều bào đã tìm đến. Theo tư liệu của báo Đoàn Kết, có hơn năm mươi thiếu nhi Việt Nam ở Paris cùng cha mẹ xuống thăm Người. Đó là một trong những cuộc gặp đầu tiên của mối gắn bó giữa Người và kiều bào, kéo dài suốt bốn tháng Người ở Pháp.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, 1946”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai vạn lính thợ và một cộng đồng","text":"Cộng đồng người Việt ở Pháp năm 1946 có khoảng hai mươi lăm nghìn người. Đông nhất là những người lính thợ: khoảng hai vạn thanh niên, phần lớn là nông dân nghèo ở Trung Kỳ và Bắc Kỳ, bị chính quyền thuộc địa tuyển mộ hoặc bắt đưa sang Pháp trong hai năm 1939–1940 để làm việc trong các nhà máy phục vụ chiến tranh. Khi Pháp thua trận năm 1940, họ bị kẹt lại, sống tập trung trong các trại ở miền Nam nước Pháp, làm những công việc nặng nhọc với đồng lương ít ỏi.\n\nBên cạnh họ là những thủy thủ, công nhân, người buôn bán nhỏ đã định cư từ trước, những cựu chiến binh, và một lớp sinh viên, trí thức: bác sĩ, dược sĩ, kỹ sư đang học tập, làm việc ở Paris, Lyon, Bordeaux, Toulouse. Nhiều người đã lập các hội ái hữu để đùm bọc nhau. Tin Cách mạng Tháng Tám thành công đến với họ qua báo chí và những lá thư hiếm hoi. Giờ đây, người đứng đầu nhà nước mới đang ở ngay giữa họ.","doc":3},{"loai":"doan","tieu_de":"Phòng khách ở khách sạn Royal Monceau","text":"Tại Paris, Người ở khách sạn Royal Monceau, số 37 đại lộ Hoche, quận 8. Chỉ trong mấy ngày đầu, phòng khách của khách sạn sang trọng ấy đã đón những đoàn khách khác thường. Theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp, ngày 24/6, Người tiếp khoảng một trăm đại biểu kiều bào quê Nam Bộ; ngày 25/6, hơn một trăm đại biểu cựu chiến binh và lính thợ; ngày 26/6, đại biểu các hội ái hữu người Việt ở Lyon, Paris, Bordeaux, Toulouse. Ngày 12/7, đến lượt các trí thức Việt kiều.\n\nCuộc tiếp đại biểu kiều bào Nam Bộ diễn ra trong một hoàn cảnh đặc biệt. Khi ấy, phía Pháp ở Sài Gòn đang ráo riết thực hiện âm mưu tách Nam Bộ khỏi Việt Nam. Ngay trong ngày lên đường, Người đã gửi thư cho đồng bào Nam Bộ, khẳng định một chân lý không thể lay chuyển.","doc":4},{"loai":"trich","text":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi!","nguoi":"Hồ Chí Minh, Thư gửi đồng bào Nam Bộ, 31/5/1946","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_with_vietnamese_expats_in_france_194.jpg","chu_thich":"Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, năm 1946.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Quốc khánh đầu tiên giữa lòng Paris","text":"Những cuộc gặp đông người nhất diễn ra giữa thủ đô nước Pháp. Ngày 15/7/1946, kiều bào tổ chức một cuộc mít tinh tại hội trường Palais de la Mutualité ở quận 5, với hơn hai nghìn người tới dự. Ngày 27/7, Việt kiều mở tiệc chiêu đãi Người tại khu vườn Bagatelle trong rừng Boulogne. Và ngày 2/9/1946, tròn một năm sau buổi chiều ở Ba Đình, lễ kỷ niệm Quốc khánh đầu tiên của nước Việt Nam Dân chủ Cộng hòa được tổ chức ngay tại Paris, ở phòng hòa nhạc Pleyel, với hơn ba nghìn người dự, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp.\n\nHãy hình dung khung cảnh ấy: những người lính thợ từ các trại ở tỉnh lên, những sinh viên, những gia đình người Việt định cư đã lâu, cùng bạn bè Pháp, ngồi kín một khán phòng ở thủ đô của nước từng cai trị mình, để mừng ngày độc lập của Tổ quốc. Có mặt giữa họ là chính người đã đọc bản Tuyên ngôn Độc lập một năm trước.","doc":6},{"loai":"ban_co_biet","text":"Từ cuối tháng 7/1946, Người ở tại nhà ông bà Raymond và Lucie Aubrac, những nhân vật nổi tiếng của phong trào kháng chiến Pháp, ở Soisy-sous-Montmorency ngoại ô Paris; Người nhận làm cha đỡ đầu cho cô con gái út của ông bà, tên thân mật là Babette.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử; Bảo tàng Hồ Chí Minh","doc":7},{"loai":"doan","tieu_de":"Chuyến tàu đặc biệt xuống phía Nam","text":"Trước ngày rời nước Pháp, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp, Người gửi thư cho kiều bào, dặn phải triệt để đoàn kết và mỗi người cần biết thạo một nghề. Sáng 16/9/1946, chuyến xe lửa đặc biệt đưa Người rời Paris đi Marseille; gần một nghìn kiều bào ra ga tiễn. Tối hôm ấy, ở ga Marseille, đông đảo kiều bào lại đã chờ sẵn.\n\nNgày 17/9, Người đến thăm các trại lính thợ ở miền Nam nước Pháp, nơi tập trung hơn ba nghìn người Việt Nam và Đông Dương. Với những người thợ đã xa quê bảy năm, Người không hứa hẹn điều gì xa vời. Theo tư liệu của báo Đoàn Kết, Người khuyên: “Kiều bào hãy cố gắng chăm lo học lấy một cái nghề tinh xảo để góp vào việc kiến thiết quốc gia”. Những năm sau đó, phần lớn lính thợ lần lượt được hồi hương, nhiều người mang theo tay nghề học được nơi xứ người.","doc":8},{"loai":"doan","tieu_de":"Những người theo Người về nước","text":"Trong những cuộc gặp trí thức kiều bào, Người không giấu điều đất nước đang thiếu nhất: người có chuyên môn. Một nước vừa giành độc lập, phần lớn dân số chưa biết chữ, cần kỹ sư, bác sĩ, nhà khoa học hơn bao giờ hết. Lời mời gọi ấy đã được đáp lại. Kỹ sư Phạm Quang Lễ, người nhiều năm học tập và nghiên cứu về vũ khí ở châu Âu, quyết định bỏ lại công việc có thu nhập cao để theo Người về nước. Về tới Việt Nam, ông được Người đặt tên mới là Trần Đại Nghĩa, giao phụ trách ngành quân giới, và trở thành người chế tạo những loại súng chống tăng đầu tiên cho bộ đội.\n\nCùng về với Người năm ấy còn có bác sĩ Trần Hữu Tước, sau này là một chuyên gia tai mũi họng hàng đầu; kỹ sư Võ Quý Huân; kỹ sư Võ Đình Quỳnh. Những năm sau, nhiều trí thức Việt kiều khác cũng lần lượt về nước. Những cuộc gặp năm 1946 vì thế đã gieo những hạt giống đầu tiên cho nền khoa học, kỹ thuật của nước Việt Nam mới.","doc":9},{"loai":"anh","src":"textures/bang_w/G14_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, 1946”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tạm ước 14/9 và hải trình về nước","text":"Trong khi Người gặp gỡ kiều bào, cuộc đàm phán chính thức ở Fontainebleau, khai mạc ngày 6/7/1946, dần đi vào bế tắc vì phía Pháp không chịu công nhận độc lập và thống nhất của Việt Nam. Trước nguy cơ chiến tranh, đêm 14/9/1946, Người ký với Bộ trưởng Marius Moutet bản Tạm ước, nhân nhượng cho Pháp một số quyền lợi kinh tế, văn hóa để kéo dài thời gian hòa hoãn (xem chuyên đề về Hiệp định Sơ bộ 6/3/1946).\n\nNgười lên tàu Dumont d'Urville ở cảng Toulon, bắt đầu hải trình dài hơn một tháng. Ngày 18/10, tại vịnh Cam Ranh, Người gặp Cao ủy Pháp d'Argenlieu. Chiều 20/10/1946, tàu cập cảng Hải Phòng, rồi Người trở về Hà Nội giữa sự đón chào của đồng bào Thủ đô. Bốn tháng xa Tổ quốc khép lại với một văn bản tạm thời, nhưng cũng với những người bạn mới, những trí thức theo về, và một cộng đồng kiều bào đã tìm thấy chỗ dựa của mình.","doc":10},{"loai":"moc","items":[["31/5/1946","Rời Hà Nội sang Pháp theo lời mời của Chính phủ Pháp; cùng ngày gửi thư cho đồng bào Nam Bộ."],["Giữa tháng 6/1946","Nghỉ tạm ở Biarritz chờ Chính phủ Pháp mới thành lập; kiều bào tìm đến thăm."],["22/6/1946","Tới Paris, ở khách sạn Royal Monceau; kiều bào đón đông ở sân bay Le Bourget."],["24–26/6/1946","Tiếp đại biểu kiều bào Nam Bộ, cựu chiến binh, lính thợ và các hội ái hữu."],["6/7/1946","Khai mạc Hội nghị Fontainebleau; phái đoàn Việt Nam do Phạm Văn Đồng dẫn đầu."],["15/7/1946","Dự cuộc mít tinh của hơn hai nghìn kiều bào tại Palais de la Mutualité."],["2/9/1946","Dự lễ kỷ niệm Quốc khánh đầu tiên do kiều bào tổ chức tại Paris."],["14/9/1946","Ký Tạm ước với Bộ trưởng Marius Moutet."],["16–17/9/1946","Rời Paris đi Marseille, thăm các trại lính thợ, lên tàu Dumont d'Urville ở Toulon."],["18/10/1946","Gặp Cao ủy d'Argenlieu tại vịnh Cam Ranh."],["20/10/1946","Về tới cảng Hải Phòng."]],"doc":11},{"loai":"ban_co_biet","text":"Ngày 1/6/1946, chỉ một ngày sau khi Chủ tịch Hồ Chí Minh lên đường sang Pháp, Cao ủy d'Argenlieu cho lập cái gọi là “Chính phủ Cộng hòa tự trị Nam Kỳ”, trái với tinh thần Hiệp định Sơ bộ, đặt cuộc đàm phán vào thế khó ngay từ trước khi bắt đầu.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử; Viện Sử học, Lịch sử Việt Nam","doc":12},{"loai":"anh","src":"textures/bang_w/G14_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, 1946”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Gần tám mươi năm đã trôi qua, nhiều địa điểm của chuyến đi năm 1946 vẫn còn. Khách sạn Royal Monceau vẫn đón khách trên đại lộ Hoche; hội trường Mutualité và phòng hòa nhạc Pleyel vẫn là những địa chỉ quen thuộc của đời sống Paris. Ở thành phố Montreuil, ngoại ô Paris, tượng bán thân Chủ tịch Hồ Chí Minh đặt trong công viên Montreau là nơi kiều bào và khách Việt Nam thường tìm đến mỗi dịp kỷ niệm.\n\nHội Người Việt Nam tại Pháp và tờ báo Đoàn Kết của hội đã dày công tập hợp ảnh, lời kể, lịch trình các cuộc gặp năm ấy, giúp thế hệ sau hiểu thêm về sợi dây nối Người với cộng đồng người Việt ở Pháp. Tấm ảnh trong gian trưng bày này là một mảnh của ký ức chung đó: một vị Chủ tịch nước giữa những đồng bào xa xứ, trong mùa hè năm 1946 đầy hy vọng và bất trắc.","doc":13}],"nguon":["Báo Đoàn Kết (Hội Người Việt Nam tại Pháp) — Chuyên đề Bác Hồ trở lại nước Pháp năm 1946, Phần 2: Bác với kiều bào: https://www.doanket.ugvf.org/doanket/toasang-ugvf.org/2019/04/07/chuyen-de-bac-ho-tro-lai-nuoc-phap-nam-1946-phan-2bac-voi-kieu-bao/index.html","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","Pierre Daum, Immigrés de force: les travailleurs indochinois en France (1939–1952), Actes Sud, 2009","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Bốn tháng trên đất Pháp: Chủ tịch Hồ Chí Minh giữa kiều bào năm 1946. Năm 1923, một thanh niên tên Nguyễn Ái Quốc lặng lẽ rời Paris. Hai mươi ba năm sau, người ấy trở lại, lần này là Chủ tịch nước Việt Nam Dân chủ Cộng hòa, thượng khách của nước Pháp. Giữa những cuộc đàm phán căng thẳng, có những buổi gặp mà Người dành trọn cho đồng bào mình: người lính thợ, người thủy thủ, cậu sinh viên, vị kỹ sư đang sống xa Tổ quốc."},{"t":"Sân bay Le Bourget, tháng 6/1946. Ngày 22/6/1946, máy bay chở Chủ tịch Hồ Chí Minh hạ cánh xuống sân bay Le Bourget ở ngoại ô Paris. Cùng với nghi lễ đón tiếp của Chính phủ Pháp dành cho một thượng khách, sân bay hôm ấy đông nghẹt kiều bào, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp. Với những người lớn tuổi trong đám đông, gương mặt ấy không hoàn toàn xa lạ. Hơn hai mươi năm trước, một thanh niên tên Nguyễn Ái Quốc từng sống ở Paris, làm nghề sửa ảnh, viết báo Le Paria, gửi bản Yêu sách của nhân dân An Nam tới Hội nghị Versailles năm 1919 và thường lui tới với những người lao động Việt Nam ở các khu phố nghèo. Tháng 6/1923, người thanh niên ấy bí mật rời Paris sang Liên Xô. Nay người trở lại, không còn phải tránh con mắt của mật thám, mà bước xuống sân bay trong tư cách người đứng đầu một quốc gia."},{"t":"Những ngày chờ ở Biarritz. Chuyến đi bắt đầu từ ngày 31/5/1946, khi Người rời Hà Nội theo lời mời của Chính phủ Pháp. Cùng thời gian ấy, phái đoàn Chính phủ do Phạm Văn Đồng dẫn đầu cũng lên đường sang dự cuộc đàm phán chính thức. Khi Người tới nơi, nước Pháp đang ở giữa một cuộc chuyển giao quyền lực: cuộc bầu cử Quốc hội lập hiến vừa diễn ra đầu tháng 6 và chính phủ mới chưa thành lập. Vì vậy, Người được mời nghỉ tạm ở Biarritz, thành phố nghỉ mát bên bờ Đại Tây Dương ở miền tây nam nước Pháp, cho đến ngày 22/6. Ngay ở nơi xa Paris ấy, kiều bào đã tìm đến. Theo tư liệu của báo Đoàn Kết, có hơn năm mươi thiếu nhi Việt Nam ở Paris cùng cha mẹ xuống thăm Người. Đó là một trong những cuộc gặp đầu tiên của mối gắn bó giữa Người và kiều bào, kéo dài suốt bốn tháng Người ở Pháp."},{"t":"Hai vạn lính thợ và một cộng đồng. Cộng đồng người Việt ở Pháp năm 1946 có khoảng hai mươi lăm nghìn người. Đông nhất là những người lính thợ: khoảng hai vạn thanh niên, phần lớn là nông dân nghèo ở Trung Kỳ và Bắc Kỳ, bị chính quyền thuộc địa tuyển mộ hoặc bắt đưa sang Pháp trong hai năm 1939–1940 để làm việc trong các nhà máy phục vụ chiến tranh. Khi Pháp thua trận năm 1940, họ bị kẹt lại, sống tập trung trong các trại ở miền Nam nước Pháp, làm những công việc nặng nhọc với đồng lương ít ỏi. Bên cạnh họ là những thủy thủ, công nhân, người buôn bán nhỏ đã định cư từ trước, những cựu chiến binh, và một lớp sinh viên, trí thức: bác sĩ, dược sĩ, kỹ sư đang học tập, làm việc ở Paris, Lyon, Bordeaux, Toulouse. Nhiều người đã lập các hội ái hữu để đùm bọc nhau. Tin Cách mạng Tháng Tám thành công đến với họ qua báo chí và những lá thư hiếm hoi. Giờ đây, người đứng đầu nhà nước mới đang ở ngay giữa họ."},{"t":"Phòng khách ở khách sạn Royal Monceau. Tại Paris, Người ở khách sạn Royal Monceau, số 37 đại lộ Hoche, quận 8. Chỉ trong mấy ngày đầu, phòng khách của khách sạn sang trọng ấy đã đón những đoàn khách khác thường. Theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp, ngày 24/6, Người tiếp khoảng một trăm đại biểu kiều bào quê Nam Bộ; ngày 25/6, hơn một trăm đại biểu cựu chiến binh và lính thợ; ngày 26/6, đại biểu các hội ái hữu người Việt ở Lyon, Paris, Bordeaux, Toulouse. Ngày 12/7, đến lượt các trí thức Việt kiều. Cuộc tiếp đại biểu kiều bào Nam Bộ diễn ra trong một hoàn cảnh đặc biệt. Khi ấy, phía Pháp ở Sài Gòn đang ráo riết thực hiện âm mưu tách Nam Bộ khỏi Việt Nam. Ngay trong ngày lên đường, Người đã gửi thư cho đồng bào Nam Bộ, khẳng định một chân lý không thể lay chuyển."},{"t":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi! — Hồ Chí Minh, Thư gửi đồng bào Nam Bộ, 31/5/1946"},{"t":"Quốc khánh đầu tiên giữa lòng Paris. Những cuộc gặp đông người nhất diễn ra giữa thủ đô nước Pháp. Ngày 15/7/1946, kiều bào tổ chức một cuộc mít tinh tại hội trường Palais de la Mutualité ở quận 5, với hơn hai nghìn người tới dự. Ngày 27/7, Việt kiều mở tiệc chiêu đãi Người tại khu vườn Bagatelle trong rừng Boulogne. Và ngày 2/9/1946, tròn một năm sau buổi chiều ở Ba Đình, lễ kỷ niệm Quốc khánh đầu tiên của nước Việt Nam Dân chủ Cộng hòa được tổ chức ngay tại Paris, ở phòng hòa nhạc Pleyel, với hơn ba nghìn người dự, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp. Hãy hình dung khung cảnh ấy: những người lính thợ từ các trại ở tỉnh lên, những sinh viên, những gia đình người Việt định cư đã lâu, cùng bạn bè Pháp, ngồi kín một khán phòng ở thủ đô của nước từng cai trị mình, để mừng ngày độc lập của Tổ quốc. Có mặt giữa họ là chính người đã đọc bản Tuyên ngôn Độc lập một năm trước."},{"t":"Bạn có biết? Từ cuối tháng 7/1946, Người ở tại nhà ông bà Raymond và Lucie Aubrac, những nhân vật nổi tiếng của phong trào kháng chiến Pháp, ở Soisy-sous-Montmorency ngoại ô Paris; Người nhận làm cha đỡ đầu cho cô con gái út của ông bà, tên thân mật là Babette."},{"t":"Chuyến tàu đặc biệt xuống phía Nam. Trước ngày rời nước Pháp, theo tư liệu do báo Đoàn Kết của Hội Người Việt Nam tại Pháp tập hợp, Người gửi thư cho kiều bào, dặn phải triệt để đoàn kết và mỗi người cần biết thạo một nghề. Sáng 16/9/1946, chuyến xe lửa đặc biệt đưa Người rời Paris đi Marseille; gần một nghìn kiều bào ra ga tiễn. Tối hôm ấy, ở ga Marseille, đông đảo kiều bào lại đã chờ sẵn. Ngày 17/9, Người đến thăm các trại lính thợ ở miền Nam nước Pháp, nơi tập trung hơn ba nghìn người Việt Nam và Đông Dương. Với những người thợ đã xa quê bảy năm, Người không hứa hẹn điều gì xa vời. Theo tư liệu của báo Đoàn Kết, Người khuyên: “Kiều bào hãy cố gắng chăm lo học lấy một cái nghề tinh xảo để góp vào việc kiến thiết quốc gia”. Những năm sau đó, phần lớn lính thợ lần lượt được hồi hương, nhiều người mang theo tay nghề học được nơi xứ người."},{"t":"Những người theo Người về nước. Trong những cuộc gặp trí thức kiều bào, Người không giấu điều đất nước đang thiếu nhất: người có chuyên môn. Một nước vừa giành độc lập, phần lớn dân số chưa biết chữ, cần kỹ sư, bác sĩ, nhà khoa học hơn bao giờ hết. Lời mời gọi ấy đã được đáp lại. Kỹ sư Phạm Quang Lễ, người nhiều năm học tập và nghiên cứu về vũ khí ở châu Âu, quyết định bỏ lại công việc có thu nhập cao để theo Người về nước. Về tới Việt Nam, ông được Người đặt tên mới là Trần Đại Nghĩa, giao phụ trách ngành quân giới, và trở thành người chế tạo những loại súng chống tăng đầu tiên cho bộ đội. Cùng về với Người năm ấy còn có bác sĩ Trần Hữu Tước, sau này là một chuyên gia tai mũi họng hàng đầu; kỹ sư Võ Quý Huân; kỹ sư Võ Đình Quỳnh. Những năm sau, nhiều trí thức Việt kiều khác cũng lần lượt về nước. Những cuộc gặp năm 1946 vì thế đã gieo những hạt giống đầu tiên cho nền khoa học, kỹ thuật của nước Việt Nam mới."},{"t":"Tạm ước 14/9 và hải trình về nước. Trong khi Người gặp gỡ kiều bào, cuộc đàm phán chính thức ở Fontainebleau, khai mạc ngày 6/7/1946, dần đi vào bế tắc vì phía Pháp không chịu công nhận độc lập và thống nhất của Việt Nam. Trước nguy cơ chiến tranh, đêm 14/9/1946, Người ký với Bộ trưởng Marius Moutet bản Tạm ước, nhân nhượng cho Pháp một số quyền lợi kinh tế, văn hóa để kéo dài thời gian hòa hoãn (xem chuyên đề về Hiệp định Sơ bộ 6/3/1946). Người lên tàu Dumont d'Urville ở cảng Toulon, bắt đầu hải trình dài hơn một tháng. Ngày 18/10, tại vịnh Cam Ranh, Người gặp Cao ủy Pháp d'Argenlieu. Chiều 20/10/1946, tàu cập cảng Hải Phòng, rồi Người trở về Hà Nội giữa sự đón chào của đồng bào Thủ đô. Bốn tháng xa Tổ quốc khép lại với một văn bản tạm thời, nhưng cũng với những người bạn mới, những trí thức theo về, và một cộng đồng kiều bào đã tìm thấy chỗ dựa của mình."},{"t":"Các mốc thời gian. 31/5/1946: Rời Hà Nội sang Pháp theo lời mời của Chính phủ Pháp; cùng ngày gửi thư cho đồng bào Nam Bộ. Giữa tháng 6/1946: Nghỉ tạm ở Biarritz chờ Chính phủ Pháp mới thành lập; kiều bào tìm đến thăm. 22/6/1946: Tới Paris, ở khách sạn Royal Monceau; kiều bào đón đông ở sân bay Le Bourget. 24–26/6/1946: Tiếp đại biểu kiều bào Nam Bộ, cựu chiến binh, lính thợ và các hội ái hữu. 6/7/1946: Khai mạc Hội nghị Fontainebleau; phái đoàn Việt Nam do Phạm Văn Đồng dẫn đầu. 15/7/1946: Dự cuộc mít tinh của hơn hai nghìn kiều bào tại Palais de la Mutualité. 2/9/1946: Dự lễ kỷ niệm Quốc khánh đầu tiên do kiều bào tổ chức tại Paris. 14/9/1946: Ký Tạm ước với Bộ trưởng Marius Moutet. 16–17/9/1946: Rời Paris đi Marseille, thăm các trại lính thợ, lên tàu Dumont d'Urville ở Toulon. 18/10/1946: Gặp Cao ủy d'Argenlieu tại vịnh Cam Ranh. 20/10/1946: Về tới cảng Hải Phòng."},{"t":"Bạn có biết? Ngày 1/6/1946, chỉ một ngày sau khi Chủ tịch Hồ Chí Minh lên đường sang Pháp, Cao ủy d'Argenlieu cho lập cái gọi là “Chính phủ Cộng hòa tự trị Nam Kỳ”, trái với tinh thần Hiệp định Sơ bộ, đặt cuộc đàm phán vào thế khó ngay từ trước khi bắt đầu."},{"t":"Dấu tích hôm nay. Gần tám mươi năm đã trôi qua, nhiều địa điểm của chuyến đi năm 1946 vẫn còn. Khách sạn Royal Monceau vẫn đón khách trên đại lộ Hoche; hội trường Mutualité và phòng hòa nhạc Pleyel vẫn là những địa chỉ quen thuộc của đời sống Paris. Ở thành phố Montreuil, ngoại ô Paris, tượng bán thân Chủ tịch Hồ Chí Minh đặt trong công viên Montreau là nơi kiều bào và khách Việt Nam thường tìm đến mỗi dịp kỷ niệm. Hội Người Việt Nam tại Pháp và tờ báo Đoàn Kết của hội đã dày công tập hợp ảnh, lời kể, lịch trình các cuộc gặp năm ấy, giúp thế hệ sau hiểu thêm về sợi dây nối Người với cộng đồng người Việt ở Pháp. Tấm ảnh trong gian trưng bày này là một mảnh của ký ức chung đó: một vị Chủ tịch nước giữa những đồng bào xa xứ, trong mùa hè năm 1946 đầy hy vọng và bất trắc."}],"so_chu":1782},{"i":11,"tieu_de_bang":"Ký Hiệp định Sơ bộ 6/3/1946","tieu_de":"Chiều 6/3/1946: một chữ ký để tránh chiến tranh","sapo":"Buổi sáng, súng nổ ở cảng Hải Phòng. Buổi chiều, trong một ngôi nhà trên phố Lý Thái Tổ, Chủ tịch Hồ Chí Minh đặt bút ký một văn bản mà nhiều người khi ấy chưa hiểu, thậm chí phản đối. Nhưng chính chữ ký ấy đã đẩy hai mươi vạn quân Tưởng về nước và mua cho nước Việt Nam non trẻ chín tháng quý giá để chuẩn bị cho cuộc chiến không thể tránh.","bia":{"src":"textures/ht/ht_anh_ho_sainteny_agreement_march_6_1946.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một buổi chiều ở phố Lý Thái Tổ","text":"Chiều 6/3/1946, tại ngôi nhà số 38 phố Lý Thái Tổ, Hà Nội, đại diện hai nước từng là thuộc địa và chính quốc ngồi vào cùng một bàn ký kết. Phía Việt Nam, Chủ tịch Hồ Chí Minh và ông Vũ Hồng Khanh, Phó Chủ tịch Ủy ban Kháng chiến, thay mặt Chính phủ đặt bút ký. Phía Pháp là Ủy viên Cộng hòa Jean Sainteny, người đã nhiều tuần đàm phán trực tiếp với Chủ tịch Hồ Chí Minh. Theo chú thích một ảnh lễ ký được TS. Đào Thị Diến giới thiệu trong bài viết về Hiệp định, có mặt trong phòng còn có Thứ trưởng Bộ Nội vụ Hoàng Minh Giám, cố vấn chính trị Léon Pignon và ông Louis Caput, đại diện Đảng Xã hội Pháp.\n\nVăn bản được ký hôm ấy mang tên Hiệp định Sơ bộ, nghĩa là bước khởi đầu cho một cuộc đàm phán lâu dài hơn. Nó ra đời chỉ vài giờ sau một vụ đụng độ ở Hải Phòng, khi chiến tranh có thể bùng nổ trên toàn miền Bắc bất cứ lúc nào. Để hiểu vì sao Người chọn ký, phải trở lại những tháng trước đó.","doc":1},{"loai":"doan","tieu_de":"Bị kẹp giữa hai đạo quân","text":"Từ tháng 9/1945, khoảng hai mươi vạn quân Tưởng Giới Thạch tràn vào miền Bắc với danh nghĩa giải giáp quân Nhật. Chúng đóng khắp các thành phố, tiêu tiền mất giá, sách nhiễu dân, và che chở cho các nhóm Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội chống phá chính quyền cách mạng. Ở phía Nam, dưới sự yểm trợ của quân Anh, thực dân Pháp đã nổ súng trở lại từ ngày 23/9/1945; đến đầu năm 1946, chúng chiếm được phần lớn các thị xã, đường giao thông quan trọng ở Nam Bộ và nam Trung Bộ, rồi chuẩn bị đưa quân ra Bắc.\n\nNgày 28/2/1946, tại Trùng Khánh, Chính phủ Tưởng Giới Thạch và Chính phủ Pháp ký Hiệp ước Hoa – Pháp. Pháp nhượng cho Tưởng một số quyền lợi ở Trung Quốc; đổi lại, Tưởng đồng ý để quân Pháp ra miền Bắc Việt Nam thay thế quân Tưởng. Hai kẻ thù đã bắt tay nhau trên lưng nước Việt Nam. Chính quyền cách mạng đứng trước nguy cơ phải cùng lúc đối phó với cả hai, khi lực lượng vũ trang còn non trẻ và thiếu thốn.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ký Hiệp định Sơ bộ 6/3/1946”, nhìn từ xa."},{"loai":"doan","tieu_de":"Lựa chọn ngày 3/3","text":"Chỉ một ngày trước đó, ngày 2/3/1946, Quốc hội khóa I vừa họp kỳ đầu tiên và lập ra Chính phủ Liên hiệp kháng chiến do Chủ tịch Hồ Chí Minh đứng đầu (xem chuyên đề về Quốc hội khóa I). Ngày 3/3/1946, Ban Thường vụ Trung ương Đảng họp, do Người chủ trì, để quyết định con đường trước mắt. Có hai khả năng: cầm súng đánh ngay khi quân Pháp đổ bộ, lúc lực lượng còn yếu và quân Tưởng vẫn đóng khắp miền Bắc; hoặc tạm thời hòa hoãn với Pháp để đẩy nhanh quân Tưởng về nước, có thêm thời gian xây dựng lực lượng.\n\nHội nghị chọn con đường thứ hai. Đây không phải lựa chọn dễ dàng. Chỉ nửa năm trước, cả dân tộc vừa thề ở Ba Đình sẽ không để thực dân Pháp trở lại. Nay chính Chính phủ lại phải đồng ý cho một số quân Pháp vào miền Bắc. Nhưng như Chủ tịch Hồ Chí Minh nhiều lần giải thích, điều quyết định không phải là giữ thể diện nhất thời, mà là giữ được nền độc lập lâu dài và tránh cho đất nước một cuộc chiến bất lợi.","doc":3},{"loai":"doan","tieu_de":"Buổi sáng ở cảng Hải Phòng","text":"Sáng 6/3/1946, tàu chiến Pháp chở quân tiến vào cảng Hải Phòng, định đổ bộ theo thỏa thuận với Tưởng. Nhưng quân Tưởng ở Hải Phòng lại nổ súng; tàu Pháp bắn trả, cuộc đấu súng gây thiệt hại cho cả hai phía. Vụ đụng độ cho thấy thỏa thuận giữa hai bên chưa hề êm thấm, và bất cứ lúc nào chiến sự cũng có thể lan rộng, kéo cả đất nước vào vòng binh lửa.\n\nChính thế giằng co ấy tạo ra một thời cơ ngắn ngủi. Phía Pháp cần một thỏa thuận với Chính phủ Việt Nam để quân mình vào miền Bắc mà không phải nổ súng. Phía Tưởng cũng muốn Việt – Pháp ký kết trước khi rút đi. Nắm lấy thời điểm đó, phía Việt Nam đòi được những nhượng bộ mà chỉ vài tuần trước phía Pháp còn khước từ. Cuộc đàm phán được đẩy nhanh, và chiều hôm ấy, hiệp định được ký.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_sainteny_agreement_march_6_1946.jpg","chu_thich":"Lễ ký Hiệp định Sơ bộ Việt – Pháp tại Hà Nội, chiều 6/3/1946.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những điều khoản chính","text":"Theo Hiệp định, Chính phủ Pháp công nhận nước Việt Nam Dân chủ Cộng hòa là một quốc gia tự do, có chính phủ, nghị viện, quân đội và tài chính riêng, nằm trong Liên bang Đông Dương và khối Liên hiệp Pháp. Về việc thống nhất ba kỳ, Pháp cam kết thừa nhận kết quả do nhân dân quyết định bằng trưng cầu dân ý. Việt Nam đồng ý để 15.000 quân Pháp ra miền Bắc thay thế quân Tưởng; theo phụ khoản quân sự, số quân này phải rút dần trong thời hạn 5 năm, mỗi năm rút một phần năm. Hai bên ngừng xung đột ở miền Nam và mở cuộc đàm phán chính thức.\n\nChữ “tự do” trong văn bản chưa phải là “độc lập” mà dân tộc mong đợi. Nhưng lần đầu tiên, nước Pháp chính thức ký một văn kiện với Chính phủ Hồ Chí Minh như với một chính phủ hợp pháp. Nước Việt Nam Dân chủ Cộng hòa bước lên bàn đàm phán quốc tế với tư cách một chủ thể có quốc hội, có quân đội, chứ không còn là một xứ thuộc địa.","doc":5},{"loai":"ban_co_biet","text":"Người cùng ký Hiệp định Sơ bộ với Chủ tịch Hồ Chí Minh là ông Vũ Hồng Khanh, một thủ lĩnh của Việt Nam Quốc dân Đảng — sự có mặt của ông thể hiện đây là quyết định của một chính phủ liên hiệp, đại diện cho nhiều khuynh hướng chính trị.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":6},{"loai":"doan","tieu_de":"Người đến giữa đồng bào","text":"Tin ký hiệp định khiến nhiều người dân băn khoăn, thậm chí bất bình, cho rằng Chính phủ đã nhân nhượng quá nhiều. Các nhóm chống đối thân Tưởng lập tức lợi dụng tâm trạng ấy để kích động. Chính quyền không né tránh. Ngày 7/3/1946, một cuộc mít tinh lớn được tổ chức trước Nhà hát Lớn Hà Nội. Võ Nguyên Giáp thay mặt Chính phủ giải thích rằng ký hiệp định là để tránh một cuộc chiến đấu bất lợi, giữ gìn lực lượng, đẩy quân Tưởng về nước và mở đường tiến tới độc lập hoàn toàn.\n\nChủ tịch Hồ Chí Minh cũng đến nói chuyện với đồng bào. Theo nhiều tư liệu, Người khẳng định suốt đời mình đã cùng đồng bào chiến đấu cho độc lập của Tổ quốc, và thà chết chứ không bao giờ bán nước. Lời nói ấy, từ người vừa đọc Tuyên ngôn Độc lập sáu tháng trước, đã làm dịu đi nỗi hoài nghi. Sách lược tạm hòa có giới hạn của nó; chín tháng sau, chính Người chỉ rõ giới hạn ấy.","doc":7},{"loai":"trich","text":"Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa!","nguoi":"Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, 19/12/1946","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","doc":8},{"loai":"doan","tieu_de":"Hòa để tiến","text":"Ngày 9/3/1946, Ban Thường vụ Trung ương Đảng ra Chỉ thị “Hòa để tiến”. Tên gọi đã nói rõ tinh thần: hòa không phải để lùi, mà để có thời gian củng cố lực lượng, đồng thời luôn cảnh giác trước âm mưu của đối phương. Hiệp định được thực hiện nghiêm túc về phía Việt Nam, nhưng cuộc chuẩn bị cho một cuộc kháng chiến lâu dài không hề dừng lại.\n\nNhững tuần sau đó dồn dập sự kiện. Ngày 18/3/1946, quân Pháp vào Hà Nội theo Hiệp định. Ngày 24/3, Chủ tịch Hồ Chí Minh gặp Cao ủy Pháp d'Argenlieu trên chiến hạm Émile Bertin ở vịnh Hạ Long; hai bên thỏa thuận mở một hội nghị trù bị. Hội nghị ấy họp ở Đà Lạt từ ngày 19/4 đến 11/5/1946 nhưng không đạt kết quả, vì phía Pháp muốn tách Nam Bộ khỏi Việt Nam. Cuộc đàm phán chính thức sau đó chuyển sang nước Pháp (xem chuyên đề về chuyến thăm Pháp và kiều bào năm 1946).","doc":9},{"loai":"anh","src":"textures/bang_w/G14_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ký Hiệp định Sơ bộ 6/3/1946”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chín tháng quý giá","text":"Nhìn lại, Hiệp định Sơ bộ đã đạt được mục tiêu lớn nhất của nó. Không còn cớ ở lại, quân Tưởng lần lượt rút khỏi miền Bắc trong những tháng tiếp theo. Mất chỗ dựa, các nhóm chống đối thân Tưởng tan rã; nhiều kẻ cầm đầu chạy theo quân Tưởng sang Trung Quốc. Chính quyền cách mạng thoát khỏi thế phải cùng lúc đối đầu với hai đạo quân nước ngoài.\n\nQuãng thời gian hòa hoãn được dùng triệt để. Quân đội được mở rộng và huấn luyện, các xưởng quân giới được xây dựng, cơ quan và kho tàng từng bước chuẩn bị di chuyển lên chiến khu. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên. Vì vậy, khi thực dân Pháp bội ước, gây hấn ở Hải Phòng, Lạng Sơn rồi ở Hà Nội cuối năm 1946, cả nước đã có đủ thế và lực để bước vào cuộc kháng chiến trường kỳ. Hiệp định Sơ bộ từ đó được nhắc đến như một mẫu mực của nghệ thuật ngoại giao Hồ Chí Minh: mềm dẻo về sách lược, kiên định về mục tiêu.","doc":10},{"loai":"moc","items":[["28/2/1946","Hiệp ước Hoa – Pháp ký tại Trùng Khánh: Tưởng đồng ý để quân Pháp ra miền Bắc."],["2/3/1946","Quốc hội khóa I họp kỳ đầu, lập Chính phủ Liên hiệp kháng chiến."],["3/3/1946","Ban Thường vụ Trung ương Đảng quyết định tạm hòa hoãn với Pháp."],["6/3/1946","Sáng đấu súng ở Hải Phòng; chiều ký Hiệp định Sơ bộ tại 38 Lý Thái Tổ."],["7/3/1946","Mít tinh trước Nhà hát Lớn Hà Nội giải thích Hiệp định."],["9/3/1946","Chỉ thị “Hòa để tiến” của Ban Thường vụ Trung ương."],["18/3/1946","Quân Pháp vào Hà Nội theo Hiệp định."],["24/3/1946","Gặp Cao ủy d'Argenlieu trên chiến hạm Émile Bertin ở vịnh Hạ Long."],["19/4 – 11/5/1946","Hội nghị trù bị Đà Lạt không đạt kết quả."],["14/9/1946","Ký Tạm ước tại Paris, kéo dài hòa hoãn."],["19/12/1946","Lời kêu gọi toàn quốc kháng chiến."]],"doc":11},{"loai":"ban_co_biet","text":"Ông Hoàng Minh Giám, Thứ trưởng Bộ Nội vụ có mặt trong lễ ký năm 1946, về sau giữ chức Bộ trưởng Bộ Ngoại giao nước Việt Nam Dân chủ Cộng hòa từ năm 1947 đến năm 1954, suốt những năm kháng chiến chống thực dân Pháp.","nguon_ten":"Bộ Ngoại giao Việt Nam; Hồ Chí Minh – Biên niên tiểu sử","doc":12},{"loai":"anh","src":"textures/bang_w/G14_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ký Hiệp định Sơ bộ 6/3/1946”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, những địa điểm gắn với mùa xuân năm 1946 vẫn nằm trong lòng Hà Nội. Phố Lý Thái Tổ vẫn là con phố rợp bóng cây gần hồ Hoàn Kiếm, với nhiều công trình kiến trúc thời Pháp. Nhà hát Lớn, nơi diễn ra cuộc mít tinh ngày 7/3 và kỳ họp đầu tiên của Quốc hội khóa I, vẫn đứng ở đầu phố Tràng Tiền. Văn bản và ảnh lễ ký Hiệp định Sơ bộ được giới thiệu trong các ấn phẩm, trưng bày của ngành lưu trữ, như một tư liệu gốc về buổi đầu của nền ngoại giao Việt Nam hiện đại.\n\nTrong gian trưng bày, tấm ảnh lễ ký được đặt cạnh những tư liệu về Tuyên ngôn Độc lập và Tổng tuyển cử. Sự sắp đặt ấy nhắc người xem rằng độc lập không chỉ được giành bằng một buổi chiều ở Ba Đình, mà còn được giữ bằng những quyết định khó khăn, có khi phải chấp nhận nhân nhượng để đi đường dài.","doc":13}],"nguon":["TS. Đào Thị Diến — Chủ tịch Hồ Chí Minh từ Hiệp định sơ bộ 6-3 đến Tạm ước 14-9-1946: https://www.archives.org.vn/gioi-thieu-tai-lieu-nghiep-vu/chu-tich-ho-chi-minh-tu-hiep-dinh-so-bo-6-3-den-tam-uoc-14-9-1946.htm","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký), NXB Quân đội nhân dân","Lịch sử 12, NXB Giáo dục Việt Nam","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Chiều 6/3/1946: một chữ ký để tránh chiến tranh. Buổi sáng, súng nổ ở cảng Hải Phòng. Buổi chiều, trong một ngôi nhà trên phố Lý Thái Tổ, Chủ tịch Hồ Chí Minh đặt bút ký một văn bản mà nhiều người khi ấy chưa hiểu, thậm chí phản đối. Nhưng chính chữ ký ấy đã đẩy hai mươi vạn quân Tưởng về nước và mua cho nước Việt Nam non trẻ chín tháng quý giá để chuẩn bị cho cuộc chiến không thể tránh."},{"t":"Một buổi chiều ở phố Lý Thái Tổ. Chiều 6/3/1946, tại ngôi nhà số 38 phố Lý Thái Tổ, Hà Nội, đại diện hai nước từng là thuộc địa và chính quốc ngồi vào cùng một bàn ký kết. Phía Việt Nam, Chủ tịch Hồ Chí Minh và ông Vũ Hồng Khanh, Phó Chủ tịch Ủy ban Kháng chiến, thay mặt Chính phủ đặt bút ký. Phía Pháp là Ủy viên Cộng hòa Jean Sainteny, người đã nhiều tuần đàm phán trực tiếp với Chủ tịch Hồ Chí Minh. Theo chú thích một ảnh lễ ký được TS. Đào Thị Diến giới thiệu trong bài viết về Hiệp định, có mặt trong phòng còn có Thứ trưởng Bộ Nội vụ Hoàng Minh Giám, cố vấn chính trị Léon Pignon và ông Louis Caput, đại diện Đảng Xã hội Pháp. Văn bản được ký hôm ấy mang tên Hiệp định Sơ bộ, nghĩa là bước khởi đầu cho một cuộc đàm phán lâu dài hơn. Nó ra đời chỉ vài giờ sau một vụ đụng độ ở Hải Phòng, khi chiến tranh có thể bùng nổ trên toàn miền Bắc bất cứ lúc nào. Để hiểu vì sao Người chọn ký, phải trở lại những tháng trước đó."},{"t":"Bị kẹp giữa hai đạo quân. Từ tháng 9/1945, khoảng hai mươi vạn quân Tưởng Giới Thạch tràn vào miền Bắc với danh nghĩa giải giáp quân Nhật. Chúng đóng khắp các thành phố, tiêu tiền mất giá, sách nhiễu dân, và che chở cho các nhóm Việt Nam Quốc dân Đảng, Việt Nam Cách mạng Đồng minh hội chống phá chính quyền cách mạng. Ở phía Nam, dưới sự yểm trợ của quân Anh, thực dân Pháp đã nổ súng trở lại từ ngày 23/9/1945; đến đầu năm 1946, chúng chiếm được phần lớn các thị xã, đường giao thông quan trọng ở Nam Bộ và nam Trung Bộ, rồi chuẩn bị đưa quân ra Bắc. Ngày 28/2/1946, tại Trùng Khánh, Chính phủ Tưởng Giới Thạch và Chính phủ Pháp ký Hiệp ước Hoa – Pháp. Pháp nhượng cho Tưởng một số quyền lợi ở Trung Quốc; đổi lại, Tưởng đồng ý để quân Pháp ra miền Bắc Việt Nam thay thế quân Tưởng. Hai kẻ thù đã bắt tay nhau trên lưng nước Việt Nam. Chính quyền cách mạng đứng trước nguy cơ phải cùng lúc đối phó với cả hai, khi lực lượng vũ trang còn non trẻ và thiếu thốn."},{"t":"Lựa chọn ngày 3/3. Chỉ một ngày trước đó, ngày 2/3/1946, Quốc hội khóa I vừa họp kỳ đầu tiên và lập ra Chính phủ Liên hiệp kháng chiến do Chủ tịch Hồ Chí Minh đứng đầu (xem chuyên đề về Quốc hội khóa I). Ngày 3/3/1946, Ban Thường vụ Trung ương Đảng họp, do Người chủ trì, để quyết định con đường trước mắt. Có hai khả năng: cầm súng đánh ngay khi quân Pháp đổ bộ, lúc lực lượng còn yếu và quân Tưởng vẫn đóng khắp miền Bắc; hoặc tạm thời hòa hoãn với Pháp để đẩy nhanh quân Tưởng về nước, có thêm thời gian xây dựng lực lượng. Hội nghị chọn con đường thứ hai. Đây không phải lựa chọn dễ dàng. Chỉ nửa năm trước, cả dân tộc vừa thề ở Ba Đình sẽ không để thực dân Pháp trở lại. Nay chính Chính phủ lại phải đồng ý cho một số quân Pháp vào miền Bắc. Nhưng như Chủ tịch Hồ Chí Minh nhiều lần giải thích, điều quyết định không phải là giữ thể diện nhất thời, mà là giữ được nền độc lập lâu dài và tránh cho đất nước một cuộc chiến bất lợi."},{"t":"Buổi sáng ở cảng Hải Phòng. Sáng 6/3/1946, tàu chiến Pháp chở quân tiến vào cảng Hải Phòng, định đổ bộ theo thỏa thuận với Tưởng. Nhưng quân Tưởng ở Hải Phòng lại nổ súng; tàu Pháp bắn trả, cuộc đấu súng gây thiệt hại cho cả hai phía. Vụ đụng độ cho thấy thỏa thuận giữa hai bên chưa hề êm thấm, và bất cứ lúc nào chiến sự cũng có thể lan rộng, kéo cả đất nước vào vòng binh lửa. Chính thế giằng co ấy tạo ra một thời cơ ngắn ngủi. Phía Pháp cần một thỏa thuận với Chính phủ Việt Nam để quân mình vào miền Bắc mà không phải nổ súng. Phía Tưởng cũng muốn Việt – Pháp ký kết trước khi rút đi. Nắm lấy thời điểm đó, phía Việt Nam đòi được những nhượng bộ mà chỉ vài tuần trước phía Pháp còn khước từ. Cuộc đàm phán được đẩy nhanh, và chiều hôm ấy, hiệp định được ký."},{"t":"Những điều khoản chính. Theo Hiệp định, Chính phủ Pháp công nhận nước Việt Nam Dân chủ Cộng hòa là một quốc gia tự do, có chính phủ, nghị viện, quân đội và tài chính riêng, nằm trong Liên bang Đông Dương và khối Liên hiệp Pháp. Về việc thống nhất ba kỳ, Pháp cam kết thừa nhận kết quả do nhân dân quyết định bằng trưng cầu dân ý. Việt Nam đồng ý để 15.000 quân Pháp ra miền Bắc thay thế quân Tưởng; theo phụ khoản quân sự, số quân này phải rút dần trong thời hạn 5 năm, mỗi năm rút một phần năm. Hai bên ngừng xung đột ở miền Nam và mở cuộc đàm phán chính thức. Chữ “tự do” trong văn bản chưa phải là “độc lập” mà dân tộc mong đợi. Nhưng lần đầu tiên, nước Pháp chính thức ký một văn kiện với Chính phủ Hồ Chí Minh như với một chính phủ hợp pháp. Nước Việt Nam Dân chủ Cộng hòa bước lên bàn đàm phán quốc tế với tư cách một chủ thể có quốc hội, có quân đội, chứ không còn là một xứ thuộc địa."},{"t":"Bạn có biết? Người cùng ký Hiệp định Sơ bộ với Chủ tịch Hồ Chí Minh là ông Vũ Hồng Khanh, một thủ lĩnh của Việt Nam Quốc dân Đảng — sự có mặt của ông thể hiện đây là quyết định của một chính phủ liên hiệp, đại diện cho nhiều khuynh hướng chính trị."},{"t":"Người đến giữa đồng bào. Tin ký hiệp định khiến nhiều người dân băn khoăn, thậm chí bất bình, cho rằng Chính phủ đã nhân nhượng quá nhiều. Các nhóm chống đối thân Tưởng lập tức lợi dụng tâm trạng ấy để kích động. Chính quyền không né tránh. Ngày 7/3/1946, một cuộc mít tinh lớn được tổ chức trước Nhà hát Lớn Hà Nội. Võ Nguyên Giáp thay mặt Chính phủ giải thích rằng ký hiệp định là để tránh một cuộc chiến đấu bất lợi, giữ gìn lực lượng, đẩy quân Tưởng về nước và mở đường tiến tới độc lập hoàn toàn. Chủ tịch Hồ Chí Minh cũng đến nói chuyện với đồng bào. Theo nhiều tư liệu, Người khẳng định suốt đời mình đã cùng đồng bào chiến đấu cho độc lập của Tổ quốc, và thà chết chứ không bao giờ bán nước. Lời nói ấy, từ người vừa đọc Tuyên ngôn Độc lập sáu tháng trước, đã làm dịu đi nỗi hoài nghi. Sách lược tạm hòa có giới hạn của nó; chín tháng sau, chính Người chỉ rõ giới hạn ấy."},{"t":"Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! — Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, 19/12/1946"},{"t":"Hòa để tiến. Ngày 9/3/1946, Ban Thường vụ Trung ương Đảng ra Chỉ thị “Hòa để tiến”. Tên gọi đã nói rõ tinh thần: hòa không phải để lùi, mà để có thời gian củng cố lực lượng, đồng thời luôn cảnh giác trước âm mưu của đối phương. Hiệp định được thực hiện nghiêm túc về phía Việt Nam, nhưng cuộc chuẩn bị cho một cuộc kháng chiến lâu dài không hề dừng lại. Những tuần sau đó dồn dập sự kiện. Ngày 18/3/1946, quân Pháp vào Hà Nội theo Hiệp định. Ngày 24/3, Chủ tịch Hồ Chí Minh gặp Cao ủy Pháp d'Argenlieu trên chiến hạm Émile Bertin ở vịnh Hạ Long; hai bên thỏa thuận mở một hội nghị trù bị. Hội nghị ấy họp ở Đà Lạt từ ngày 19/4 đến 11/5/1946 nhưng không đạt kết quả, vì phía Pháp muốn tách Nam Bộ khỏi Việt Nam. Cuộc đàm phán chính thức sau đó chuyển sang nước Pháp (xem chuyên đề về chuyến thăm Pháp và kiều bào năm 1946)."},{"t":"Chín tháng quý giá. Nhìn lại, Hiệp định Sơ bộ đã đạt được mục tiêu lớn nhất của nó. Không còn cớ ở lại, quân Tưởng lần lượt rút khỏi miền Bắc trong những tháng tiếp theo. Mất chỗ dựa, các nhóm chống đối thân Tưởng tan rã; nhiều kẻ cầm đầu chạy theo quân Tưởng sang Trung Quốc. Chính quyền cách mạng thoát khỏi thế phải cùng lúc đối đầu với hai đạo quân nước ngoài. Quãng thời gian hòa hoãn được dùng triệt để. Quân đội được mở rộng và huấn luyện, các xưởng quân giới được xây dựng, cơ quan và kho tàng từng bước chuẩn bị di chuyển lên chiến khu. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên. Vì vậy, khi thực dân Pháp bội ước, gây hấn ở Hải Phòng, Lạng Sơn rồi ở Hà Nội cuối năm 1946, cả nước đã có đủ thế và lực để bước vào cuộc kháng chiến trường kỳ. Hiệp định Sơ bộ từ đó được nhắc đến như một mẫu mực của nghệ thuật ngoại giao Hồ Chí Minh: mềm dẻo về sách lược, kiên định về mục tiêu."},{"t":"Các mốc thời gian. 28/2/1946: Hiệp ước Hoa – Pháp ký tại Trùng Khánh: Tưởng đồng ý để quân Pháp ra miền Bắc. 2/3/1946: Quốc hội khóa I họp kỳ đầu, lập Chính phủ Liên hiệp kháng chiến. 3/3/1946: Ban Thường vụ Trung ương Đảng quyết định tạm hòa hoãn với Pháp. 6/3/1946: Sáng đấu súng ở Hải Phòng; chiều ký Hiệp định Sơ bộ tại 38 Lý Thái Tổ. 7/3/1946: Mít tinh trước Nhà hát Lớn Hà Nội giải thích Hiệp định. 9/3/1946: Chỉ thị “Hòa để tiến” của Ban Thường vụ Trung ương. 18/3/1946: Quân Pháp vào Hà Nội theo Hiệp định. 24/3/1946: Gặp Cao ủy d'Argenlieu trên chiến hạm Émile Bertin ở vịnh Hạ Long. 19/4 – 11/5/1946: Hội nghị trù bị Đà Lạt không đạt kết quả. 14/9/1946: Ký Tạm ước tại Paris, kéo dài hòa hoãn. 19/12/1946: Lời kêu gọi toàn quốc kháng chiến."},{"t":"Bạn có biết? Ông Hoàng Minh Giám, Thứ trưởng Bộ Nội vụ có mặt trong lễ ký năm 1946, về sau giữ chức Bộ trưởng Bộ Ngoại giao nước Việt Nam Dân chủ Cộng hòa từ năm 1947 đến năm 1954, suốt những năm kháng chiến chống thực dân Pháp."},{"t":"Dấu tích hôm nay. Ngày nay, những địa điểm gắn với mùa xuân năm 1946 vẫn nằm trong lòng Hà Nội. Phố Lý Thái Tổ vẫn là con phố rợp bóng cây gần hồ Hoàn Kiếm, với nhiều công trình kiến trúc thời Pháp. Nhà hát Lớn, nơi diễn ra cuộc mít tinh ngày 7/3 và kỳ họp đầu tiên của Quốc hội khóa I, vẫn đứng ở đầu phố Tràng Tiền. Văn bản và ảnh lễ ký Hiệp định Sơ bộ được giới thiệu trong các ấn phẩm, trưng bày của ngành lưu trữ, như một tư liệu gốc về buổi đầu của nền ngoại giao Việt Nam hiện đại. Trong gian trưng bày, tấm ảnh lễ ký được đặt cạnh những tư liệu về Tuyên ngôn Độc lập và Tổng tuyển cử. Sự sắp đặt ấy nhắc người xem rằng độc lập không chỉ được giành bằng một buổi chiều ở Ba Đình, mà còn được giữ bằng những quyết định khó khăn, có khi phải chấp nhận nhân nhượng để đi đường dài."}],"so_chu":1875},{"i":12,"tieu_de_bang":"Toàn cảnh lễ đài Ba Đình ngày 2/9/1945","tieu_de":"Bảy ngày dựng một quảng trường: toàn cảnh lễ đài ngày Độc lập","sapo":"Bức ảnh toàn cảnh lễ đài chiều 2 tháng 9 năm 1945, nay lưu trong hệ thống Lưu trữ quốc gia, cho thấy một quảng trường rợp cờ và một biển người trải dài đến tận các góc phố. Nhưng đứng sau khung hình tĩnh lặng ấy là một guồng máy khẩn trương chỉ có đúng một tuần để chuẩn bị, một sĩ quan Mỹ xin đứng lẫn giữa đám đông thay vì ngồi ghế danh dự, và một phóng viên ảnh trẻ chạy vội lên vườn hoa với chiếc máy cũ trên tay. Toàn cảnh ấy, nhìn kỹ, kể một câu chuyện khác với những gì người ta vẫn thường nhớ về ngày hôm đó.","bia":{"src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bảy ngày để dựng một quốc gia","text":"Ngày 26 tháng 8 năm 1945, tại căn gác hai ngôi nhà số 48 phố Hàng Ngang, Ban Thường vụ Trung ương Đảng họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, quyết định một việc hệ trọng: tổ chức một cuộc mít tinh lớn ở Hà Nội để Chính phủ lâm thời ra mắt quốc dân và long trọng tuyên bố nền độc lập của đất nước. Từ cuộc họp ấy đến buổi chiều lịch sử chỉ còn đúng một tuần. Đó là quãng thời gian ngắn ngủi đến nghiệt ngã: phải chọn địa điểm, dựng lễ đài, huy động loa đài, sắp xếp cho hàng chục vạn người từ khắp Hà Nội và các vùng lân cận cùng đổ về một chỗ trong trật tự, trong khi bộ máy hành chính của chính quyền cách mạng còn chưa đầy nửa tháng tuổi, ngân khố gần như trống rỗng và quân đội Nhật bại trận vẫn còn đóng rải rác khắp thành phố. Không có một tiền lệ nào để noi theo — mọi việc, từ lớn đến nhỏ, đều phải nghĩ ra và làm ngay trong tuần lễ ngắn ngủi đó.","doc":1},{"loai":"doan","tieu_de":"Một quảng trường phải lo đủ mọi việc","text":"Địa điểm được chọn là vườn hoa Ba Đình, khoảng đất rộng ngay gần khu trung tâm hành chính cũ của chính quyền thuộc địa — vì sao lại là nơi này đã được kể ở một chuyên đề khác của gian trưng bày. Nhưng chọn xong địa điểm mới chỉ là bước đầu. Phải dựng một lễ đài đủ trang nghiêm cho giờ phút khai sinh một nhà nước, việc này được giao cho kiến trúc sư trẻ Ngô Huy Quỳnh — câu chuyện về lễ đài ấy cũng được kể riêng trong gian. Song song đó là hàng loạt việc không tên: kéo dây loa để giọng nói từ lễ đài vọng tới những người đứng xa nhất, dựng hàng rào và bố trí các đội tự vệ giữ trật tự dọc các ngả đường đổ về quảng trường, sắp xếp khu vực riêng cho các nhà báo và một số khách mời nước ngoài. Mỗi hạng mục đều phải hoàn thành trong những ngày cuối tháng 8, khi Hà Nội còn ngổn ngang trăm công nghìn việc của một chính quyền vừa mới ra đời.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_12_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Toàn cảnh lễ đài Ba Đình ngày 2/9/1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người khách xin đứng lẫn trong đám đông","text":"Trong số khách mời có một người nước ngoài đặc biệt: thiếu tá Archimedes Patti, sĩ quan Cơ quan Tình báo Chiến lược Mỹ (OSS), người trước đó ít ngày đã được Chủ tịch Hồ Chí Minh mời đọc trước bản thảo Tuyên ngôn Độc lập và trao đổi về tương lai đất nước. Theo hồi ký của chính ông, xuất bản nhiều năm sau, buổi chiều 2 tháng 9, dù được sắp chỗ ngồi ở khu ghế danh dự gần lễ đài, Patti đã xin phép đứng lẫn vào giữa đám đông để quan sát như một người dân bình thường. Từ vị trí ấy, ông ghi lại hình ảnh một Hà Nội rợp cờ và biểu ngữ viết bằng ba thứ tiếng Việt, Pháp, Anh, cùng dòng người đủ mọi thành phần — nông dân, công nhân, đồng bào các dân tộc — kéo về từ sáng sớm. Cái nhìn của một sĩ quan nước ngoài giữa biển người Việt Nam hôm ấy trở thành một tư liệu hiếm hoi, cho thấy ngày Độc lập không chỉ được nhìn từ phía trong.","doc":3},{"loai":"doan","tieu_de":"Trình tự một buổi lễ chưa từng có tiền lệ","text":"Không ai trong Ban tổ chức từng dự một lễ tuyên bố độc lập nào trước đó, nên chương trình buổi chiều hôm ấy được sắp xếp giản dị mà chặt chẽ. Mở đầu là lễ chào cờ: lá cờ đỏ sao vàng — được Quốc dân Đại hội họp ở Tân Trào trong hai ngày 16 và 17 tháng 8 quyết định chọn làm quốc kỳ — từ từ kéo lên giữa quảng trường, trong tiếng hát bài Tiến quân ca, cũng được Đại hội ấy chọn làm quốc ca. Đây là lần đầu tiên cả quốc kỳ lẫn quốc ca của một nước Việt Nam độc lập được cử hành công khai trước đông đảo dân chúng. Tiếp đó, Chủ tịch Hồ Chí Minh, thay mặt Chính phủ lâm thời, đọc bản Tuyên ngôn Độc lập vừa hoàn thành trên căn gác nhà 48 Hàng Ngang ít ngày trước. Sau khi Người đọc xong, các thành viên Chính phủ lâm thời lần lượt ra mắt quốc dân và làm lễ tuyên thệ, nguyện đem hết sức lực gìn giữ nền độc lập vừa giành được. Buổi lễ khép lại, nhưng một chặng đường mới, đầy thử thách, mới thật sự bắt đầu.","doc":4},{"loai":"trich","text":"Cụ ngồi đó, bình thản với nụ cười hiền hậu, dáng người nhỏ bé, nhưng trở nên vĩ đại trong tiếng hoan hô của quần chúng.","nguoi":"Archimedes Patti","nguon_ten":"Hồi ký Why Vietnam? Prelude to America's Albatross, dẫn theo báo Dân trí","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","chu_thich":"Toàn cảnh lễ đài tại Quảng trường Ba Đình chiều 2/9/1945 — một trong số ít bức ảnh toàn cảnh về buổi lễ còn được lưu giữ, hiện thuộc hệ thống Lưu trữ quốc gia.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người cầm máy ảnh giữa vườn hoa","text":"Rất ít người khi ấy có trong tay một chiếc máy ảnh, và còn ít hơn nữa những người kịp đưa máy lên đúng khoảnh khắc lịch sử. Một trong số đó là Nguyễn Bá Khoản, phóng viên ảnh của báo Cứu Quốc. Theo lời ông kể lại, chiều 2 tháng 9, sau khi được tòa soạn dặn dò, ông xách chiếc máy ảnh cũ của mình lên thẳng vườn hoa Ba Đình trước giờ khai mạc, chọn góc đứng, canh ánh sáng rồi bấm liên tiếp nhiều kiểu ảnh với những tốc độ khác nhau để chắc chắn không bỏ lỡ khoảnh khắc. Những bức ảnh như thế — trong đó có các khung hình toàn cảnh quảng trường và lễ đài — trở thành một phần hiếm hoi trong kho tư liệu hình ảnh còn sót lại về ngày 2 tháng 9. Nhiều năm sau, ông và gia đình đã hiến tặng hàng nghìn phim gốc cho bảo tàng, để những khoảnh khắc ấy không chỉ còn trong trí nhớ của một thế hệ đã dần thưa vắng.","doc":6},{"loai":"ban_co_biet","text":"Theo hồi ký của Patti, khi soạn những dòng mở đầu trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776, Chủ tịch Hồ Chí Minh viết theo trí nhớ và đã hỏi lại ông để xác nhận cho đúng câu chữ.","nguon_ten":"Archimedes Patti, hồi ký Why Vietnam?","doc":7},{"loai":"doan","tieu_de":"Những nguy cơ giấu sau tấm phông đỏ","text":"Vẻ ngoài trang nghiêm của buổi lễ che giấu một tình thế hết sức mong manh. Quân đội Nhật, dù đã tuyên bố đầu hàng Đồng minh, vẫn còn đóng rải rác trong thành phố và giữ vũ khí; theo thỏa thuận quốc tế, quân Trung Hoa Dân quốc sắp tiến vào miền Bắc với danh nghĩa giải giáp quân Nhật, còn quân Pháp thì đang tìm cách trở lại Đông Dương. Giữa bối cảnh ấy, việc tập hợp hàng chục vạn người vào một quảng trường vừa là biểu dương sức mạnh của chính quyền cách mạng, vừa là một rủi ro an ninh không nhỏ. Các đội tự vệ chiến đấu và thanh niên xung phong được huy động để giữ trật tự dọc các tuyến phố và quanh khu vực lễ đài, sẵn sàng ứng phó nếu có biến. May mắn thay, buổi lễ diễn ra trọn vẹn, không xảy ra sự cố nào — một kết quả mà bản thân sự bình yên ấy, trong hoàn cảnh năm 1945, đã là một thành công không nhỏ của những người đứng sau tổ chức nó.","doc":8},{"loai":"anh","src":"textures/bang_w/G14_12_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Toàn cảnh lễ đài Ba Đình ngày 2/9/1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ mảnh phim nhỏ đến tài liệu lưu trữ quốc gia","text":"Tấm ảnh toàn cảnh lễ đài dùng làm hình minh họa cho chuyên đề này cho thấy một góc nhìn bao quát: lễ đài dựng giữa quảng trường, phông nền sẫm màu, cờ và biểu ngữ giăng xung quanh, và ở phía xa là biển người trải dài đến tận các con phố lân cận. Không giống những bức cận cảnh Chủ tịch Hồ Chí Minh trên lễ đài, giá trị của tấm ảnh này nằm ở chính sự bao quát ấy — nó là bằng chứng hình ảnh hiếm hoi cho thấy quy mô thật sự của buổi lễ, thứ mà lời kể, dù chi tiết đến đâu, cũng khó lột tả trọn vẹn. Nhờ những tấm ảnh như thế, cùng các bản vẽ và mô tả còn lưu lại, không gian ba chiều của quảng trường Ba Đình chiều 2/9/1945 trong gian trưng bày này mới có thể được phục dựng gần với sự thật lịch sử, thay vì chỉ dựa trên trí tưởng tượng.","doc":9},{"loai":"ban_co_biet","text":"Ảnh và phim gốc về ngày 2/9/1945 hiện được bảo quản rải rác ở nhiều nơi — Bảo tàng Hồ Chí Minh, Bảo tàng Lịch sử quốc gia, hệ thống Lưu trữ quốc gia — nên phần lớn công chúng chỉ được xem qua các đợt trưng bày nhân dịp Quốc khánh.","nguon_ten":"Bảo tàng Hồ Chí Minh; Cục Văn thư và Lưu trữ nhà nước","doc":10},{"loai":"anh","src":"textures/bang_w/G14_12_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Toàn cảnh lễ đài Ba Đình ngày 2/9/1945”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Lễ đài dựng gấp trong một tuần của năm 1945 không còn tồn tại — nó chỉ là một kết cấu tạm, đúng như tính chất khẩn cấp của những ngày lập quốc. Nhưng những tấm ảnh ghi lại nó thì còn ở lại, và ngày càng trở nên quý giá theo thời gian, khi số người từng có mặt ở quảng trường chiều hôm ấy ngày một thưa dần. Ngày nay, những bức ảnh gốc như tấm toàn cảnh này vẫn được các cơ quan lưu trữ, bảo tàng gìn giữ cẩn trọng, và định kỳ được đưa ra trưng bày mỗi dịp Quốc khánh 2 tháng 9, để những thế hệ chưa từng sống qua năm 1945 có thể nhìn thấy, dù chỉ qua một khung hình đen trắng, hình ảnh một dân tộc đang đứng giữa chính quảng trường của mình, lần đầu tiên tự xưng là một quốc gia độc lập.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Cục Văn thư và Lưu trữ nhà nước – Trung tâm Lưu trữ quốc gia","Bảo tàng Hồ Chí Minh","Archimedes Patti, hồi ký Why Vietnam? Prelude to America's Albatross — dẫn theo báo Dân trí, 30/8/2021: https://dantri.com.vn/thoi-su/ngay-le-doc-lap-291945-trong-mat-mot-nhan-chung-nguoi-my-dac-biet-20210830111953977.htm","Người chép sử bằng hình ảnh và những khoảnh khắc lịch sử trên Quảng trường Ba Đình, Báo Lào Cai: https://baolaocai.vn/nguoi-chep-su-bang-hinh-anh-va-nhung-khoanh-khac-lich-su-tren-quang-truong-ba-dinh-post372998.html","Bảo tàng Lịch sử quốc gia; Lịch sử Đảng Cộng sản Việt Nam"],"doc":[{"t":"Bảy ngày dựng một quảng trường: toàn cảnh lễ đài ngày Độc lập. Bức ảnh toàn cảnh lễ đài chiều 2 tháng 9 năm 1945, nay lưu trong hệ thống Lưu trữ quốc gia, cho thấy một quảng trường rợp cờ và một biển người trải dài đến tận các góc phố. Nhưng đứng sau khung hình tĩnh lặng ấy là một guồng máy khẩn trương chỉ có đúng một tuần để chuẩn bị, một sĩ quan Mỹ xin đứng lẫn giữa đám đông thay vì ngồi ghế danh dự, và một phóng viên ảnh trẻ chạy vội lên vườn hoa với chiếc máy cũ trên tay. Toàn cảnh ấy, nhìn kỹ, kể một câu chuyện khác với những gì người ta vẫn thường nhớ về ngày hôm đó."},{"t":"Bảy ngày để dựng một quốc gia. Ngày 26 tháng 8 năm 1945, tại căn gác hai ngôi nhà số 48 phố Hàng Ngang, Ban Thường vụ Trung ương Đảng họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, quyết định một việc hệ trọng: tổ chức một cuộc mít tinh lớn ở Hà Nội để Chính phủ lâm thời ra mắt quốc dân và long trọng tuyên bố nền độc lập của đất nước. Từ cuộc họp ấy đến buổi chiều lịch sử chỉ còn đúng một tuần. Đó là quãng thời gian ngắn ngủi đến nghiệt ngã: phải chọn địa điểm, dựng lễ đài, huy động loa đài, sắp xếp cho hàng chục vạn người từ khắp Hà Nội và các vùng lân cận cùng đổ về một chỗ trong trật tự, trong khi bộ máy hành chính của chính quyền cách mạng còn chưa đầy nửa tháng tuổi, ngân khố gần như trống rỗng và quân đội Nhật bại trận vẫn còn đóng rải rác khắp thành phố. Không có một tiền lệ nào để noi theo — mọi việc, từ lớn đến nhỏ, đều phải nghĩ ra và làm ngay trong tuần lễ ngắn ngủi đó."},{"t":"Một quảng trường phải lo đủ mọi việc. Địa điểm được chọn là vườn hoa Ba Đình, khoảng đất rộng ngay gần khu trung tâm hành chính cũ của chính quyền thuộc địa — vì sao lại là nơi này đã được kể ở một chuyên đề khác của gian trưng bày. Nhưng chọn xong địa điểm mới chỉ là bước đầu. Phải dựng một lễ đài đủ trang nghiêm cho giờ phút khai sinh một nhà nước, việc này được giao cho kiến trúc sư trẻ Ngô Huy Quỳnh — câu chuyện về lễ đài ấy cũng được kể riêng trong gian. Song song đó là hàng loạt việc không tên: kéo dây loa để giọng nói từ lễ đài vọng tới những người đứng xa nhất, dựng hàng rào và bố trí các đội tự vệ giữ trật tự dọc các ngả đường đổ về quảng trường, sắp xếp khu vực riêng cho các nhà báo và một số khách mời nước ngoài. Mỗi hạng mục đều phải hoàn thành trong những ngày cuối tháng 8, khi Hà Nội còn ngổn ngang trăm công nghìn việc của một chính quyền vừa mới ra đời."},{"t":"Người khách xin đứng lẫn trong đám đông. Trong số khách mời có một người nước ngoài đặc biệt: thiếu tá Archimedes Patti, sĩ quan Cơ quan Tình báo Chiến lược Mỹ (OSS), người trước đó ít ngày đã được Chủ tịch Hồ Chí Minh mời đọc trước bản thảo Tuyên ngôn Độc lập và trao đổi về tương lai đất nước. Theo hồi ký của chính ông, xuất bản nhiều năm sau, buổi chiều 2 tháng 9, dù được sắp chỗ ngồi ở khu ghế danh dự gần lễ đài, Patti đã xin phép đứng lẫn vào giữa đám đông để quan sát như một người dân bình thường. Từ vị trí ấy, ông ghi lại hình ảnh một Hà Nội rợp cờ và biểu ngữ viết bằng ba thứ tiếng Việt, Pháp, Anh, cùng dòng người đủ mọi thành phần — nông dân, công nhân, đồng bào các dân tộc — kéo về từ sáng sớm. Cái nhìn của một sĩ quan nước ngoài giữa biển người Việt Nam hôm ấy trở thành một tư liệu hiếm hoi, cho thấy ngày Độc lập không chỉ được nhìn từ phía trong."},{"t":"Trình tự một buổi lễ chưa từng có tiền lệ. Không ai trong Ban tổ chức từng dự một lễ tuyên bố độc lập nào trước đó, nên chương trình buổi chiều hôm ấy được sắp xếp giản dị mà chặt chẽ. Mở đầu là lễ chào cờ: lá cờ đỏ sao vàng — được Quốc dân Đại hội họp ở Tân Trào trong hai ngày 16 và 17 tháng 8 quyết định chọn làm quốc kỳ — từ từ kéo lên giữa quảng trường, trong tiếng hát bài Tiến quân ca, cũng được Đại hội ấy chọn làm quốc ca. Đây là lần đầu tiên cả quốc kỳ lẫn quốc ca của một nước Việt Nam độc lập được cử hành công khai trước đông đảo dân chúng. Tiếp đó, Chủ tịch Hồ Chí Minh, thay mặt Chính phủ lâm thời, đọc bản Tuyên ngôn Độc lập vừa hoàn thành trên căn gác nhà 48 Hàng Ngang ít ngày trước. Sau khi Người đọc xong, các thành viên Chính phủ lâm thời lần lượt ra mắt quốc dân và làm lễ tuyên thệ, nguyện đem hết sức lực gìn giữ nền độc lập vừa giành được. Buổi lễ khép lại, nhưng một chặng đường mới, đầy thử thách, mới thật sự bắt đầu."},{"t":"Cụ ngồi đó, bình thản với nụ cười hiền hậu, dáng người nhỏ bé, nhưng trở nên vĩ đại trong tiếng hoan hô của quần chúng. — Archimedes Patti"},{"t":"Người cầm máy ảnh giữa vườn hoa. Rất ít người khi ấy có trong tay một chiếc máy ảnh, và còn ít hơn nữa những người kịp đưa máy lên đúng khoảnh khắc lịch sử. Một trong số đó là Nguyễn Bá Khoản, phóng viên ảnh của báo Cứu Quốc. Theo lời ông kể lại, chiều 2 tháng 9, sau khi được tòa soạn dặn dò, ông xách chiếc máy ảnh cũ của mình lên thẳng vườn hoa Ba Đình trước giờ khai mạc, chọn góc đứng, canh ánh sáng rồi bấm liên tiếp nhiều kiểu ảnh với những tốc độ khác nhau để chắc chắn không bỏ lỡ khoảnh khắc. Những bức ảnh như thế — trong đó có các khung hình toàn cảnh quảng trường và lễ đài — trở thành một phần hiếm hoi trong kho tư liệu hình ảnh còn sót lại về ngày 2 tháng 9. Nhiều năm sau, ông và gia đình đã hiến tặng hàng nghìn phim gốc cho bảo tàng, để những khoảnh khắc ấy không chỉ còn trong trí nhớ của một thế hệ đã dần thưa vắng."},{"t":"Bạn có biết? Theo hồi ký của Patti, khi soạn những dòng mở đầu trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776, Chủ tịch Hồ Chí Minh viết theo trí nhớ và đã hỏi lại ông để xác nhận cho đúng câu chữ."},{"t":"Những nguy cơ giấu sau tấm phông đỏ. Vẻ ngoài trang nghiêm của buổi lễ che giấu một tình thế hết sức mong manh. Quân đội Nhật, dù đã tuyên bố đầu hàng Đồng minh, vẫn còn đóng rải rác trong thành phố và giữ vũ khí; theo thỏa thuận quốc tế, quân Trung Hoa Dân quốc sắp tiến vào miền Bắc với danh nghĩa giải giáp quân Nhật, còn quân Pháp thì đang tìm cách trở lại Đông Dương. Giữa bối cảnh ấy, việc tập hợp hàng chục vạn người vào một quảng trường vừa là biểu dương sức mạnh của chính quyền cách mạng, vừa là một rủi ro an ninh không nhỏ. Các đội tự vệ chiến đấu và thanh niên xung phong được huy động để giữ trật tự dọc các tuyến phố và quanh khu vực lễ đài, sẵn sàng ứng phó nếu có biến. May mắn thay, buổi lễ diễn ra trọn vẹn, không xảy ra sự cố nào — một kết quả mà bản thân sự bình yên ấy, trong hoàn cảnh năm 1945, đã là một thành công không nhỏ của những người đứng sau tổ chức nó."},{"t":"Từ mảnh phim nhỏ đến tài liệu lưu trữ quốc gia. Tấm ảnh toàn cảnh lễ đài dùng làm hình minh họa cho chuyên đề này cho thấy một góc nhìn bao quát: lễ đài dựng giữa quảng trường, phông nền sẫm màu, cờ và biểu ngữ giăng xung quanh, và ở phía xa là biển người trải dài đến tận các con phố lân cận. Không giống những bức cận cảnh Chủ tịch Hồ Chí Minh trên lễ đài, giá trị của tấm ảnh này nằm ở chính sự bao quát ấy — nó là bằng chứng hình ảnh hiếm hoi cho thấy quy mô thật sự của buổi lễ, thứ mà lời kể, dù chi tiết đến đâu, cũng khó lột tả trọn vẹn. Nhờ những tấm ảnh như thế, cùng các bản vẽ và mô tả còn lưu lại, không gian ba chiều của quảng trường Ba Đình chiều 2/9/1945 trong gian trưng bày này mới có thể được phục dựng gần với sự thật lịch sử, thay vì chỉ dựa trên trí tưởng tượng."},{"t":"Bạn có biết? Ảnh và phim gốc về ngày 2/9/1945 hiện được bảo quản rải rác ở nhiều nơi — Bảo tàng Hồ Chí Minh, Bảo tàng Lịch sử quốc gia, hệ thống Lưu trữ quốc gia — nên phần lớn công chúng chỉ được xem qua các đợt trưng bày nhân dịp Quốc khánh."},{"t":"Dấu tích hôm nay. Lễ đài dựng gấp trong một tuần của năm 1945 không còn tồn tại — nó chỉ là một kết cấu tạm, đúng như tính chất khẩn cấp của những ngày lập quốc. Nhưng những tấm ảnh ghi lại nó thì còn ở lại, và ngày càng trở nên quý giá theo thời gian, khi số người từng có mặt ở quảng trường chiều hôm ấy ngày một thưa dần. Ngày nay, những bức ảnh gốc như tấm toàn cảnh này vẫn được các cơ quan lưu trữ, bảo tàng gìn giữ cẩn trọng, và định kỳ được đưa ra trưng bày mỗi dịp Quốc khánh 2 tháng 9, để những thế hệ chưa từng sống qua năm 1945 có thể nhìn thấy, dù chỉ qua một khung hình đen trắng, hình ảnh một dân tộc đang đứng giữa chính quảng trường của mình, lần đầu tiên tự xưng là một quốc gia độc lập."}],"so_chu":1696},{"i":13,"tieu_de_bang":"Bản Tuyên ngôn Độc lập — Trung tâm Lưu trữ quốc gia III","tieu_de":"Đọc chậm bản Tuyên ngôn Độc lập: lý lẽ, cáo trạng và tờ giấy được gìn giữ","sapo":"Chỉ vài trang giấy, được viết trong hai ngày trên một căn gác phố cổ, nhưng bản Tuyên ngôn Độc lập chứa cả một phiên tòa lịch sử: có lý lẽ, có chứng cứ, có phán quyết. Hôm nay, văn bản ấy được gìn giữ tại Trung tâm Lưu trữ quốc gia III. Hãy thử đọc chậm từng phần, như một nhà lưu trữ lật giở tập hồ sơ quý nhất của mình.","bia":{"src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bốn chữ mở đầu","text":"“Hỡi đồng bào cả nước”. Đó là những chữ đầu tiên của văn bản mà tấm ảnh trên bảng này ghi lại: bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa, tài liệu đang được lưu giữ tại Trung tâm Lưu trữ quốc gia III ở Hà Nội. Hình ảnh văn bản được đưa lên kho ảnh tự do Wikimedia Commons vào tháng 8/2020, ít ngày trước lễ kỷ niệm 75 năm Quốc khánh, với ghi chú nguồn là Chính phủ Việt Nam.\n\nNhiều người thuộc lòng vài câu trong bản Tuyên ngôn, nhưng ít ai có dịp đọc chậm toàn văn như đọc một hồ sơ. Làm như thế, ta sẽ thấy văn kiện chỉ dài vài trang ấy được dựng lên như một bản luận tội trước tòa án của lịch sử. Phần đầu nêu cơ sở pháp lý. Phần giữa đưa ra cáo trạng và chứng cứ. Phần cuối là phán quyết: một lời tuyên bố với thế giới và một lời thề của cả dân tộc.","doc":1},{"loai":"doan","tieu_de":"Mượn lời của hai cuộc cách mạng","text":"Người mở đầu không bằng lời của mình, mà bằng lời của người khác. Câu đầu tiên được trích từ bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ, văn kiện khai sinh một quốc gia từng là thuộc địa của Anh. Tiếp đó là bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp: người ta sinh ra tự do và bình đẳng về quyền lợi, và phải luôn luôn được tự do và bình đẳng về quyền lợi.\n\nTừ hai nguyên lý ấy, Người “suy rộng ra” thành quyền của các dân tộc: dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do. Lựa chọn này rất có chủ đích. Mỹ là một cường quốc Đồng minh vừa thắng trận. Pháp là nước đang tìm cách quay lại Đông Dương. Dẫn lời của chính họ, bản Tuyên ngôn khiến mọi sự phủ nhận quyền độc lập của Việt Nam trở thành sự phủ nhận chính những lý tưởng mà họ từng tuyên bố. Theo hồi ký của thiếu tá Archimedes Patti, sĩ quan tình báo Mỹ có mặt ở Hà Nội khi ấy, ông đã được Chủ tịch Hồ Chí Minh cho biết trước nội dung bản thảo.","doc":2},{"loai":"trich","text":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.","nguoi":"Hồ Chí Minh dẫn Tuyên ngôn Độc lập năm 1776 của nước Mỹ, trong Tuyên ngôn Độc lập, 2/9/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật, 2011","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","chu_thich":"Bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa, tài liệu lưu tại Trung tâm Lưu trữ quốc gia III.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bản cáo trạng hơn tám mươi năm","text":"Sau phần lý lẽ là bản cáo trạng. Câu chuyển ý rất ngắn: “Thế mà hơn 80 năm nay, bọn thực dân Pháp lợi dụng lá cờ tự do, bình đẳng, bác ái, đến cướp đất nước ta, áp bức đồng bào ta”. Hai chữ “thế mà” đặt những lý tưởng cao đẹp vừa trích dẫn ngay cạnh hành động của kẻ tự nhận là người mang chúng đến.\n\nVề chính trị, bản Tuyên ngôn liệt kê từng tội bằng một loạt câu mở đầu với chữ “Chúng”. Chúng tuyệt đối không cho nhân dân ta một chút tự do dân chủ nào. Chúng lập ba chế độ khác nhau ở Trung, Nam, Bắc để ngăn cản dân tộc ta đoàn kết. Chúng lập ra nhà tù nhiều hơn trường học, tắm các cuộc khởi nghĩa của ta trong những bể máu. Chúng thi hành chính sách ngu dân, dùng thuốc phiện, rượu cồn để làm cho nòi giống ta suy nhược. Những câu ngắn, cùng một chủ ngữ, nối nhau như những nhát búa. Nhịp điệu ấy rất hợp với một văn bản được viết để đọc to trước đám đông.","doc":4},{"loai":"doan","tieu_de":"Chứng cứ có tên đất, có con số","text":"Về kinh tế, cáo trạng cũng cụ thể như thế. Thực dân cướp không ruộng đất, hầm mỏ, nguyên liệu. Chúng giữ độc quyền in giấy bạc, xuất cảng và nhập cảng. Chúng đặt ra hàng trăm thứ thuế vô lý, làm cho dân cày và dân buôn trở nên bần cùng, không cho các nhà tư sản ta ngóc đầu lên.\n\nRồi bản Tuyên ngôn chuyển sang những sự kiện mà người nghe năm 1945 còn nhớ như in. Mùa thu năm 1940, phát xít Nhật vào Đông Dương, thực dân Pháp quỳ gối đầu hàng, mở cửa nước ta rước Nhật, để dân ta chịu hai tầng xiềng xích. Cuối năm 1944 sang đầu năm 1945, từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào bị chết đói. Ngày 9/3/1945, Nhật tước khí giới quân Pháp; kẻ tự xưng “bảo hộ” hoặc bỏ chạy, hoặc đầu hàng. Văn bản kết luận: trong năm năm, chúng đã bán nước ta hai lần cho Nhật. Khi thua chạy, chúng còn giết nốt số đông tù chính trị ở Yên Bái và Cao Bằng. Mỗi chứng cứ đều có thời gian, địa danh, con số.","doc":5},{"loai":"anh","src":"textures/bang_w/G14_13_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản Tuyên ngôn Độc lập — Trung tâm Lưu trữ quốc gia III”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai lần “Sự thật là”","text":"Phần then chốt về pháp lý nằm ở hai câu cùng mở đầu bằng ba chữ “Sự thật là”. Câu thứ nhất khẳng định: từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Câu thứ hai: dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.\n\nHai câu ấy bác bỏ tận gốc cái cớ mà thực dân Pháp đang chuẩn bị viện ra để trở lại: rằng Đông Dương vẫn là thuộc địa của Pháp, chỉ tạm thời bị Nhật chiếm. Nếu Pháp đã hai lần bán nước ta cho Nhật, rồi bỏ chạy trước Nhật, thì họ không còn danh nghĩa nào để đòi lại. Tiếp theo là một câu chưa đầy mười chữ mà tóm cả một mùa thu: “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị”. Bản Tuyên ngôn khẳng định dân ta đã đánh đổ xiềng xích thực dân, đồng thời đánh đổ chế độ quân chủ mấy mươi thế kỷ để lập nên chế độ Dân chủ Cộng hòa. Văn kiện vì thế ghi nhận cùng lúc hai cuộc đổi thay: giành lại độc lập và thay đổi chính thể.","doc":6},{"loai":"ban_co_biet","text":"Ngay trong bản cáo trạng, Tuyên ngôn vẫn ghi nhận thái độ khoan hồng của người Việt: sau cuộc biến động ngày 9/3/1945, Việt Minh đã giúp nhiều người Pháp chạy qua biên thùy, cứu nhiều người Pháp ra khỏi nhà giam Nhật và bảo vệ tính mạng, tài sản cho họ.","nguon_ten":"Tuyên ngôn Độc lập, 2/9/1945 — Hồ Chí Minh Toàn tập, tập 4","doc":7},{"loai":"doan","tieu_de":"Lời tuyên bố gửi thế giới","text":"Từ các chứng cứ, bản Tuyên ngôn đi đến phần tuyên bố. Chính phủ lâm thời, đại biểu cho toàn dân Việt Nam, tuyên bố thoát ly hẳn quan hệ thực dân với Pháp, xóa bỏ hết những hiệp ước mà Pháp đã ký về nước Việt Nam, xóa bỏ mọi đặc quyền của Pháp trên đất nước này. Chế độ bảo hộ được xác lập bằng Hiệp ước Patenôtre năm 1884; hơn sáu mươi năm sau, chỉ bằng một câu, cả nền móng pháp lý ấy bị gạt bỏ.\n\nVăn kiện hướng tới các nước Đồng minh. Người nhắc rằng họ đã công nhận nguyên tắc dân tộc bình đẳng ở Hội nghị Tê-hê-răng cuối năm 1943 và Hội nghị Cựu Kim Sơn năm 1945, nơi Hiến chương Liên hợp quốc ra đời. Vì thế, họ “quyết không thể không công nhận quyền độc lập của dân Việt Nam”. Lối phủ định hai lần ấy biến lời đề nghị thành một đòi hỏi hợp lẽ. Câu kết của bản Tuyên ngôn là một lời thề (xem chuyên đề Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…”).","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, 2/9/1945.","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ lễ đài đến đời sống của một văn kiện","text":"Chiều 2/9/1945, văn bản được Chủ tịch Hồ Chí Minh đọc trước hàng chục vạn đồng bào ở Quảng trường Ba Đình. Từ đó, nó bắt đầu cuộc đời thứ hai: cuộc đời của một văn kiện nhà nước. Tuyên ngôn được in lại, được phổ biến tới các địa phương, trở thành nền tảng cho mọi hoạt động của chính quyền mới trong quan hệ với quốc dân và với nước ngoài.\n\nViệc những tờ giấy của mùa thu năm 1945 còn đến hôm nay là điều không hề hiển nhiên. Chỉ hơn một năm sau, cuộc kháng chiến toàn quốc bùng nổ, Hà Nội chìm trong khói lửa, các cơ quan trung ương phải rời Thủ đô lên chiến khu. Giấy thời chiến lại thường mỏng, dễ giòn, dễ ố. Bởi vậy, mỗi văn bản của những ngày lập quốc còn giữ được đều là tư liệu vô giá, bằng chứng trực tiếp về sự ra đời của một nhà nước.","doc":9},{"loai":"anh","src":"textures/bang_w/G14_13_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản Tuyên ngôn Độc lập — Trung tâm Lưu trữ quốc gia III”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ngôi nhà của hồ sơ quốc gia","text":"Trung tâm Lưu trữ quốc gia III thuộc Cục Văn thư và Lưu trữ nhà nước, Bộ Nội vụ. Trong hệ thống lưu trữ quốc gia, mỗi trung tâm giữ một mảng ký ức riêng. Trung tâm Lưu trữ quốc gia I ở Hà Nội lưu tài liệu thời phong kiến và thời Pháp thuộc, trong đó có châu bản triều Nguyễn. Trung tâm II ở Thành phố Hồ Chí Minh giữ tài liệu thời Pháp thuộc ở Nam Kỳ và của các chính quyền ở miền Nam trước năm 1975. Trung tâm IV ở Đà Lạt bảo quản mộc bản triều Nguyễn, di sản tư liệu được UNESCO ghi danh năm 2009.\n\nTrung tâm III đảm nhận phần ký ức của nhà nước Việt Nam từ năm 1945 trở đi: tài liệu của các cơ quan trung ương thời Việt Nam Dân chủ Cộng hòa và Cộng hòa xã hội chủ nghĩa Việt Nam. Bản Tuyên ngôn Độc lập vì thế thuộc về lớp tài liệu khởi đầu của cả kho tư liệu ấy, cùng với những sắc lệnh và văn bản đầu tiên của Chính phủ lâm thời.","doc":10},{"loai":"anh","src":"textures/bang_w/G14_13_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản Tuyên ngôn Độc lập — Trung tâm Lưu trữ quốc gia III”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Đọc Tuyên ngôn hôm nay","text":"Những tài liệu gốc như thế thường được giữ trong kho có kiểm soát nhiệt độ, độ ẩm, và chỉ đến với công chúng qua các đợt trưng bày hay bản sao. Văn bản Tuyên ngôn Độc lập đã được giới thiệu qua các hoạt động trưng bày tài liệu lưu trữ. Với người đọc hôm nay, toàn văn Tuyên ngôn được in trong tập 4 của bộ Hồ Chí Minh Toàn tập, xuất bản năm 2011.\n\nỞ Hà Nội, khách tham quan có thể nối ba điểm của cùng một câu chuyện: căn gác ở số 48 Hàng Ngang, nơi văn bản được viết; Quảng trường Ba Đình, nơi văn bản được đọc; và kho lưu trữ, nơi văn bản được gìn giữ. Khi đứng trước tấm ảnh này trong bảo tàng, hãy thử đọc lại bốn chữ “Hỡi đồng bào cả nước”. Đó là lời gọi của một văn kiện viết cho toàn dân, và đến hôm nay vẫn chưa thôi hướng về mỗi người đọc.","doc":11},{"loai":"ban_co_biet","text":"Bản Tuyên ngôn Nhân quyền và Dân quyền được Quốc hội Pháp thông qua năm 1789, rồi được đặt ở phần mở đầu bản Hiến pháp năm 1791 của nước Pháp. Đó là cách giải thích thường được nêu cho mốc năm 1791 ghi trong Tuyên ngôn Độc lập của Việt Nam.","nguon_ten":"Tuyên ngôn Độc lập — Hồ Chí Minh Toàn tập, tập 4; Déclaration des droits de l'homme et du citoyen (1789)","doc":12}],"nguon":["Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật, 2011 — Tuyên ngôn Độc lập","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Trung tâm Lưu trữ quốc gia III — Cục Văn thư và Lưu trữ nhà nước, Bộ Nội vụ","Archimedes L. A. Patti, Why Viet Nam? Prelude to America's Albatross, University of California Press, 1980","Báo Hà Nội Mới — Archimedes Patti, nhân chứng lịch sử ngày 2-9-1945"],"doc":[{"t":"Đọc chậm bản Tuyên ngôn Độc lập: lý lẽ, cáo trạng và tờ giấy được gìn giữ. Chỉ vài trang giấy, được viết trong hai ngày trên một căn gác phố cổ, nhưng bản Tuyên ngôn Độc lập chứa cả một phiên tòa lịch sử: có lý lẽ, có chứng cứ, có phán quyết. Hôm nay, văn bản ấy được gìn giữ tại Trung tâm Lưu trữ quốc gia III. Hãy thử đọc chậm từng phần, như một nhà lưu trữ lật giở tập hồ sơ quý nhất của mình."},{"t":"Bốn chữ mở đầu. “Hỡi đồng bào cả nước”. Đó là những chữ đầu tiên của văn bản mà tấm ảnh trên bảng này ghi lại: bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa, tài liệu đang được lưu giữ tại Trung tâm Lưu trữ quốc gia III ở Hà Nội. Hình ảnh văn bản được đưa lên kho ảnh tự do Wikimedia Commons vào tháng 8/2020, ít ngày trước lễ kỷ niệm 75 năm Quốc khánh, với ghi chú nguồn là Chính phủ Việt Nam. Nhiều người thuộc lòng vài câu trong bản Tuyên ngôn, nhưng ít ai có dịp đọc chậm toàn văn như đọc một hồ sơ. Làm như thế, ta sẽ thấy văn kiện chỉ dài vài trang ấy được dựng lên như một bản luận tội trước tòa án của lịch sử. Phần đầu nêu cơ sở pháp lý. Phần giữa đưa ra cáo trạng và chứng cứ. Phần cuối là phán quyết: một lời tuyên bố với thế giới và một lời thề của cả dân tộc."},{"t":"Mượn lời của hai cuộc cách mạng. Người mở đầu không bằng lời của mình, mà bằng lời của người khác. Câu đầu tiên được trích từ bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ, văn kiện khai sinh một quốc gia từng là thuộc địa của Anh. Tiếp đó là bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp: người ta sinh ra tự do và bình đẳng về quyền lợi, và phải luôn luôn được tự do và bình đẳng về quyền lợi. Từ hai nguyên lý ấy, Người “suy rộng ra” thành quyền của các dân tộc: dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do. Lựa chọn này rất có chủ đích. Mỹ là một cường quốc Đồng minh vừa thắng trận. Pháp là nước đang tìm cách quay lại Đông Dương. Dẫn lời của chính họ, bản Tuyên ngôn khiến mọi sự phủ nhận quyền độc lập của Việt Nam trở thành sự phủ nhận chính những lý tưởng mà họ từng tuyên bố. Theo hồi ký của thiếu tá Archimedes Patti, sĩ quan tình báo Mỹ có mặt ở Hà Nội khi ấy, ông đã được Chủ tịch Hồ Chí Minh cho biết trước nội dung bản thảo."},{"t":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. — Hồ Chí Minh dẫn Tuyên ngôn Độc lập năm 1776 của nước Mỹ, trong Tuyên ngôn Độc lập, 2/9/1945"},{"t":"Bản cáo trạng hơn tám mươi năm. Sau phần lý lẽ là bản cáo trạng. Câu chuyển ý rất ngắn: “Thế mà hơn 80 năm nay, bọn thực dân Pháp lợi dụng lá cờ tự do, bình đẳng, bác ái, đến cướp đất nước ta, áp bức đồng bào ta”. Hai chữ “thế mà” đặt những lý tưởng cao đẹp vừa trích dẫn ngay cạnh hành động của kẻ tự nhận là người mang chúng đến. Về chính trị, bản Tuyên ngôn liệt kê từng tội bằng một loạt câu mở đầu với chữ “Chúng”. Chúng tuyệt đối không cho nhân dân ta một chút tự do dân chủ nào. Chúng lập ba chế độ khác nhau ở Trung, Nam, Bắc để ngăn cản dân tộc ta đoàn kết. Chúng lập ra nhà tù nhiều hơn trường học, tắm các cuộc khởi nghĩa của ta trong những bể máu. Chúng thi hành chính sách ngu dân, dùng thuốc phiện, rượu cồn để làm cho nòi giống ta suy nhược. Những câu ngắn, cùng một chủ ngữ, nối nhau như những nhát búa. Nhịp điệu ấy rất hợp với một văn bản được viết để đọc to trước đám đông."},{"t":"Chứng cứ có tên đất, có con số. Về kinh tế, cáo trạng cũng cụ thể như thế. Thực dân cướp không ruộng đất, hầm mỏ, nguyên liệu. Chúng giữ độc quyền in giấy bạc, xuất cảng và nhập cảng. Chúng đặt ra hàng trăm thứ thuế vô lý, làm cho dân cày và dân buôn trở nên bần cùng, không cho các nhà tư sản ta ngóc đầu lên. Rồi bản Tuyên ngôn chuyển sang những sự kiện mà người nghe năm 1945 còn nhớ như in. Mùa thu năm 1940, phát xít Nhật vào Đông Dương, thực dân Pháp quỳ gối đầu hàng, mở cửa nước ta rước Nhật, để dân ta chịu hai tầng xiềng xích. Cuối năm 1944 sang đầu năm 1945, từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào bị chết đói. Ngày 9/3/1945, Nhật tước khí giới quân Pháp; kẻ tự xưng “bảo hộ” hoặc bỏ chạy, hoặc đầu hàng. Văn bản kết luận: trong năm năm, chúng đã bán nước ta hai lần cho Nhật. Khi thua chạy, chúng còn giết nốt số đông tù chính trị ở Yên Bái và Cao Bằng. Mỗi chứng cứ đều có thời gian, địa danh, con số."},{"t":"Hai lần “Sự thật là”. Phần then chốt về pháp lý nằm ở hai câu cùng mở đầu bằng ba chữ “Sự thật là”. Câu thứ nhất khẳng định: từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Câu thứ hai: dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp. Hai câu ấy bác bỏ tận gốc cái cớ mà thực dân Pháp đang chuẩn bị viện ra để trở lại: rằng Đông Dương vẫn là thuộc địa của Pháp, chỉ tạm thời bị Nhật chiếm. Nếu Pháp đã hai lần bán nước ta cho Nhật, rồi bỏ chạy trước Nhật, thì họ không còn danh nghĩa nào để đòi lại. Tiếp theo là một câu chưa đầy mười chữ mà tóm cả một mùa thu: “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị”. Bản Tuyên ngôn khẳng định dân ta đã đánh đổ xiềng xích thực dân, đồng thời đánh đổ chế độ quân chủ mấy mươi thế kỷ để lập nên chế độ Dân chủ Cộng hòa. Văn kiện vì thế ghi nhận cùng lúc hai cuộc đổi thay: giành lại độc lập và thay đổi chính thể."},{"t":"Bạn có biết? Ngay trong bản cáo trạng, Tuyên ngôn vẫn ghi nhận thái độ khoan hồng của người Việt: sau cuộc biến động ngày 9/3/1945, Việt Minh đã giúp nhiều người Pháp chạy qua biên thùy, cứu nhiều người Pháp ra khỏi nhà giam Nhật và bảo vệ tính mạng, tài sản cho họ."},{"t":"Lời tuyên bố gửi thế giới. Từ các chứng cứ, bản Tuyên ngôn đi đến phần tuyên bố. Chính phủ lâm thời, đại biểu cho toàn dân Việt Nam, tuyên bố thoát ly hẳn quan hệ thực dân với Pháp, xóa bỏ hết những hiệp ước mà Pháp đã ký về nước Việt Nam, xóa bỏ mọi đặc quyền của Pháp trên đất nước này. Chế độ bảo hộ được xác lập bằng Hiệp ước Patenôtre năm 1884; hơn sáu mươi năm sau, chỉ bằng một câu, cả nền móng pháp lý ấy bị gạt bỏ. Văn kiện hướng tới các nước Đồng minh. Người nhắc rằng họ đã công nhận nguyên tắc dân tộc bình đẳng ở Hội nghị Tê-hê-răng cuối năm 1943 và Hội nghị Cựu Kim Sơn năm 1945, nơi Hiến chương Liên hợp quốc ra đời. Vì thế, họ “quyết không thể không công nhận quyền độc lập của dân Việt Nam”. Lối phủ định hai lần ấy biến lời đề nghị thành một đòi hỏi hợp lẽ. Câu kết của bản Tuyên ngôn là một lời thề (xem chuyên đề Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…”)."},{"t":"Từ lễ đài đến đời sống của một văn kiện. Chiều 2/9/1945, văn bản được Chủ tịch Hồ Chí Minh đọc trước hàng chục vạn đồng bào ở Quảng trường Ba Đình. Từ đó, nó bắt đầu cuộc đời thứ hai: cuộc đời của một văn kiện nhà nước. Tuyên ngôn được in lại, được phổ biến tới các địa phương, trở thành nền tảng cho mọi hoạt động của chính quyền mới trong quan hệ với quốc dân và với nước ngoài. Việc những tờ giấy của mùa thu năm 1945 còn đến hôm nay là điều không hề hiển nhiên. Chỉ hơn một năm sau, cuộc kháng chiến toàn quốc bùng nổ, Hà Nội chìm trong khói lửa, các cơ quan trung ương phải rời Thủ đô lên chiến khu. Giấy thời chiến lại thường mỏng, dễ giòn, dễ ố. Bởi vậy, mỗi văn bản của những ngày lập quốc còn giữ được đều là tư liệu vô giá, bằng chứng trực tiếp về sự ra đời của một nhà nước."},{"t":"Ngôi nhà của hồ sơ quốc gia. Trung tâm Lưu trữ quốc gia III thuộc Cục Văn thư và Lưu trữ nhà nước, Bộ Nội vụ. Trong hệ thống lưu trữ quốc gia, mỗi trung tâm giữ một mảng ký ức riêng. Trung tâm Lưu trữ quốc gia I ở Hà Nội lưu tài liệu thời phong kiến và thời Pháp thuộc, trong đó có châu bản triều Nguyễn. Trung tâm II ở Thành phố Hồ Chí Minh giữ tài liệu thời Pháp thuộc ở Nam Kỳ và của các chính quyền ở miền Nam trước năm 1975. Trung tâm IV ở Đà Lạt bảo quản mộc bản triều Nguyễn, di sản tư liệu được UNESCO ghi danh năm 2009. Trung tâm III đảm nhận phần ký ức của nhà nước Việt Nam từ năm 1945 trở đi: tài liệu của các cơ quan trung ương thời Việt Nam Dân chủ Cộng hòa và Cộng hòa xã hội chủ nghĩa Việt Nam. Bản Tuyên ngôn Độc lập vì thế thuộc về lớp tài liệu khởi đầu của cả kho tư liệu ấy, cùng với những sắc lệnh và văn bản đầu tiên của Chính phủ lâm thời."},{"t":"Đọc Tuyên ngôn hôm nay. Những tài liệu gốc như thế thường được giữ trong kho có kiểm soát nhiệt độ, độ ẩm, và chỉ đến với công chúng qua các đợt trưng bày hay bản sao. Văn bản Tuyên ngôn Độc lập đã được giới thiệu qua các hoạt động trưng bày tài liệu lưu trữ. Với người đọc hôm nay, toàn văn Tuyên ngôn được in trong tập 4 của bộ Hồ Chí Minh Toàn tập, xuất bản năm 2011. Ở Hà Nội, khách tham quan có thể nối ba điểm của cùng một câu chuyện: căn gác ở số 48 Hàng Ngang, nơi văn bản được viết; Quảng trường Ba Đình, nơi văn bản được đọc; và kho lưu trữ, nơi văn bản được gìn giữ. Khi đứng trước tấm ảnh này trong bảo tàng, hãy thử đọc lại bốn chữ “Hỡi đồng bào cả nước”. Đó là lời gọi của một văn kiện viết cho toàn dân, và đến hôm nay vẫn chưa thôi hướng về mỗi người đọc."},{"t":"Bạn có biết? Bản Tuyên ngôn Nhân quyền và Dân quyền được Quốc hội Pháp thông qua năm 1789, rồi được đặt ở phần mở đầu bản Hiến pháp năm 1791 của nước Pháp. Đó là cách giải thích thường được nêu cho mốc năm 1791 ghi trong Tuyên ngôn Độc lập của Việt Nam."}],"so_chu":1904},{"i":14,"tieu_de_bang":"Phố Hàng Ngang (rue des Cantonnais) đầu thế kỷ XX","tieu_de":"Hàng Ngang — \"rue des Cantonnais\": con phố buôn bán rồi sẽ giữ một bí mật lớn của dân tộc","sapo":"Tấm ảnh đen trắng chụp đầu thế kỷ XX chỉ cho thấy một con phố buôn bán bình thường của Hà Nội: mái ngói san sát, biển hiệu, người đi bộ và xe tay ngược xuôi. Không có gì trong khung hình báo trước rằng vài chục năm sau, trên gác hai của một ngôi nhà giữa dãy phố ấy, một văn kiện làm thay đổi vận mệnh dân tộc sẽ ra đời. Người Pháp khi ấy gọi con phố này là \"rue des Cantonnais\" — phố của người Quảng Đông. Để hiểu vì sao Hàng Ngang trở thành một địa chỉ lịch sử, hãy quay lại với con phố buôn bán bình dị trong tấm ảnh này.","bia":{"src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một khung hình của phố cổ","text":"Tấm ảnh được ghi chú vắn tắt là chụp \"đầu thế kỷ XX\", không rõ tác giả, hiện được lưu trong kho ảnh tự do dưới dạng tư liệu công cộng. Trong khung hình là một đoạn phố nhỏ đặc trưng của khu phố cổ Hà Nội: hai dãy nhà ống thấp tầng áp sát nhau, mái ngói cũ, mặt tiền là những cửa hiệu san sát với biển hiệu treo ngang hoặc dọc theo cột nhà. Lòng đường hẹp, chưa trải nhựa phẳng như đường phố hiện đại, đủ chỗ cho người đi bộ, quang gánh và xe tay qua lại. Không có ô tô, không có đèn tín hiệu; nhịp sống của phố nằm ở tiếng rao hàng, tiếng mặc cả và tiếng guốc gỗ trên nền đường.\n\nĐây là một trong hàng chục con phố nghề của khu \"36 phố phường\" — tên gọi dân gian chỉ khu buôn bán cổ của Hà Nội, nơi mỗi phố từng gắn với một nghề hoặc một mặt hàng: Hàng Bạc bán đồ kim hoàn, Hàng Thiếc bán đồ thiếc, Hàng Đào bán vải nhuộm. Hàng Ngang nằm giữa chuỗi phố ấy, ở một vị trí không hề ngẫu nhiên: nó nối liền Hàng Đào ở phía nam với Hàng Đường ở phía bắc, trên trục đường dẫn thẳng tới chợ Đồng Xuân. Nhìn tấm ảnh cũ này, ít ai hình dung được rằng vài chục năm sau, một trong những ngôi nhà nằm khuất trong dãy phố ấy sẽ trở thành nơi ra đời của một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại.","doc":1},{"loai":"doan","tieu_de":"Vì sao gọi là Hàng Ngang","text":"Tên phố Hàng Ngang, giống như phần lớn tên phố cổ Hà Nội, gắn với sinh hoạt buôn bán chứ không phải với một danh nhân hay sự kiện. Theo cách giải thích được nhiều tài liệu về phố cổ nêu ra, tên gọi này bắt nguồn từ những cánh cổng gỗ từng được dựng chắn ngang hai đầu phố, một tập quán từng phổ biến ở các phố phường Thăng Long xưa nhằm giữ an ninh cho khu buôn bán. Cứ tối đến, cổng phố đóng lại; sáng ra, cổng lại mở để người buôn bán tiếp tục công việc. Lối tổ chức không gian đô thị theo phường hội, mỗi phố một nghề, mỗi phố có cổng riêng, là đặc trưng của các đô thị buôn bán cổ, và Thăng Long — Hà Nội cũng không ngoại lệ.\n\nKhông giống Hàng Bạc hay Hàng Thiếc, tên phố Hàng Ngang không chỉ đích danh một mặt hàng, mà mô tả một đặc điểm không gian: những cánh cổng ngang. Theo thời gian, khi các cổng phố không còn được dựng nữa, cái tên vẫn ở lại, trở thành một dấu vết ngôn ngữ của một Hà Nội đã đổi thay diện mạo nhiều lần nhưng vẫn giữ nguyên tên gọi những con phố cũ. Ngày nay, đi hết chiều dài phố Hàng Ngang chỉ mất vài phút, nhưng cái tên ấy mang theo cả một thời tổ chức thị dân theo kiểu phường hội của Thăng Long thuở trước.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_14_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phố Hàng Ngang (rue des Cantonnais) đầu thế kỷ XX”, nhìn từ xa."},{"loai":"doan","tieu_de":"\"Rue des Cantonnais\" — tên gọi thời thuộc địa","text":"Tấm ảnh của bảng này còn cho thấy một lớp tên gọi khác: chính quyền thuộc địa Pháp gọi con phố này là \"rue des Cantonnais\" — phố của người Quảng Đông. Từ cuối thế kỷ XIX, khi người Pháp thiết lập bộ máy cai trị ở Hà Nội, họ tiến hành đặt tên Pháp song song với tên Việt cho hầu hết các phố trong khu phố cổ, phục vụ việc quản lý hành chính và bản đồ đô thị. Cái tên \"rue des Cantonnais\" phản ánh một thực tế xã hội: từ trước đó rất lâu, nhiều thương nhân gốc Hoa, trong đó có không ít người gốc Quảng Đông, đã tới lập nghiệp và buôn bán tại khu vực này, tạo thành những cộng đồng Hoa kiều có ảnh hưởng trong đời sống thương mại của Hà Nội.\n\nSong song với tên Pháp, người Hà Nội vẫn quen gọi con phố bằng tên Việt truyền thống: Hàng Ngang. Hai hệ tên gọi ấy tồn tại song song suốt thời thuộc địa, một bên dùng trong giấy tờ hành chính và bản đồ chính thức, một bên sống trong lời ăn tiếng nói hằng ngày của người dân. Sự phân đôi ấy, nhỏ như nó có vẻ, lại là một lát cắt thu nhỏ của cả xã hội Hà Nội nửa đầu thế kỷ XX: một đô thị vừa mang bộ mặt hành chính kiểu phương Tây, vừa giữ nguyên nhịp sống và ký ức bản địa bên dưới lớp vỏ ấy.","doc":3},{"loai":"doan","tieu_de":"Kiến trúc nhà ống và đời sống phố nghề","text":"Những ngôi nhà trong tấm ảnh mang dáng dấp điển hình của kiến trúc nhà ống phố cổ: mặt tiền hẹp, chiều sâu kéo dài về phía sau, đôi khi thông qua nhiều lớp sân trong trước khi tới ngõ sau. Cách bố trí ấy xuất phát từ tập quán tính thuế theo bề rộng mặt tiền thời phong kiến, khiến người dân xây nhà hẹp ngang nhưng sâu để tiết kiệm diện tích chịu thuế mà vẫn có đủ không gian sinh hoạt và kinh doanh. Tầng trệt thường dành cho cửa hiệu, bày bán hàng hóa ra sát mặt phố; tầng trên, nếu nhà có gác, là nơi ở của gia đình chủ hiệu.\n\nVào những năm đầu thế kỷ XX, nhiều nhà ống ở Hàng Ngang được xây hoặc cải tạo lại theo lối kiến trúc pha trộn: khung nhà truyền thống kết hợp mặt tiền mang chi tiết trang trí kiểu Pháp, cửa chớp gỗ, ban công sắt uốn. Trong dãy phố buôn bán tấp nập ấy, ngôi nhà mang số 48 cũng là một cửa hiệu như bao cửa hiệu khác: hiệu tơ lụa Phúc Lợi, chuyên bán tơ lụa và vải vóc, một trong những mặt hàng gắn liền với tên tuổi của cả khu phố Hàng Đào — Hàng Ngang từ nhiều đời trước.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_memorial_in_honour_of_ho_chi_minh_in_the_hanoi_o.jpg","chu_thich":"Số 48 Hàng Ngang hôm nay — cũng chính ngôi nhà từng xuất hiện trong dãy phố ở tấm ảnh xưa, nay là di tích lịch sử (ảnh chụp năm 2016).","credit":"Ảnh: shankar s. from Dubai, united arab emira · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Gia đình yêu nước giữa phố buôn","text":"Chủ hiệu Phúc Lợi là ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, một trong những gia đình tư sản dân tộc có tiếng ở Hà Nội trước Cách mạng tháng Tám. Giữa một con phố mà phần lớn các cửa hiệu chỉ chuyên tâm vào việc buôn bán, gia đình ông bà Trịnh Văn Bô là một trường hợp khác: từ trước năm 1945, họ đã có cảm tình sâu sắc và âm thầm ủng hộ Mặt trận Việt Minh, trong bối cảnh việc bộc lộ thái độ chính trị như vậy có thể mang lại rủi ro lớn dưới chế độ thuộc địa và sự kiểm soát của phát xít Nhật.\n\nChính niềm tin ấy khiến ngôi nhà của họ, giữa bao nhiêu cửa hiệu khác trên phố Hàng Ngang, được chọn làm nơi đón một vị khách đặc biệt khi cách mạng thành công. Chỉ ít lâu sau, khi chính quyền cách mạng còn non trẻ và ngân khố gần như trống rỗng, gia đình ông bà Trịnh Văn Bô còn là một trong những gia đình đóng góp tài sản lớn cho phong trào Tuần lễ Vàng, góp phần giải quyết khó khăn tài chính buổi đầu của nước Việt Nam Dân chủ Cộng hòa (xem chuyên đề Tuần lễ Vàng: cả nước góp vàng giữ độc lập). Một cửa hiệu tơ lụa bình dị trên phố buôn, nhờ vậy, đã hai lần góp mặt vào những trang sử lớn của dân tộc.","doc":5},{"loai":"anh","src":"textures/bang_w/G14_14_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phố Hàng Ngang (rue des Cantonnais) đầu thế kỷ XX”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ phố buôn đến địa chỉ lập quốc","text":"Ngày 25/8/1945, chỉ vài ngày sau khi rời chiến khu Việt Bắc về Hà Nội, Chủ tịch Hồ Chí Minh được bố trí đến ở tại căn gác trên cửa hiệu Phúc Lợi, số 48 Hàng Ngang. Giữa một con phố buôn bán đông đúc, không ai bên ngoài có thể ngờ rằng phía trên những tấm vải lụa bày bán là nơi ở và làm việc của người đứng đầu Chính phủ lâm thời. Cách chọn địa điểm như vậy vừa bảo đảm bí mật, vừa cho thấy sự tin cậy đặc biệt mà cách mạng dành cho những gia đình công thương yêu nước giữa lòng Hà Nội (xem chuyên đề Nhà số 48 Hàng Ngang).\n\nTrong những ngày cuối tháng 8/1945, trên chính căn gác ấy, Người soạn thảo bản Tuyên ngôn Độc lập, văn kiện sẽ được đọc trước quốc dân tại Quảng trường Ba Đình vào chiều 2/9 (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn). Từ thời điểm đó, phố Hàng Ngang, vốn chỉ được biết đến như một con phố buôn bán tơ lụa, chính thức bước vào lịch sử như một trong những địa chỉ khai sinh nước Việt Nam Dân chủ Cộng hòa, đứng cạnh Quảng trường Ba Đình trong ký ức chung của cả dân tộc về mùa thu năm ấy.","doc":6},{"loai":"anh","src":"textures/bang_w/G14_14_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phố Hàng Ngang (rue des Cantonnais) đầu thế kỷ XX”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Con phố hôm nay","text":"Hơn tám mươi năm đã trôi qua kể từ khi tấm ảnh này được chụp, nhưng Hàng Ngang hôm nay vẫn là một trong những con phố buôn bán sầm uất bậc nhất khu phố cổ Hà Nội. Nhà ống mái ngói phần nhiều đã được cải tạo, nhiều cửa hiệu đổi chủ, đổi mặt hàng qua nhiều thế hệ, nhưng nhịp sống thương mại của con phố thì gần như không đứt đoạn: nối tiếp Hàng Đào, Hàng Ngang vẫn là nơi người Hà Nội và du khách tìm đến mua sắm, đặc biệt vào các dịp lễ Tết khi phố cổ rực rỡ đèn hoa.\n\nGiữa dòng chảy buôn bán không ngừng ấy, ngôi nhà số 48 vẫn đứng đó, nay đã trở thành di tích lịch sử được gìn giữ, đón khách tham quan quanh năm (xem chuyên đề Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay). Đặt tấm ảnh phố xưa cạnh hình ảnh con phố ngày nay, người xem có thể nhận ra: khung cảnh đã đổi khác nhiều, nhưng vị trí của ngôi nhà lịch sử ấy, giữa lòng một con phố nghề của Thăng Long xưa, thì vẫn nguyên vẹn như một điểm neo giữa hai thời đại.","doc":7},{"loai":"ban_co_biet","text":"Theo cách giải thích được nhiều tài liệu về phố cổ Hà Nội nêu ra, tên gọi Hàng Ngang bắt nguồn từ những cánh cổng gỗ từng dựng chắn ngang hai đầu phố, đóng mở theo giờ để giữ an ninh cho khu buôn bán — một tập quán từng phổ biến ở nhiều phố phường Thăng Long xưa.","nguon_ten":"Ban Quản lý phố cổ Hà Nội","doc":8},{"loai":"ban_co_biet","text":"Trục phố Hàng Đào — Hàng Ngang — Hàng Đường dẫn thẳng tới chợ Đồng Xuân, ngôi chợ được người Pháp xây dựng năm 1889 và đến nay vẫn là chợ đầu mối lớn nhất khu phố cổ Hà Nội.","nguon_ten":"Ban Quản lý phố cổ Hà Nội","doc":9},{"loai":"ban_co_biet","text":"Sau ngày giải phóng Thủ đô 10/10/1954, hệ thống tên phố tiếng Pháp như \"rue des Cantonnais\" được thay thế hoàn toàn bằng tên Việt truyền thống; cái tên Hàng Ngang, vốn chưa từng mất đi trong lời ăn tiếng nói của người dân, trở lại là tên gọi chính thức duy nhất của con phố.","nguon_ten":"Ban Quản lý phố cổ Hà Nội; Lịch sử Hà Nội","doc":10}],"nguon":["Di tích 48 Hàng Ngang, Hà Nội","Ban Quản lý phố cổ Hà Nội","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật"],"doc":[{"t":"Hàng Ngang — \"rue des Cantonnais\": con phố buôn bán rồi sẽ giữ một bí mật lớn của dân tộc. Tấm ảnh đen trắng chụp đầu thế kỷ XX chỉ cho thấy một con phố buôn bán bình thường của Hà Nội: mái ngói san sát, biển hiệu, người đi bộ và xe tay ngược xuôi. Không có gì trong khung hình báo trước rằng vài chục năm sau, trên gác hai của một ngôi nhà giữa dãy phố ấy, một văn kiện làm thay đổi vận mệnh dân tộc sẽ ra đời. Người Pháp khi ấy gọi con phố này là \"rue des Cantonnais\" — phố của người Quảng Đông. Để hiểu vì sao Hàng Ngang trở thành một địa chỉ lịch sử, hãy quay lại với con phố buôn bán bình dị trong tấm ảnh này."},{"t":"Một khung hình của phố cổ. Tấm ảnh được ghi chú vắn tắt là chụp \"đầu thế kỷ XX\", không rõ tác giả, hiện được lưu trong kho ảnh tự do dưới dạng tư liệu công cộng. Trong khung hình là một đoạn phố nhỏ đặc trưng của khu phố cổ Hà Nội: hai dãy nhà ống thấp tầng áp sát nhau, mái ngói cũ, mặt tiền là những cửa hiệu san sát với biển hiệu treo ngang hoặc dọc theo cột nhà. Lòng đường hẹp, chưa trải nhựa phẳng như đường phố hiện đại, đủ chỗ cho người đi bộ, quang gánh và xe tay qua lại. Không có ô tô, không có đèn tín hiệu; nhịp sống của phố nằm ở tiếng rao hàng, tiếng mặc cả và tiếng guốc gỗ trên nền đường. Đây là một trong hàng chục con phố nghề của khu \"36 phố phường\" — tên gọi dân gian chỉ khu buôn bán cổ của Hà Nội, nơi mỗi phố từng gắn với một nghề hoặc một mặt hàng: Hàng Bạc bán đồ kim hoàn, Hàng Thiếc bán đồ thiếc, Hàng Đào bán vải nhuộm. Hàng Ngang nằm giữa chuỗi phố ấy, ở một vị trí không hề ngẫu nhiên: nó nối liền Hàng Đào ở phía nam với Hàng Đường ở phía bắc, trên trục đường dẫn thẳng tới chợ Đồng Xuân. Nhìn tấm ảnh cũ này, ít ai hình dung được rằng vài chục năm sau, một trong những ngôi nhà nằm khuất trong dãy phố ấy sẽ trở thành nơi ra đời của một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại."},{"t":"Vì sao gọi là Hàng Ngang. Tên phố Hàng Ngang, giống như phần lớn tên phố cổ Hà Nội, gắn với sinh hoạt buôn bán chứ không phải với một danh nhân hay sự kiện. Theo cách giải thích được nhiều tài liệu về phố cổ nêu ra, tên gọi này bắt nguồn từ những cánh cổng gỗ từng được dựng chắn ngang hai đầu phố, một tập quán từng phổ biến ở các phố phường Thăng Long xưa nhằm giữ an ninh cho khu buôn bán. Cứ tối đến, cổng phố đóng lại; sáng ra, cổng lại mở để người buôn bán tiếp tục công việc. Lối tổ chức không gian đô thị theo phường hội, mỗi phố một nghề, mỗi phố có cổng riêng, là đặc trưng của các đô thị buôn bán cổ, và Thăng Long — Hà Nội cũng không ngoại lệ. Không giống Hàng Bạc hay Hàng Thiếc, tên phố Hàng Ngang không chỉ đích danh một mặt hàng, mà mô tả một đặc điểm không gian: những cánh cổng ngang. Theo thời gian, khi các cổng phố không còn được dựng nữa, cái tên vẫn ở lại, trở thành một dấu vết ngôn ngữ của một Hà Nội đã đổi thay diện mạo nhiều lần nhưng vẫn giữ nguyên tên gọi những con phố cũ. Ngày nay, đi hết chiều dài phố Hàng Ngang chỉ mất vài phút, nhưng cái tên ấy mang theo cả một thời tổ chức thị dân theo kiểu phường hội của Thăng Long thuở trước."},{"t":"\"Rue des Cantonnais\" — tên gọi thời thuộc địa. Tấm ảnh của bảng này còn cho thấy một lớp tên gọi khác: chính quyền thuộc địa Pháp gọi con phố này là \"rue des Cantonnais\" — phố của người Quảng Đông. Từ cuối thế kỷ XIX, khi người Pháp thiết lập bộ máy cai trị ở Hà Nội, họ tiến hành đặt tên Pháp song song với tên Việt cho hầu hết các phố trong khu phố cổ, phục vụ việc quản lý hành chính và bản đồ đô thị. Cái tên \"rue des Cantonnais\" phản ánh một thực tế xã hội: từ trước đó rất lâu, nhiều thương nhân gốc Hoa, trong đó có không ít người gốc Quảng Đông, đã tới lập nghiệp và buôn bán tại khu vực này, tạo thành những cộng đồng Hoa kiều có ảnh hưởng trong đời sống thương mại của Hà Nội. Song song với tên Pháp, người Hà Nội vẫn quen gọi con phố bằng tên Việt truyền thống: Hàng Ngang. Hai hệ tên gọi ấy tồn tại song song suốt thời thuộc địa, một bên dùng trong giấy tờ hành chính và bản đồ chính thức, một bên sống trong lời ăn tiếng nói hằng ngày của người dân. Sự phân đôi ấy, nhỏ như nó có vẻ, lại là một lát cắt thu nhỏ của cả xã hội Hà Nội nửa đầu thế kỷ XX: một đô thị vừa mang bộ mặt hành chính kiểu phương Tây, vừa giữ nguyên nhịp sống và ký ức bản địa bên dưới lớp vỏ ấy."},{"t":"Kiến trúc nhà ống và đời sống phố nghề. Những ngôi nhà trong tấm ảnh mang dáng dấp điển hình của kiến trúc nhà ống phố cổ: mặt tiền hẹp, chiều sâu kéo dài về phía sau, đôi khi thông qua nhiều lớp sân trong trước khi tới ngõ sau. Cách bố trí ấy xuất phát từ tập quán tính thuế theo bề rộng mặt tiền thời phong kiến, khiến người dân xây nhà hẹp ngang nhưng sâu để tiết kiệm diện tích chịu thuế mà vẫn có đủ không gian sinh hoạt và kinh doanh. Tầng trệt thường dành cho cửa hiệu, bày bán hàng hóa ra sát mặt phố; tầng trên, nếu nhà có gác, là nơi ở của gia đình chủ hiệu. Vào những năm đầu thế kỷ XX, nhiều nhà ống ở Hàng Ngang được xây hoặc cải tạo lại theo lối kiến trúc pha trộn: khung nhà truyền thống kết hợp mặt tiền mang chi tiết trang trí kiểu Pháp, cửa chớp gỗ, ban công sắt uốn. Trong dãy phố buôn bán tấp nập ấy, ngôi nhà mang số 48 cũng là một cửa hiệu như bao cửa hiệu khác: hiệu tơ lụa Phúc Lợi, chuyên bán tơ lụa và vải vóc, một trong những mặt hàng gắn liền với tên tuổi của cả khu phố Hàng Đào — Hàng Ngang từ nhiều đời trước."},{"t":"Gia đình yêu nước giữa phố buôn. Chủ hiệu Phúc Lợi là ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, một trong những gia đình tư sản dân tộc có tiếng ở Hà Nội trước Cách mạng tháng Tám. Giữa một con phố mà phần lớn các cửa hiệu chỉ chuyên tâm vào việc buôn bán, gia đình ông bà Trịnh Văn Bô là một trường hợp khác: từ trước năm 1945, họ đã có cảm tình sâu sắc và âm thầm ủng hộ Mặt trận Việt Minh, trong bối cảnh việc bộc lộ thái độ chính trị như vậy có thể mang lại rủi ro lớn dưới chế độ thuộc địa và sự kiểm soát của phát xít Nhật. Chính niềm tin ấy khiến ngôi nhà của họ, giữa bao nhiêu cửa hiệu khác trên phố Hàng Ngang, được chọn làm nơi đón một vị khách đặc biệt khi cách mạng thành công. Chỉ ít lâu sau, khi chính quyền cách mạng còn non trẻ và ngân khố gần như trống rỗng, gia đình ông bà Trịnh Văn Bô còn là một trong những gia đình đóng góp tài sản lớn cho phong trào Tuần lễ Vàng, góp phần giải quyết khó khăn tài chính buổi đầu của nước Việt Nam Dân chủ Cộng hòa (xem chuyên đề Tuần lễ Vàng: cả nước góp vàng giữ độc lập). Một cửa hiệu tơ lụa bình dị trên phố buôn, nhờ vậy, đã hai lần góp mặt vào những trang sử lớn của dân tộc."},{"t":"Từ phố buôn đến địa chỉ lập quốc. Ngày 25/8/1945, chỉ vài ngày sau khi rời chiến khu Việt Bắc về Hà Nội, Chủ tịch Hồ Chí Minh được bố trí đến ở tại căn gác trên cửa hiệu Phúc Lợi, số 48 Hàng Ngang. Giữa một con phố buôn bán đông đúc, không ai bên ngoài có thể ngờ rằng phía trên những tấm vải lụa bày bán là nơi ở và làm việc của người đứng đầu Chính phủ lâm thời. Cách chọn địa điểm như vậy vừa bảo đảm bí mật, vừa cho thấy sự tin cậy đặc biệt mà cách mạng dành cho những gia đình công thương yêu nước giữa lòng Hà Nội (xem chuyên đề Nhà số 48 Hàng Ngang). Trong những ngày cuối tháng 8/1945, trên chính căn gác ấy, Người soạn thảo bản Tuyên ngôn Độc lập, văn kiện sẽ được đọc trước quốc dân tại Quảng trường Ba Đình vào chiều 2/9 (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn). Từ thời điểm đó, phố Hàng Ngang, vốn chỉ được biết đến như một con phố buôn bán tơ lụa, chính thức bước vào lịch sử như một trong những địa chỉ khai sinh nước Việt Nam Dân chủ Cộng hòa, đứng cạnh Quảng trường Ba Đình trong ký ức chung của cả dân tộc về mùa thu năm ấy."},{"t":"Con phố hôm nay. Hơn tám mươi năm đã trôi qua kể từ khi tấm ảnh này được chụp, nhưng Hàng Ngang hôm nay vẫn là một trong những con phố buôn bán sầm uất bậc nhất khu phố cổ Hà Nội. Nhà ống mái ngói phần nhiều đã được cải tạo, nhiều cửa hiệu đổi chủ, đổi mặt hàng qua nhiều thế hệ, nhưng nhịp sống thương mại của con phố thì gần như không đứt đoạn: nối tiếp Hàng Đào, Hàng Ngang vẫn là nơi người Hà Nội và du khách tìm đến mua sắm, đặc biệt vào các dịp lễ Tết khi phố cổ rực rỡ đèn hoa. Giữa dòng chảy buôn bán không ngừng ấy, ngôi nhà số 48 vẫn đứng đó, nay đã trở thành di tích lịch sử được gìn giữ, đón khách tham quan quanh năm (xem chuyên đề Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay). Đặt tấm ảnh phố xưa cạnh hình ảnh con phố ngày nay, người xem có thể nhận ra: khung cảnh đã đổi khác nhiều, nhưng vị trí của ngôi nhà lịch sử ấy, giữa lòng một con phố nghề của Thăng Long xưa, thì vẫn nguyên vẹn như một điểm neo giữa hai thời đại."},{"t":"Bạn có biết? Theo cách giải thích được nhiều tài liệu về phố cổ Hà Nội nêu ra, tên gọi Hàng Ngang bắt nguồn từ những cánh cổng gỗ từng dựng chắn ngang hai đầu phố, đóng mở theo giờ để giữ an ninh cho khu buôn bán — một tập quán từng phổ biến ở nhiều phố phường Thăng Long xưa."},{"t":"Bạn có biết? Trục phố Hàng Đào — Hàng Ngang — Hàng Đường dẫn thẳng tới chợ Đồng Xuân, ngôi chợ được người Pháp xây dựng năm 1889 và đến nay vẫn là chợ đầu mối lớn nhất khu phố cổ Hà Nội."},{"t":"Bạn có biết? Sau ngày giải phóng Thủ đô 10/10/1954, hệ thống tên phố tiếng Pháp như \"rue des Cantonnais\" được thay thế hoàn toàn bằng tên Việt truyền thống; cái tên Hàng Ngang, vốn chưa từng mất đi trong lời ăn tiếng nói của người dân, trở lại là tên gọi chính thức duy nhất của con phố."}],"so_chu":1950},{"i":15,"tieu_de_bang":"Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay","tieu_de":"Số 48 Hàng Ngang hôm nay: bước qua một ngưỡng cửa, lùi lại tám mươi năm","sapo":"Giữa dãy phố Hàng Ngang tấp nập người mua kẻ bán, có một cánh cửa mà bước qua, thời gian như quay ngược lại tám mươi năm. Tấm ảnh chụp năm 2016 ghi lại khoảnh khắc rất đời thường ấy: một di tích lịch sử nép mình giữa những cửa hàng, không cờ hoa rực rỡ, không hàng rào ngăn cách. Ngôi nhà số 48 hôm nay đón khách tham quan quanh năm, nhưng mỗi dịp Quốc khánh, con phố buôn bán này lại trở thành điểm hẹn của một ký ức chung.","bia":{"src":"textures/ht/ht_anh_memorial_in_honour_of_ho_chi_minh_in_the_hanoi_o.jpg","credit":"Ảnh: shankar s. from Dubai, united arab emira · CC BY 2.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một di tích không cần hàng rào","text":"Không giống nhiều di tích lịch sử được quy hoạch thành khuôn viên riêng với hàng rào, sân vườn và bãi đỗ xe, ngôi nhà số 48 Hàng Ngang nằm lọt thỏm giữa dãy phố buôn bán, mặt tiền chỉ rộng vài mét, sát ngay bên những cửa hàng bán vải, bán đồ chơi, bán bánh kẹo. Tấm biển di tích lịch sử gắn khiêm tốn bên cửa ra vào, nếu không để ý, người qua đường hoàn toàn có thể đi lướt qua mà không nhận ra. Chính sự khiêm nhường ấy lại là một phần câu chuyện: ngôi nhà này chưa từng được xây dựng để trở thành di tích, nó vốn chỉ là một cửa hiệu tơ lụa bình thường, và chỉ trở nên đặc biệt bởi những gì đã diễn ra bên trong vào cuối tháng 8 năm 1945.\n\nBước qua ngưỡng cửa hẹp ấy, khách tham quan rời khỏi nhịp sống ồn ã của phố xá để bước vào một không gian tĩnh lặng hơn hẳn. Sự tương phản giữa bên ngoài và bên trong, giữa tiếng rao hàng và sự im lặng của di tích, là điều mà hầu hết những người từng ghé thăm 48 Hàng Ngang đều nhắc tới như ấn tượng đầu tiên.","doc":1},{"loai":"doan","tieu_de":"Bước qua cửa hiệu, lên căn gác","text":"Theo bố cục nhà ống truyền thống, tầng trệt của ngôi nhà từng là nơi bày bán tơ lụa của hiệu Phúc Lợi, nay được sử dụng làm không gian đón tiếp và giới thiệu những thông tin đầu tiên về di tích cho khách tham quan. Từ đây, một cầu thang gỗ hẹp dẫn lên gác hai — nơi Chủ tịch Hồ Chí Minh đã ở và làm việc trong những ngày cuối tháng 8/1945, và cũng là nơi bản Tuyên ngôn Độc lập được soạn thảo (xem chuyên đề Nhà số 48 Hàng Ngang; Căn phòng soạn thảo Tuyên ngôn).\n\nKhông gian trên gác được giữ ở quy mô nguyên bản của một căn nhà phố cổ: trần thấp, cửa sổ nhỏ, ánh sáng tự nhiên hắt vào không nhiều. Chính sự chật hẹp, giản dị ấy lại gây ấn tượng mạnh với người xem hôm nay, vốn quen hình dung những quyết định lịch sử lớn phải được đưa ra trong những không gian trang trọng, bề thế. Ở đây, mọi chuyện diễn ra ngược lại: một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại đã được viết ra trong một căn phòng nhỏ, giữa một khu phố buôn bán bình dân.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","chu_thich":"Phố Hàng Ngang đầu thế kỷ XX — cùng con phố, cùng dãy nhà, khi ngôi nhà số 48 còn là cửa hiệu tơ lụa Phúc Lợi.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một góc phố không đổi, một ngôi nhà đổi vai trò","text":"Đặt tấm ảnh phố Hàng Ngang đầu thế kỷ XX cạnh di tích hôm nay, có thể nhận ra: dáng phố xưa với những dãy nhà ống mái ngói thấp tầng phần lớn đã nhường chỗ cho những ngôi nhà cao hơn, hiện đại hơn, nhưng khoảng cách giữa các con phố, trục đường Hàng Đào — Hàng Ngang — Hàng Đường thì gần như không đổi. Ngôi nhà số 48, qua tấm ảnh cũ, chỉ là một trong hàng chục mặt tiền cửa hiệu san sát, không có gì tách biệt nó khỏi những ngôi nhà xung quanh.\n\nĐiều làm nên sự khác biệt không nằm ở kiến trúc, mà ở vai trò: từ một cửa hiệu buôn bán như bao cửa hiệu khác trên phố, ngôi nhà này đã được lịch sử chọn làm nơi diễn ra một sự kiện đặc biệt, để rồi mang một vai trò hoàn toàn mới — không còn là nơi kinh doanh, mà là nơi lưu giữ ký ức. Hành trình từ \"cửa hiệu Phúc Lợi\" tới \"Di tích lịch sử 48 Hàng Ngang\" là hành trình của chính con phố này, thu nhỏ vào một địa chỉ duy nhất.","doc":3},{"loai":"doan","tieu_de":"Không gian được gìn giữ","text":"Ngày nay, di tích 48 Hàng Ngang trưng bày nhiều tư liệu, hình ảnh liên quan tới những ngày Chủ tịch Hồ Chí Minh ở và làm việc tại đây, cùng thông tin về gia đình chủ nhà, ông bà Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, những người đã dành ngôi nhà và sau này còn đóng góp nhiều tài sản cho cách mạng buổi đầu. Một số đồ vật, bàn ghế được bài trí để gợi lại không khí làm việc của những ngày lịch sử ấy, dù phần lớn hiện vật gốc đã không còn nguyên vẹn qua nhiều biến động của thời gian và chiến tranh.\n\nBan quản lý di tích cũng giới thiệu bối cảnh rộng hơn: vì sao gia đình họ Trịnh được cách mạng tin cậy, con phố Hàng Ngang khi đó ra sao, và mối liên hệ giữa căn gác nhỏ này với Quảng trường Ba Đình, nơi bản Tuyên ngôn được đọc lên chỉ ít ngày sau khi viết xong (xem chuyên đề Hai địa điểm). Với nhiều khách tham quan, đặc biệt là học sinh, sinh viên, đây là dịp hiếm hoi để hình dung cụ thể một sự kiện vốn chỉ được biết đến qua sách vở và những thước phim tư liệu ít ỏi.","doc":4},{"loai":"anh","src":"textures/bang_w/G14_15_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ngày thường và ngày lễ","text":"Vào những ngày thường, di tích 48 Hàng Ngang đón lượng khách tham quan không đông, chủ yếu là những người quan tâm đặc biệt tới lịch sử hoặc khách du lịch tìm hiểu sâu về Hà Nội, ghé qua giữa lịch trình khám phá phố cổ. Không khí trong nhà, vì vậy, thường tĩnh lặng, đủ để người xem có thời gian đứng lâu trước từng bức ảnh, từng dòng chú thích.\n\nNhưng vào dịp Quốc khánh 2/9 hằng năm, khung cảnh đổi khác hẳn. Nhiều đoàn khách, trong đó có không ít cựu chiến binh, giáo viên và học sinh, tìm về con phố này như một cách kỷ niệm ngày Tuyên ngôn Độc lập ra đời. Với họ, việc đứng trong căn phòng nơi văn kiện ấy được viết ra, đúng vào dịp cả nước hướng về ngày 2/9, mang một ý nghĩa khác hẳn so với một chuyến tham quan thông thường: đó là cách để nối mình với một khoảnh khắc cụ thể của lịch sử, thay vì chỉ đọc về nó.","doc":5},{"loai":"anh","src":"textures/bang_w/G14_15_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bảo tồn giữa một phố cổ đang đổi thay","text":"Giữ gìn một di tích nằm giữa khu phố cổ đang sầm uất kinh doanh không phải việc dễ dàng. Khu phố cổ Hà Nội, nơi có phố Hàng Ngang, đã được xếp hạng di tích lịch sử — văn hóa cấp quốc gia, đặt dưới các quy định bảo tồn nghiêm ngặt về kiến trúc, chiều cao công trình và việc cải tạo mặt tiền. Ngôi nhà số 48, vì vậy, vừa phải được gìn giữ như một di tích lưu niệm, vừa tồn tại giữa áp lực đổi mới không ngừng của một khu phố thương mại sầm uất bậc nhất Thủ đô.\n\nTheo tư liệu về di tích, về sau gia đình ông bà Trịnh Văn Bô đã dành ngôi nhà này để Nhà nước gìn giữ như một địa chỉ lưu niệm về Chủ tịch Hồ Chí Minh, thay vì tiếp tục sử dụng như một tài sản kinh doanh riêng. Quyết định ấy, nối tiếp tinh thần của Tuần lễ Vàng năm 1945, là một biểu hiện khác của cùng một tấm lòng: đặt lợi ích chung của đất nước lên trên tài sản riêng của gia đình.","doc":6},{"loai":"anh","src":"textures/bang_w/G14_15_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hàng Ngang hôm nay, nhìn từ trong di tích","text":"Đứng trong căn gác nhỏ ấy và nhìn qua khung cửa sổ xuống phố Hàng Ngang, khách tham quan hôm nay vẫn thấy một con phố buôn bán tấp nập không khác nhiều so với tám mươi năm trước: người mua kẻ bán, hàng hóa bày kín các cửa hiệu, xe cộ len lỏi qua những con ngõ hẹp. Điều khác biệt, có lẽ, là bây giờ dòng người ấy đã biết rằng phía trên một trong những cửa hiệu mình đi ngang qua, một bản Tuyên ngôn Độc lập đã ra đời.\n\nSự bình dị của khung cảnh ấy chính là điều khiến di tích 48 Hàng Ngang trở nên đặc biệt so với nhiều địa chỉ lịch sử khác. Nó không tách mình khỏi đời sống thường nhật bằng tường rào hay quảng trường, mà nằm ngay giữa lòng đời sống ấy, nhắc mỗi người đi qua rằng lịch sử lớn của một dân tộc đôi khi bắt đầu từ những nơi rất đỗi bình thường.","doc":7},{"loai":"ban_co_biet","text":"Trục phố Hàng Đào — Hàng Ngang từ lâu đã gắn với nghề buôn tơ lụa, vải vóc của người Hà Nội; hiệu Phúc Lợi tại số 48 Hàng Ngang cũng là một cửa hiệu tơ lụa trước khi trở thành nơi lưu niệm lịch sử.","nguon_ten":"Ban Quản lý phố cổ Hà Nội; Di tích 48 Hàng Ngang","doc":8},{"loai":"ban_co_biet","text":"Khu phố cổ Hà Nội, gồm 36 phố phường trong đó có Hàng Ngang, đã được xếp hạng Di tích lịch sử — văn hóa cấp quốc gia, đặt dưới sự quản lý bảo tồn riêng của thành phố.","nguon_ten":"Bộ Văn hóa, Thể thao và Du lịch; Ban Quản lý phố cổ Hà Nội","doc":9},{"loai":"ban_co_biet","text":"Ngoài 48 Hàng Ngang, một địa chỉ khác gắn liền với những ngày lập quốc năm 1945 là Bắc Bộ phủ bên hồ Hoàn Kiếm — nơi Chính phủ lâm thời họp phiên đầu tiên ngày 3/9/1945 (xem chuyên đề Hai địa điểm).","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":10}],"nguon":["Di tích 48 Hàng Ngang, Hà Nội","Ban Quản lý phố cổ Hà Nội","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Bộ Văn hóa, Thể thao và Du lịch"],"doc":[{"t":"Số 48 Hàng Ngang hôm nay: bước qua một ngưỡng cửa, lùi lại tám mươi năm. Giữa dãy phố Hàng Ngang tấp nập người mua kẻ bán, có một cánh cửa mà bước qua, thời gian như quay ngược lại tám mươi năm. Tấm ảnh chụp năm 2016 ghi lại khoảnh khắc rất đời thường ấy: một di tích lịch sử nép mình giữa những cửa hàng, không cờ hoa rực rỡ, không hàng rào ngăn cách. Ngôi nhà số 48 hôm nay đón khách tham quan quanh năm, nhưng mỗi dịp Quốc khánh, con phố buôn bán này lại trở thành điểm hẹn của một ký ức chung."},{"t":"Một di tích không cần hàng rào. Không giống nhiều di tích lịch sử được quy hoạch thành khuôn viên riêng với hàng rào, sân vườn và bãi đỗ xe, ngôi nhà số 48 Hàng Ngang nằm lọt thỏm giữa dãy phố buôn bán, mặt tiền chỉ rộng vài mét, sát ngay bên những cửa hàng bán vải, bán đồ chơi, bán bánh kẹo. Tấm biển di tích lịch sử gắn khiêm tốn bên cửa ra vào, nếu không để ý, người qua đường hoàn toàn có thể đi lướt qua mà không nhận ra. Chính sự khiêm nhường ấy lại là một phần câu chuyện: ngôi nhà này chưa từng được xây dựng để trở thành di tích, nó vốn chỉ là một cửa hiệu tơ lụa bình thường, và chỉ trở nên đặc biệt bởi những gì đã diễn ra bên trong vào cuối tháng 8 năm 1945. Bước qua ngưỡng cửa hẹp ấy, khách tham quan rời khỏi nhịp sống ồn ã của phố xá để bước vào một không gian tĩnh lặng hơn hẳn. Sự tương phản giữa bên ngoài và bên trong, giữa tiếng rao hàng và sự im lặng của di tích, là điều mà hầu hết những người từng ghé thăm 48 Hàng Ngang đều nhắc tới như ấn tượng đầu tiên."},{"t":"Bước qua cửa hiệu, lên căn gác. Theo bố cục nhà ống truyền thống, tầng trệt của ngôi nhà từng là nơi bày bán tơ lụa của hiệu Phúc Lợi, nay được sử dụng làm không gian đón tiếp và giới thiệu những thông tin đầu tiên về di tích cho khách tham quan. Từ đây, một cầu thang gỗ hẹp dẫn lên gác hai — nơi Chủ tịch Hồ Chí Minh đã ở và làm việc trong những ngày cuối tháng 8/1945, và cũng là nơi bản Tuyên ngôn Độc lập được soạn thảo (xem chuyên đề Nhà số 48 Hàng Ngang; Căn phòng soạn thảo Tuyên ngôn). Không gian trên gác được giữ ở quy mô nguyên bản của một căn nhà phố cổ: trần thấp, cửa sổ nhỏ, ánh sáng tự nhiên hắt vào không nhiều. Chính sự chật hẹp, giản dị ấy lại gây ấn tượng mạnh với người xem hôm nay, vốn quen hình dung những quyết định lịch sử lớn phải được đưa ra trong những không gian trang trọng, bề thế. Ở đây, mọi chuyện diễn ra ngược lại: một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại đã được viết ra trong một căn phòng nhỏ, giữa một khu phố buôn bán bình dân."},{"t":"Một góc phố không đổi, một ngôi nhà đổi vai trò. Đặt tấm ảnh phố Hàng Ngang đầu thế kỷ XX cạnh di tích hôm nay, có thể nhận ra: dáng phố xưa với những dãy nhà ống mái ngói thấp tầng phần lớn đã nhường chỗ cho những ngôi nhà cao hơn, hiện đại hơn, nhưng khoảng cách giữa các con phố, trục đường Hàng Đào — Hàng Ngang — Hàng Đường thì gần như không đổi. Ngôi nhà số 48, qua tấm ảnh cũ, chỉ là một trong hàng chục mặt tiền cửa hiệu san sát, không có gì tách biệt nó khỏi những ngôi nhà xung quanh. Điều làm nên sự khác biệt không nằm ở kiến trúc, mà ở vai trò: từ một cửa hiệu buôn bán như bao cửa hiệu khác trên phố, ngôi nhà này đã được lịch sử chọn làm nơi diễn ra một sự kiện đặc biệt, để rồi mang một vai trò hoàn toàn mới — không còn là nơi kinh doanh, mà là nơi lưu giữ ký ức. Hành trình từ \"cửa hiệu Phúc Lợi\" tới \"Di tích lịch sử 48 Hàng Ngang\" là hành trình của chính con phố này, thu nhỏ vào một địa chỉ duy nhất."},{"t":"Không gian được gìn giữ. Ngày nay, di tích 48 Hàng Ngang trưng bày nhiều tư liệu, hình ảnh liên quan tới những ngày Chủ tịch Hồ Chí Minh ở và làm việc tại đây, cùng thông tin về gia đình chủ nhà, ông bà Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, những người đã dành ngôi nhà và sau này còn đóng góp nhiều tài sản cho cách mạng buổi đầu. Một số đồ vật, bàn ghế được bài trí để gợi lại không khí làm việc của những ngày lịch sử ấy, dù phần lớn hiện vật gốc đã không còn nguyên vẹn qua nhiều biến động của thời gian và chiến tranh. Ban quản lý di tích cũng giới thiệu bối cảnh rộng hơn: vì sao gia đình họ Trịnh được cách mạng tin cậy, con phố Hàng Ngang khi đó ra sao, và mối liên hệ giữa căn gác nhỏ này với Quảng trường Ba Đình, nơi bản Tuyên ngôn được đọc lên chỉ ít ngày sau khi viết xong (xem chuyên đề Hai địa điểm). Với nhiều khách tham quan, đặc biệt là học sinh, sinh viên, đây là dịp hiếm hoi để hình dung cụ thể một sự kiện vốn chỉ được biết đến qua sách vở và những thước phim tư liệu ít ỏi."},{"t":"Ngày thường và ngày lễ. Vào những ngày thường, di tích 48 Hàng Ngang đón lượng khách tham quan không đông, chủ yếu là những người quan tâm đặc biệt tới lịch sử hoặc khách du lịch tìm hiểu sâu về Hà Nội, ghé qua giữa lịch trình khám phá phố cổ. Không khí trong nhà, vì vậy, thường tĩnh lặng, đủ để người xem có thời gian đứng lâu trước từng bức ảnh, từng dòng chú thích. Nhưng vào dịp Quốc khánh 2/9 hằng năm, khung cảnh đổi khác hẳn. Nhiều đoàn khách, trong đó có không ít cựu chiến binh, giáo viên và học sinh, tìm về con phố này như một cách kỷ niệm ngày Tuyên ngôn Độc lập ra đời. Với họ, việc đứng trong căn phòng nơi văn kiện ấy được viết ra, đúng vào dịp cả nước hướng về ngày 2/9, mang một ý nghĩa khác hẳn so với một chuyến tham quan thông thường: đó là cách để nối mình với một khoảnh khắc cụ thể của lịch sử, thay vì chỉ đọc về nó."},{"t":"Bảo tồn giữa một phố cổ đang đổi thay. Giữ gìn một di tích nằm giữa khu phố cổ đang sầm uất kinh doanh không phải việc dễ dàng. Khu phố cổ Hà Nội, nơi có phố Hàng Ngang, đã được xếp hạng di tích lịch sử — văn hóa cấp quốc gia, đặt dưới các quy định bảo tồn nghiêm ngặt về kiến trúc, chiều cao công trình và việc cải tạo mặt tiền. Ngôi nhà số 48, vì vậy, vừa phải được gìn giữ như một di tích lưu niệm, vừa tồn tại giữa áp lực đổi mới không ngừng của một khu phố thương mại sầm uất bậc nhất Thủ đô. Theo tư liệu về di tích, về sau gia đình ông bà Trịnh Văn Bô đã dành ngôi nhà này để Nhà nước gìn giữ như một địa chỉ lưu niệm về Chủ tịch Hồ Chí Minh, thay vì tiếp tục sử dụng như một tài sản kinh doanh riêng. Quyết định ấy, nối tiếp tinh thần của Tuần lễ Vàng năm 1945, là một biểu hiện khác của cùng một tấm lòng: đặt lợi ích chung của đất nước lên trên tài sản riêng của gia đình."},{"t":"Hàng Ngang hôm nay, nhìn từ trong di tích. Đứng trong căn gác nhỏ ấy và nhìn qua khung cửa sổ xuống phố Hàng Ngang, khách tham quan hôm nay vẫn thấy một con phố buôn bán tấp nập không khác nhiều so với tám mươi năm trước: người mua kẻ bán, hàng hóa bày kín các cửa hiệu, xe cộ len lỏi qua những con ngõ hẹp. Điều khác biệt, có lẽ, là bây giờ dòng người ấy đã biết rằng phía trên một trong những cửa hiệu mình đi ngang qua, một bản Tuyên ngôn Độc lập đã ra đời. Sự bình dị của khung cảnh ấy chính là điều khiến di tích 48 Hàng Ngang trở nên đặc biệt so với nhiều địa chỉ lịch sử khác. Nó không tách mình khỏi đời sống thường nhật bằng tường rào hay quảng trường, mà nằm ngay giữa lòng đời sống ấy, nhắc mỗi người đi qua rằng lịch sử lớn của một dân tộc đôi khi bắt đầu từ những nơi rất đỗi bình thường."},{"t":"Bạn có biết? Trục phố Hàng Đào — Hàng Ngang từ lâu đã gắn với nghề buôn tơ lụa, vải vóc của người Hà Nội; hiệu Phúc Lợi tại số 48 Hàng Ngang cũng là một cửa hiệu tơ lụa trước khi trở thành nơi lưu niệm lịch sử."},{"t":"Bạn có biết? Khu phố cổ Hà Nội, gồm 36 phố phường trong đó có Hàng Ngang, đã được xếp hạng Di tích lịch sử — văn hóa cấp quốc gia, đặt dưới sự quản lý bảo tồn riêng của thành phố."},{"t":"Bạn có biết? Ngoài 48 Hàng Ngang, một địa chỉ khác gắn liền với những ngày lập quốc năm 1945 là Bắc Bộ phủ bên hồ Hoàn Kiếm — nơi Chính phủ lâm thời họp phiên đầu tiên ngày 3/9/1945 (xem chuyên đề Hai địa điểm)."}],"so_chu":1599},{"i":16,"tieu_de_bang":"Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…”","tieu_de":"“Quyết đem tất cả tinh thần và lực lượng…”: lời thề của một dân tộc, được giữ trọn bằng máu","sapo":"Câu văn khép lại bản Tuyên ngôn Độc lập không phải một lời tự hào suông. Đó là một lời thề, được cả một dân tộc chuẩn bị phải giữ bằng chính tính mạng của mình chỉ ít lâu sau đó. Từ Quảng trường Ba Đình chiều 2/9/1945, lời thề ấy đã đi qua ba mươi năm chiến tranh, để trở thành một trong những câu nói được nhắc tới nhiều nhất trong lịch sử Việt Nam hiện đại.","bia":{"src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Câu kết của một bản cáo trạng","text":"Bản Tuyên ngôn Độc lập được dựng theo một mạch lập luận chặt chẽ: mở đầu bằng những nguyên lý về quyền con người và quyền dân tộc, tiếp đến là bản cáo trạng tội ác thực dân kéo dài hơn tám mươi năm, rồi tới lời tuyên bố thoát ly quan hệ với Pháp và khai sinh nước Việt Nam Dân chủ Cộng hòa. Nhưng bản Tuyên ngôn không dừng lại ở lời tuyên bố. Câu văn khép lại toàn bộ văn kiện gồm hai vế nối liền nhau: một vế khẳng định thực tế, một vế là lời cam kết. Vế đầu nêu rõ nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập — không phải một khát vọng, mà là một thực tế đã hoàn thành ngay tại thời điểm bản Tuyên ngôn được đọc lên.\n\nVế thứ hai mới là điều khiến câu văn này trở thành một lời thề chứ không chỉ là một tuyên bố: toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy. Đây không phải lời hứa của riêng Chủ tịch Hồ Chí Minh, cũng không phải chỉ của Chính phủ lâm thời, mà được đặt vào miệng của “toàn thể dân tộc” — một sự ràng buộc mang tính tập thể, trong đó mỗi người dân, khi nghe hoặc đọc câu văn ấy, đều trở thành một bên cam kết.","doc":1},{"loai":"trich","text":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.","nguoi":"Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập, 2/9/1945 — Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật, 2011","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","chu_thich":"Quảng trường Ba Đình chiều 2/9/1945 — nơi hàng chục vạn đồng bào cùng nghe lời thề khép lại bản Tuyên ngôn Độc lập.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người đọc chậm, người nghe lặng","text":"Chiều 2/9/1945, câu văn khép lại bản Tuyên ngôn vang lên như đỉnh điểm của cả buổi lễ tại Quảng trường Ba Đình, sau khi Chủ tịch Hồ Chí Minh đã lần lượt đọc qua phần lý lẽ và bản cáo trạng tội ác thực dân (xem chuyên đề Lễ đài Ba Đình, 2/9/1945 về khung cảnh buổi lễ). Khác với những đoạn cáo trạng đanh thép trước đó, đến câu kết, giọng đọc của Người mang một sắc thái khác: chậm rãi và trang trọng hơn, như đang cùng đứng vào hàng ngũ của đám đông để cùng tuyên thệ, chứ không còn là người đọc văn kiện cho người khác nghe.\n\nKhi câu văn cuối cùng vang lên, lời thề ấy không chỉ được đọc ra mà còn được cả biển người phía dưới lễ đài đón nhận trong tư thế của người trong cuộc, chứ không phải người ngoài cuộc lắng nghe một lời tuyên bố. Với rất nhiều người có mặt hôm ấy, buổi lễ tại Ba Đình là lần đầu tiên trong đời họ được đứng giữa một quảng trường với tư cách công dân của một nước độc lập, thay vì thần dân của một xứ thuộc địa.","doc":3},{"loai":"doan","tieu_de":"Vì sao phải thề","text":"Lời thề trong Tuyên ngôn không phải một cách nói tu từ, mà phản ánh đúng thực tế nguy hiểm của thời điểm ấy. Ngay khi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn, quân đội Anh, với danh nghĩa đại diện phe Đồng minh vào giải giáp quân Nhật, đã chuẩn bị tiến vào miền Nam Việt Nam từ phía nam vĩ tuyến 16, và trên thực tế sẽ mở đường cho quân Pháp trở lại. Ở phía bắc, hàng chục vạn quân Trung Hoa Dân quốc, dưới danh nghĩa tương tự, kéo vào với nhiều toan tính riêng đối với chính quyền cách mạng non trẻ.\n\nChủ tịch Hồ Chí Minh, với kinh nghiệm hoạt động cách mạng và ngoại giao dày dạn, hiểu rõ các thế lực đế quốc chưa hề từ bỏ tham vọng đặt lại ách thống trị lên Việt Nam, chỉ là hình thức và thời điểm hành động của họ chưa lộ rõ. Đặt lời thề giữa văn kiện, ngay sau khi vừa tuyên bố độc lập, là cách Người báo trước với cả dân tộc và với thế giới: nền độc lập vừa giành được sẽ còn phải trải qua thử thách, và người Việt Nam đã sẵn sàng cho điều đó ngay từ giờ phút đầu tiên.","doc":4},{"loai":"anh","src":"textures/bang_w/G14_16_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…””, nhìn từ xa."},{"loai":"doan","tieu_de":"Lời thề bị thách thức","text":"Lời thề trong Tuyên ngôn không phải chờ lâu mới gặp thử thách đầu tiên. Chỉ ba tuần sau ngày 2/9, đêm 22 rạng 23/9/1945, quân Pháp núp bóng quân Anh đã nổ súng đánh chiếm các công sở tại Sài Gòn, mở đầu cuộc chiến tái xâm lược Nam Bộ. Đồng bào Nam Bộ, với vũ khí thô sơ trong tay, đã đứng lên kháng chiến ngay trong đêm ấy, trở thành những người đầu tiên thực hiện lời thề “quyết đem tất cả tinh thần và lực lượng” bằng hành động cụ thể, chỉ chưa đầy một tháng sau khi lời thề được đọc lên ở Ba Đình.\n\nỞ miền Bắc, để tránh phải đối đầu cùng lúc với nhiều kẻ thù, Chính phủ ta chọn sách lược hòa hoãn có nguyên tắc. Ngày 6/3/1946, Chủ tịch Hồ Chí Minh ký với đại diện Pháp là Jean Sainteny bản Hiệp định Sơ bộ, theo đó Pháp công nhận Việt Nam là một quốc gia tự do nằm trong Liên bang Đông Dương, còn Việt Nam chấp nhận cho quân Pháp ra miền Bắc thay chân quân Tưởng trong một thời hạn nhất định. Đó là một bước lùi chiến thuật để giữ vững sách lược lâu dài, chứ hoàn toàn không phải sự từ bỏ lời thề độc lập.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","chu_thich":"Toàn cảnh lễ đài tại Quảng trường Ba Đình ngày 2/9/1945, nơi lời thề giữ vững nền độc lập được đọc lên.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đêm 19 tháng Chạp năm 1946","text":"Hòa hoãn không kéo dài được lâu. Cuối năm 1946, sau khi chuyến đi Pháp đàm phán không mang lại kết quả như mong muốn, quan hệ Việt – Pháp ngày càng căng thẳng, các vụ khiêu khích quân sự của Pháp tại Hải Phòng, Lạng Sơn và Hà Nội liên tiếp xảy ra. Đêm 19/12/1946, tại làng Vạn Phúc, Hà Đông, Chủ tịch Hồ Chí Minh thay mặt Trung ương Đảng và Chính phủ ra Lời kêu gọi toàn quốc kháng chiến, chính thức mở đầu cuộc kháng chiến trường kỳ chống thực dân Pháp trên phạm vi cả nước.\n\nLời kêu gọi ấy vang lên đúng như tinh thần đã được đặt ra hơn một năm trước ở Ba Đình. Toàn dân tộc, không phân biệt già trẻ, gái trai, tôn giáo, đảng phái, được kêu gọi đứng lên chống thực dân Pháp để cứu Tổ quốc. Nếu lời thề trong Tuyên ngôn là một cam kết mang tính nguyên tắc, thì Lời kêu gọi toàn quốc kháng chiến chính là bản cụ thể hóa cam kết ấy thành hành động, biến “tinh thần và lực lượng” của cả dân tộc thành một cuộc kháng chiến kéo dài suốt chín năm sau đó.","doc":6},{"loai":"trich","text":"Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.","nguoi":"Hồ Chí Minh","nguon_ten":"Lời kêu gọi toàn quốc kháng chiến, 19/12/1946 — Hồ Chí Minh Toàn tập, tập 4","doc":7},{"loai":"anh","src":"textures/bang_w/G14_16_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…””, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"“Không có gì quý hơn độc lập, tự do”","text":"Hai mươi năm sau lời thề ở Ba Đình, khi cuộc kháng chiến chống Mỹ, cứu nước bước vào giai đoạn ác liệt, ngày 17/7/1966, Chủ tịch Hồ Chí Minh ra Lời kêu gọi đồng bào và chiến sĩ cả nước, trong đó Người đúc kết tinh thần của cả một dân tộc bằng một câu nói ngắn gọn đã trở thành chân lý: “Không có gì quý hơn độc lập, tự do”. Nếu lời thề năm 1945 còn được diễn đạt bằng một câu văn chính luận nhiều mệnh đề, thì đến năm 1966, cùng một tinh thần ấy đã được cô đọng lại chỉ còn bảy chữ, dễ nhớ, dễ thuộc, dễ truyền đi khắp các mặt trận.\n\nBa câu nói, cách nhau hơn hai mươi năm và trải qua hai cuộc chiến tranh, cùng phát ra từ một nguồn: lời thề tại Quảng trường Ba Đình chiều 2/9/1945, lời kêu gọi giữa đêm đông Hà Nội năm 1946, và chân lý được đúc kết năm 1966. Với nhiều thế hệ người Việt Nam, ba câu nói ấy không tách rời nhau, mà là ba chặng của cùng một lời thề được nhắc lại, mỗi lần một hoàn cảnh, nhưng chưa một lần bị lãng quên.","doc":8},{"loai":"doan","tieu_de":"Lời thề đã giữ trọn","text":"Lời thề trong Tuyên ngôn Độc lập cuối cùng đã được giữ trọn, nhưng cái giá phải trả là ba mươi năm chiến tranh liên tục, với biết bao thế hệ người Việt Nam đã ngã xuống đúng như lời cam kết: đem cả tính mạng và của cải để giữ vững quyền tự do, độc lập. Ngày 30/4/1975, khi đất nước hoàn toàn thống nhất, lời thề của mùa thu năm 1945 mới thực sự khép lại trọn vẹn, sau đúng ba mươi năm kể từ buổi chiều tại Quảng trường Ba Đình.\n\nHôm nay, khi đọc lại câu văn kết thúc bản Tuyên ngôn Độc lập, người ta không chỉ đọc một áng văn chính luận đẹp, mà còn đọc một lời cam kết đã được cả một dân tộc thực hiện bằng máu xương của mình qua nhiều thế hệ. Đó là lý do vì sao, giữa hàng vạn câu chữ về lịch sử cách mạng Việt Nam, câu nói “quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy” vẫn được nhắc lại, được khắc ghi, và được xem như một trong những lời thề thiêng liêng nhất của dân tộc.","doc":9},{"loai":"ban_co_biet","text":"Theo thỏa thuận của phe Đồng minh, việc giải giáp quân Nhật ở Đông Dương sau Thế chiến II được chia theo vĩ tuyến 16: quân Anh vào từ phía nam, còn quân Trung Hoa Dân quốc — do tướng Lư Hán chỉ huy — vào từ phía bắc; đây chính là hai đạo quân mà lời thề trong Tuyên ngôn đã ngầm nhắc tới.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":10},{"loai":"ban_co_biet","text":"Cùng ngày 2/9/1945 mà Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Hà Nội, trên chiến hạm Missouri ở vịnh Tokyo, đại diện Nhật Bản ký văn kiện đầu hàng Đồng minh, chính thức kết thúc Chiến tranh thế giới thứ hai.","nguon_ten":"Văn kiện đầu hàng của Nhật Bản, ký ngày 2/9/1945","doc":11},{"loai":"ban_co_biet","text":"Câu “Không có gì quý hơn độc lập, tự do” trong Lời kêu gọi ngày 17/7/1966 sau này trở thành một trong những câu nói tiêu biểu nhất của Chủ tịch Hồ Chí Minh, thường được trích lại trong các văn kiện và diễn văn dịp kỷ niệm Quốc khánh.","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật, 2011","doc":12}],"nguon":["Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật, 2011","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Lời kêu gọi toàn quốc kháng chiến, 19/12/1946","Lời kêu gọi ngày 17/7/1966 — Hồ Chí Minh Toàn tập"],"doc":[{"t":"“Quyết đem tất cả tinh thần và lực lượng…”: lời thề của một dân tộc, được giữ trọn bằng máu. Câu văn khép lại bản Tuyên ngôn Độc lập không phải một lời tự hào suông. Đó là một lời thề, được cả một dân tộc chuẩn bị phải giữ bằng chính tính mạng của mình chỉ ít lâu sau đó. Từ Quảng trường Ba Đình chiều 2/9/1945, lời thề ấy đã đi qua ba mươi năm chiến tranh, để trở thành một trong những câu nói được nhắc tới nhiều nhất trong lịch sử Việt Nam hiện đại."},{"t":"Câu kết của một bản cáo trạng. Bản Tuyên ngôn Độc lập được dựng theo một mạch lập luận chặt chẽ: mở đầu bằng những nguyên lý về quyền con người và quyền dân tộc, tiếp đến là bản cáo trạng tội ác thực dân kéo dài hơn tám mươi năm, rồi tới lời tuyên bố thoát ly quan hệ với Pháp và khai sinh nước Việt Nam Dân chủ Cộng hòa. Nhưng bản Tuyên ngôn không dừng lại ở lời tuyên bố. Câu văn khép lại toàn bộ văn kiện gồm hai vế nối liền nhau: một vế khẳng định thực tế, một vế là lời cam kết. Vế đầu nêu rõ nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập — không phải một khát vọng, mà là một thực tế đã hoàn thành ngay tại thời điểm bản Tuyên ngôn được đọc lên. Vế thứ hai mới là điều khiến câu văn này trở thành một lời thề chứ không chỉ là một tuyên bố: toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy. Đây không phải lời hứa của riêng Chủ tịch Hồ Chí Minh, cũng không phải chỉ của Chính phủ lâm thời, mà được đặt vào miệng của “toàn thể dân tộc” — một sự ràng buộc mang tính tập thể, trong đó mỗi người dân, khi nghe hoặc đọc câu văn ấy, đều trở thành một bên cam kết."},{"t":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy. — Hồ Chí Minh"},{"t":"Người đọc chậm, người nghe lặng. Chiều 2/9/1945, câu văn khép lại bản Tuyên ngôn vang lên như đỉnh điểm của cả buổi lễ tại Quảng trường Ba Đình, sau khi Chủ tịch Hồ Chí Minh đã lần lượt đọc qua phần lý lẽ và bản cáo trạng tội ác thực dân (xem chuyên đề Lễ đài Ba Đình, 2/9/1945 về khung cảnh buổi lễ). Khác với những đoạn cáo trạng đanh thép trước đó, đến câu kết, giọng đọc của Người mang một sắc thái khác: chậm rãi và trang trọng hơn, như đang cùng đứng vào hàng ngũ của đám đông để cùng tuyên thệ, chứ không còn là người đọc văn kiện cho người khác nghe. Khi câu văn cuối cùng vang lên, lời thề ấy không chỉ được đọc ra mà còn được cả biển người phía dưới lễ đài đón nhận trong tư thế của người trong cuộc, chứ không phải người ngoài cuộc lắng nghe một lời tuyên bố. Với rất nhiều người có mặt hôm ấy, buổi lễ tại Ba Đình là lần đầu tiên trong đời họ được đứng giữa một quảng trường với tư cách công dân của một nước độc lập, thay vì thần dân của một xứ thuộc địa."},{"t":"Vì sao phải thề. Lời thề trong Tuyên ngôn không phải một cách nói tu từ, mà phản ánh đúng thực tế nguy hiểm của thời điểm ấy. Ngay khi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn, quân đội Anh, với danh nghĩa đại diện phe Đồng minh vào giải giáp quân Nhật, đã chuẩn bị tiến vào miền Nam Việt Nam từ phía nam vĩ tuyến 16, và trên thực tế sẽ mở đường cho quân Pháp trở lại. Ở phía bắc, hàng chục vạn quân Trung Hoa Dân quốc, dưới danh nghĩa tương tự, kéo vào với nhiều toan tính riêng đối với chính quyền cách mạng non trẻ. Chủ tịch Hồ Chí Minh, với kinh nghiệm hoạt động cách mạng và ngoại giao dày dạn, hiểu rõ các thế lực đế quốc chưa hề từ bỏ tham vọng đặt lại ách thống trị lên Việt Nam, chỉ là hình thức và thời điểm hành động của họ chưa lộ rõ. Đặt lời thề giữa văn kiện, ngay sau khi vừa tuyên bố độc lập, là cách Người báo trước với cả dân tộc và với thế giới: nền độc lập vừa giành được sẽ còn phải trải qua thử thách, và người Việt Nam đã sẵn sàng cho điều đó ngay từ giờ phút đầu tiên."},{"t":"Lời thề bị thách thức. Lời thề trong Tuyên ngôn không phải chờ lâu mới gặp thử thách đầu tiên. Chỉ ba tuần sau ngày 2/9, đêm 22 rạng 23/9/1945, quân Pháp núp bóng quân Anh đã nổ súng đánh chiếm các công sở tại Sài Gòn, mở đầu cuộc chiến tái xâm lược Nam Bộ. Đồng bào Nam Bộ, với vũ khí thô sơ trong tay, đã đứng lên kháng chiến ngay trong đêm ấy, trở thành những người đầu tiên thực hiện lời thề “quyết đem tất cả tinh thần và lực lượng” bằng hành động cụ thể, chỉ chưa đầy một tháng sau khi lời thề được đọc lên ở Ba Đình. Ở miền Bắc, để tránh phải đối đầu cùng lúc với nhiều kẻ thù, Chính phủ ta chọn sách lược hòa hoãn có nguyên tắc. Ngày 6/3/1946, Chủ tịch Hồ Chí Minh ký với đại diện Pháp là Jean Sainteny bản Hiệp định Sơ bộ, theo đó Pháp công nhận Việt Nam là một quốc gia tự do nằm trong Liên bang Đông Dương, còn Việt Nam chấp nhận cho quân Pháp ra miền Bắc thay chân quân Tưởng trong một thời hạn nhất định. Đó là một bước lùi chiến thuật để giữ vững sách lược lâu dài, chứ hoàn toàn không phải sự từ bỏ lời thề độc lập."},{"t":"Đêm 19 tháng Chạp năm 1946. Hòa hoãn không kéo dài được lâu. Cuối năm 1946, sau khi chuyến đi Pháp đàm phán không mang lại kết quả như mong muốn, quan hệ Việt – Pháp ngày càng căng thẳng, các vụ khiêu khích quân sự của Pháp tại Hải Phòng, Lạng Sơn và Hà Nội liên tiếp xảy ra. Đêm 19/12/1946, tại làng Vạn Phúc, Hà Đông, Chủ tịch Hồ Chí Minh thay mặt Trung ương Đảng và Chính phủ ra Lời kêu gọi toàn quốc kháng chiến, chính thức mở đầu cuộc kháng chiến trường kỳ chống thực dân Pháp trên phạm vi cả nước. Lời kêu gọi ấy vang lên đúng như tinh thần đã được đặt ra hơn một năm trước ở Ba Đình. Toàn dân tộc, không phân biệt già trẻ, gái trai, tôn giáo, đảng phái, được kêu gọi đứng lên chống thực dân Pháp để cứu Tổ quốc. Nếu lời thề trong Tuyên ngôn là một cam kết mang tính nguyên tắc, thì Lời kêu gọi toàn quốc kháng chiến chính là bản cụ thể hóa cam kết ấy thành hành động, biến “tinh thần và lực lượng” của cả dân tộc thành một cuộc kháng chiến kéo dài suốt chín năm sau đó."},{"t":"Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ. — Hồ Chí Minh"},{"t":"“Không có gì quý hơn độc lập, tự do”. Hai mươi năm sau lời thề ở Ba Đình, khi cuộc kháng chiến chống Mỹ, cứu nước bước vào giai đoạn ác liệt, ngày 17/7/1966, Chủ tịch Hồ Chí Minh ra Lời kêu gọi đồng bào và chiến sĩ cả nước, trong đó Người đúc kết tinh thần của cả một dân tộc bằng một câu nói ngắn gọn đã trở thành chân lý: “Không có gì quý hơn độc lập, tự do”. Nếu lời thề năm 1945 còn được diễn đạt bằng một câu văn chính luận nhiều mệnh đề, thì đến năm 1966, cùng một tinh thần ấy đã được cô đọng lại chỉ còn bảy chữ, dễ nhớ, dễ thuộc, dễ truyền đi khắp các mặt trận. Ba câu nói, cách nhau hơn hai mươi năm và trải qua hai cuộc chiến tranh, cùng phát ra từ một nguồn: lời thề tại Quảng trường Ba Đình chiều 2/9/1945, lời kêu gọi giữa đêm đông Hà Nội năm 1946, và chân lý được đúc kết năm 1966. Với nhiều thế hệ người Việt Nam, ba câu nói ấy không tách rời nhau, mà là ba chặng của cùng một lời thề được nhắc lại, mỗi lần một hoàn cảnh, nhưng chưa một lần bị lãng quên."},{"t":"Lời thề đã giữ trọn. Lời thề trong Tuyên ngôn Độc lập cuối cùng đã được giữ trọn, nhưng cái giá phải trả là ba mươi năm chiến tranh liên tục, với biết bao thế hệ người Việt Nam đã ngã xuống đúng như lời cam kết: đem cả tính mạng và của cải để giữ vững quyền tự do, độc lập. Ngày 30/4/1975, khi đất nước hoàn toàn thống nhất, lời thề của mùa thu năm 1945 mới thực sự khép lại trọn vẹn, sau đúng ba mươi năm kể từ buổi chiều tại Quảng trường Ba Đình. Hôm nay, khi đọc lại câu văn kết thúc bản Tuyên ngôn Độc lập, người ta không chỉ đọc một áng văn chính luận đẹp, mà còn đọc một lời cam kết đã được cả một dân tộc thực hiện bằng máu xương của mình qua nhiều thế hệ. Đó là lý do vì sao, giữa hàng vạn câu chữ về lịch sử cách mạng Việt Nam, câu nói “quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy” vẫn được nhắc lại, được khắc ghi, và được xem như một trong những lời thề thiêng liêng nhất của dân tộc."},{"t":"Bạn có biết? Theo thỏa thuận của phe Đồng minh, việc giải giáp quân Nhật ở Đông Dương sau Thế chiến II được chia theo vĩ tuyến 16: quân Anh vào từ phía nam, còn quân Trung Hoa Dân quốc — do tướng Lư Hán chỉ huy — vào từ phía bắc; đây chính là hai đạo quân mà lời thề trong Tuyên ngôn đã ngầm nhắc tới."},{"t":"Bạn có biết? Cùng ngày 2/9/1945 mà Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Hà Nội, trên chiến hạm Missouri ở vịnh Tokyo, đại diện Nhật Bản ký văn kiện đầu hàng Đồng minh, chính thức kết thúc Chiến tranh thế giới thứ hai."},{"t":"Bạn có biết? Câu “Không có gì quý hơn độc lập, tự do” trong Lời kêu gọi ngày 17/7/1966 sau này trở thành một trong những câu nói tiêu biểu nhất của Chủ tịch Hồ Chí Minh, thường được trích lại trong các văn kiện và diễn văn dịp kỷ niệm Quốc khánh."}],"so_chu":1835},{"i":17,"tieu_de_bang":"Nhà số 48 Hàng Ngang","tieu_de":"Ngôi nhà hiệu lụa Phúc Lợi: vì sao 48 Hàng Ngang được chọn cho những ngày lập quốc","sapo":"Ngày 25 tháng 8 năm 1945, một vị khách đặc biệt lặng lẽ bước lên căn gác hai của một hiệu buôn tơ lụa giữa phố cổ Hà Nội. Chín ngày sau, từ chính căn gác ấy, người khách đó bước ra Quảng trường Ba Đình đọc bản Tuyên ngôn Độc lập trước hàng chục vạn đồng bào. Vì sao trong cả Hà Nội, một ngôi nhà buôn bán bình thường lại được chọn cho những ngày quyết định bậc nhất của một dân tộc?","bia":{"src":"textures/bai/G14_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một địa chỉ không ngẫu nhiên","text":"Nhà số 48 Hàng Ngang là một ngôi nhà nhiều tầng có đặc điểm hiếm gặp giữa khu phố cổ: ngôi nhà thông ra hai mặt phố — mặt trước là phố Hàng Ngang sầm uất, mặt sau ăn thông sang phố Hàng Cân — lại có cửa sắt chắc chắn, và từ tầng trên có thể bao quát được cả khu vực xung quanh. Với những người lo việc bảo vệ an toàn cho lãnh tụ giữa một Hà Nội vừa giành được chính quyền, còn ngổn ngang bao bất trắc từ nhiều phía, đây là một địa điểm gần như lý tưởng: vừa kín đáo giữa phố xá đông người qua lại, vừa có lối thoát khi cần, vừa đủ gần các cơ quan Trung ương để tiện việc liên lạc, hội họp. Chủ nhân ngôi nhà, gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, lại là một gia đình tư sản dân tộc đã âm thầm có cảm tình và ủng hộ Việt Minh từ trước ngày Tổng khởi nghĩa. An toàn về kiến trúc và tin cậy về con người — hai điều kiện hiếm khi cùng hội đủ ở một địa chỉ — đã gặp nhau đúng lúc lịch sử cần đến chúng.","doc":1},{"loai":"doan","tieu_de":"Hiệu lụa Phúc Lợi giữa phố buôn sầm uất","text":"Đầu thế kỷ 20, Hàng Ngang là một trong những phố buôn bán nhộn nhịp bậc nhất của khu 36 phố phường, đến mức người Pháp từng gọi đây là “rue des Cantonnais” — phố của người Quảng Đông — vì từng có đông thương nhân gốc Hoa cư ngụ, buôn bán tơ lụa, vải vóc (xem chuyên đề Phố Hàng Ngang). Giữa dãy phố ấy, hiệu Phúc Lợi của gia đình ông bà Trịnh Văn Bô là một trong những hiệu buôn tơ lụa có tiếng, đủ tiềm lực để có một cơ ngơi khang trang nhiều tầng — điều không dễ có giữa một khu phố mà phần lớn nhà chỉ hẹp mặt tiền, sâu hun hút vào trong. Nhưng ông bà Trịnh Văn Bô không chỉ là những thương gia thành đạt. Từ trước Cách mạng Tháng Tám, gia đình đã kín đáo ủng hộ tài chính cho phong trào Việt Minh, bất chấp rủi ro bị chính quyền thực dân phát hiện. Khi cách mạng thành công, chính sự tin cậy gây dựng âm thầm suốt nhiều năm ấy đã trở thành một trong những lý do để gia đình được đề nghị dành ngôi nhà cho vị lãnh tụ vừa từ chiến khu trở về.","doc":2},{"loai":"anh","src":"textures/bang_w/G14_17_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 48 Hàng Ngang”, nhìn từ xa."},{"loai":"doan","tieu_de":"Trạm dừng cuối trước khi vào nội thành","text":"Trước khi tới Hàng Ngang, hành trình của Chủ tịch Hồ Chí Minh từ chiến khu về Hà Nội không đi thẳng một mạch. Trước đó, chính tại Tân Trào, Quốc dân Đại hội đã họp trong hai ngày 16 và 17 tháng 8 năm 1945, cử ra Ủy ban Dân tộc giải phóng Việt Nam do Người đứng đầu — tiền thân của Chính phủ lâm thời sau này. Rời chiến khu Tân Trào ngày 22 tháng 8, Người dừng chân tại một ngôi nhà ở làng Phú Gia ven Hồ Tây, nay thuộc phường Phú Thượng, Hà Nội, từ ngày 23 đến 25 tháng 8 — vừa để bảo đảm an toàn, vừa để nắm thêm tình hình trước khi chính thức xuất hiện giữa nội thành. Mãi đến ngày 25 tháng 8, khi công việc chuẩn bị đã tương đối ổn thỏa, Người mới vào nội thành và được đưa tới nhà số 48 Hàng Ngang. Quãng dừng chân ở Phú Gia ít được nhắc tới hơn căn gác Hàng Ngang, nhưng cho thấy sự thận trọng cần thiết của những ngày đầu chính quyền cách mạng còn non trẻ, khi an toàn của lãnh tụ luôn phải được đặt lên hàng đầu. Từ khu rừng Tân Trào, qua ngôi nhà nhỏ ở Phú Gia, rồi tới căn gác phố Hàng Ngang — khoảng cách địa lý chỉ vài chục cây số, nhưng đó là cả một hành trình đưa cách mạng từ chiến khu về giữa lòng thủ đô.","doc":3},{"loai":"doan","tieu_de":"Chín ngày trên một căn gác","text":"Suốt chín ngày, từ 25 tháng 8 đến sáng 2 tháng 9, tầng hai nhà 48 Hàng Ngang trở thành nơi Chủ tịch Hồ Chí Minh vừa ở, vừa làm việc, vừa hội họp — một guồng quay gần như không có phút nghỉ. Đó là quãng thời gian bản lề: Ủy ban Dân tộc giải phóng phải nhanh chóng chuyển thành Chính phủ lâm thời, danh sách các bộ phải được cân nhắc kỹ để quy tụ được nhiều thành phần trong xã hội, một buổi lễ chưa từng có tiền lệ phải được chuẩn bị chu đáo, trong khi tin tức giành chính quyền từ khắp các tỉnh thành cả nước vẫn dồn dập gửi về mỗi ngày. Không có phòng làm việc tách bạch với phòng viết hay chỗ nghỉ ngơi — tất cả gói gọn trong một căn gác không lớn, nơi Người vừa tiếp khách, vừa nghe báo cáo, vừa dành ra những khoảng lặng hiếm hoi để suy nghĩ về văn kiện quan trọng bậc nhất sắp công bố trước quốc dân và thế giới.","doc":4},{"loai":"ban_co_biet","text":"Theo Ban Quản lý Di tích Danh thắng Hà Nội, ngôi nhà 48 Hàng Ngang thông ra hai mặt phố Hàng Ngang và Hàng Cân, lại có cửa sắt chắc chắn — những chi tiết kiến trúc khiến nơi đây được chọn trước hết vì lý do an toàn, chứ không chỉ vì tấm lòng của gia chủ.","nguon_ten":"Ban Quản lý Di tích Danh thắng Hà Nội","doc":5},{"loai":"doan","tieu_de":"Cuộc họp quyết định ngày 26 tháng Tám","text":"Ngày 26 tháng 8 năm 1945, ngay tại căn gác này, Chủ tịch Hồ Chí Minh chủ trì cuộc họp Ban Thường vụ Trung ương Đảng. Nội dung cuộc họp xoay quanh ba việc lớn: gấp rút chuyển Ủy ban Dân tộc giải phóng thành một Chính phủ lâm thời chính thức ra mắt quốc dân; mở rộng thành phần Chính phủ để quy tụ thêm nhân sĩ, trí thức ngoài Việt Minh, nhằm tạo khối đoàn kết rộng rãi cho nhà nước non trẻ; và ấn định việc tổ chức một buổi lễ trọng thể để tuyên bố nền độc lập trước toàn dân và trước thế giới. Đây là một trong những phiên họp đặt nền cho tất cả những gì diễn ra chỉ một tuần sau đó tại Quảng trường Ba Đình, trong đó có quyết định phải có một bản tuyên ngôn chính thức — công việc soạn thảo được giao ngay cho Người, ngay trong căn gác nơi cuộc họp vừa kết thúc (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn).","doc":6},{"loai":"anh","src":"textures/bang_w/G14_17_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 48 Hàng Ngang”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tấm lòng của một gia đình buôn bán","text":"Trong chín ngày ấy, gia đình ông bà Trịnh Văn Bô không chỉ nhường lại không gian sống quen thuộc của mình. Cả gia đình phải âm thầm lo liệu chuyện ăn ở, tiếp đón kín đáo cho một đoàn công tác đặc biệt, giữ bí mật tuyệt đối về sự có mặt của một nhân vật mà khi đó phần lớn người Hà Nội, kể cả nhiều người trong khu phố, còn chưa biết mặt. Đó là một hình thức đóng góp thầm lặng nhưng không kém phần quan trọng so với những đóng góp về sau: che chở, bảo đảm hậu cần, và trên hết là sự tin cậy tuyệt đối dành cho cách mạng giữa lúc cục diện chính trị còn nhiều bất trắc. Sự đón tiếp ấy trở thành biểu tượng cho tấm lòng của giới công thương Hà Nội đối với chính quyền cách mạng buổi đầu — không phải bằng lời nói, mà bằng việc mở cửa ngôi nhà, mở cả sự an toàn của chính gia đình mình.","doc":7},{"loai":"ban_co_biet","text":"Chỉ ít tuần sau khi tiễn Người rời căn gác, gia đình ông bà Trịnh Văn Bô tiếp tục đóng góp cho chính quyền cách mạng non trẻ trong phong trào Tuần lễ Vàng cuối năm 1945 (xem chuyên đề Tuần lễ Vàng).","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":8},{"loai":"doan","tieu_de":"Kiến trúc một ngôi nhà ống phố cổ","text":"Như phần lớn nhà trong khu 36 phố phường, nhà 48 Hàng Ngang mang dáng dấp kiểu nhà ống truyền thống: mặt tiền hẹp, chiều sâu lớn, các lớp nhà nối nhau qua những khoảng sân trong lấy ánh sáng và không khí, tầng dưới dùng làm cửa hiệu buôn bán, tầng trên là nơi ở và sinh hoạt của cả gia đình. Đó là kiểu kiến trúc thích ứng với lối sống “tiền buôn hậu cư” — trước là chỗ buôn bán, sau là nhà ở — đặc trưng của phố cổ Hà Nội suốt nhiều thế kỷ. Nhà 48 Hàng Ngang giữ đúng khuôn mẫu ấy, nhưng có một điểm hiếm gặp: ngôi nhà ăn thông sang tận phố Hàng Cân phía sau, tạo thành hai mặt tiền thay vì một. Chính đặc điểm kiến trúc tưởng như chỉ phục vụ việc buôn bán ấy, vào mùa thu năm 1945, lại trở thành một lợi thế an ninh không nhỏ cho những ngày lịch sử diễn ra bên trong.","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_memorial_in_honour_of_ho_chi_minh_in_the_hanoi_o.jpg","chu_thich":"Di tích 48 Hàng Ngang giữa phố cổ Hà Nội ngày nay (ảnh chụp năm 2016).","credit":"Ảnh: shankar s. from Dubai, united arab emira · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngôi nhà 48 Hàng Ngang ngày nay là một di tích lưu niệm về Chủ tịch Hồ Chí Minh giữa lòng phố cổ Hà Nội, do Ban Quản lý Di tích Danh thắng Hà Nội trực tiếp quản lý. Tài liệu, hiện vật liên quan đến những ngày Người ở và làm việc tại đây được trưng bày ngay tại tầng một, nơi trước kia là cửa hiệu tơ lụa Phúc Lợi. Khách tham quan có thể lên tầng hai, nơi không gian căn gác được giữ gìn để gợi lại chín ngày mùa thu năm 1945 (xem chuyên đề Di tích 48 Hàng Ngang hôm nay). Giữa nhịp sống sầm uất của một con phố vẫn còn buôn bán tấp nập, ngôi nhà nhỏ mang tấm biển di tích ấy là một điểm dừng lặng lẽ, nơi lịch sử và đời sống thường nhật cùng tồn tại trên một con phố.","doc":10},{"loai":"ban_co_biet","text":"Ngôi nhà được Bộ Văn hóa – Thông tin xếp hạng Di tích cấp Quốc gia theo Quyết định số 54/VH-TT/QĐ ngày 29 tháng 4 năm 1979, trở thành một trong những di tích được công nhận sớm về Chủ tịch Hồ Chí Minh tại Hà Nội.","nguon_ten":"Ban Quản lý Di tích Danh thắng Hà Nội","doc":11},{"loai":"anh","src":"textures/bang_w/G14_17_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 48 Hàng Ngang”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Trong không gian bảo tàng 3D","text":"Trong gian trưng bày “Hà Nội 1945 – Ba Đình” của Bảo tàng Hành trình 3D, hình ảnh ngôi nhà 48 Hàng Ngang được dựng lại như điểm khởi đầu của toàn bộ câu chuyện mùa thu Độc lập — nối liền với căn phòng soạn thảo Tuyên ngôn ở ngay bên trong (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn) và lễ đài giữa quảng trường cách đó không xa (xem chuyên đề Lễ đài Ba Đình, 2/9/1945). Những góc không gian ba chiều quanh bảng này được dựng để khách tham quan hình dung một góc phố cổ đông đúc năm 1945, nơi một quyết định làm thay đổi vận mệnh dân tộc đã được ấp ủ lặng lẽ sau cánh cửa sắt của một hiệu buôn bình dị giữa lòng Hà Nội.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Ban Quản lý Di tích Danh thắng Hà Nội – Di tích ngôi nhà 48 Hàng Ngang (banqldtdthanoi.vn)","Bảo tàng Hồ Chí Minh","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch"],"doc":[{"t":"Ngôi nhà hiệu lụa Phúc Lợi: vì sao 48 Hàng Ngang được chọn cho những ngày lập quốc. Ngày 25 tháng 8 năm 1945, một vị khách đặc biệt lặng lẽ bước lên căn gác hai của một hiệu buôn tơ lụa giữa phố cổ Hà Nội. Chín ngày sau, từ chính căn gác ấy, người khách đó bước ra Quảng trường Ba Đình đọc bản Tuyên ngôn Độc lập trước hàng chục vạn đồng bào. Vì sao trong cả Hà Nội, một ngôi nhà buôn bán bình thường lại được chọn cho những ngày quyết định bậc nhất của một dân tộc?"},{"t":"Một địa chỉ không ngẫu nhiên. Nhà số 48 Hàng Ngang là một ngôi nhà nhiều tầng có đặc điểm hiếm gặp giữa khu phố cổ: ngôi nhà thông ra hai mặt phố — mặt trước là phố Hàng Ngang sầm uất, mặt sau ăn thông sang phố Hàng Cân — lại có cửa sắt chắc chắn, và từ tầng trên có thể bao quát được cả khu vực xung quanh. Với những người lo việc bảo vệ an toàn cho lãnh tụ giữa một Hà Nội vừa giành được chính quyền, còn ngổn ngang bao bất trắc từ nhiều phía, đây là một địa điểm gần như lý tưởng: vừa kín đáo giữa phố xá đông người qua lại, vừa có lối thoát khi cần, vừa đủ gần các cơ quan Trung ương để tiện việc liên lạc, hội họp. Chủ nhân ngôi nhà, gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ, lại là một gia đình tư sản dân tộc đã âm thầm có cảm tình và ủng hộ Việt Minh từ trước ngày Tổng khởi nghĩa. An toàn về kiến trúc và tin cậy về con người — hai điều kiện hiếm khi cùng hội đủ ở một địa chỉ — đã gặp nhau đúng lúc lịch sử cần đến chúng."},{"t":"Hiệu lụa Phúc Lợi giữa phố buôn sầm uất. Đầu thế kỷ 20, Hàng Ngang là một trong những phố buôn bán nhộn nhịp bậc nhất của khu 36 phố phường, đến mức người Pháp từng gọi đây là “rue des Cantonnais” — phố của người Quảng Đông — vì từng có đông thương nhân gốc Hoa cư ngụ, buôn bán tơ lụa, vải vóc (xem chuyên đề Phố Hàng Ngang). Giữa dãy phố ấy, hiệu Phúc Lợi của gia đình ông bà Trịnh Văn Bô là một trong những hiệu buôn tơ lụa có tiếng, đủ tiềm lực để có một cơ ngơi khang trang nhiều tầng — điều không dễ có giữa một khu phố mà phần lớn nhà chỉ hẹp mặt tiền, sâu hun hút vào trong. Nhưng ông bà Trịnh Văn Bô không chỉ là những thương gia thành đạt. Từ trước Cách mạng Tháng Tám, gia đình đã kín đáo ủng hộ tài chính cho phong trào Việt Minh, bất chấp rủi ro bị chính quyền thực dân phát hiện. Khi cách mạng thành công, chính sự tin cậy gây dựng âm thầm suốt nhiều năm ấy đã trở thành một trong những lý do để gia đình được đề nghị dành ngôi nhà cho vị lãnh tụ vừa từ chiến khu trở về."},{"t":"Trạm dừng cuối trước khi vào nội thành. Trước khi tới Hàng Ngang, hành trình của Chủ tịch Hồ Chí Minh từ chiến khu về Hà Nội không đi thẳng một mạch. Trước đó, chính tại Tân Trào, Quốc dân Đại hội đã họp trong hai ngày 16 và 17 tháng 8 năm 1945, cử ra Ủy ban Dân tộc giải phóng Việt Nam do Người đứng đầu — tiền thân của Chính phủ lâm thời sau này. Rời chiến khu Tân Trào ngày 22 tháng 8, Người dừng chân tại một ngôi nhà ở làng Phú Gia ven Hồ Tây, nay thuộc phường Phú Thượng, Hà Nội, từ ngày 23 đến 25 tháng 8 — vừa để bảo đảm an toàn, vừa để nắm thêm tình hình trước khi chính thức xuất hiện giữa nội thành. Mãi đến ngày 25 tháng 8, khi công việc chuẩn bị đã tương đối ổn thỏa, Người mới vào nội thành và được đưa tới nhà số 48 Hàng Ngang. Quãng dừng chân ở Phú Gia ít được nhắc tới hơn căn gác Hàng Ngang, nhưng cho thấy sự thận trọng cần thiết của những ngày đầu chính quyền cách mạng còn non trẻ, khi an toàn của lãnh tụ luôn phải được đặt lên hàng đầu. Từ khu rừng Tân Trào, qua ngôi nhà nhỏ ở Phú Gia, rồi tới căn gác phố Hàng Ngang — khoảng cách địa lý chỉ vài chục cây số, nhưng đó là cả một hành trình đưa cách mạng từ chiến khu về giữa lòng thủ đô."},{"t":"Chín ngày trên một căn gác. Suốt chín ngày, từ 25 tháng 8 đến sáng 2 tháng 9, tầng hai nhà 48 Hàng Ngang trở thành nơi Chủ tịch Hồ Chí Minh vừa ở, vừa làm việc, vừa hội họp — một guồng quay gần như không có phút nghỉ. Đó là quãng thời gian bản lề: Ủy ban Dân tộc giải phóng phải nhanh chóng chuyển thành Chính phủ lâm thời, danh sách các bộ phải được cân nhắc kỹ để quy tụ được nhiều thành phần trong xã hội, một buổi lễ chưa từng có tiền lệ phải được chuẩn bị chu đáo, trong khi tin tức giành chính quyền từ khắp các tỉnh thành cả nước vẫn dồn dập gửi về mỗi ngày. Không có phòng làm việc tách bạch với phòng viết hay chỗ nghỉ ngơi — tất cả gói gọn trong một căn gác không lớn, nơi Người vừa tiếp khách, vừa nghe báo cáo, vừa dành ra những khoảng lặng hiếm hoi để suy nghĩ về văn kiện quan trọng bậc nhất sắp công bố trước quốc dân và thế giới."},{"t":"Bạn có biết? Theo Ban Quản lý Di tích Danh thắng Hà Nội, ngôi nhà 48 Hàng Ngang thông ra hai mặt phố Hàng Ngang và Hàng Cân, lại có cửa sắt chắc chắn — những chi tiết kiến trúc khiến nơi đây được chọn trước hết vì lý do an toàn, chứ không chỉ vì tấm lòng của gia chủ."},{"t":"Cuộc họp quyết định ngày 26 tháng Tám. Ngày 26 tháng 8 năm 1945, ngay tại căn gác này, Chủ tịch Hồ Chí Minh chủ trì cuộc họp Ban Thường vụ Trung ương Đảng. Nội dung cuộc họp xoay quanh ba việc lớn: gấp rút chuyển Ủy ban Dân tộc giải phóng thành một Chính phủ lâm thời chính thức ra mắt quốc dân; mở rộng thành phần Chính phủ để quy tụ thêm nhân sĩ, trí thức ngoài Việt Minh, nhằm tạo khối đoàn kết rộng rãi cho nhà nước non trẻ; và ấn định việc tổ chức một buổi lễ trọng thể để tuyên bố nền độc lập trước toàn dân và trước thế giới. Đây là một trong những phiên họp đặt nền cho tất cả những gì diễn ra chỉ một tuần sau đó tại Quảng trường Ba Đình, trong đó có quyết định phải có một bản tuyên ngôn chính thức — công việc soạn thảo được giao ngay cho Người, ngay trong căn gác nơi cuộc họp vừa kết thúc (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn)."},{"t":"Tấm lòng của một gia đình buôn bán. Trong chín ngày ấy, gia đình ông bà Trịnh Văn Bô không chỉ nhường lại không gian sống quen thuộc của mình. Cả gia đình phải âm thầm lo liệu chuyện ăn ở, tiếp đón kín đáo cho một đoàn công tác đặc biệt, giữ bí mật tuyệt đối về sự có mặt của một nhân vật mà khi đó phần lớn người Hà Nội, kể cả nhiều người trong khu phố, còn chưa biết mặt. Đó là một hình thức đóng góp thầm lặng nhưng không kém phần quan trọng so với những đóng góp về sau: che chở, bảo đảm hậu cần, và trên hết là sự tin cậy tuyệt đối dành cho cách mạng giữa lúc cục diện chính trị còn nhiều bất trắc. Sự đón tiếp ấy trở thành biểu tượng cho tấm lòng của giới công thương Hà Nội đối với chính quyền cách mạng buổi đầu — không phải bằng lời nói, mà bằng việc mở cửa ngôi nhà, mở cả sự an toàn của chính gia đình mình."},{"t":"Bạn có biết? Chỉ ít tuần sau khi tiễn Người rời căn gác, gia đình ông bà Trịnh Văn Bô tiếp tục đóng góp cho chính quyền cách mạng non trẻ trong phong trào Tuần lễ Vàng cuối năm 1945 (xem chuyên đề Tuần lễ Vàng)."},{"t":"Kiến trúc một ngôi nhà ống phố cổ. Như phần lớn nhà trong khu 36 phố phường, nhà 48 Hàng Ngang mang dáng dấp kiểu nhà ống truyền thống: mặt tiền hẹp, chiều sâu lớn, các lớp nhà nối nhau qua những khoảng sân trong lấy ánh sáng và không khí, tầng dưới dùng làm cửa hiệu buôn bán, tầng trên là nơi ở và sinh hoạt của cả gia đình. Đó là kiểu kiến trúc thích ứng với lối sống “tiền buôn hậu cư” — trước là chỗ buôn bán, sau là nhà ở — đặc trưng của phố cổ Hà Nội suốt nhiều thế kỷ. Nhà 48 Hàng Ngang giữ đúng khuôn mẫu ấy, nhưng có một điểm hiếm gặp: ngôi nhà ăn thông sang tận phố Hàng Cân phía sau, tạo thành hai mặt tiền thay vì một. Chính đặc điểm kiến trúc tưởng như chỉ phục vụ việc buôn bán ấy, vào mùa thu năm 1945, lại trở thành một lợi thế an ninh không nhỏ cho những ngày lịch sử diễn ra bên trong."},{"t":"Dấu tích hôm nay. Ngôi nhà 48 Hàng Ngang ngày nay là một di tích lưu niệm về Chủ tịch Hồ Chí Minh giữa lòng phố cổ Hà Nội, do Ban Quản lý Di tích Danh thắng Hà Nội trực tiếp quản lý. Tài liệu, hiện vật liên quan đến những ngày Người ở và làm việc tại đây được trưng bày ngay tại tầng một, nơi trước kia là cửa hiệu tơ lụa Phúc Lợi. Khách tham quan có thể lên tầng hai, nơi không gian căn gác được giữ gìn để gợi lại chín ngày mùa thu năm 1945 (xem chuyên đề Di tích 48 Hàng Ngang hôm nay). Giữa nhịp sống sầm uất của một con phố vẫn còn buôn bán tấp nập, ngôi nhà nhỏ mang tấm biển di tích ấy là một điểm dừng lặng lẽ, nơi lịch sử và đời sống thường nhật cùng tồn tại trên một con phố."},{"t":"Bạn có biết? Ngôi nhà được Bộ Văn hóa – Thông tin xếp hạng Di tích cấp Quốc gia theo Quyết định số 54/VH-TT/QĐ ngày 29 tháng 4 năm 1979, trở thành một trong những di tích được công nhận sớm về Chủ tịch Hồ Chí Minh tại Hà Nội."},{"t":"Trong không gian bảo tàng 3D. Trong gian trưng bày “Hà Nội 1945 – Ba Đình” của Bảo tàng Hành trình 3D, hình ảnh ngôi nhà 48 Hàng Ngang được dựng lại như điểm khởi đầu của toàn bộ câu chuyện mùa thu Độc lập — nối liền với căn phòng soạn thảo Tuyên ngôn ở ngay bên trong (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn) và lễ đài giữa quảng trường cách đó không xa (xem chuyên đề Lễ đài Ba Đình, 2/9/1945). Những góc không gian ba chiều quanh bảng này được dựng để khách tham quan hình dung một góc phố cổ đông đúc năm 1945, nơi một quyết định làm thay đổi vận mệnh dân tộc đã được ấp ủ lặng lẽ sau cánh cửa sắt của một hiệu buôn bình dị giữa lòng Hà Nội."}],"so_chu":1900},{"i":18,"tieu_de_bang":"Căn phòng soạn thảo Tuyên ngôn","tieu_de":"Căn phòng nhỏ trên gác hai: bản Tuyên ngôn Độc lập được viết ra như thế nào","sapo":"Chỉ một căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, bàn viết kê sát cửa sổ nhìn ra phố. Nhưng chính tại đây, trong những ngày cuối tháng Tám năm 1945, giữa bộn bề công việc của một chính quyền vừa ra đời, Chủ tịch Hồ Chí Minh đã đặt bút viết nên văn kiện lập quốc của nước Việt Nam Dân chủ Cộng hòa.","bia":{"src":"textures/bai/G14_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Giữa bộn bề của những ngày đầu","text":"Ngày 28 tháng 8 năm 1945, danh sách Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa được công bố trước quốc dân. Cùng ngày hôm ấy, tại căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, Chủ tịch Hồ Chí Minh bắt đầu ngồi vào bàn, viết những dòng đầu tiên của bản Tuyên ngôn Độc lập. Đó là một trong những ngày bận rộn nhất của chính quyền cách mạng còn non trẻ: lễ ra mắt quốc dân đang được gấp rút chuẩn bị, các bộ trong nội các mới phải nhanh chóng bắt tay vào việc, còn tin tức giành chính quyền từ khắp các địa phương trong cả nước vẫn không ngừng gửi về Hà Nội. Giữa nhịp làm việc khẩn trương ấy, Người vẫn dành ra khoảng thời gian quý giá để cân nhắc từng ý, từng câu cho văn kiện quan trọng bậc nhất của nhà nước mới ra đời — văn kiện sẽ được đọc trước hàng chục vạn đồng bào chỉ năm ngày sau đó.","doc":1},{"loai":"doan","tieu_de":"Ngoài khung cửa sổ, một Hà Nội đang đổi thay","text":"Trong khi Người cặm cụi bên trang viết, phía ngoài khung cửa sổ nhìn xuống phố Hàng Ngang là một Hà Nội đang chuyển động từng ngày. Cờ đỏ sao vàng xuất hiện ngày một nhiều trên các dãy phố, các Ủy ban nhân dân cách mạng lâm thời được thành lập ở nhiều khu vực để duy trì trật tự và tổ chức đời sống, các đoàn thể quần chúng — thanh niên, phụ nữ, công nhân — tấp nập chuẩn bị cho ngày lễ lớn sắp diễn ra tại Ba Đình. Cả thành phố, cũng như cả nước, đang trải qua những ngày bản lề giữa một chính quyền cũ vừa sụp đổ và một nhà nước mới còn chưa kịp định hình đầy đủ bộ máy. Chính trong bối cảnh ấy, việc có một văn kiện chính thức, mạch lạc và có sức thuyết phục để tuyên bố với quốc dân và thế giới về sự ra đời của nhà nước mới trở nên cấp thiết hơn bao giờ hết — và trách nhiệm ấy đặt trọn vẹn lên vai người đang ngồi viết trong căn phòng nhỏ trên gác hai.","doc":2},{"loai":"doan","tieu_de":"Viết tay, rồi đưa đánh máy","text":"Theo các tài liệu còn lưu lại, bản thảo Tuyên ngôn Độc lập được Người viết tay trước, sau đó mới đưa đánh máy để hoàn thiện. Cách làm việc ấy cho thấy sự thận trọng cần thiết với một văn kiện có tính chất pháp lý và lịch sử đặc biệt: từng câu chữ có thể được sửa đi sửa lại nhiều lần trên bản viết tay, trước khi được chuyển thành bản đánh máy chính thức. Theo hồi ức của những người từng có mặt bên Người trong những ngày ấy, trước khi công bố, bản thảo còn được đọc lại để một số đồng chí trong Thường vụ Trung ương góp ý, bổ sung. Không phải mọi chi tiết của quá trình ấy đều được ghi chép đầy đủ, nhưng điều chắc chắn là bản Tuyên ngôn Độc lập không phải một áng văn được viết trong một hơi, mà là kết quả của nhiều ngày cân nhắc, chỉnh sửa, giữa một trong những giai đoạn bận rộn nhất trong cuộc đời hoạt động cách mạng của Người.","doc":3},{"loai":"anh","src":"textures/bang_w/G14_18_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Căn phòng soạn thảo Tuyên ngôn”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một văn kiện hướng ra thế giới","text":"Ngay trong căn phòng nhỏ ấy, bản Tuyên ngôn Độc lập được viết ra không chỉ để tuyên bố với đồng bào trong nước, mà còn hướng đến dư luận quốc tế, đặc biệt là các nước Đồng minh vừa thắng trận trong Thế chiến thứ hai. Cách Người mở đầu văn kiện bằng những lời trích từ Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ và Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, cách tố cáo tội ác thực dân bằng những dẫn chứng cụ thể, cho thấy một tầm nhìn đối ngoại sâu sắc được cân nhắc kỹ ngay từ căn gác nhỏ này (xem chuyên đề Đọc kỹ bản Tuyên ngôn Độc lập). Đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại — đó là một lựa chọn có chủ đích, không phải ngẫu nhiên, được hình thành qua nhiều ngày suy nghĩ trong không gian chật hẹp của một căn phòng trên phố Hàng Ngang.","doc":4},{"loai":"trich","text":"Một dân tộc đã gan góc chống ách nô lệ của Pháp hơn 80 năm nay, một dân tộc đã gan góc đứng về phe Đồng minh chống phát xít mấy năm nay, dân tộc đó phải được tự do! Dân tộc đó phải được độc lập!","nguoi":"Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập, 2/9/1945 — Hồ Chí Minh Toàn tập, tập 4","doc":5},{"loai":"doan","tieu_de":"Không khí căn gác những ngày ấy","text":"Những người có dịp lui tới căn gác trong những ngày cuối tháng Tám kể lại một không khí vừa khẩn trương vừa giản dị. Ánh đèn bàn vẫn còn sáng tới khuya, giấy tờ, báo cáo từ các nơi gửi về được đặt cạnh bản thảo đang viết dở. Người làm việc không theo giờ giấc cố định, mà theo nhịp công việc: có lúc mải miết hàng giờ bên trang viết, có lúc phải dừng lại để tiếp một cán bộ vừa từ tỉnh xa lên báo cáo tình hình, rồi lại quay về với những dòng chữ dang dở. Căn phòng nhỏ vì thế không đơn thuần là nơi viết văn kiện, mà là một đầu mối làm việc thu nhỏ của cả bộ máy chính quyền cách mạng những ngày đầu tiên, nơi mọi việc lớn nhỏ của đất nước dường như đều phải đi qua trước khi được quyết định.","doc":6},{"loai":"ban_co_biet","text":"Trước khi tới căn gác này, Người đã dừng chân ba ngày, từ 23 đến 25 tháng 8 năm 1945, tại một ngôi nhà ở làng Phú Gia ven Hồ Tây, nay thuộc phường Phú Thượng, Hà Nội (xem chuyên đề Nhà số 48 Hàng Ngang).","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","chu_thich":"Trang bản thảo Tuyên ngôn Độc lập, hiện lưu giữ tại Trung tâm Lưu trữ quốc gia III.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Số phận của bản thảo","text":"Sau khi hoàn thành, bản thảo viết tay của Tuyên ngôn Độc lập không biến mất cùng những ngày mùa thu năm 1945. Trang viết ấy được gìn giữ qua nhiều biến động của lịch sử đất nước, và ngày nay là một trong những tài liệu quý giá nhất được bảo quản tại Trung tâm Lưu trữ quốc gia III (xem chuyên đề Bản Tuyên ngôn Độc lập). Từ một tập giấy viết vội trên chiếc bàn nhỏ giữa những ngày bận rộn, bản thảo đã trở thành một bảo vật của quốc gia, được nghiên cứu, sao chụp, trưng bày để nhiều thế hệ sau có thể tận mắt nhìn thấy nét chữ của Người trên chính văn kiện đã khai sinh ra một nhà nước. Ít ai, khi đứng trước bản sao trang trọng ấy trong viện lưu trữ hay trong bảo tàng, hình dung được rằng nó từng chỉ là những trang giấy viết tay trong một căn phòng chật hẹp, dưới áp lực của một tuần lễ gấp gáp nhất trong lịch sử hiện đại Việt Nam.","doc":8},{"loai":"ban_co_biet","text":"Ngày 28 tháng 8 năm 1945 — ngày danh sách Chính phủ lâm thời được công bố trước quốc dân — cũng chính là ngày Người bắt đầu ngồi vào bàn viết những dòng đầu tiên của bản Tuyên ngôn Độc lập.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử","doc":9},{"loai":"anh","src":"textures/bang_w/G14_18_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Căn phòng soạn thảo Tuyên ngôn”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Từ gác hai xuống tầng trệt","text":"Trong không gian trưng bày của Bảo tàng Hành trình 3D, căn phòng soạn thảo được dựng lại ở tầng trệt để khách tham quan dễ dàng tiếp cận, dù trên thực tế lịch sử, căn phòng nằm ở gác hai của ngôi nhà. Đó là một sự giản lược có chủ đích, đánh đổi giữa tính chính xác không gian và trải nghiệm của người xem. Các đồ vật đặt trong phòng — bàn viết, ghế tựa, đèn bàn, tủ sách, chiếc đồng hồ trên tường — đều là đồ phục dựng, nhằm gợi lại không khí làm việc của những ngày ấy, chứ không phải hiện vật gốc còn giữ được nguyên trạng. Điều căn phòng muốn kể với khách tham quan, vì thế, không nằm ở từng món đồ đạc cụ thể, mà ở tinh thần làm việc của Người trong những ngày tháng Tám: giản dị, khẩn trương, tập trung tuyệt đối, và luôn đặt lợi ích của dân tộc lên trên hết mọi mối bận tâm riêng.","doc":10},{"loai":"anh","src":"textures/bang_w/G14_18_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Căn phòng soạn thảo Tuyên ngôn”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Ý nghĩa của một căn phòng nhỏ","text":"Không có kiến trúc nguy nga, không có nghi thức trang trọng, căn phòng nơi bản Tuyên ngôn Độc lập ra đời chỉ là một góc nhỏ trên gác hai của một hiệu buôn tơ lụa. Nhưng chính sự giản dị ấy lại làm nổi bật điều cốt lõi: những văn kiện làm thay đổi vận mệnh một dân tộc không nhất thiết phải ra đời từ những cung điện hay phòng họp uy nghi, mà có thể được viết ra từ một chiếc bàn nhỏ, trong một căn phòng chật, giữa những ngày làm việc không ngơi nghỉ. Đó cũng là một phần lý do vì sao căn phòng nhỏ này, dù không còn giữ được một món đồ nguyên bản nào, vẫn xứng đáng có một vị trí riêng trong hành trình kể chuyện của bảo tàng — như một lời nhắc rằng lịch sử đôi khi được viết nên từ những không gian bình dị nhất.","doc":11}],"nguon":["Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Trung tâm Lưu trữ quốc gia III","Di tích 48 Hàng Ngang, Hà Nội"],"doc":[{"t":"Căn phòng nhỏ trên gác hai: bản Tuyên ngôn Độc lập được viết ra như thế nào. Chỉ một căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, bàn viết kê sát cửa sổ nhìn ra phố. Nhưng chính tại đây, trong những ngày cuối tháng Tám năm 1945, giữa bộn bề công việc của một chính quyền vừa ra đời, Chủ tịch Hồ Chí Minh đã đặt bút viết nên văn kiện lập quốc của nước Việt Nam Dân chủ Cộng hòa."},{"t":"Giữa bộn bề của những ngày đầu. Ngày 28 tháng 8 năm 1945, danh sách Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa được công bố trước quốc dân. Cùng ngày hôm ấy, tại căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, Chủ tịch Hồ Chí Minh bắt đầu ngồi vào bàn, viết những dòng đầu tiên của bản Tuyên ngôn Độc lập. Đó là một trong những ngày bận rộn nhất của chính quyền cách mạng còn non trẻ: lễ ra mắt quốc dân đang được gấp rút chuẩn bị, các bộ trong nội các mới phải nhanh chóng bắt tay vào việc, còn tin tức giành chính quyền từ khắp các địa phương trong cả nước vẫn không ngừng gửi về Hà Nội. Giữa nhịp làm việc khẩn trương ấy, Người vẫn dành ra khoảng thời gian quý giá để cân nhắc từng ý, từng câu cho văn kiện quan trọng bậc nhất của nhà nước mới ra đời — văn kiện sẽ được đọc trước hàng chục vạn đồng bào chỉ năm ngày sau đó."},{"t":"Ngoài khung cửa sổ, một Hà Nội đang đổi thay. Trong khi Người cặm cụi bên trang viết, phía ngoài khung cửa sổ nhìn xuống phố Hàng Ngang là một Hà Nội đang chuyển động từng ngày. Cờ đỏ sao vàng xuất hiện ngày một nhiều trên các dãy phố, các Ủy ban nhân dân cách mạng lâm thời được thành lập ở nhiều khu vực để duy trì trật tự và tổ chức đời sống, các đoàn thể quần chúng — thanh niên, phụ nữ, công nhân — tấp nập chuẩn bị cho ngày lễ lớn sắp diễn ra tại Ba Đình. Cả thành phố, cũng như cả nước, đang trải qua những ngày bản lề giữa một chính quyền cũ vừa sụp đổ và một nhà nước mới còn chưa kịp định hình đầy đủ bộ máy. Chính trong bối cảnh ấy, việc có một văn kiện chính thức, mạch lạc và có sức thuyết phục để tuyên bố với quốc dân và thế giới về sự ra đời của nhà nước mới trở nên cấp thiết hơn bao giờ hết — và trách nhiệm ấy đặt trọn vẹn lên vai người đang ngồi viết trong căn phòng nhỏ trên gác hai."},{"t":"Viết tay, rồi đưa đánh máy. Theo các tài liệu còn lưu lại, bản thảo Tuyên ngôn Độc lập được Người viết tay trước, sau đó mới đưa đánh máy để hoàn thiện. Cách làm việc ấy cho thấy sự thận trọng cần thiết với một văn kiện có tính chất pháp lý và lịch sử đặc biệt: từng câu chữ có thể được sửa đi sửa lại nhiều lần trên bản viết tay, trước khi được chuyển thành bản đánh máy chính thức. Theo hồi ức của những người từng có mặt bên Người trong những ngày ấy, trước khi công bố, bản thảo còn được đọc lại để một số đồng chí trong Thường vụ Trung ương góp ý, bổ sung. Không phải mọi chi tiết của quá trình ấy đều được ghi chép đầy đủ, nhưng điều chắc chắn là bản Tuyên ngôn Độc lập không phải một áng văn được viết trong một hơi, mà là kết quả của nhiều ngày cân nhắc, chỉnh sửa, giữa một trong những giai đoạn bận rộn nhất trong cuộc đời hoạt động cách mạng của Người."},{"t":"Một văn kiện hướng ra thế giới. Ngay trong căn phòng nhỏ ấy, bản Tuyên ngôn Độc lập được viết ra không chỉ để tuyên bố với đồng bào trong nước, mà còn hướng đến dư luận quốc tế, đặc biệt là các nước Đồng minh vừa thắng trận trong Thế chiến thứ hai. Cách Người mở đầu văn kiện bằng những lời trích từ Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ và Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, cách tố cáo tội ác thực dân bằng những dẫn chứng cụ thể, cho thấy một tầm nhìn đối ngoại sâu sắc được cân nhắc kỹ ngay từ căn gác nhỏ này (xem chuyên đề Đọc kỹ bản Tuyên ngôn Độc lập). Đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại — đó là một lựa chọn có chủ đích, không phải ngẫu nhiên, được hình thành qua nhiều ngày suy nghĩ trong không gian chật hẹp của một căn phòng trên phố Hàng Ngang."},{"t":"Một dân tộc đã gan góc chống ách nô lệ của Pháp hơn 80 năm nay, một dân tộc đã gan góc đứng về phe Đồng minh chống phát xít mấy năm nay, dân tộc đó phải được tự do! Dân tộc đó phải được độc lập! — Hồ Chí Minh"},{"t":"Không khí căn gác những ngày ấy. Những người có dịp lui tới căn gác trong những ngày cuối tháng Tám kể lại một không khí vừa khẩn trương vừa giản dị. Ánh đèn bàn vẫn còn sáng tới khuya, giấy tờ, báo cáo từ các nơi gửi về được đặt cạnh bản thảo đang viết dở. Người làm việc không theo giờ giấc cố định, mà theo nhịp công việc: có lúc mải miết hàng giờ bên trang viết, có lúc phải dừng lại để tiếp một cán bộ vừa từ tỉnh xa lên báo cáo tình hình, rồi lại quay về với những dòng chữ dang dở. Căn phòng nhỏ vì thế không đơn thuần là nơi viết văn kiện, mà là một đầu mối làm việc thu nhỏ của cả bộ máy chính quyền cách mạng những ngày đầu tiên, nơi mọi việc lớn nhỏ của đất nước dường như đều phải đi qua trước khi được quyết định."},{"t":"Bạn có biết? Trước khi tới căn gác này, Người đã dừng chân ba ngày, từ 23 đến 25 tháng 8 năm 1945, tại một ngôi nhà ở làng Phú Gia ven Hồ Tây, nay thuộc phường Phú Thượng, Hà Nội (xem chuyên đề Nhà số 48 Hàng Ngang)."},{"t":"Số phận của bản thảo. Sau khi hoàn thành, bản thảo viết tay của Tuyên ngôn Độc lập không biến mất cùng những ngày mùa thu năm 1945. Trang viết ấy được gìn giữ qua nhiều biến động của lịch sử đất nước, và ngày nay là một trong những tài liệu quý giá nhất được bảo quản tại Trung tâm Lưu trữ quốc gia III (xem chuyên đề Bản Tuyên ngôn Độc lập). Từ một tập giấy viết vội trên chiếc bàn nhỏ giữa những ngày bận rộn, bản thảo đã trở thành một bảo vật của quốc gia, được nghiên cứu, sao chụp, trưng bày để nhiều thế hệ sau có thể tận mắt nhìn thấy nét chữ của Người trên chính văn kiện đã khai sinh ra một nhà nước. Ít ai, khi đứng trước bản sao trang trọng ấy trong viện lưu trữ hay trong bảo tàng, hình dung được rằng nó từng chỉ là những trang giấy viết tay trong một căn phòng chật hẹp, dưới áp lực của một tuần lễ gấp gáp nhất trong lịch sử hiện đại Việt Nam."},{"t":"Bạn có biết? Ngày 28 tháng 8 năm 1945 — ngày danh sách Chính phủ lâm thời được công bố trước quốc dân — cũng chính là ngày Người bắt đầu ngồi vào bàn viết những dòng đầu tiên của bản Tuyên ngôn Độc lập."},{"t":"Từ gác hai xuống tầng trệt. Trong không gian trưng bày của Bảo tàng Hành trình 3D, căn phòng soạn thảo được dựng lại ở tầng trệt để khách tham quan dễ dàng tiếp cận, dù trên thực tế lịch sử, căn phòng nằm ở gác hai của ngôi nhà. Đó là một sự giản lược có chủ đích, đánh đổi giữa tính chính xác không gian và trải nghiệm của người xem. Các đồ vật đặt trong phòng — bàn viết, ghế tựa, đèn bàn, tủ sách, chiếc đồng hồ trên tường — đều là đồ phục dựng, nhằm gợi lại không khí làm việc của những ngày ấy, chứ không phải hiện vật gốc còn giữ được nguyên trạng. Điều căn phòng muốn kể với khách tham quan, vì thế, không nằm ở từng món đồ đạc cụ thể, mà ở tinh thần làm việc của Người trong những ngày tháng Tám: giản dị, khẩn trương, tập trung tuyệt đối, và luôn đặt lợi ích của dân tộc lên trên hết mọi mối bận tâm riêng."},{"t":"Ý nghĩa của một căn phòng nhỏ. Không có kiến trúc nguy nga, không có nghi thức trang trọng, căn phòng nơi bản Tuyên ngôn Độc lập ra đời chỉ là một góc nhỏ trên gác hai của một hiệu buôn tơ lụa. Nhưng chính sự giản dị ấy lại làm nổi bật điều cốt lõi: những văn kiện làm thay đổi vận mệnh một dân tộc không nhất thiết phải ra đời từ những cung điện hay phòng họp uy nghi, mà có thể được viết ra từ một chiếc bàn nhỏ, trong một căn phòng chật, giữa những ngày làm việc không ngơi nghỉ. Đó cũng là một phần lý do vì sao căn phòng nhỏ này, dù không còn giữ được một món đồ nguyên bản nào, vẫn xứng đáng có một vị trí riêng trong hành trình kể chuyện của bảo tàng — như một lời nhắc rằng lịch sử đôi khi được viết nên từ những không gian bình dị nhất."}],"so_chu":1603},{"i":19,"tieu_de_bang":"Lễ đài Ba Đình, 2/9/1945","tieu_de":"Lễ đài Độc lập: một công trình gỗ và vải dựng trong một ngày đêm","sapo":"Lễ đài nơi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập không phải một công trình kiên cố được chuẩn bị từ trước, mà là một kết cấu gỗ và vải, dựng gấp trong chưa đầy một ngày đêm. Vậy mà hình ảnh giản dị ấy đã trở thành một trong những biểu tượng được nhớ đến nhiều nhất của lịch sử Việt Nam hiện đại.","bia":{"src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Nhiệm vụ giao trong một ngày","text":"Ngày 1 tháng 9 năm 1945 — chỉ một ngày trước buổi lễ trọng đại — kiến trúc sư Ngô Huy Quỳnh được cấp trên giao nhiệm vụ thiết kế và chỉ đạo dựng lễ đài tại Quảng trường Ba Đình. Khi ấy ông mới 25 tuổi, quê ở làng Ngọc Lập, xã Phùng Chí Kiên, huyện Mỹ Hào, tỉnh Hưng Yên. Một kiến trúc sư trẻ, một khối lượng công việc lớn, và một quỹ thời gian gần như không tưởng: lễ đài phải đủ trang nghiêm cho giờ phút khai sinh một quốc gia, phải đủ cao và đủ nổi bật để hàng chục vạn người đứng từ xa vẫn nhìn thấy vị Chủ tịch, trong khi vật liệu và nhân lực giữa những ngày đầu cách mạng đều hết sức hạn chế. Không có bản vẽ nào được chuẩn bị từ trước cả tháng, không có thời gian để thử nghiệm phương án — mọi quyết định về hình dáng, vật liệu, cách dựng đều phải được đưa ra và thực hiện gần như cùng lúc.","doc":1},{"loai":"doan","tieu_de":"Bồn cỏ giữa vườn hoa Ba Đình","text":"Địa điểm được chọn để dựng lễ đài là bồn cỏ hình tròn nằm giữa vườn hoa Ba Đình — khi đó vẫn còn mang những dấu vết của một vườn hoa kiểu Pháp với các lối đi rợp bóng cây. Đây là một lựa chọn hợp lý: khoảng đất trống đủ rộng để làm trung tâm thị giác cho cả quảng trường, xung quanh lại có không gian mở để hàng chục vạn người có thể đứng vây quanh mà vẫn nhìn thấy lễ đài từ nhiều hướng. Trong bối cảnh gấp gáp, việc tận dụng một không gian công cộng có sẵn, không cần giải phóng hay cải tạo mặt bằng, là điều kiện tiên quyết để công trình có thể hoàn thành đúng hạn. Từ một bồn cỏ bình thường của một vườn hoa công cộng, nơi đây bất ngờ trở thành tâm điểm của một sự kiện làm thay đổi vận mệnh cả một dân tộc.","doc":2},{"loai":"doan","tieu_de":"Cờ, cột cờ và một bản nhạc mới","text":"Bên cạnh lễ đài, một cột cờ được dựng lên để lá cờ đỏ sao vàng — quốc kỳ của nhà nước vừa ra đời — tung bay trong suốt buổi lễ, trở thành điểm nhấn thị giác song song với khối kiến trúc bọc lụa của lễ đài. Trước khi Chủ tịch Hồ Chí Minh bước lên đọc Tuyên ngôn Độc lập, buổi lễ mở đầu bằng nghi thức chào cờ, với bài “Tiến quân ca” được cử hành như một bản quốc ca của nước Việt Nam Dân chủ Cộng hòa — một trong những lần đầu tiên bản nhạc ấy vang lên chính thức trước đông đảo quốc dân trong một nghi lễ nhà nước. Chỉ trong khuôn khổ chật hẹp của một buổi chiều, giữa một quảng trường vừa được chọn làm nơi tổ chức lễ và một lễ đài vừa dựng xong lúc rạng sáng, gần như mọi biểu tượng của một quốc gia độc lập — quốc kỳ, quốc ca, và bản tuyên ngôn lập quốc — cùng lúc xuất hiện lần đầu trước công chúng.","doc":3},{"loai":"anh","src":"textures/bang_w/G14_19_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lễ đài Ba Đình, 2/9/1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Đóng đinh, bọc lụa, chạy đua với bình minh","text":"Lễ đài được dựng bằng khung gỗ theo cách đóng đinh — phương pháp thi công nhanh, phù hợp với quỹ thời gian ít ỏi — rồi bọc lụa xung quanh để tạo vẻ trang trọng. Công trình được thiết kế với gam màu vàng nhạt chủ đạo, cùng một vòng tay ôm lấy phía sau lễ đài mang màu đỏ, hai bên đặt hai bình hương. Những chi tiết ấy tuy đơn giản nhưng được tính toán để tạo hiệu ứng thị giác trang nghiêm khi nhìn từ xa, giữa không gian rộng lớn của quảng trường. Toàn bộ công trình được hoàn thành chỉ trong một ngày đêm, xong trước rạng đông ngày 2 tháng 9 — nghĩa là đội thi công gần như phải làm việc suốt đêm mùng 1 rạng ngày 2 tháng 9 để kịp bàn giao cho buổi lễ diễn ra ngay buổi chiều hôm đó. Không có nhiều tư liệu ghi lại tên tuổi những người thợ trực tiếp dựng lễ đài đêm ấy, nhưng thành quả của họ đã trở thành một phần không thể tách rời của khoảnh khắc lịch sử.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập trên lễ đài giữa Quảng trường Ba Đình, chiều 2 tháng 9 năm 1945.","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Khoảnh khắc trên bục gỗ","text":"Chiều 2 tháng 9 năm 1945, trước hàng chục vạn đồng bào tề tựu tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh bước lên chính lễ đài vừa được dựng xong ấy, thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa buổi lễ, Người bất ngờ dừng lại, hỏi đồng bào một câu giản dị: “Tôi nói, đồng bào nghe rõ không?” (xem chuyên đề “Tôi nói, đồng bào nghe rõ không?”). Câu hỏi ấy không nằm trong bất kỳ bản thảo nào, nhưng lại vang lên đúng từ chiếc bục gỗ bọc lụa mà kiến trúc sư Ngô Huy Quỳnh và các cộng sự vừa hoàn thành trong đêm trước đó — biến một công trình tạm thời thành sân khấu của một trong những khoảnh khắc được ghi nhớ nhiều nhất trong lịch sử dân tộc.","doc":5},{"loai":"ban_co_biet","text":"Cùng ngày 2 tháng 9 năm 1945 mà Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở Hà Nội, trên chiến hạm Missouri tại vịnh Tokyo, đại diện Nhật Bản ký văn kiện đầu hàng Đồng minh, chính thức kết thúc Chiến tranh thế giới thứ hai.","nguon_ten":"Văn kiện đầu hàng của Nhật Bản, ký ngày 2/9/1945","doc":6},{"loai":"anh","src":"textures/bang_w/G14_19_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lễ đài Ba Đình, 2/9/1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một buổi lễ trọng đại giữa những ngày thiếu thốn","text":"Cần nhớ rằng lễ đài Ba Đình được dựng lên chỉ vài tuần sau khi chính quyền cách mạng còn phải lo đối phó với nạn đói, nạn dốt, ngân khố gần như trống rỗng. Vật liệu xây dựng, nhân lực có tay nghề, thời gian — tất cả đều là những nguồn lực khan hiếm. Việc dựng được một lễ đài đủ trang nghiêm chỉ trong một ngày đêm, bằng gỗ và vải thay vì đá và bê tông, cho thấy một cách ứng xử rất đặc trưng của những ngày đầu cách mạng: không đợi có đầy đủ điều kiện lý tưởng mới hành động, mà tận dụng tối đa những gì đang có để đạt được mục tiêu quan trọng nhất. Sự giản dị của vật liệu không hề làm giảm đi ý nghĩa của buổi lễ — trái lại, nó càng làm nổi bật tinh thần tự lực, tự cường của một dân tộc vừa giành lại quyền làm chủ đất nước mình.","doc":7},{"loai":"anh","src":"textures/bang_w/G14_19_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lễ đài Ba Đình, 2/9/1945”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Người kiến trúc sư và một sự nghiệp về sau","text":"Sau ngày 2 tháng 9 năm 1945, Ngô Huy Quỳnh tiếp tục con đường của một kiến trúc sư và nhà giáo, có nhiều đóng góp cho ngành xây dựng và quy hoạch đô thị Việt Nam trong những thập niên sau đó. Với ông, việc được giao thiết kế lễ đài Độc lập khi mới 25 tuổi hẳn là một dấu mốc không thể quên trong cả sự nghiệp — một công trình nhỏ về quy mô, dựng vội trong một đêm, nhưng lại gắn liền vĩnh viễn với một trong những khoảnh khắc trọng đại nhất của lịch sử dân tộc. Câu chuyện của ông cũng là một lát cắt tiêu biểu cho thế hệ trí thức trẻ Việt Nam những năm 1945: được trao trọng trách lớn giữa hoàn cảnh ngặt nghèo, và đã hoàn thành bằng tất cả sự nhiệt thành, khẩn trương của tuổi trẻ.","doc":8},{"loai":"doan","tieu_de":"Quảng trường không còn lễ đài, nhưng còn ký ức","text":"Lễ đài năm 1945 chỉ là một công trình tạm thời và không còn tồn tại đến ngày nay; nó đã được tháo dỡ sau khi hoàn thành nhiệm vụ lịch sử của mình. Nhưng Quảng trường Ba Đình vẫn còn đó, và vẫn là trái tim chính trị của đất nước, nơi diễn ra những sự kiện trọng đại nhất của quốc gia trong suốt tám mươi năm qua. Mỗi năm, vào dịp 2 tháng 9, rất nhiều người vẫn tìm về Ba Đình, đứng trên chính khoảng đất nơi cha ông họ từng nghe những lời đầu tiên của bản Tuyên ngôn Độc lập, để tự nhắc mình về cái giá của hai chữ độc lập — dù chiếc lễ đài gỗ giản dị năm xưa giờ chỉ còn trong những tấm ảnh tư liệu và trong không gian phục dựng của bảo tàng. Vị trí chính xác của bồn cỏ từng dựng lễ đài, theo thời gian, cũng đã hòa vào tổng thể quy hoạch mới của quảng trường, không còn được đánh dấu riêng biệt. Nhưng với những ai biết câu chuyện, mỗi lần đi ngang qua khoảng sân rộng trước Lăng, vẫn có thể hình dung ra dáng hình mộc mạc của một lễ đài bằng gỗ và lụa, đứng đó trong một buổi chiều mùa thu tám mươi năm về trước.","doc":9},{"loai":"ban_co_biet","text":"Lăng Chủ tịch Hồ Chí Minh được xây dựng ngay bên cạnh Quảng trường Ba Đình, khởi công ngày 2 tháng 9 năm 1973 và khánh thành ngày 29 tháng 8 năm 1975.","nguon_ten":"Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Báo Hà Nội Mới – Người thiết kế Lễ đài Độc lập trên Quảng trường Ba Đình ngày 2/9/1945 (hanoimoi.vn)","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Văn kiện đầu hàng của Nhật Bản, ký ngày 2/9/1945","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Lễ đài Độc lập: một công trình gỗ và vải dựng trong một ngày đêm. Lễ đài nơi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập không phải một công trình kiên cố được chuẩn bị từ trước, mà là một kết cấu gỗ và vải, dựng gấp trong chưa đầy một ngày đêm. Vậy mà hình ảnh giản dị ấy đã trở thành một trong những biểu tượng được nhớ đến nhiều nhất của lịch sử Việt Nam hiện đại."},{"t":"Nhiệm vụ giao trong một ngày. Ngày 1 tháng 9 năm 1945 — chỉ một ngày trước buổi lễ trọng đại — kiến trúc sư Ngô Huy Quỳnh được cấp trên giao nhiệm vụ thiết kế và chỉ đạo dựng lễ đài tại Quảng trường Ba Đình. Khi ấy ông mới 25 tuổi, quê ở làng Ngọc Lập, xã Phùng Chí Kiên, huyện Mỹ Hào, tỉnh Hưng Yên. Một kiến trúc sư trẻ, một khối lượng công việc lớn, và một quỹ thời gian gần như không tưởng: lễ đài phải đủ trang nghiêm cho giờ phút khai sinh một quốc gia, phải đủ cao và đủ nổi bật để hàng chục vạn người đứng từ xa vẫn nhìn thấy vị Chủ tịch, trong khi vật liệu và nhân lực giữa những ngày đầu cách mạng đều hết sức hạn chế. Không có bản vẽ nào được chuẩn bị từ trước cả tháng, không có thời gian để thử nghiệm phương án — mọi quyết định về hình dáng, vật liệu, cách dựng đều phải được đưa ra và thực hiện gần như cùng lúc."},{"t":"Bồn cỏ giữa vườn hoa Ba Đình. Địa điểm được chọn để dựng lễ đài là bồn cỏ hình tròn nằm giữa vườn hoa Ba Đình — khi đó vẫn còn mang những dấu vết của một vườn hoa kiểu Pháp với các lối đi rợp bóng cây. Đây là một lựa chọn hợp lý: khoảng đất trống đủ rộng để làm trung tâm thị giác cho cả quảng trường, xung quanh lại có không gian mở để hàng chục vạn người có thể đứng vây quanh mà vẫn nhìn thấy lễ đài từ nhiều hướng. Trong bối cảnh gấp gáp, việc tận dụng một không gian công cộng có sẵn, không cần giải phóng hay cải tạo mặt bằng, là điều kiện tiên quyết để công trình có thể hoàn thành đúng hạn. Từ một bồn cỏ bình thường của một vườn hoa công cộng, nơi đây bất ngờ trở thành tâm điểm của một sự kiện làm thay đổi vận mệnh cả một dân tộc."},{"t":"Cờ, cột cờ và một bản nhạc mới. Bên cạnh lễ đài, một cột cờ được dựng lên để lá cờ đỏ sao vàng — quốc kỳ của nhà nước vừa ra đời — tung bay trong suốt buổi lễ, trở thành điểm nhấn thị giác song song với khối kiến trúc bọc lụa của lễ đài. Trước khi Chủ tịch Hồ Chí Minh bước lên đọc Tuyên ngôn Độc lập, buổi lễ mở đầu bằng nghi thức chào cờ, với bài “Tiến quân ca” được cử hành như một bản quốc ca của nước Việt Nam Dân chủ Cộng hòa — một trong những lần đầu tiên bản nhạc ấy vang lên chính thức trước đông đảo quốc dân trong một nghi lễ nhà nước. Chỉ trong khuôn khổ chật hẹp của một buổi chiều, giữa một quảng trường vừa được chọn làm nơi tổ chức lễ và một lễ đài vừa dựng xong lúc rạng sáng, gần như mọi biểu tượng của một quốc gia độc lập — quốc kỳ, quốc ca, và bản tuyên ngôn lập quốc — cùng lúc xuất hiện lần đầu trước công chúng."},{"t":"Đóng đinh, bọc lụa, chạy đua với bình minh. Lễ đài được dựng bằng khung gỗ theo cách đóng đinh — phương pháp thi công nhanh, phù hợp với quỹ thời gian ít ỏi — rồi bọc lụa xung quanh để tạo vẻ trang trọng. Công trình được thiết kế với gam màu vàng nhạt chủ đạo, cùng một vòng tay ôm lấy phía sau lễ đài mang màu đỏ, hai bên đặt hai bình hương. Những chi tiết ấy tuy đơn giản nhưng được tính toán để tạo hiệu ứng thị giác trang nghiêm khi nhìn từ xa, giữa không gian rộng lớn của quảng trường. Toàn bộ công trình được hoàn thành chỉ trong một ngày đêm, xong trước rạng đông ngày 2 tháng 9 — nghĩa là đội thi công gần như phải làm việc suốt đêm mùng 1 rạng ngày 2 tháng 9 để kịp bàn giao cho buổi lễ diễn ra ngay buổi chiều hôm đó. Không có nhiều tư liệu ghi lại tên tuổi những người thợ trực tiếp dựng lễ đài đêm ấy, nhưng thành quả của họ đã trở thành một phần không thể tách rời của khoảnh khắc lịch sử."},{"t":"Khoảnh khắc trên bục gỗ. Chiều 2 tháng 9 năm 1945, trước hàng chục vạn đồng bào tề tựu tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh bước lên chính lễ đài vừa được dựng xong ấy, thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa buổi lễ, Người bất ngờ dừng lại, hỏi đồng bào một câu giản dị: “Tôi nói, đồng bào nghe rõ không?” (xem chuyên đề “Tôi nói, đồng bào nghe rõ không?”). Câu hỏi ấy không nằm trong bất kỳ bản thảo nào, nhưng lại vang lên đúng từ chiếc bục gỗ bọc lụa mà kiến trúc sư Ngô Huy Quỳnh và các cộng sự vừa hoàn thành trong đêm trước đó — biến một công trình tạm thời thành sân khấu của một trong những khoảnh khắc được ghi nhớ nhiều nhất trong lịch sử dân tộc."},{"t":"Bạn có biết? Cùng ngày 2 tháng 9 năm 1945 mà Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở Hà Nội, trên chiến hạm Missouri tại vịnh Tokyo, đại diện Nhật Bản ký văn kiện đầu hàng Đồng minh, chính thức kết thúc Chiến tranh thế giới thứ hai."},{"t":"Một buổi lễ trọng đại giữa những ngày thiếu thốn. Cần nhớ rằng lễ đài Ba Đình được dựng lên chỉ vài tuần sau khi chính quyền cách mạng còn phải lo đối phó với nạn đói, nạn dốt, ngân khố gần như trống rỗng. Vật liệu xây dựng, nhân lực có tay nghề, thời gian — tất cả đều là những nguồn lực khan hiếm. Việc dựng được một lễ đài đủ trang nghiêm chỉ trong một ngày đêm, bằng gỗ và vải thay vì đá và bê tông, cho thấy một cách ứng xử rất đặc trưng của những ngày đầu cách mạng: không đợi có đầy đủ điều kiện lý tưởng mới hành động, mà tận dụng tối đa những gì đang có để đạt được mục tiêu quan trọng nhất. Sự giản dị của vật liệu không hề làm giảm đi ý nghĩa của buổi lễ — trái lại, nó càng làm nổi bật tinh thần tự lực, tự cường của một dân tộc vừa giành lại quyền làm chủ đất nước mình."},{"t":"Người kiến trúc sư và một sự nghiệp về sau. Sau ngày 2 tháng 9 năm 1945, Ngô Huy Quỳnh tiếp tục con đường của một kiến trúc sư và nhà giáo, có nhiều đóng góp cho ngành xây dựng và quy hoạch đô thị Việt Nam trong những thập niên sau đó. Với ông, việc được giao thiết kế lễ đài Độc lập khi mới 25 tuổi hẳn là một dấu mốc không thể quên trong cả sự nghiệp — một công trình nhỏ về quy mô, dựng vội trong một đêm, nhưng lại gắn liền vĩnh viễn với một trong những khoảnh khắc trọng đại nhất của lịch sử dân tộc. Câu chuyện của ông cũng là một lát cắt tiêu biểu cho thế hệ trí thức trẻ Việt Nam những năm 1945: được trao trọng trách lớn giữa hoàn cảnh ngặt nghèo, và đã hoàn thành bằng tất cả sự nhiệt thành, khẩn trương của tuổi trẻ."},{"t":"Quảng trường không còn lễ đài, nhưng còn ký ức. Lễ đài năm 1945 chỉ là một công trình tạm thời và không còn tồn tại đến ngày nay; nó đã được tháo dỡ sau khi hoàn thành nhiệm vụ lịch sử của mình. Nhưng Quảng trường Ba Đình vẫn còn đó, và vẫn là trái tim chính trị của đất nước, nơi diễn ra những sự kiện trọng đại nhất của quốc gia trong suốt tám mươi năm qua. Mỗi năm, vào dịp 2 tháng 9, rất nhiều người vẫn tìm về Ba Đình, đứng trên chính khoảng đất nơi cha ông họ từng nghe những lời đầu tiên của bản Tuyên ngôn Độc lập, để tự nhắc mình về cái giá của hai chữ độc lập — dù chiếc lễ đài gỗ giản dị năm xưa giờ chỉ còn trong những tấm ảnh tư liệu và trong không gian phục dựng của bảo tàng. Vị trí chính xác của bồn cỏ từng dựng lễ đài, theo thời gian, cũng đã hòa vào tổng thể quy hoạch mới của quảng trường, không còn được đánh dấu riêng biệt. Nhưng với những ai biết câu chuyện, mỗi lần đi ngang qua khoảng sân rộng trước Lăng, vẫn có thể hình dung ra dáng hình mộc mạc của một lễ đài bằng gỗ và lụa, đứng đó trong một buổi chiều mùa thu tám mươi năm về trước."},{"t":"Bạn có biết? Lăng Chủ tịch Hồ Chí Minh được xây dựng ngay bên cạnh Quảng trường Ba Đình, khởi công ngày 2 tháng 9 năm 1973 và khánh thành ngày 29 tháng 8 năm 1975."}],"so_chu":1558},{"i":20,"tieu_de_bang":"Hai địa điểm","tieu_de":"Từ căn gác đến quảng trường: hai cây số của mùa thu 1945","sapo":"Phố Hàng Ngang và Quảng trường Ba Đình cách nhau chừng hai cây số. Quãng đường ấy nối khu phố buôn bán của người Việt với khu hành chính thời thuộc địa — và nối căn phòng nơi bản Tuyên ngôn Độc lập được viết ra với nơi nó được đọc lên trước toàn dân.","bia":{"src":"textures/bai/G14_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai nửa của một thành phố","text":"Hà Nội năm 1945 có thể hình dung như hai nửa mang diện mạo rất khác nhau. Phía đông là khu phố cổ với những con phố mang tên nghề buôn — Hàng Đào, Hàng Ngang, Hàng Đường, Hàng Bạc — dày đặc những ngôi nhà ống mái ngói, cửa hiệu san sát, nơi sinh sống và buôn bán của đông đảo người Việt qua nhiều thế hệ. Phía tây là khu vực quanh Ba Đình, với những đại lộ rộng rợp bóng cây và các dinh thự do người Pháp xây dựng trong hơn nửa thế kỷ đô hộ, trong đó lớn nhất là Phủ Toàn quyền Đông Dương. Hai địa điểm chính của gian trưng bày này — một căn gác giữa phố buôn, một quảng trường ngay cạnh khu dinh thự cũ — nằm ở hai nửa khác biệt ấy của cùng một thành phố, phản chiếu hai lớp lịch sử chồng lên nhau: một Hà Nội bản địa lâu đời, và một Hà Nội mang dấu ấn quy hoạch thuộc địa.","doc":1},{"loai":"doan","tieu_de":"Con phố nghề và đại lộ thuộc địa","text":"Sự khác biệt giữa hai khu vực không chỉ nằm ở kiến trúc, mà còn ở cách con người sử dụng không gian. Ở khu phố cổ, đường phố chật hẹp, đông đúc, là nơi diễn ra mọi hoạt động buôn bán, sinh hoạt của thị dân — không gian công cộng gần như không tồn tại theo nghĩa hiện đại. Ở khu Ba Đình, những đại lộ rộng, các vườn hoa, quảng trường được quy hoạch theo mô hình đô thị châu Âu, vốn phục vụ trước hết cho bộ máy hành chính thực dân. Chính vì thế, việc chọn Quảng trường Ba Đình — biểu tượng của không gian quyền lực thời thuộc địa — làm nơi tuyên bố nền độc lập của một nước Việt Nam mới, mang một ý nghĩa biểu tượng sâu sắc: không gian từng thuộc về chính quyền cai trị nay trở thành nơi cả dân tộc cùng chứng kiến giờ phút mình làm chủ vận mệnh của mình.","doc":2},{"loai":"doan","tieu_de":"Khu 36 phố phường và tên những con phố","text":"Tên gọi “khu 36 phố phường” xuất phát từ truyền thống lâu đời của Thăng Long – Hà Nội, nơi mỗi con phố ban đầu thường gắn với một phường nghề hoặc một mặt hàng buôn bán cụ thể: Hàng Bạc là nơi thợ kim hoàn, Hàng Đường là nơi bán đường mứt, Hàng Đào là nơi bán tơ lụa nhuộm màu. Phố Hàng Ngang cũng mang tên theo lối gọi ấy, dù nghề gốc gắn với tên phố nay không còn được nhắc đến rõ ràng như một số phố khác trong khu vực. Trải qua nhiều thế kỷ, ranh giới và nghề nghiệp của từng phố đã đổi thay nhiều lần, nhưng tên gọi cũ vẫn được giữ lại, trở thành một phần bản sắc của khu phố cổ cho tới tận hôm nay. Chính trong không gian mang đậm dấu ấn buôn bán truyền thống ấy, giữa những mái ngói rêu phong và những cửa hiệu san sát, một quyết định làm thay đổi vận mệnh dân tộc đã được ấp ủ trong im lặng — một sự tương phản mà bất kỳ ai tìm hiểu về mùa thu năm 1945 cũng khó lòng không để ý.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","chu_thich":"Phố Hàng Ngang (“rue des Cantonnais”) đầu thế kỷ 20 — nơi có ngôi nhà số 48, cách Quảng trường Ba Đình chừng hai cây số.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Điểm thứ ba: Bắc Bộ phủ","text":"Trong những tháng từ 1945 đến 1946, ngoài Hàng Ngang và Ba Đình, còn một địa chỉ quan trọng khác trong hành trình của Chủ tịch Hồ Chí Minh tại Hà Nội: Bắc Bộ phủ, nguyên là dinh Thống sứ Bắc Kỳ thời Pháp thuộc, nằm gần hồ Hoàn Kiếm, nay là Nhà khách Chính phủ tại số 12 phố Ngô Quyền. Ngày 19 tháng 8 năm 1945, trong cao trào Tổng khởi nghĩa, quần chúng cách mạng đã chiếm giữ nơi này; từ đó Bắc Bộ phủ trở thành trụ sở làm việc của Chính phủ lâm thời và của Chủ tịch Hồ Chí Minh trong những ngày đầu. Phiên họp đầu tiên của Chính phủ lâm thời, ngày 3 tháng 9 năm 1945 — chỉ một ngày sau lễ Độc lập — cũng diễn ra tại đây. Ba địa điểm Hàng Ngang, Ba Đình, Bắc Bộ phủ, vì vậy, tạo thành một tam giác địa lý gói trọn những ngày lập quốc đầu tiên của nước Việt Nam Dân chủ Cộng hòa.","doc":4},{"loai":"anh","src":"textures/bang_w/G14_20_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hai địa điểm”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vì sao gọi là Ba Đình","text":"Cái tên “Ba Đình” không có sẵn từ đầu. Trước năm 1945, khu vực này mang tên Pháp là “Rond Point Puginier”. Chính bác sĩ Trần Văn Lai, đốc lý người Việt đầu tiên của Hà Nội, nhậm chức từ tháng 4 năm 1945, là người đã đổi tên nơi này thành “Vườn hoa Ba Đình”. Tên gọi ấy được đặt theo cuộc khởi nghĩa Ba Đình những năm 1886–1887 tại vùng đất thuộc ba làng Mỹ Khê, Thượng Thọ và Mậu Thịnh, huyện Nga Sơn, tỉnh Thanh Hóa — một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương chống thực dân Pháp, do các thủ lĩnh Phạm Bành và Đinh Công Tráng lãnh đạo. Sau đó, đến tháng 12 năm 1945, nơi này từng mang tên “Vườn hoa Độc Lập” trong một thời gian, trước khi tên gọi Ba Đình được khôi phục sau ngày giải phóng Thủ đô 10 tháng 10 năm 1954 và tồn tại cho đến ngày nay dưới tên gọi Quảng trường Ba Đình.","doc":5},{"loai":"doan","tieu_de":"Từ trang giấy đến quảng trường","text":"Nhìn theo một cách khác, hai địa điểm của gian trưng bày này chính là hai đầu của hành trình một văn kiện. Bản Tuyên ngôn Độc lập được viết ra trong một căn phòng chật hẹp trên gác hai nhà 48 Hàng Ngang (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn), rồi từ đó, qua khoảng hai cây số đường phố, được mang tới lễ đài giữa Quảng trường Ba Đình để đọc trước hàng chục vạn đồng bào (xem chuyên đề Lễ đài Ba Đình, 2/9/1945). Quãng đường vật lý ấy không dài, có thể đi bộ trong chưa đầy nửa giờ, nhưng nó gói trọn cả một quá trình: từ những dòng chữ được cân nhắc âm thầm trong riêng tư, đến khoảnh khắc những dòng chữ ấy trở thành tài sản chung của cả một dân tộc, vang lên giữa không gian công cộng lớn nhất Hà Nội.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","chu_thich":"Quảng trường Ba Đình ngày 2 tháng 9 năm 1945, nơi diễn ra lễ Tuyên ngôn Độc lập.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Sáng 19 tháng 8 năm 1945, cuộc khởi nghĩa giành chính quyền ở Hà Nội bắt đầu bằng cuộc mít tinh lớn tại quảng trường Nhà hát Lớn; sau đó quần chúng chia nhau đi chiếm Phủ Khâm sai (Bắc Bộ phủ) cùng các công sở quan trọng khác trong thành phố.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử; Lịch sử Hà Nội","doc":7},{"loai":"doan","tieu_de":"Trong không gian 3D","text":"Để khách tham quan có thể cảm nhận được cả hai địa điểm chỉ trong một lượt đi, gian trưng bày nối phố Hàng Ngang với Quảng trường Ba Đình bằng một đoạn đại lộ rợp bóng cây — một sự giản lược có chủ đích, không phải một tấm bản đồ đúng tỷ lệ. Trên thực tế lịch sử, từ khu phố cổ tới Ba Đình phải đi qua nhiều con phố khác nhau, với những khúc rẽ và khoảng cách không đều. Nhưng trong không gian ba chiều của bảo tàng, việc rút gọn quãng đường ấy thành một trục đi bộ duy nhất giúp người xem dễ hình dung mối liên hệ giữa hai địa điểm, thay vì bị phân tán bởi chi tiết địa lý. Đi bộ theo đại lộ ấy, khách tham quan có thể tưởng tượng dòng người từ khắp các phố phường đổ về quảng trường chiều 2 tháng 9 năm 1945, và cả hành trình của bản Tuyên ngôn: từ trang bản thảo trên căn gác nhỏ đến giọng đọc vang lên trước hàng chục vạn đồng bào.","doc":8},{"loai":"anh","src":"textures/bang_w/G14_20_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hai địa điểm”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Đi lại quãng đường ấy hôm nay","text":"Ngày nay, đoạn đường từ phố Hàng Ngang tới Quảng trường Ba Đình đã đổi khác nhiều so với năm 1945: xe cộ đông đúc hơn, nhiều công trình mới đã mọc lên, nhưng hướng đi cơ bản — từ khu phố cổ, qua khu vực hồ Hoàn Kiếm, tới các trục đường lớn dẫn về Ba Đình — vẫn không thay đổi. Với những ai từng đọc về mùa thu năm 1945, quãng đường quen thuộc ấy mang thêm một lớp ý nghĩa: mỗi ngã tư, mỗi con phố đi qua, đều có thể từng in dấu chân của dòng người đổ về nghe Tuyên ngôn Độc lập tám mươi năm trước. Đó cũng là điều mà hai địa điểm trong gian trưng bày này muốn gợi lại — không chỉ hai công trình riêng lẻ, mà cả một tấm bản đồ sống động của những ngày lập quốc, nơi từng con phố của Hà Nội đều mang trong mình một phần câu chuyện.","doc":9},{"loai":"ban_co_biet","text":"Phủ Toàn quyền Đông Dương, xây dựng trong các năm 1900–1906 gần vườn hoa Ba Đình, sau ngày Độc lập trở thành Phủ Chủ tịch nước Việt Nam Dân chủ Cộng hòa — nơi Chủ tịch Hồ Chí Minh từng làm việc, tiếp khách trước khi chuyển ra sống tại ngôi nhà sàn từ tháng 5 năm 1958.","nguon_ten":"Khu di tích Phủ Chủ tịch","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Di tích 48 Hàng Ngang, Hà Nội","Ban Quản lý phố cổ Hà Nội","Tên gọi Ba Đình được ra đời như thế nào (nongthonvaphattrien.vn)","Khu di tích Phủ Chủ tịch"],"doc":[{"t":"Từ căn gác đến quảng trường: hai cây số của mùa thu 1945. Phố Hàng Ngang và Quảng trường Ba Đình cách nhau chừng hai cây số. Quãng đường ấy nối khu phố buôn bán của người Việt với khu hành chính thời thuộc địa — và nối căn phòng nơi bản Tuyên ngôn Độc lập được viết ra với nơi nó được đọc lên trước toàn dân."},{"t":"Hai nửa của một thành phố. Hà Nội năm 1945 có thể hình dung như hai nửa mang diện mạo rất khác nhau. Phía đông là khu phố cổ với những con phố mang tên nghề buôn — Hàng Đào, Hàng Ngang, Hàng Đường, Hàng Bạc — dày đặc những ngôi nhà ống mái ngói, cửa hiệu san sát, nơi sinh sống và buôn bán của đông đảo người Việt qua nhiều thế hệ. Phía tây là khu vực quanh Ba Đình, với những đại lộ rộng rợp bóng cây và các dinh thự do người Pháp xây dựng trong hơn nửa thế kỷ đô hộ, trong đó lớn nhất là Phủ Toàn quyền Đông Dương. Hai địa điểm chính của gian trưng bày này — một căn gác giữa phố buôn, một quảng trường ngay cạnh khu dinh thự cũ — nằm ở hai nửa khác biệt ấy của cùng một thành phố, phản chiếu hai lớp lịch sử chồng lên nhau: một Hà Nội bản địa lâu đời, và một Hà Nội mang dấu ấn quy hoạch thuộc địa."},{"t":"Con phố nghề và đại lộ thuộc địa. Sự khác biệt giữa hai khu vực không chỉ nằm ở kiến trúc, mà còn ở cách con người sử dụng không gian. Ở khu phố cổ, đường phố chật hẹp, đông đúc, là nơi diễn ra mọi hoạt động buôn bán, sinh hoạt của thị dân — không gian công cộng gần như không tồn tại theo nghĩa hiện đại. Ở khu Ba Đình, những đại lộ rộng, các vườn hoa, quảng trường được quy hoạch theo mô hình đô thị châu Âu, vốn phục vụ trước hết cho bộ máy hành chính thực dân. Chính vì thế, việc chọn Quảng trường Ba Đình — biểu tượng của không gian quyền lực thời thuộc địa — làm nơi tuyên bố nền độc lập của một nước Việt Nam mới, mang một ý nghĩa biểu tượng sâu sắc: không gian từng thuộc về chính quyền cai trị nay trở thành nơi cả dân tộc cùng chứng kiến giờ phút mình làm chủ vận mệnh của mình."},{"t":"Khu 36 phố phường và tên những con phố. Tên gọi “khu 36 phố phường” xuất phát từ truyền thống lâu đời của Thăng Long – Hà Nội, nơi mỗi con phố ban đầu thường gắn với một phường nghề hoặc một mặt hàng buôn bán cụ thể: Hàng Bạc là nơi thợ kim hoàn, Hàng Đường là nơi bán đường mứt, Hàng Đào là nơi bán tơ lụa nhuộm màu. Phố Hàng Ngang cũng mang tên theo lối gọi ấy, dù nghề gốc gắn với tên phố nay không còn được nhắc đến rõ ràng như một số phố khác trong khu vực. Trải qua nhiều thế kỷ, ranh giới và nghề nghiệp của từng phố đã đổi thay nhiều lần, nhưng tên gọi cũ vẫn được giữ lại, trở thành một phần bản sắc của khu phố cổ cho tới tận hôm nay. Chính trong không gian mang đậm dấu ấn buôn bán truyền thống ấy, giữa những mái ngói rêu phong và những cửa hiệu san sát, một quyết định làm thay đổi vận mệnh dân tộc đã được ấp ủ trong im lặng — một sự tương phản mà bất kỳ ai tìm hiểu về mùa thu năm 1945 cũng khó lòng không để ý."},{"t":"Điểm thứ ba: Bắc Bộ phủ. Trong những tháng từ 1945 đến 1946, ngoài Hàng Ngang và Ba Đình, còn một địa chỉ quan trọng khác trong hành trình của Chủ tịch Hồ Chí Minh tại Hà Nội: Bắc Bộ phủ, nguyên là dinh Thống sứ Bắc Kỳ thời Pháp thuộc, nằm gần hồ Hoàn Kiếm, nay là Nhà khách Chính phủ tại số 12 phố Ngô Quyền. Ngày 19 tháng 8 năm 1945, trong cao trào Tổng khởi nghĩa, quần chúng cách mạng đã chiếm giữ nơi này; từ đó Bắc Bộ phủ trở thành trụ sở làm việc của Chính phủ lâm thời và của Chủ tịch Hồ Chí Minh trong những ngày đầu. Phiên họp đầu tiên của Chính phủ lâm thời, ngày 3 tháng 9 năm 1945 — chỉ một ngày sau lễ Độc lập — cũng diễn ra tại đây. Ba địa điểm Hàng Ngang, Ba Đình, Bắc Bộ phủ, vì vậy, tạo thành một tam giác địa lý gói trọn những ngày lập quốc đầu tiên của nước Việt Nam Dân chủ Cộng hòa."},{"t":"Vì sao gọi là Ba Đình. Cái tên “Ba Đình” không có sẵn từ đầu. Trước năm 1945, khu vực này mang tên Pháp là “Rond Point Puginier”. Chính bác sĩ Trần Văn Lai, đốc lý người Việt đầu tiên của Hà Nội, nhậm chức từ tháng 4 năm 1945, là người đã đổi tên nơi này thành “Vườn hoa Ba Đình”. Tên gọi ấy được đặt theo cuộc khởi nghĩa Ba Đình những năm 1886–1887 tại vùng đất thuộc ba làng Mỹ Khê, Thượng Thọ và Mậu Thịnh, huyện Nga Sơn, tỉnh Thanh Hóa — một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương chống thực dân Pháp, do các thủ lĩnh Phạm Bành và Đinh Công Tráng lãnh đạo. Sau đó, đến tháng 12 năm 1945, nơi này từng mang tên “Vườn hoa Độc Lập” trong một thời gian, trước khi tên gọi Ba Đình được khôi phục sau ngày giải phóng Thủ đô 10 tháng 10 năm 1954 và tồn tại cho đến ngày nay dưới tên gọi Quảng trường Ba Đình."},{"t":"Từ trang giấy đến quảng trường. Nhìn theo một cách khác, hai địa điểm của gian trưng bày này chính là hai đầu của hành trình một văn kiện. Bản Tuyên ngôn Độc lập được viết ra trong một căn phòng chật hẹp trên gác hai nhà 48 Hàng Ngang (xem chuyên đề Căn phòng soạn thảo Tuyên ngôn), rồi từ đó, qua khoảng hai cây số đường phố, được mang tới lễ đài giữa Quảng trường Ba Đình để đọc trước hàng chục vạn đồng bào (xem chuyên đề Lễ đài Ba Đình, 2/9/1945). Quãng đường vật lý ấy không dài, có thể đi bộ trong chưa đầy nửa giờ, nhưng nó gói trọn cả một quá trình: từ những dòng chữ được cân nhắc âm thầm trong riêng tư, đến khoảnh khắc những dòng chữ ấy trở thành tài sản chung của cả một dân tộc, vang lên giữa không gian công cộng lớn nhất Hà Nội."},{"t":"Bạn có biết? Sáng 19 tháng 8 năm 1945, cuộc khởi nghĩa giành chính quyền ở Hà Nội bắt đầu bằng cuộc mít tinh lớn tại quảng trường Nhà hát Lớn; sau đó quần chúng chia nhau đi chiếm Phủ Khâm sai (Bắc Bộ phủ) cùng các công sở quan trọng khác trong thành phố."},{"t":"Trong không gian 3D. Để khách tham quan có thể cảm nhận được cả hai địa điểm chỉ trong một lượt đi, gian trưng bày nối phố Hàng Ngang với Quảng trường Ba Đình bằng một đoạn đại lộ rợp bóng cây — một sự giản lược có chủ đích, không phải một tấm bản đồ đúng tỷ lệ. Trên thực tế lịch sử, từ khu phố cổ tới Ba Đình phải đi qua nhiều con phố khác nhau, với những khúc rẽ và khoảng cách không đều. Nhưng trong không gian ba chiều của bảo tàng, việc rút gọn quãng đường ấy thành một trục đi bộ duy nhất giúp người xem dễ hình dung mối liên hệ giữa hai địa điểm, thay vì bị phân tán bởi chi tiết địa lý. Đi bộ theo đại lộ ấy, khách tham quan có thể tưởng tượng dòng người từ khắp các phố phường đổ về quảng trường chiều 2 tháng 9 năm 1945, và cả hành trình của bản Tuyên ngôn: từ trang bản thảo trên căn gác nhỏ đến giọng đọc vang lên trước hàng chục vạn đồng bào."},{"t":"Đi lại quãng đường ấy hôm nay. Ngày nay, đoạn đường từ phố Hàng Ngang tới Quảng trường Ba Đình đã đổi khác nhiều so với năm 1945: xe cộ đông đúc hơn, nhiều công trình mới đã mọc lên, nhưng hướng đi cơ bản — từ khu phố cổ, qua khu vực hồ Hoàn Kiếm, tới các trục đường lớn dẫn về Ba Đình — vẫn không thay đổi. Với những ai từng đọc về mùa thu năm 1945, quãng đường quen thuộc ấy mang thêm một lớp ý nghĩa: mỗi ngã tư, mỗi con phố đi qua, đều có thể từng in dấu chân của dòng người đổ về nghe Tuyên ngôn Độc lập tám mươi năm trước. Đó cũng là điều mà hai địa điểm trong gian trưng bày này muốn gợi lại — không chỉ hai công trình riêng lẻ, mà cả một tấm bản đồ sống động của những ngày lập quốc, nơi từng con phố của Hà Nội đều mang trong mình một phần câu chuyện."},{"t":"Bạn có biết? Phủ Toàn quyền Đông Dương, xây dựng trong các năm 1900–1906 gần vườn hoa Ba Đình, sau ngày Độc lập trở thành Phủ Chủ tịch nước Việt Nam Dân chủ Cộng hòa — nơi Chủ tịch Hồ Chí Minh từng làm việc, tiếp khách trước khi chuyển ra sống tại ngôi nhà sàn từ tháng 5 năm 1958."}],"so_chu":1557}],"do_vat":[{"id":"table@10.4,69.6","x":10.4,"y":0.22,"z":69.6,"loai":"table","ten":"Bàn viết (phục dựng)","tieu_de":"Chiếc bàn của những ngày viết Tuyên ngôn","text":"Trong góc phòng phục dựng của gian trưng bày là một chiếc bàn viết bằng gỗ mộc, mặt bàn hẹp và thấp, bốn chân tiện thẳng, có một ngăn kéo nhỏ đựng giấy, bút và nghiên mực — kiểu bàn làm việc quen thuộc trong các gia đình khá giả ở Hà Nội đầu thế kỷ 20, thường được kê áp cửa sổ để tận dụng ánh sáng ban ngày. Đây là đồ vật phục dựng, dựng lại để gợi không khí một góc làm việc, không phải hiện vật gốc còn giữ nguyên vẹn đến ngày nay.\n\nỞ Hà Nội mùa thu năm 1945, những chiếc bàn như thế có mặt trong hầu hết các gia đình buôn bán trên phố cổ — vừa là nơi ghi chép sổ sách, tính toán chuyện buôn bán tơ lụa, vừa là chỗ con cháu trong nhà ngồi học chữ quốc ngữ mỗi tối. Cửa hàng và căn nhà nép mình giữa dãy phố Hàng Ngang tấp nập người mua kẻ bán, không ai ngoài phố ngờ rằng tầng gác phía trên đang diễn ra những giờ phút quan trọng bậc nhất của lịch sử dân tộc.\n\nChính bên một chiếc bàn như vậy, trên gác hai nhà số 48 Hàng Ngang, trong hai ngày 28 và 29 tháng 8 năm 1945, Chủ tịch Hồ Chí Minh đã soạn thảo bản Tuyên ngôn Độc lập — văn kiện mở đầu bằng lời trích dẫn Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ, tiếp đến là Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, trước khi khép lại bằng lời khẳng định quyền tự do, độc lập của dân tộc Việt Nam và lời thề đem tất cả tinh thần, lực lượng, tính mạng và của cải để giữ vững quyền ấy. Người viết trong sự thận trọng, cân nhắc từng câu chữ, bởi đây sẽ là văn kiện pháp lý đầu tiên tuyên bố với thế giới về sự ra đời của một nhà nước độc lập, sau gần một thế kỷ dân tộc chịu ách đô hộ.\n\nCác tài liệu chính thống được công bố về những ngày này chủ yếu ghi lại thời gian, trình tự công việc và nội dung bản thảo, chứ không mô tả chi tiết hình dáng chiếc bàn nguyên bản — vì vậy bản phục dựng trong gian trưng bày chỉ dựng lại theo hình dung chung về đồ gỗ văn phòng Hà Nội những năm 1940, giúp người xem cảm nhận không khí làm việc chứ không khẳng định là bản sao chính xác của đồ vật gốc.\n\nNgôi nhà 48 Hàng Ngang — nơi có căn phòng làm việc năm xưa — ngày nay được gìn giữ như một di tích lưu niệm về Chủ tịch Hồ Chí Minh, nằm giữa dòng chảy buôn bán sầm uất của phố cổ Hà Nội, đón khách trong và ngoài nước đến tham quan, tìm hiểu về những ngày bản Tuyên ngôn Độc lập ra đời. Tại chính căn phòng ấy, di tích hiện vẫn giữ lại một góc làm việc phục dựng với bàn gỗ, đèn dầu và tập bản thảo viết tay, để du khách hình dung không gian nơi văn kiện lập quốc từng được soạn ra.\n\nCon đường từ căn gác nhỏ này tới nơi bản Tuyên ngôn Độc lập được đọc lên chỉ dài chừng hai cây số — quãng đường nối khu phố buôn bán của người Việt trên phố Hàng Ngang với Quảng trường Ba Đình, khi đó là trung tâm hành chính thời thuộc địa. Chiếc bàn viết trong căn phòng nhỏ, chật hẹp và giản dị, với lễ đài giữa quảng trường rộng lớn đón hàng chục vạn người, vì thế là hai đầu của một hành trình ngắn về khoảng cách địa lý nhưng dài về ý nghĩa lịch sử: từ nơi ý chí độc lập được đặt thành từng câu chữ, đến nơi ý chí ấy được tuyên bố trước toàn thể quốc dân và thế giới.","nguon":"Hồ Chí Minh – Biên niên tiểu sử; hochiminh.vn; Trung tâm Lưu trữ quốc gia III","doc":[{"t":"Chiếc bàn của những ngày viết Tuyên ngôn. Trong góc phòng phục dựng của gian trưng bày là một chiếc bàn viết bằng gỗ mộc, mặt bàn hẹp và thấp, bốn chân tiện thẳng, có một ngăn kéo nhỏ đựng giấy, bút và nghiên mực — kiểu bàn làm việc quen thuộc trong các gia đình khá giả ở Hà Nội đầu thế kỷ 20, thường được kê áp cửa sổ để tận dụng ánh sáng ban ngày. Đây là đồ vật phục dựng, dựng lại để gợi không khí một góc làm việc, không phải hiện vật gốc còn giữ nguyên vẹn đến ngày nay."},{"t":"Ở Hà Nội mùa thu năm 1945, những chiếc bàn như thế có mặt trong hầu hết các gia đình buôn bán trên phố cổ — vừa là nơi ghi chép sổ sách, tính toán chuyện buôn bán tơ lụa, vừa là chỗ con cháu trong nhà ngồi học chữ quốc ngữ mỗi tối. Cửa hàng và căn nhà nép mình giữa dãy phố Hàng Ngang tấp nập người mua kẻ bán, không ai ngoài phố ngờ rằng tầng gác phía trên đang diễn ra những giờ phút quan trọng bậc nhất của lịch sử dân tộc."},{"t":"Chính bên một chiếc bàn như vậy, trên gác hai nhà số 48 Hàng Ngang, trong hai ngày 28 và 29 tháng 8 năm 1945, Chủ tịch Hồ Chí Minh đã soạn thảo bản Tuyên ngôn Độc lập — văn kiện mở đầu bằng lời trích dẫn Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ, tiếp đến là Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, trước khi khép lại bằng lời khẳng định quyền tự do, độc lập của dân tộc Việt Nam và lời thề đem tất cả tinh thần, lực lượng, tính mạng và của cải để giữ vững quyền ấy. Người viết trong sự thận trọng, cân nhắc từng câu chữ, bởi đây sẽ là văn kiện pháp lý đầu tiên tuyên bố với thế giới về sự ra đời của một nhà nước độc lập, sau gần một thế kỷ dân tộc chịu ách đô hộ."},{"t":"Các tài liệu chính thống được công bố về những ngày này chủ yếu ghi lại thời gian, trình tự công việc và nội dung bản thảo, chứ không mô tả chi tiết hình dáng chiếc bàn nguyên bản — vì vậy bản phục dựng trong gian trưng bày chỉ dựng lại theo hình dung chung về đồ gỗ văn phòng Hà Nội những năm 1940, giúp người xem cảm nhận không khí làm việc chứ không khẳng định là bản sao chính xác của đồ vật gốc."},{"t":"Ngôi nhà 48 Hàng Ngang — nơi có căn phòng làm việc năm xưa — ngày nay được gìn giữ như một di tích lưu niệm về Chủ tịch Hồ Chí Minh, nằm giữa dòng chảy buôn bán sầm uất của phố cổ Hà Nội, đón khách trong và ngoài nước đến tham quan, tìm hiểu về những ngày bản Tuyên ngôn Độc lập ra đời. Tại chính căn phòng ấy, di tích hiện vẫn giữ lại một góc làm việc phục dựng với bàn gỗ, đèn dầu và tập bản thảo viết tay, để du khách hình dung không gian nơi văn kiện lập quốc từng được soạn ra."},{"t":"Con đường từ căn gác nhỏ này tới nơi bản Tuyên ngôn Độc lập được đọc lên chỉ dài chừng hai cây số — quãng đường nối khu phố buôn bán của người Việt trên phố Hàng Ngang với Quảng trường Ba Đình, khi đó là trung tâm hành chính thời thuộc địa. Chiếc bàn viết trong căn phòng nhỏ, chật hẹp và giản dị, với lễ đài giữa quảng trường rộng lớn đón hàng chục vạn người, vì thế là hai đầu của một hành trình ngắn về khoảng cách địa lý nhưng dài về ý nghĩa lịch sử: từ nơi ý chí độc lập được đặt thành từng câu chữ, đến nơi ý chí ấy được tuyên bố trước toàn thể quốc dân và thế giới."},{"t":"Bạn có biết? Bản Tuyên ngôn Độc lập được viết ra từ căn phòng này hiện được lưu giữ như một trong những tài liệu quý giá nhất của lịch sử Việt Nam hiện đại, tại Trung tâm Lưu trữ quốc gia III, Hà Nội."}],"ban_co_biet":"Bản Tuyên ngôn Độc lập được viết ra từ căn phòng này hiện được lưu giữ như một trong những tài liệu quý giá nhất của lịch sử Việt Nam hiện đại, tại Trung tâm Lưu trữ quốc gia III, Hà Nội."},{"id":"table@9.6,69.6","x":9.6,"y":0.22,"z":69.6,"loai":"table","ten":"Bàn họp (phục dựng)","tieu_de":"Cuộc họp ngày 26 tháng 8 năm 1945","text":"Kê cạnh bàn viết trong căn phòng phục dựng là một chiếc bàn lớn hơn, mặt bàn hình chữ nhật, có thể xếp quanh vài chiếc ghế — hình dung về một chiếc bàn khách hoặc bàn ăn trong nhà một gia đình tư sản Hà Nội, được trưng dụng làm nơi hội họp trong những ngày biến động của mùa thu năm 1945. Cũng như chiếc bàn viết bên cạnh, đây là đồ phục dựng nhằm gợi lại không gian, không phải hiện vật gốc.\n\nNgày 26 tháng 8 năm 1945, chỉ một ngày sau khi về tới Hà Nội và tạm trú tại nhà số 48 Hàng Ngang, Chủ tịch Hồ Chí Minh đã chủ trì một cuộc họp quan trọng của Ban Thường vụ Trung ương Đảng ngay tại ngôi nhà này. Đó là những ngày chính quyền cách mạng còn hết sức non trẻ: Ủy ban Dân tộc giải phóng vừa cải tổ thành Chính phủ lâm thời ít ngày trước, trong khi tình hình quân sự và chính trị trong nước lẫn quốc tế đều hết sức khẩn cấp, đòi hỏi phải nhanh chóng đưa ra những quyết sách lớn.\n\nTại cuộc họp bên chiếc bàn ấy, Trung ương Đảng đã thống nhất ba việc lớn: chuẩn bị bản Tuyên ngôn Độc lập để công bố với quốc dân và thế giới; tổ chức một cuộc mít tinh lớn tại Hà Nội để Chính phủ lâm thời ra mắt nhân dân và tuyên bố nền độc lập; đồng thời mở rộng thành phần Chính phủ, mời thêm các nhân sĩ, trí thức yêu nước thuộc nhiều xu hướng khác nhau cùng tham gia, nhằm quy tụ rộng rãi sức mạnh đoàn kết toàn dân tộc trong buổi đầu dựng nước. Chỉ hai ngày sau, ngày 28 tháng 8, thành phần Chính phủ lâm thời mở rộng ấy được công bố.\n\nKhông khí những cuộc họp như thế được nhiều người trong cuộc sau này nhắc lại là hết sức khẩn trương, có khi kéo dài thâu đêm, bởi quỹ thời gian cho việc chuẩn bị một sự kiện trọng đại — lễ Độc lập tại Quảng trường Ba Đình — chỉ còn tính bằng ngày. Từ một chiếc bàn giản dị trong căn nhà buôn bán tơ lụa, những quyết định làm thay đổi vận mệnh cả một dân tộc đã được đưa ra trong một thời gian ngắn đến kinh ngạc.\n\nChiếc bàn họp phục dựng trong gian trưng bày, đặt cạnh chiếc bàn viết, giúp người xem hình dung hai công việc song song diễn ra trên cùng một gác hai của ngôi nhà 48 Hàng Ngang trong những ngày cuối tháng 8 năm 1945: một bên là nơi bàn định sách lược của cả dân tộc, một bên là nơi từng câu chữ của bản Tuyên ngôn Độc lập được viết ra.\n\nQuyết định mở rộng thành phần Chính phủ được đưa ra quanh chiếc bàn họp ấy không chỉ là một thủ tục hành chính. Đó là một lựa chọn chính trị có tầm nhìn xa: giữa lúc chính quyền cách mạng còn non trẻ, việc mời thêm những nhân sĩ, trí thức ngoài Việt Minh — như học giả Nguyễn Văn Tố, luật sư Vũ Trọng Khánh, bác sĩ Phạm Ngọc Thạch hay trí thức Công giáo Nguyễn Mạnh Hà — cùng tham gia Chính phủ đã giúp tạo dựng ngay từ đầu hình ảnh một nhà nước của khối đại đoàn kết toàn dân tộc, chứ không phải của riêng một lực lượng chính trị.\n\nCũng tại căn nhà 48 Hàng Ngang những ngày ấy, nhiều cuộc gặp gỡ, trao đổi khác giữa Chủ tịch Hồ Chí Minh với các cộng sự, các nhân sĩ được mời tham gia chính quyền mới cũng diễn ra bên những chiếc bàn tương tự — cho thấy một guồng máy làm việc khẩn trương, nơi các quyết định lớn được bàn bạc, thống nhất trong một không gian gia đình bình dị, xa cách hẳn với hình dung thông thường về một dinh thự hay công sở.","nguon":"Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Cuộc họp ngày 26 tháng 8 năm 1945. Kê cạnh bàn viết trong căn phòng phục dựng là một chiếc bàn lớn hơn, mặt bàn hình chữ nhật, có thể xếp quanh vài chiếc ghế — hình dung về một chiếc bàn khách hoặc bàn ăn trong nhà một gia đình tư sản Hà Nội, được trưng dụng làm nơi hội họp trong những ngày biến động của mùa thu năm 1945. Cũng như chiếc bàn viết bên cạnh, đây là đồ phục dựng nhằm gợi lại không gian, không phải hiện vật gốc."},{"t":"Ngày 26 tháng 8 năm 1945, chỉ một ngày sau khi về tới Hà Nội và tạm trú tại nhà số 48 Hàng Ngang, Chủ tịch Hồ Chí Minh đã chủ trì một cuộc họp quan trọng của Ban Thường vụ Trung ương Đảng ngay tại ngôi nhà này. Đó là những ngày chính quyền cách mạng còn hết sức non trẻ: Ủy ban Dân tộc giải phóng vừa cải tổ thành Chính phủ lâm thời ít ngày trước, trong khi tình hình quân sự và chính trị trong nước lẫn quốc tế đều hết sức khẩn cấp, đòi hỏi phải nhanh chóng đưa ra những quyết sách lớn."},{"t":"Tại cuộc họp bên chiếc bàn ấy, Trung ương Đảng đã thống nhất ba việc lớn: chuẩn bị bản Tuyên ngôn Độc lập để công bố với quốc dân và thế giới; tổ chức một cuộc mít tinh lớn tại Hà Nội để Chính phủ lâm thời ra mắt nhân dân và tuyên bố nền độc lập; đồng thời mở rộng thành phần Chính phủ, mời thêm các nhân sĩ, trí thức yêu nước thuộc nhiều xu hướng khác nhau cùng tham gia, nhằm quy tụ rộng rãi sức mạnh đoàn kết toàn dân tộc trong buổi đầu dựng nước. Chỉ hai ngày sau, ngày 28 tháng 8, thành phần Chính phủ lâm thời mở rộng ấy được công bố."},{"t":"Không khí những cuộc họp như thế được nhiều người trong cuộc sau này nhắc lại là hết sức khẩn trương, có khi kéo dài thâu đêm, bởi quỹ thời gian cho việc chuẩn bị một sự kiện trọng đại — lễ Độc lập tại Quảng trường Ba Đình — chỉ còn tính bằng ngày. Từ một chiếc bàn giản dị trong căn nhà buôn bán tơ lụa, những quyết định làm thay đổi vận mệnh cả một dân tộc đã được đưa ra trong một thời gian ngắn đến kinh ngạc."},{"t":"Chiếc bàn họp phục dựng trong gian trưng bày, đặt cạnh chiếc bàn viết, giúp người xem hình dung hai công việc song song diễn ra trên cùng một gác hai của ngôi nhà 48 Hàng Ngang trong những ngày cuối tháng 8 năm 1945: một bên là nơi bàn định sách lược của cả dân tộc, một bên là nơi từng câu chữ của bản Tuyên ngôn Độc lập được viết ra."},{"t":"Quyết định mở rộng thành phần Chính phủ được đưa ra quanh chiếc bàn họp ấy không chỉ là một thủ tục hành chính. Đó là một lựa chọn chính trị có tầm nhìn xa: giữa lúc chính quyền cách mạng còn non trẻ, việc mời thêm những nhân sĩ, trí thức ngoài Việt Minh — như học giả Nguyễn Văn Tố, luật sư Vũ Trọng Khánh, bác sĩ Phạm Ngọc Thạch hay trí thức Công giáo Nguyễn Mạnh Hà — cùng tham gia Chính phủ đã giúp tạo dựng ngay từ đầu hình ảnh một nhà nước của khối đại đoàn kết toàn dân tộc, chứ không phải của riêng một lực lượng chính trị."},{"t":"Cũng tại căn nhà 48 Hàng Ngang những ngày ấy, nhiều cuộc gặp gỡ, trao đổi khác giữa Chủ tịch Hồ Chí Minh với các cộng sự, các nhân sĩ được mời tham gia chính quyền mới cũng diễn ra bên những chiếc bàn tương tự — cho thấy một guồng máy làm việc khẩn trương, nơi các quyết định lớn được bàn bạc, thống nhất trong một không gian gia đình bình dị, xa cách hẳn với hình dung thông thường về một dinh thự hay công sở."},{"t":"Bạn có biết? Chỉ trong vòng tám ngày, từ 25 tháng 8 đến 2 tháng 9 năm 1945, thành phần Chính phủ lâm thời được công bố, bản Tuyên ngôn Độc lập được hoàn thành và một buổi lễ cho hàng chục vạn người được chuẩn bị xong."}],"ban_co_biet":"Chỉ trong vòng tám ngày, từ 25 tháng 8 đến 2 tháng 9 năm 1945, thành phần Chính phủ lâm thời được công bố, bản Tuyên ngôn Độc lập được hoàn thành và một buổi lễ cho hàng chục vạn người được chuẩn bị xong."},{"id":"desk_lamp_arm_01@10.6,70.1","x":10.6,"y":1,"z":70.1,"loai":"desk_lamp_arm_01","ten":"Đèn bàn (phục dựng)","tieu_de":"Ngọn đèn của những ngày làm việc không nghỉ","text":"Chiếc đèn bàn có cánh tay điều chỉnh được, chao đèn nhỏ hình chóp, đặt cạnh bàn viết trong căn phòng phục dựng, là hình ảnh quen thuộc của một góc làm việc ban đêm giữa thế kỷ 20 — khi ấy Hà Nội đã có mạng lưới điện, nhưng nguồn điện tại các khu phố buôn bán vẫn thường chập chờn, và ánh đèn dầu hay đèn bàn nhỏ vẫn là chỗ dựa quen thuộc cho những ai phải thức khuya với giấy bút. Đây cũng là một đồ vật phục dựng, dùng để gợi không khí làm việc chứ không phải vật dụng nguyên gốc từ năm 1945.\n\nNhững ngày cuối tháng 8 năm 1945, lịch làm việc của Chủ tịch Hồ Chí Minh trên căn gác nhà 48 Hàng Ngang gần như không có ranh giới giữa ngày và đêm. Ban ngày là những cuộc gặp gỡ, trao đổi với các cộng sự, chuẩn bị nhân sự cho Chính phủ lâm thời; ban đêm là những giờ ngồi một mình bên trang bản thảo, chỉnh sửa từng câu chữ của văn kiện sẽ được đọc trước quốc dân. Ánh đèn trên bàn viết, vì thế, gắn liền với hình ảnh một người vừa gánh trọng trách lãnh đạo một chính quyền cách mạng non trẻ, vừa trực tiếp cầm bút viết nên văn kiện lập quốc.\n\nNhịp làm việc dồn dập ấy có thể hình dung qua chuỗi sự kiện dồn nén trong chưa đầy hai tuần: ngày 25 tháng 8, Người về tới Hà Nội sau khi rời chiến khu Việt Bắc; ngày 26 tháng 8, chủ trì họp Ban Thường vụ Trung ương Đảng; ngày 28 tháng 8, thành phần Chính phủ lâm thời được công bố, cùng lúc bản thảo Tuyên ngôn Độc lập được hoàn thiện trong hai ngày 28 và 29; và chiều Chủ nhật 2 tháng 9, bản Tuyên ngôn ấy được đọc trước hàng chục vạn đồng bào tại Quảng trường Ba Đình. Chỉ tám ngày, một chính phủ được thành lập, một văn kiện lập quốc được viết xong, và một buổi lễ trọng đại được chuẩn bị chu đáo.\n\nKhông có tư liệu nào mô tả cụ thể kiểu dáng ngọn đèn được dùng trên bàn làm việc của Người tại 48 Hàng Ngang; chi tiết này, cũng như chiếc bàn viết, được phục dựng dựa trên hình dung chung về đồ dùng văn phòng thời kỳ đó, nhằm tái hiện không khí một góc làm việc giản dị nhưng khẩn trương, nơi đã ra đời một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại.\n\nTrong không gian phục dựng của gian trưng bày, ngọn đèn bàn nhỏ ấy — cùng chiếc bàn viết bên dưới nó — là lời nhắc rằng đằng sau một sự kiện trọng đại được ghi trong sách sử, luôn có những giờ làm việc thầm lặng, đơn độc và bền bỉ của một con người.\n\nÍt lâu sau khi bản Tuyên ngôn Độc lập được đọc lên, cũng chính Chủ tịch Hồ Chí Minh là người đặt việc chống nạn mù chữ vào hàng những nhiệm vụ cấp bách nhất của chính quyền cách mạng. Trên khắp cả nước, khi ấy hơn chín phần mười dân số chưa biết chữ, hàng vạn ngọn đèn dầu khác cũng được thắp lên mỗi tối tại các lớp bình dân học vụ, nơi người biết chữ dạy cho người chưa biết, \"vợ chưa biết thì chồng bảo\". Ngọn đèn trên bàn làm việc của Người ở 48 Hàng Ngang, vì thế, có thể xem như một trong những ngọn đèn đầu tiên của một phong trào ánh sáng tri thức lan rộng khắp đất nước ngay sau ngày độc lập.","nguon":"Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Ngọn đèn của những ngày làm việc không nghỉ. Chiếc đèn bàn có cánh tay điều chỉnh được, chao đèn nhỏ hình chóp, đặt cạnh bàn viết trong căn phòng phục dựng, là hình ảnh quen thuộc của một góc làm việc ban đêm giữa thế kỷ 20 — khi ấy Hà Nội đã có mạng lưới điện, nhưng nguồn điện tại các khu phố buôn bán vẫn thường chập chờn, và ánh đèn dầu hay đèn bàn nhỏ vẫn là chỗ dựa quen thuộc cho những ai phải thức khuya với giấy bút. Đây cũng là một đồ vật phục dựng, dùng để gợi không khí làm việc chứ không phải vật dụng nguyên gốc từ năm 1945."},{"t":"Những ngày cuối tháng 8 năm 1945, lịch làm việc của Chủ tịch Hồ Chí Minh trên căn gác nhà 48 Hàng Ngang gần như không có ranh giới giữa ngày và đêm. Ban ngày là những cuộc gặp gỡ, trao đổi với các cộng sự, chuẩn bị nhân sự cho Chính phủ lâm thời; ban đêm là những giờ ngồi một mình bên trang bản thảo, chỉnh sửa từng câu chữ của văn kiện sẽ được đọc trước quốc dân. Ánh đèn trên bàn viết, vì thế, gắn liền với hình ảnh một người vừa gánh trọng trách lãnh đạo một chính quyền cách mạng non trẻ, vừa trực tiếp cầm bút viết nên văn kiện lập quốc."},{"t":"Nhịp làm việc dồn dập ấy có thể hình dung qua chuỗi sự kiện dồn nén trong chưa đầy hai tuần: ngày 25 tháng 8, Người về tới Hà Nội sau khi rời chiến khu Việt Bắc; ngày 26 tháng 8, chủ trì họp Ban Thường vụ Trung ương Đảng; ngày 28 tháng 8, thành phần Chính phủ lâm thời được công bố, cùng lúc bản thảo Tuyên ngôn Độc lập được hoàn thiện trong hai ngày 28 và 29; và chiều Chủ nhật 2 tháng 9, bản Tuyên ngôn ấy được đọc trước hàng chục vạn đồng bào tại Quảng trường Ba Đình. Chỉ tám ngày, một chính phủ được thành lập, một văn kiện lập quốc được viết xong, và một buổi lễ trọng đại được chuẩn bị chu đáo."},{"t":"Không có tư liệu nào mô tả cụ thể kiểu dáng ngọn đèn được dùng trên bàn làm việc của Người tại 48 Hàng Ngang; chi tiết này, cũng như chiếc bàn viết, được phục dựng dựa trên hình dung chung về đồ dùng văn phòng thời kỳ đó, nhằm tái hiện không khí một góc làm việc giản dị nhưng khẩn trương, nơi đã ra đời một trong những văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại."},{"t":"Trong không gian phục dựng của gian trưng bày, ngọn đèn bàn nhỏ ấy — cùng chiếc bàn viết bên dưới nó — là lời nhắc rằng đằng sau một sự kiện trọng đại được ghi trong sách sử, luôn có những giờ làm việc thầm lặng, đơn độc và bền bỉ của một con người."},{"t":"Ít lâu sau khi bản Tuyên ngôn Độc lập được đọc lên, cũng chính Chủ tịch Hồ Chí Minh là người đặt việc chống nạn mù chữ vào hàng những nhiệm vụ cấp bách nhất của chính quyền cách mạng. Trên khắp cả nước, khi ấy hơn chín phần mười dân số chưa biết chữ, hàng vạn ngọn đèn dầu khác cũng được thắp lên mỗi tối tại các lớp bình dân học vụ, nơi người biết chữ dạy cho người chưa biết, \"vợ chưa biết thì chồng bảo\". Ngọn đèn trên bàn làm việc của Người ở 48 Hàng Ngang, vì thế, có thể xem như một trong những ngọn đèn đầu tiên của một phong trào ánh sáng tri thức lan rộng khắp đất nước ngay sau ngày độc lập."}]},{"id":"vintage_grandfather_clock_01@12.2,68.5","x":12.22,"y":0.26,"z":68.45,"loai":"vintage_grandfather_clock_01","ten":"Đồng hồ đứng (phục dựng)","tieu_de":"Tám ngày lập quốc","text":"Chiếc đồng hồ quả lắc đứng, thân gỗ cao gần chạm trần, mặt số tròn viền kim loại, là loại đồ nội thất thường thấy trong phòng khách những gia đình khá giả ở Hà Nội đầu thế kỷ 20 — vừa để xem giờ, vừa là vật trang trí thể hiện sự sung túc của chủ nhà. Đặt trong căn phòng phục dựng của gian trưng bày, chiếc đồng hồ này không phải hiện vật gốc, mà được dựng lại để gợi lại nhịp thời gian gấp gáp của những ngày cuối tháng 8 năm 1945 tại nhà số 48 Hàng Ngang.\n\nNếu có thể đếm ngược theo tiếng tích tắc của một chiếc đồng hồ như thế, người ta sẽ thấy đó là những ngày dồn nén hiếm có trong lịch sử: ngày 25 tháng 8, Chủ tịch Hồ Chí Minh về tới Hà Nội sau khi rời chiến khu Việt Bắc, được bố trí ở tại căn gác hai nhà 48 Hàng Ngang; ngày 26 tháng 8, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng ngay tại ngôi nhà này, thống nhất chuẩn bị Tuyên ngôn Độc lập và mở rộng thành phần Chính phủ; ngày 28 tháng 8, thành phần Chính phủ lâm thời mở rộng được công bố, cùng lúc Người dành hai ngày 28 và 29 để hoàn thành bản thảo Tuyên ngôn Độc lập; ngày 30 tháng 8, tại Huế, vua Bảo Đại tuyên bố thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời, chính thức chấm dứt chế độ quân chủ tồn tại hàng nghìn năm ở Việt Nam.\n\nVà rồi đến chiều Chủ nhật, ngày 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, trước hàng chục vạn đồng bào, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa — nhà nước công nông đầu tiên ở Đông Nam Á. Tính từ ngày Người đặt chân về Hà Nội đến buổi chiều lịch sử ấy, vỏn vẹn chỉ có tám ngày.\n\nTám ngày ấy không chỉ có ý nghĩa biểu tượng, mà còn cho thấy cường độ làm việc phi thường của một bộ máy lãnh đạo cách mạng còn rất mỏng về nhân lực, vừa phải lo đối nội, đối ngoại, an ninh trật tự, vừa phải chuẩn bị chu đáo cho một buổi lễ có ý nghĩa lịch sử trọng đại, với sự tham dự của hàng chục vạn người. Không có nhiều thời gian để chần chừ hay do dự — mọi quyết định đều phải đưa ra nhanh và đúng.\n\nTrong gian trưng bày, chiếc đồng hồ đứng phục dựng, đặt lặng lẽ trong góc căn phòng tái hiện không gian làm việc năm xưa, như một cách nhắc người xem về giá trị của những tháng ngày ấy: một dân tộc, chỉ trong chưa đầy hai tuần, đã tự đứng lên giành lấy quyền làm chủ vận mệnh của chính mình.\n\nNếu kim đồng hồ ấy tiếp tục quay qua những tháng năm sau đó, nó sẽ còn điểm thêm nhiều mốc quan trọng khác của chính quyền non trẻ: ngày 6 tháng 1 năm 1946, cuộc Tổng tuyển cử đầu tiên trong lịch sử dân tộc được tổ chức trên cả nước; ngày 6 tháng 3 năm 1946, Chủ tịch Hồ Chí Minh ký với đại diện Pháp bản Hiệp định Sơ bộ, tranh thủ thời gian hòa hoãn quý giá; và đêm 19 tháng 12 năm 1946, Người ra Lời kêu gọi toàn quốc kháng chiến, mở đầu chặng đường kháng chiến trường kỳ để bảo vệ chính nền độc lập vừa giành được tám ngày trước đó tại Quảng trường Ba Đình. Từ một căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, dòng thời gian ấy đã kéo dài thành cả một giai đoạn lịch sử đầy biến động của dân tộc.","nguon":"Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Tám ngày lập quốc. Chiếc đồng hồ quả lắc đứng, thân gỗ cao gần chạm trần, mặt số tròn viền kim loại, là loại đồ nội thất thường thấy trong phòng khách những gia đình khá giả ở Hà Nội đầu thế kỷ 20 — vừa để xem giờ, vừa là vật trang trí thể hiện sự sung túc của chủ nhà. Đặt trong căn phòng phục dựng của gian trưng bày, chiếc đồng hồ này không phải hiện vật gốc, mà được dựng lại để gợi lại nhịp thời gian gấp gáp của những ngày cuối tháng 8 năm 1945 tại nhà số 48 Hàng Ngang."},{"t":"Nếu có thể đếm ngược theo tiếng tích tắc của một chiếc đồng hồ như thế, người ta sẽ thấy đó là những ngày dồn nén hiếm có trong lịch sử: ngày 25 tháng 8, Chủ tịch Hồ Chí Minh về tới Hà Nội sau khi rời chiến khu Việt Bắc, được bố trí ở tại căn gác hai nhà 48 Hàng Ngang; ngày 26 tháng 8, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng ngay tại ngôi nhà này, thống nhất chuẩn bị Tuyên ngôn Độc lập và mở rộng thành phần Chính phủ; ngày 28 tháng 8, thành phần Chính phủ lâm thời mở rộng được công bố, cùng lúc Người dành hai ngày 28 và 29 để hoàn thành bản thảo Tuyên ngôn Độc lập; ngày 30 tháng 8, tại Huế, vua Bảo Đại tuyên bố thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời, chính thức chấm dứt chế độ quân chủ tồn tại hàng nghìn năm ở Việt Nam."},{"t":"Và rồi đến chiều Chủ nhật, ngày 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, trước hàng chục vạn đồng bào, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa — nhà nước công nông đầu tiên ở Đông Nam Á. Tính từ ngày Người đặt chân về Hà Nội đến buổi chiều lịch sử ấy, vỏn vẹn chỉ có tám ngày."},{"t":"Tám ngày ấy không chỉ có ý nghĩa biểu tượng, mà còn cho thấy cường độ làm việc phi thường của một bộ máy lãnh đạo cách mạng còn rất mỏng về nhân lực, vừa phải lo đối nội, đối ngoại, an ninh trật tự, vừa phải chuẩn bị chu đáo cho một buổi lễ có ý nghĩa lịch sử trọng đại, với sự tham dự của hàng chục vạn người. Không có nhiều thời gian để chần chừ hay do dự — mọi quyết định đều phải đưa ra nhanh và đúng."},{"t":"Trong gian trưng bày, chiếc đồng hồ đứng phục dựng, đặt lặng lẽ trong góc căn phòng tái hiện không gian làm việc năm xưa, như một cách nhắc người xem về giá trị của những tháng ngày ấy: một dân tộc, chỉ trong chưa đầy hai tuần, đã tự đứng lên giành lấy quyền làm chủ vận mệnh của chính mình."},{"t":"Nếu kim đồng hồ ấy tiếp tục quay qua những tháng năm sau đó, nó sẽ còn điểm thêm nhiều mốc quan trọng khác của chính quyền non trẻ: ngày 6 tháng 1 năm 1946, cuộc Tổng tuyển cử đầu tiên trong lịch sử dân tộc được tổ chức trên cả nước; ngày 6 tháng 3 năm 1946, Chủ tịch Hồ Chí Minh ký với đại diện Pháp bản Hiệp định Sơ bộ, tranh thủ thời gian hòa hoãn quý giá; và đêm 19 tháng 12 năm 1946, Người ra Lời kêu gọi toàn quốc kháng chiến, mở đầu chặng đường kháng chiến trường kỳ để bảo vệ chính nền độc lập vừa giành được tám ngày trước đó tại Quảng trường Ba Đình. Từ một căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, dòng thời gian ấy đã kéo dài thành cả một giai đoạn lịch sử đầy biến động của dân tộc."},{"t":"Bạn có biết? Ngày 30 tháng 8 năm 1945, cùng thời điểm bản Tuyên ngôn Độc lập đang được hoàn tất tại Hà Nội, vua Bảo Đại tuyên bố thoái vị tại Huế, chấm dứt chế độ quân chủ ở Việt Nam."}],"ban_co_biet":"Ngày 30 tháng 8 năm 1945, cùng thời điểm bản Tuyên ngôn Độc lập đang được hoàn tất tại Hà Nội, vua Bảo Đại tuyên bố thoái vị tại Huế, chấm dứt chế độ quân chủ ở Việt Nam."},{"id":"bookshelf@12.2,67.2","x":12.2,"y":0.22,"z":67.2,"loai":"bookshelf","ten":"Tủ sách (phục dựng)","tieu_de":"Hai bản tuyên ngôn được trích dẫn","text":"Chiếc tủ sách gỗ với những ngăn kệ xếp đầy sách báo, đặt trong góc phòng phục dựng, gợi lại hình ảnh một không gian làm việc trí thức những năm 1940 — nơi sách vở không chỉ để trang trí mà là công cụ tra cứu, đối chiếu trong quá trình viết lách. Đây là đồ vật phục dựng mang tính biểu tượng, không phải bản sao của một tủ sách có thật từng đặt tại nhà 48 Hàng Ngang.\n\nBản Tuyên ngôn Độc lập mà Chủ tịch Hồ Chí Minh viết trong hai ngày 28 và 29 tháng 8 năm 1945 mở đầu bằng một lựa chọn đầy dụng ý: trích dẫn nguyên văn một đoạn trong Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ, rằng mọi người sinh ra đều có quyền bình đẳng, quyền sống, quyền tự do và quyền mưu cầu hạnh phúc; tiếp đó là Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, về quyền tự do và quyền bình đẳng của con người. Từ hai bản tuyên ngôn nổi tiếng của thế giới ấy, Người \"suy rộng ra\" thành một luận điểm mới: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.\n\nCách lập luận ấy cho thấy một vốn hiểu biết sâu rộng về lịch sử, chính trị và văn hóa phương Tây — điều mà Người đã tích lũy qua ba mươi năm bôn ba tìm đường cứu nước, sống và hoạt động ở nhiều quốc gia, tiếp xúc với nhiều nền văn hóa, nhiều trào lưu tư tưởng khác nhau. Việc trích dẫn hai văn kiện lập quốc nổi tiếng của Mỹ và Pháp — hai cường quốc có quan hệ trực tiếp với vận mệnh Việt Nam đương thời — không chỉ là một thủ pháp lập luận sắc bén, mà còn đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại, khiến bản Tuyên ngôn có sức thuyết phục vượt ra ngoài biên giới Việt Nam.\n\nTiếp sau phần mở đầu mang tính lý luận ấy, bản Tuyên ngôn Độc lập chuyển sang phần cáo trạng, vạch rõ những tội ác của thực dân Pháp trong suốt hơn tám mươi năm đô hộ, trước khi khẳng định quyền độc lập, tự do của dân tộc Việt Nam và khép lại bằng lời thề của toàn dân tộc. Một văn kiện chỉ gồm vài trang giấy, nhưng cô đọng trong đó là lý lẽ pháp lý, chứng cứ lịch sử và khát vọng của cả một dân tộc.\n\nChiếc tủ sách trong gian trưng bày, vì thế, không chỉ là một món đồ nội thất phục dựng, mà là một cách gợi nhắc: đằng sau mỗi câu chữ của bản Tuyên ngôn Độc lập là cả một nền tảng tri thức được bồi đắp bền bỉ suốt nhiều năm tháng.\n\nCâu kết của bản Tuyên ngôn — lời khẳng định toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần, lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập — không chỉ là một tuyên bố trang trọng, mà thực sự là một lời thề của cả dân tộc. Chưa đầy một năm rưỡi sau, khi thực dân Pháp trở lại gây hấn và Chủ tịch Hồ Chí Minh phải ra Lời kêu gọi toàn quốc kháng chiến vào đêm 19 tháng 12 năm 1946, lời thề ấy đã được thử thách bằng chính những năm tháng kháng chiến gian khổ của cả dân tộc. Điều đó cho thấy bản Tuyên ngôn không chỉ là văn bản pháp lý tuyên bố độc lập, mà còn là lời cam kết mà cả một dân tộc đã phải đổ máu để gìn giữ trong nhiều năm sau đó.","nguon":"Tuyên ngôn Độc lập, 2/9/1945 — Hồ Chí Minh Toàn tập, tập 4; hochiminh.vn","doc":[{"t":"Hai bản tuyên ngôn được trích dẫn. Chiếc tủ sách gỗ với những ngăn kệ xếp đầy sách báo, đặt trong góc phòng phục dựng, gợi lại hình ảnh một không gian làm việc trí thức những năm 1940 — nơi sách vở không chỉ để trang trí mà là công cụ tra cứu, đối chiếu trong quá trình viết lách. Đây là đồ vật phục dựng mang tính biểu tượng, không phải bản sao của một tủ sách có thật từng đặt tại nhà 48 Hàng Ngang."},{"t":"Bản Tuyên ngôn Độc lập mà Chủ tịch Hồ Chí Minh viết trong hai ngày 28 và 29 tháng 8 năm 1945 mở đầu bằng một lựa chọn đầy dụng ý: trích dẫn nguyên văn một đoạn trong Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ, rằng mọi người sinh ra đều có quyền bình đẳng, quyền sống, quyền tự do và quyền mưu cầu hạnh phúc; tiếp đó là Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, về quyền tự do và quyền bình đẳng của con người. Từ hai bản tuyên ngôn nổi tiếng của thế giới ấy, Người \"suy rộng ra\" thành một luận điểm mới: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do."},{"t":"Cách lập luận ấy cho thấy một vốn hiểu biết sâu rộng về lịch sử, chính trị và văn hóa phương Tây — điều mà Người đã tích lũy qua ba mươi năm bôn ba tìm đường cứu nước, sống và hoạt động ở nhiều quốc gia, tiếp xúc với nhiều nền văn hóa, nhiều trào lưu tư tưởng khác nhau. Việc trích dẫn hai văn kiện lập quốc nổi tiếng của Mỹ và Pháp — hai cường quốc có quan hệ trực tiếp với vận mệnh Việt Nam đương thời — không chỉ là một thủ pháp lập luận sắc bén, mà còn đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại, khiến bản Tuyên ngôn có sức thuyết phục vượt ra ngoài biên giới Việt Nam."},{"t":"Tiếp sau phần mở đầu mang tính lý luận ấy, bản Tuyên ngôn Độc lập chuyển sang phần cáo trạng, vạch rõ những tội ác của thực dân Pháp trong suốt hơn tám mươi năm đô hộ, trước khi khẳng định quyền độc lập, tự do của dân tộc Việt Nam và khép lại bằng lời thề của toàn dân tộc. Một văn kiện chỉ gồm vài trang giấy, nhưng cô đọng trong đó là lý lẽ pháp lý, chứng cứ lịch sử và khát vọng của cả một dân tộc."},{"t":"Chiếc tủ sách trong gian trưng bày, vì thế, không chỉ là một món đồ nội thất phục dựng, mà là một cách gợi nhắc: đằng sau mỗi câu chữ của bản Tuyên ngôn Độc lập là cả một nền tảng tri thức được bồi đắp bền bỉ suốt nhiều năm tháng."},{"t":"Câu kết của bản Tuyên ngôn — lời khẳng định toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần, lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập — không chỉ là một tuyên bố trang trọng, mà thực sự là một lời thề của cả dân tộc. Chưa đầy một năm rưỡi sau, khi thực dân Pháp trở lại gây hấn và Chủ tịch Hồ Chí Minh phải ra Lời kêu gọi toàn quốc kháng chiến vào đêm 19 tháng 12 năm 1946, lời thề ấy đã được thử thách bằng chính những năm tháng kháng chiến gian khổ của cả dân tộc. Điều đó cho thấy bản Tuyên ngôn không chỉ là văn bản pháp lý tuyên bố độc lập, mà còn là lời cam kết mà cả một dân tộc đã phải đổ máu để gìn giữ trong nhiều năm sau đó."},{"t":"Bạn có biết? Bản Tuyên ngôn Độc lập của Việt Nam là một trong số ít văn kiện lập quốc trên thế giới mở đầu bằng cách trích dẫn nguyên văn hai bản tuyên ngôn nổi tiếng của hai quốc gia khác — Hoa Kỳ và Pháp."}],"ban_co_biet":"Bản Tuyên ngôn Độc lập của Việt Nam là một trong số ít văn kiện lập quốc trên thế giới mở đầu bằng cách trích dẫn nguyên văn hai bản tuyên ngôn nổi tiếng của hai quốc gia khác — Hoa Kỳ và Pháp."},{"id":"vintage_day_bed@7.9,67.0","x":7.9,"y":0.26,"z":66.95,"loai":"vintage_day_bed","ten":"Giường nghỉ (phục dựng)","tieu_de":"Căn gác vừa ở vừa làm việc","text":"Chiếc giường nghỉ nhỏ, khung gỗ đơn giản, kê sát vách trong căn phòng phục dựng, nhắc người xem rằng căn gác hai nhà 48 Hàng Ngang trong những ngày cuối tháng 8 năm 1945 không phải một văn phòng theo nghĩa thông thường, mà vừa là chỗ ở, vừa là nơi làm việc, hội họp của Chủ tịch Hồ Chí Minh và các cộng sự thân cận. Đây là đồ vật phục dựng, dựng lại để gợi không khí sinh hoạt giản dị của căn phòng, không phải hiện vật nguyên bản.\n\nChỉ vài tuần trước khi về tới Hà Nội, tại lán Nà Lừa ở Tân Trào, Chủ tịch Hồ Chí Minh vừa trải qua một trận ốm rất nặng, có những lúc tưởng chừng nguy kịch, khiến các đồng chí xung quanh hết sức lo lắng. Vậy mà chỉ ít lâu sau khi bình phục, Người đã lên đường về Hà Nội, và ngay khi đặt chân tới căn gác nhỏ trên phố Hàng Ngang, đã bắt tay ngay vào một khối lượng công việc đồ sộ: họp bàn với Trung ương Đảng, chuẩn bị nhân sự cho Chính phủ lâm thời, tiếp các nhân sĩ, trí thức, và trực tiếp soạn thảo bản Tuyên ngôn Độc lập.\n\nNhiều người từng có dịp gần gũi, làm việc cùng Người trong giai đoạn này sau đó kể lại, qua các hồi ký được công bố, về một nếp sống hết sức giản dị: bữa ăn đơn sơ, giờ nghỉ ngơi ít ỏi, phần lớn thời gian dành cho công việc chung. Căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang — vốn là một phần không gian sinh hoạt của gia đình chủ nhà buôn tơ lụa — trong ít ngày đã trở thành trung tâm của những quyết định làm thay đổi vận mệnh một dân tộc, mà không hề có sự khác biệt lớn giữa nơi Người nghỉ ngơi và nơi Người làm việc.\n\nSự giản dị ấy càng có ý nghĩa khi đặt bên cạnh tầm vóc của những việc được quyết định tại chính căn phòng này: một bản Tuyên ngôn Độc lập làm thay đổi vị thế của cả một dân tộc trên bản đồ thế giới, một Chính phủ lâm thời được mở rộng để quy tụ sức mạnh đoàn kết toàn dân, và một buổi lễ trọng đại được chuẩn bị chỉ trong vài ngày ngắn ngủi. Tất cả đều bắt đầu từ một căn phòng nhỏ, giản dị, nơi ranh giới giữa chỗ ở và nơi làm việc gần như không tồn tại.\n\nChiếc giường nghỉ phục dựng trong gian trưng bày, đặt cạnh bàn viết và bàn họp, giúp người xem hình dung trọn vẹn hơn về nhịp sống của những ngày lịch sử ấy — không phải một văn phòng trang nghiêm biệt lập, mà là một góc sinh hoạt gia đình bình dị, nơi một con người vừa dưỡng sức sau cơn bệnh nặng, vừa từng giờ từng phút chuẩn bị cho sự ra đời của một quốc gia.\n\nGia đình đã dành căn gác của mình cho Chủ tịch Hồ Chí Minh nghỉ ngơi và làm việc — ông bà Trịnh Văn Bô và Hoàng Thị Minh Hồ, chủ hiệu tơ lụa Phúc Lợi — sau này còn tiếp tục gắn bó với chính quyền cách mạng non trẻ theo một cách khác: trong phong trào Tuần lễ Vàng phát động tháng 9 năm 1945 để quyên góp cho ngân khố quốc gia gần như trống rỗng, gia đình ông bà đã đóng góp một số lượng vàng rất lớn. Từ một căn phòng nhỏ cho mượn để nghỉ ngơi và làm việc, đến việc hiến vàng cho đất nước, đó là hình ảnh tiêu biểu cho tinh thần của nhiều gia đình tư sản dân tộc Hà Nội trong những ngày đầu chính quyền cách mạng còn non trẻ.","nguon":"Hồ Chí Minh – Biên niên tiểu sử; Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký)","doc":[{"t":"Căn gác vừa ở vừa làm việc. Chiếc giường nghỉ nhỏ, khung gỗ đơn giản, kê sát vách trong căn phòng phục dựng, nhắc người xem rằng căn gác hai nhà 48 Hàng Ngang trong những ngày cuối tháng 8 năm 1945 không phải một văn phòng theo nghĩa thông thường, mà vừa là chỗ ở, vừa là nơi làm việc, hội họp của Chủ tịch Hồ Chí Minh và các cộng sự thân cận. Đây là đồ vật phục dựng, dựng lại để gợi không khí sinh hoạt giản dị của căn phòng, không phải hiện vật nguyên bản."},{"t":"Chỉ vài tuần trước khi về tới Hà Nội, tại lán Nà Lừa ở Tân Trào, Chủ tịch Hồ Chí Minh vừa trải qua một trận ốm rất nặng, có những lúc tưởng chừng nguy kịch, khiến các đồng chí xung quanh hết sức lo lắng. Vậy mà chỉ ít lâu sau khi bình phục, Người đã lên đường về Hà Nội, và ngay khi đặt chân tới căn gác nhỏ trên phố Hàng Ngang, đã bắt tay ngay vào một khối lượng công việc đồ sộ: họp bàn với Trung ương Đảng, chuẩn bị nhân sự cho Chính phủ lâm thời, tiếp các nhân sĩ, trí thức, và trực tiếp soạn thảo bản Tuyên ngôn Độc lập."},{"t":"Nhiều người từng có dịp gần gũi, làm việc cùng Người trong giai đoạn này sau đó kể lại, qua các hồi ký được công bố, về một nếp sống hết sức giản dị: bữa ăn đơn sơ, giờ nghỉ ngơi ít ỏi, phần lớn thời gian dành cho công việc chung. Căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang — vốn là một phần không gian sinh hoạt của gia đình chủ nhà buôn tơ lụa — trong ít ngày đã trở thành trung tâm của những quyết định làm thay đổi vận mệnh một dân tộc, mà không hề có sự khác biệt lớn giữa nơi Người nghỉ ngơi và nơi Người làm việc."},{"t":"Sự giản dị ấy càng có ý nghĩa khi đặt bên cạnh tầm vóc của những việc được quyết định tại chính căn phòng này: một bản Tuyên ngôn Độc lập làm thay đổi vị thế của cả một dân tộc trên bản đồ thế giới, một Chính phủ lâm thời được mở rộng để quy tụ sức mạnh đoàn kết toàn dân, và một buổi lễ trọng đại được chuẩn bị chỉ trong vài ngày ngắn ngủi. Tất cả đều bắt đầu từ một căn phòng nhỏ, giản dị, nơi ranh giới giữa chỗ ở và nơi làm việc gần như không tồn tại."},{"t":"Chiếc giường nghỉ phục dựng trong gian trưng bày, đặt cạnh bàn viết và bàn họp, giúp người xem hình dung trọn vẹn hơn về nhịp sống của những ngày lịch sử ấy — không phải một văn phòng trang nghiêm biệt lập, mà là một góc sinh hoạt gia đình bình dị, nơi một con người vừa dưỡng sức sau cơn bệnh nặng, vừa từng giờ từng phút chuẩn bị cho sự ra đời của một quốc gia."},{"t":"Gia đình đã dành căn gác của mình cho Chủ tịch Hồ Chí Minh nghỉ ngơi và làm việc — ông bà Trịnh Văn Bô và Hoàng Thị Minh Hồ, chủ hiệu tơ lụa Phúc Lợi — sau này còn tiếp tục gắn bó với chính quyền cách mạng non trẻ theo một cách khác: trong phong trào Tuần lễ Vàng phát động tháng 9 năm 1945 để quyên góp cho ngân khố quốc gia gần như trống rỗng, gia đình ông bà đã đóng góp một số lượng vàng rất lớn. Từ một căn phòng nhỏ cho mượn để nghỉ ngơi và làm việc, đến việc hiến vàng cho đất nước, đó là hình ảnh tiêu biểu cho tinh thần của nhiều gia đình tư sản dân tộc Hà Nội trong những ngày đầu chính quyền cách mạng còn non trẻ."}]},{"id":"ArmChair_01@8.7,71.0","x":8.7,"y":0.26,"z":70.95,"loai":"ArmChair_01","ten":"Ghế tiếp khách (phục dựng)","tieu_de":"Mời người tài đức cùng gánh việc nước","text":"Chiếc ghế tựa bọc đệm, tay vịn gỗ, được kê trong góc tiếp khách của căn phòng phục dựng, gợi lại không gian nơi Chủ tịch Hồ Chí Minh đã tiếp nhiều nhân sĩ, trí thức trong những ngày chuẩn bị thành lập Chính phủ lâm thời tại Hà Nội cuối tháng 8 năm 1945. Cũng như những đồ nội thất khác trong gian phục dựng, đây không phải hiện vật gốc mà là vật dụng mang tính gợi tả không gian.\n\nMột trong những đặc điểm nổi bật của Chính phủ lâm thời được công bố ngày 28 tháng 8 năm 1945 là thành phần hết sức rộng rãi, vượt ra ngoài khuôn khổ những người từng tham gia Mặt trận Việt Minh. Bên cạnh các chiến sĩ cách mạng kỳ cựu, Chủ tịch Hồ Chí Minh đã mời nhiều nhân sĩ, trí thức có uy tín thuộc nhiều xu hướng chính trị, tôn giáo khác nhau cùng tham gia gánh vác việc nước: học giả Nguyễn Văn Tố phụ trách Bộ Cứu tế xã hội, luật sư Vũ Trọng Khánh giữ chức Bộ trưởng Bộ Tư pháp, bác sĩ Phạm Ngọc Thạch phụ trách Bộ Y tế, ông Nguyễn Mạnh Hà — một trí thức Công giáo — giữ chức Bộ trưởng Bộ Kinh tế quốc dân.\n\nViệc mời gọi những người ngoài Việt Minh, thậm chí từng có quan điểm khác biệt, cùng tham gia chính quyền là một chủ trương có chủ đích rõ ràng: xây dựng một Chính phủ đại diện cho khối đại đoàn kết toàn dân tộc ngay từ những ngày đầu lập quốc, thay vì một chính quyền của riêng một đảng phái hay một lực lượng chính trị. Trong bối cảnh đất nước vừa thoát khỏi ách đô hộ, đứng trước muôn vàn khó khăn về đối nội lẫn đối ngoại, sự đoàn kết rộng rãi ấy có ý nghĩa sống còn đối với việc củng cố chính quyền cách mạng còn non trẻ.\n\nNhững cuộc tiếp xúc, mời gọi nhân sĩ, trí thức tham gia Chính phủ diễn ra dồn dập trong những ngày Chủ tịch Hồ Chí Minh ở tại nhà 48 Hàng Ngang — bên cạnh khối lượng công việc soạn thảo Tuyên ngôn Độc lập và chuẩn bị cho lễ Độc lập. Chỉ trong vài ngày ngắn ngủi, một nội các đa dạng về thành phần nhưng thống nhất về mục tiêu đã được hình thành, trở thành nền móng đầu tiên của bộ máy nhà nước Việt Nam Dân chủ Cộng hòa.\n\nChiếc ghế tiếp khách phục dựng trong gian trưng bày, đặt đối diện với góc bàn làm việc, là một cách nhắc lại tinh thần ấy: một chính quyền cách mạng mới ra đời, nhưng ngay từ đầu đã biết mở rộng vòng tay, quy tụ người tài đức khắp mọi giới để cùng chung sức dựng xây đất nước.\n\nKhông phải mọi thành viên Chính phủ lâm thời đều là gương mặt mới gặp lần đầu trên chiếc ghế ấy. Bên cạnh những nhân sĩ, trí thức được mời tham gia, có những cộng sự đã sát cánh cùng Chủ tịch Hồ Chí Minh từ trước, như ông Võ Nguyên Giáp, khi đó giữ chức Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời — người đã gặp Người lần đầu tại Côn Minh (Trung Quốc) từ năm năm trước đó. Sự kết hợp giữa những gương mặt quen thuộc của cách mạng và những nhân sĩ, trí thức mới được mời gọi, cùng ngồi lại bàn việc nước ngay trong căn phòng nhỏ này, chính là hình ảnh thu nhỏ của một Chính phủ liên hiệp, đoàn kết rộng rãi mà Chủ tịch Hồ Chí Minh chủ trương xây dựng ngay từ những ngày đầu lập quốc.","nguon":"Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Mời người tài đức cùng gánh việc nước. Chiếc ghế tựa bọc đệm, tay vịn gỗ, được kê trong góc tiếp khách của căn phòng phục dựng, gợi lại không gian nơi Chủ tịch Hồ Chí Minh đã tiếp nhiều nhân sĩ, trí thức trong những ngày chuẩn bị thành lập Chính phủ lâm thời tại Hà Nội cuối tháng 8 năm 1945. Cũng như những đồ nội thất khác trong gian phục dựng, đây không phải hiện vật gốc mà là vật dụng mang tính gợi tả không gian."},{"t":"Một trong những đặc điểm nổi bật của Chính phủ lâm thời được công bố ngày 28 tháng 8 năm 1945 là thành phần hết sức rộng rãi, vượt ra ngoài khuôn khổ những người từng tham gia Mặt trận Việt Minh. Bên cạnh các chiến sĩ cách mạng kỳ cựu, Chủ tịch Hồ Chí Minh đã mời nhiều nhân sĩ, trí thức có uy tín thuộc nhiều xu hướng chính trị, tôn giáo khác nhau cùng tham gia gánh vác việc nước: học giả Nguyễn Văn Tố phụ trách Bộ Cứu tế xã hội, luật sư Vũ Trọng Khánh giữ chức Bộ trưởng Bộ Tư pháp, bác sĩ Phạm Ngọc Thạch phụ trách Bộ Y tế, ông Nguyễn Mạnh Hà — một trí thức Công giáo — giữ chức Bộ trưởng Bộ Kinh tế quốc dân."},{"t":"Việc mời gọi những người ngoài Việt Minh, thậm chí từng có quan điểm khác biệt, cùng tham gia chính quyền là một chủ trương có chủ đích rõ ràng: xây dựng một Chính phủ đại diện cho khối đại đoàn kết toàn dân tộc ngay từ những ngày đầu lập quốc, thay vì một chính quyền của riêng một đảng phái hay một lực lượng chính trị. Trong bối cảnh đất nước vừa thoát khỏi ách đô hộ, đứng trước muôn vàn khó khăn về đối nội lẫn đối ngoại, sự đoàn kết rộng rãi ấy có ý nghĩa sống còn đối với việc củng cố chính quyền cách mạng còn non trẻ."},{"t":"Những cuộc tiếp xúc, mời gọi nhân sĩ, trí thức tham gia Chính phủ diễn ra dồn dập trong những ngày Chủ tịch Hồ Chí Minh ở tại nhà 48 Hàng Ngang — bên cạnh khối lượng công việc soạn thảo Tuyên ngôn Độc lập và chuẩn bị cho lễ Độc lập. Chỉ trong vài ngày ngắn ngủi, một nội các đa dạng về thành phần nhưng thống nhất về mục tiêu đã được hình thành, trở thành nền móng đầu tiên của bộ máy nhà nước Việt Nam Dân chủ Cộng hòa."},{"t":"Chiếc ghế tiếp khách phục dựng trong gian trưng bày, đặt đối diện với góc bàn làm việc, là một cách nhắc lại tinh thần ấy: một chính quyền cách mạng mới ra đời, nhưng ngay từ đầu đã biết mở rộng vòng tay, quy tụ người tài đức khắp mọi giới để cùng chung sức dựng xây đất nước."},{"t":"Không phải mọi thành viên Chính phủ lâm thời đều là gương mặt mới gặp lần đầu trên chiếc ghế ấy. Bên cạnh những nhân sĩ, trí thức được mời tham gia, có những cộng sự đã sát cánh cùng Chủ tịch Hồ Chí Minh từ trước, như ông Võ Nguyên Giáp, khi đó giữ chức Bộ trưởng Bộ Nội vụ trong Chính phủ lâm thời — người đã gặp Người lần đầu tại Côn Minh (Trung Quốc) từ năm năm trước đó. Sự kết hợp giữa những gương mặt quen thuộc của cách mạng và những nhân sĩ, trí thức mới được mời gọi, cùng ngồi lại bàn việc nước ngay trong căn phòng nhỏ này, chính là hình ảnh thu nhỏ của một Chính phủ liên hiệp, đoàn kết rộng rãi mà Chủ tịch Hồ Chí Minh chủ trương xây dựng ngay từ những ngày đầu lập quốc."}]},{"id":"vintage_suitcase@6.2,66.8","x":6.2,"y":0.26,"z":66.85,"loai":"vintage_suitcase","ten":"Va li (đồ vật minh họa)","tieu_de":"Từ chiến khu về Thủ đô","text":"Chiếc va li da cũ, góc cạnh sờn màu thời gian, đặt khiêm tốn trong góc phòng phục dựng, là một đồ vật minh họa — không phải hiện vật gốc — được dùng để gợi lại hình ảnh một hành trình: chuyến đi từ chiến khu Việt Bắc về Thủ đô Hà Nội của Chủ tịch Hồ Chí Minh vào cuối tháng 8 năm 1945.\n\nNgày 22 tháng 8 năm 1945, sau những ngày tháng lãnh đạo cuộc Tổng khởi nghĩa từ chiến khu Tân Trào, Chủ tịch Hồ Chí Minh rời căn cứ địa để về xuôi. Ngày 25 tháng 8, Người vào tới nội thành Hà Nội, được bố trí ở tạm tại một số địa điểm trước khi chuyển đến căn gác nhà số 48 Hàng Ngang. Đó là một chuyến đi không có nhiều hành lý theo nghĩa vật chất thông thường — điều Người mang theo quan trọng hơn cả là ý chí và quyết tâm đã được hun đúc qua nhiều tháng ngày gian khổ ở chiến khu.\n\nTheo hồi ký của Đại tướng Võ Nguyên Giáp, ngay tại Tân Trào, trong những ngày còn đang dưỡng bệnh sau một trận ốm nặng, Chủ tịch Hồ Chí Minh đã nói với ông về quyết tâm chớp lấy thời cơ giành độc lập, đại ý rằng lúc này thời cơ thuận lợi đã tới, dù phải hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập. Quyết tâm ấy — chứ không phải bất cứ hành lý vật chất nào — mới là điều thực sự theo Người suốt chặng đường từ chiến khu về Thủ đô.\n\nChặng đường ấy đưa Người đi qua một quãng chuyển tiếp đầy ý nghĩa: từ một chiến khu bí mật giữa núi rừng Việt Bắc, nơi các quyết định về Tổng khởi nghĩa được đưa ra trong bí mật, đến giữa lòng một thành phố vừa được Việt Minh giành lại quyền kiểm soát, nơi trong ít ngày tới hàng chục vạn con người sẽ tụ hội trong buổi lễ ra mắt một quốc gia độc lập. Ít ai ngoài những người trong cuộc khi ấy biết rằng người khách vừa lặng lẽ bước lên căn gác một cửa hàng tơ lụa trên phố Hàng Ngang chính là vị lãnh tụ mà cả dân tộc đang hướng về.\n\nChiếc va li minh họa trong gian trưng bày, vì vậy, không nhằm tái hiện một vật dụng có thật, mà là một hình ảnh biểu tượng cho hành trình từ bưng biền kháng chiến đến Thủ đô, từ bí mật đến công khai, từ những ngày bôn ba gian khổ đến giờ phút chuẩn bị tuyên bố nền độc lập cho cả một dân tộc — một hành trình ngắn về thời gian nhưng mang tầm vóc lịch sử vô cùng lớn lao.\n\nSau buổi lễ Độc lập chiều 2 tháng 9, hành trình ấy chưa dừng lại. Chủ tịch Hồ Chí Minh tiếp tục ở lại làm việc tại Hà Nội, chuyển đến Bắc Bộ phủ để điều hành Chính phủ lâm thời, lãnh đạo cuộc chiến chống giặc đói, giặc dốt, chuẩn bị Tổng tuyển cử. Suốt hành trình từ chiến khu Việt Bắc về Thủ đô rồi bắt tay ngay vào công việc dựng nước, hành lý mà Người mang theo, như nhiều người từng chứng kiến kể lại, luôn hết sức đơn giản — phản ánh một nếp sống giản dị được giữ gìn suốt cả cuộc đời hoạt động cách mạng, chứ không riêng gì trong chuyến trở về Hà Nội mùa thu năm 1945.","nguon":"Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký); Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Từ chiến khu về Thủ đô. Chiếc va li da cũ, góc cạnh sờn màu thời gian, đặt khiêm tốn trong góc phòng phục dựng, là một đồ vật minh họa — không phải hiện vật gốc — được dùng để gợi lại hình ảnh một hành trình: chuyến đi từ chiến khu Việt Bắc về Thủ đô Hà Nội của Chủ tịch Hồ Chí Minh vào cuối tháng 8 năm 1945."},{"t":"Ngày 22 tháng 8 năm 1945, sau những ngày tháng lãnh đạo cuộc Tổng khởi nghĩa từ chiến khu Tân Trào, Chủ tịch Hồ Chí Minh rời căn cứ địa để về xuôi. Ngày 25 tháng 8, Người vào tới nội thành Hà Nội, được bố trí ở tạm tại một số địa điểm trước khi chuyển đến căn gác nhà số 48 Hàng Ngang. Đó là một chuyến đi không có nhiều hành lý theo nghĩa vật chất thông thường — điều Người mang theo quan trọng hơn cả là ý chí và quyết tâm đã được hun đúc qua nhiều tháng ngày gian khổ ở chiến khu."},{"t":"Theo hồi ký của Đại tướng Võ Nguyên Giáp, ngay tại Tân Trào, trong những ngày còn đang dưỡng bệnh sau một trận ốm nặng, Chủ tịch Hồ Chí Minh đã nói với ông về quyết tâm chớp lấy thời cơ giành độc lập, đại ý rằng lúc này thời cơ thuận lợi đã tới, dù phải hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập. Quyết tâm ấy — chứ không phải bất cứ hành lý vật chất nào — mới là điều thực sự theo Người suốt chặng đường từ chiến khu về Thủ đô."},{"t":"Chặng đường ấy đưa Người đi qua một quãng chuyển tiếp đầy ý nghĩa: từ một chiến khu bí mật giữa núi rừng Việt Bắc, nơi các quyết định về Tổng khởi nghĩa được đưa ra trong bí mật, đến giữa lòng một thành phố vừa được Việt Minh giành lại quyền kiểm soát, nơi trong ít ngày tới hàng chục vạn con người sẽ tụ hội trong buổi lễ ra mắt một quốc gia độc lập. Ít ai ngoài những người trong cuộc khi ấy biết rằng người khách vừa lặng lẽ bước lên căn gác một cửa hàng tơ lụa trên phố Hàng Ngang chính là vị lãnh tụ mà cả dân tộc đang hướng về."},{"t":"Chiếc va li minh họa trong gian trưng bày, vì vậy, không nhằm tái hiện một vật dụng có thật, mà là một hình ảnh biểu tượng cho hành trình từ bưng biền kháng chiến đến Thủ đô, từ bí mật đến công khai, từ những ngày bôn ba gian khổ đến giờ phút chuẩn bị tuyên bố nền độc lập cho cả một dân tộc — một hành trình ngắn về thời gian nhưng mang tầm vóc lịch sử vô cùng lớn lao."},{"t":"Sau buổi lễ Độc lập chiều 2 tháng 9, hành trình ấy chưa dừng lại. Chủ tịch Hồ Chí Minh tiếp tục ở lại làm việc tại Hà Nội, chuyển đến Bắc Bộ phủ để điều hành Chính phủ lâm thời, lãnh đạo cuộc chiến chống giặc đói, giặc dốt, chuẩn bị Tổng tuyển cử. Suốt hành trình từ chiến khu Việt Bắc về Thủ đô rồi bắt tay ngay vào công việc dựng nước, hành lý mà Người mang theo, như nhiều người từng chứng kiến kể lại, luôn hết sức đơn giản — phản ánh một nếp sống giản dị được giữ gìn suốt cả cuộc đời hoạt động cách mạng, chứ không riêng gì trong chuyến trở về Hà Nội mùa thu năm 1945."},{"t":"Bạn có biết? Theo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi rời Tân Trào, Chủ tịch Hồ Chí Minh từng nói: dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập."}],"ban_co_biet":"Theo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi rời Tân Trào, Chủ tịch Hồ Chí Minh từng nói: dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập."},{"id":"table@0.0,-92.2","x":0,"y":1.9,"z":-92.2,"loai":"table","ten":"Bàn trên lễ đài","tieu_de":"Trên lễ đài Độc lập","text":"Chiếc bàn gỗ phủ khăn, đặt phía trên lễ đài phục dựng của gian trưng bày, gợi lại vị trí trung tâm của buổi lễ trọng đại chiều ngày 2 tháng 9 năm 1945 tại Quảng trường Ba Đình — nơi Chủ tịch Hồ Chí Minh cùng các thành viên Chính phủ lâm thời đứng ra mắt quốc dân. Đây là đồ vật phục dựng, dựng lại theo hình dung về khung cảnh buổi lễ, không phải hiện vật nguyên bản còn được lưu giữ.\n\nLễ đài tại Quảng trường Ba Đình được dựng gấp trong những ngày trước lễ Độc lập, do kiến trúc sư Ngô Huy Quỳnh — khi đó còn rất trẻ — phác thảo và trực tiếp chỉ đạo thi công. Đó là một khung gỗ giản dị khoác vải, có phông nền phía sau, đủ trang nghiêm cho một buổi lễ mang ý nghĩa lịch sử trọng đại nhưng được chuẩn bị trong một khoảng thời gian hết sức gấp rút. Trên lễ đài ấy, một chiếc bàn được kê ra để phục vụ cho các nghi thức của buổi lễ.\n\nChiều Chủ nhật, 2 tháng 9 năm 1945, trước hàng chục vạn đồng bào Hà Nội và các tỉnh lân cận tụ hội tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa buổi đọc, Người bất chợt dừng lại, hỏi đồng bào một câu giản dị mà xúc động: \"Tôi nói, đồng bào nghe rõ không?\" — câu hỏi không có trong bất kỳ bản thảo nào, đã trở thành một trong những khoảnh khắc được nhắc nhớ nhiều nhất của ngày Độc lập, cho thấy hình ảnh một vị lãnh tụ gần gũi, giản dị giữa muôn triệu đồng bào.\n\nSau khi đọc xong bản Tuyên ngôn Độc lập, trên chính lễ đài ấy đã diễn ra lễ tuyên thệ của các thành viên Chính phủ lâm thời trước quốc dân đồng bào, thể hiện quyết tâm phụng sự Tổ quốc, phụng sự nhân dân của chính quyền cách mạng còn non trẻ. Buổi lễ khép lại trong không khí trang nghiêm mà xúc động, đánh dấu thời khắc một quốc gia độc lập chính thức ra đời sau gần một thế kỷ chịu ách đô hộ.\n\nChiếc bàn trên lễ đài phục dựng trong gian trưng bày, tuy chỉ là một chi tiết nhỏ trong toàn cảnh buổi lễ, nhưng gợi nhắc người xem về không gian cụ thể — không phải một cung điện nguy nga, mà là một lễ đài dựng tạm giữa quảng trường — nơi đã diễn ra một trong những sự kiện trọng đại bậc nhất của lịch sử Việt Nam hiện đại.\n\nĐứng trên lễ đài ấy nhìn xuống, Chủ tịch Hồ Chí Minh và các thành viên Chính phủ lâm thời thấy trước mắt mình một biển người trải rộng khắp quảng trường, phía trên là lá cờ đỏ sao vàng — quốc kỳ vừa được Quốc dân Đại hội Tân Trào quy định ít ngày trước đó — tung bay trên cột cờ. Để giọng đọc của Người có thể vang tới hàng chục vạn đồng bào đứng chật quảng trường và các phố lân cận, một hệ thống loa phóng thanh cũng được bố trí quanh khu vực lễ đài — một nỗ lực kỹ thuật không nhỏ trong điều kiện chuẩn bị gấp rút của những ngày ấy. Phía sau lễ đài, sừng sững tòa nhà từng là Phủ Toàn quyền Đông Dương thời Pháp thuộc — nơi mà chỉ ít lâu sau trở thành một phần của Phủ Chủ tịch nước Việt Nam Dân chủ Cộng hòa — như một hình ảnh đối lập giữa quá khứ thuộc địa vừa khép lại và một kỷ nguyên độc lập vừa mở ra.","nguon":"Hồ Chí Minh – Biên niên tiểu sử","doc":[{"t":"Trên lễ đài Độc lập. Chiếc bàn gỗ phủ khăn, đặt phía trên lễ đài phục dựng của gian trưng bày, gợi lại vị trí trung tâm của buổi lễ trọng đại chiều ngày 2 tháng 9 năm 1945 tại Quảng trường Ba Đình — nơi Chủ tịch Hồ Chí Minh cùng các thành viên Chính phủ lâm thời đứng ra mắt quốc dân. Đây là đồ vật phục dựng, dựng lại theo hình dung về khung cảnh buổi lễ, không phải hiện vật nguyên bản còn được lưu giữ."},{"t":"Lễ đài tại Quảng trường Ba Đình được dựng gấp trong những ngày trước lễ Độc lập, do kiến trúc sư Ngô Huy Quỳnh — khi đó còn rất trẻ — phác thảo và trực tiếp chỉ đạo thi công. Đó là một khung gỗ giản dị khoác vải, có phông nền phía sau, đủ trang nghiêm cho một buổi lễ mang ý nghĩa lịch sử trọng đại nhưng được chuẩn bị trong một khoảng thời gian hết sức gấp rút. Trên lễ đài ấy, một chiếc bàn được kê ra để phục vụ cho các nghi thức của buổi lễ."},{"t":"Chiều Chủ nhật, 2 tháng 9 năm 1945, trước hàng chục vạn đồng bào Hà Nội và các tỉnh lân cận tụ hội tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa buổi đọc, Người bất chợt dừng lại, hỏi đồng bào một câu giản dị mà xúc động: \"Tôi nói, đồng bào nghe rõ không?\" — câu hỏi không có trong bất kỳ bản thảo nào, đã trở thành một trong những khoảnh khắc được nhắc nhớ nhiều nhất của ngày Độc lập, cho thấy hình ảnh một vị lãnh tụ gần gũi, giản dị giữa muôn triệu đồng bào."},{"t":"Sau khi đọc xong bản Tuyên ngôn Độc lập, trên chính lễ đài ấy đã diễn ra lễ tuyên thệ của các thành viên Chính phủ lâm thời trước quốc dân đồng bào, thể hiện quyết tâm phụng sự Tổ quốc, phụng sự nhân dân của chính quyền cách mạng còn non trẻ. Buổi lễ khép lại trong không khí trang nghiêm mà xúc động, đánh dấu thời khắc một quốc gia độc lập chính thức ra đời sau gần một thế kỷ chịu ách đô hộ."},{"t":"Chiếc bàn trên lễ đài phục dựng trong gian trưng bày, tuy chỉ là một chi tiết nhỏ trong toàn cảnh buổi lễ, nhưng gợi nhắc người xem về không gian cụ thể — không phải một cung điện nguy nga, mà là một lễ đài dựng tạm giữa quảng trường — nơi đã diễn ra một trong những sự kiện trọng đại bậc nhất của lịch sử Việt Nam hiện đại."},{"t":"Đứng trên lễ đài ấy nhìn xuống, Chủ tịch Hồ Chí Minh và các thành viên Chính phủ lâm thời thấy trước mắt mình một biển người trải rộng khắp quảng trường, phía trên là lá cờ đỏ sao vàng — quốc kỳ vừa được Quốc dân Đại hội Tân Trào quy định ít ngày trước đó — tung bay trên cột cờ. Để giọng đọc của Người có thể vang tới hàng chục vạn đồng bào đứng chật quảng trường và các phố lân cận, một hệ thống loa phóng thanh cũng được bố trí quanh khu vực lễ đài — một nỗ lực kỹ thuật không nhỏ trong điều kiện chuẩn bị gấp rút của những ngày ấy. Phía sau lễ đài, sừng sững tòa nhà từng là Phủ Toàn quyền Đông Dương thời Pháp thuộc — nơi mà chỉ ít lâu sau trở thành một phần của Phủ Chủ tịch nước Việt Nam Dân chủ Cộng hòa — như một hình ảnh đối lập giữa quá khứ thuộc địa vừa khép lại và một kỷ nguyên độc lập vừa mở ra."},{"t":"Bạn có biết? Toàn bộ lễ đài tại Quảng trường Ba Đình — khung gỗ khoác vải, phông nền, bậc lên xuống — do kiến trúc sư Ngô Huy Quỳnh phác thảo và chỉ đạo dựng gấp rút chỉ trong vài ngày trước lễ Độc lập."}],"ban_co_biet":"Toàn bộ lễ đài tại Quảng trường Ba Đình — khung gỗ khoác vải, phông nền, bậc lên xuống — do kiến trúc sư Ngô Huy Quỳnh phác thảo và chỉ đạo dựng gấp rút chỉ trong vài ngày trước lễ Độc lập."}]};
